class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  def solve(): Unit = {
    val N = ni()
    val A = na(N)
    val cum = cumXor(A)
    debug("cum")
    debug(cum)
    val cum0 = Array.ofDim[Int](N + 2)
    val pos = Array.fill[ArrayBuffer[Int]](1 << 20)(ArrayBuffer())

    // cumに対してループする
    REP(N + 1) { i =>
      if (cum(i) != 0) pos(cum(i)) += i
      cum0(i + 1) = cum0(i) + (if (cum(i) == 0) 1 else 0)
    }
    debug("cum0")
    debug(cum0)

    DEBUG {
      REP(1 << 20) { i =>
        if (pos(i).nonEmpty) {
          debug(s"pos($i)")
          debug(pos(i).mkString(" "))
        }
      }
    }

    def count(x: Int): Array[Long] = {
      debug(s"count($x)")
      val P = pos(x)
      val n = P.length
      // 0は必ず最初の0が１ついるだけ
      val dp = Array.ofDim[Long](2) // 0: 0-1-0の組み合わせ, 1: 0-1の組み合わせ

      REP(2 * n) { i =>
        // 1
        if (i % 2 == 0) {
          dp(1) = (dp(1) + dp(0) + 1) % MOD

        // 0
        } else {
          val ii = i / 2
          val cnt = if (i == 2 * n - 1) {
            cum0(N + 1) - cum0(P.last)
          } else {
            cum0(P(ii + 1)) - cum0(P(ii))
          }

          dp(0) = (dp(0) + dp(1) * cnt) % MOD
        }
        debug(dp)
      }

      dp
    }

    if (cum(N) == 0) {
      var ans = 0L
      REP(pos.length) { i =>
        if (pos(i).nonEmpty) {
          ans += count(i)(1) // 途中で x状態になった数
        }
      }
      ans += powMod(2, cum0(N + 1) - 2, MOD) // x == 0の場合。最初、最後の0は選択できない
      out.println(ans % MOD)
    } else {
      // 全部をxorした結果がXなので、(X^X)* ^ X かならずこの形式になる
      out.println((count(cum(N))(0) + 1) % MOD) // 途中で0状態になった数。countは0-1-0の組みを返すので0を１つ足してやる
    }
  }

  def powMod(x: Int, n: Int, m: Int): Int = {
    def step(x: Long, n: Int, stack: Long): Long = {
      n match {
        case 0 => stack
        case _ => step(x * x % m, n / 2, if (n % 2 == 1) stack * x % m else stack)
      }
    }
    step(x, n, 1).toInt
  }
}

