int a[N], pre[N];
int dp[N];
map<int,int> m, m1;
void solve(){
	int n;
	cin >> n;
	fr(i, 1, n){
		cin >> a[i];
		pre[i] = pre[i - 1] ^ a[i];
	}
	int ans = 0;
	if(pre[n] != 0){ // xor != 0 and odd partitions ...
		int s0 = 1, s1 = 0;
		int val = pre[n];
		fr(i, 1, n){
			if(pre[i] == val){
				dp[i] = s0;
				s1 += dp[i];
			}
			else if(pre[i] == 0){
				dp[i] = s1;
				s0 += dp[i];
			}
		}
		cout << dp[n] << endl;
		return;
	}
	// xor = 0
	int c = 0;
	fr(i, 1, n - 1){
		if(pre[i] == 0)
			c++;
	}
	ans = pwr(2, c, mod);
	// xor != 0
	int c0 = 1;
	m[0] = 1;
	dp[0] = 1;
	fr(i, 1, n){
		if(pre[i] == 0){
			c0++;
		}
		else{
			dp[i] = (m1[pre[i]] * c0 - m[pre[i]] + mod + 1) % mod;
			ans += dp[i];
			ans %= mod;
			m[pre[i]] += c0 * dp[i];
			m[pre[i]] %= mod;
			m1[pre[i]] += dp[i];
			m1[pre[i]] %= mod;
		}
	}
	cout << ans;
}
