    cout << dp[n] << endl;
  }else{
    mem[0] = dp[0];
    for(ll i = 1;i <= n;i++){
      c = c^a[i];
      dp[i] = mem[c^b];
      mem[c] += dp[i];
      mem[c] %= mod;
    }
    for(ll i = 1;i <= n;i++){
      b = b^a[i];
      d[i] = b;
      if(b == 0) zero[i]++;
    }
    for(ll i = 1;i <= n;i++){
      zero[i] += zero[i-1];
    }
    fill(dp0,dp0+e5,1ll);
    for(ll i = 1;i <= n;i++){
      if(d[i] != 0){
        dp0[d[i]] += dpx[d[i]]*(zero[i]-zero[pre[d[i]]]);
        dpx[d[i]] += dp0[d[i]];
        dp0[d[i]] %= mod;
        dpx[d[i]] %= mod;
        pre[d[i]] = i;
      }
    }
    cout << dp[n] + accumulate(dpx,dpx+e5,0ll) << endl;
  }


}

