ll temp[MAXN];

ll f(ll id){
    ll num = c[id][0];
    ll cnt = 0;

    ll ans = num;
    forI(i, gap[id].size()){
        ll val = (num * c[id][i] % MOD * gap[id][i - 1] % MOD + cnt * c[id][i] % MOD) % MOD;

        ans += val + c[id][i];
        ans %= MOD;

        cnt = (cnt + num * gap[id][i - 1]) % MOD;
        num = val;
    }
    return ans;
}

ll pw(ll a, ll b){
    if(b == 0) return 1;
    ll e = pw(a, b >> 1);
    if(b & 1) return e * e % MOD * a % MOD;
    return e * e % MOD;
}

ll solve() {
    //cin >> n;
    ll xr = 0;
    vector<ll> gc;
    ll block_num = 0;
    forI(i, n){
        //cin >> arr[i];
        xr ^= arr[i];
        xar[i] = xr;

        ++temp[xr];
        if(temp[xr] == 1) gc.push_back(xr);

        if(xr == 0){
            ++block_num;
            for(ll e: gc){
                c[e].push_back(temp[e]);
                temp[e] = 0;

                if(pre[e])
                    gap[e].push_back(block_num - pre[e]);
                pre[e] = block_num;
            }
            gc.clear();
        }
    }

    for(ll e: gc) temp[e] = 0;


    if(xr){
        ///delete line below!!!
        return -1;

        ll cnt = 0;
        forI(i, n){
            if(cnt % 2 == 0 && xar[i] == xr) ++cnt;
            else if(cnt % 2 == 1 && xar[i] == 0) ++cnt;
        }
        //fibonacci?
        ll a = 0;
        ll b = 1;
        fori(i, cnt - 1){
            a += b;
            if(a >= MOD) a -= MOD;
            swap(a, b);
        }
        return b;
    }


    ll ans = pw(2, block_num - 1);
    fori(i, MAXN){
        if(pre[i]){
            //delete?
            if(i == 0) continue;


            ans += f(i);
            ans %= MOD;

            //pre[i] = 0;
        }
    }
    return ans;
}

ll rec(ll it, ll crxr = 0, ll xr = -1){
    crxr ^= arr[it];
    if(it == n){
        if(crxr == xr || xr == -1) return 1;
        return 0;
    }

    ll c = rec(it + 1, crxr, xr);

    if(xr == -1 || crxr == xr){
        xr = crxr;
        c += rec(it + 1, 0, xr);
    }
    return c;
}

ll brut(){
    return rec(1);
}

void fff(){
    while(true){
        n = rand() % 5 + 1;
        forI(i, n) arr[i] = rand() % 7 + 1;

        fori(i, MAXN) gap[i].clear(), c[i].clear(), temp[i] = pre[i] = 0;
        ll e = solve();
        ll e2 = brut();
        if(e != e2){
            fori(i, MAXN) gap[i].clear(), c[i].clear(), temp[i] = pre[i] = 0;
            ll a = solve();
            ll b = brut();
            cout << a << " " << b;
            return;
        }
    }
}

