template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }

  static int get_mod() { return mod; }
};

using modint = ModInt< MOD >;
using vm = vector<modint>;
using P = pair<modint,modint>;

void solve(){
  ini(N);
  vi a(N); in(a);
  vi rui(N + 1);
  rep(i , N) rui[i + 1] = rui[i] ^ a[i];

  vi zero(N + 1);
  rep(i , N) zero[i + 1] = zero[i] + (rui[i] == 0);

  auto f = [&](vi a) -> P{
    int idx = 0;
    P ret = P(1 , 0);
    while(idx < sz(a)){
      // a[idx]はA
      ret.se += ret.fi;

      // a[idx]とa[idx + 1]の間にzeroは何個？
      int cnt = (zero[idx + 1 < sz(a) ? a[idx + 1] : N])- zero[a[idx]];
      ret.fi += ret.se * cnt;

      idx++;
    }
    return ret;
  };

  if(rui[N] != 0){
    vi nya;
    rep1(i , N - 1) if(rui[i] == rui[N]) nya.pb(i);
    auto nyaa = f(nya);
    die(nyaa.first);
  }
  else{
    map<int , vi> m;
    rep1(i , N - 1) m[rui[i]].pb(i);
    modint ans = 0;
    trc(m[0]);
    ans += modint(2).pow(sz(m[0]));
    each(nya , m){
      if(nya.first == 0) continue;
      auto nyaa = f(nya.second);
      trc(nya , nyaa);
      ans += nyaa.second;
    } 
    die(ans);
  }



}

