    pr[0] = 0;
    for (int i = 0; i < n; ++i) {
        pr[i + 1] = pr[i] ^ a[i];
    }
    /*for (int i = 0; i <= n; ++i)
        cerr << pr[i] << " ";
    cerr << endl;*/
    vector<vector<int> > pos(N);
    for (int i = 1; i <= n; ++i)
        pos[pr[i]].push_back(i);
    vector<int> pr0(n + 1, 0);
    for (int i = 1; i <= n; ++i)
        pr0[i] = pr0[i - 1] + (pr[i] == 0);
    ll res = 0;
    if (pr[n] != 0) {
        //pll cur = solve(n, pr, pos[pr[n]], pr0);
        //cerr << cur.first << " " << cur.second << endl;
