vector < long long > v[1200000];
long long b[1200000] , cnt;
long long dp[2][1200000];
long long ans;
long long ksm ( long long f , long long x ) {
	long long s = 1;
	while ( x ) {
		if ( x % 2 ) s = s * f % mod;
		f = f * f % mod; x = x / 2;
	}
	return s % mod;
}
void solve ( long long t , long long ned ) {
	long long i;
	cnt = 0;
	for ( i = 0 ; i < v[t].size() ; i++ ) {
		if ( i != 0 && zero[v[t][i]] != zero[v[t][i-1]] ) b[++cnt] = zero[v[t][i]] - zero[v[t][i-1]];
		b[++cnt] = -1;
	}
	if ( ned == 0 ) {
		if ( zero[n] - zero[v[t][i-1]] >= 1 ) {
			if ( zero[n] - zero[v[t][i-1]] > 1 )
				b[++cnt] = zero[n] - zero[v[t][i-1]] - 1;
			b[++cnt] = 1;
		}
	}
	dp[0][0] = 1;
	dp[1][0] = 0;
	//printf ( "%lld\n" , t );
	for ( i = 1 ; i <= cnt ; i++ ) {
		if ( b[i] == -1 ) {
			dp[1][i] = (dp[1][i-1] + dp[0][i-1]) % mod;
			dp[0][i] = dp[0][i-1];
		}
		else {
			dp[0][i] = (dp[0][i-1] + dp[1][i-1] * b[i]) % mod;
			dp[1][i] = dp[1][i-1];
		}
		//printf ( "%lld %lld %lld\n" , b[i] , dp[0][i] , dp[1][i] );
	}
	//printf ( "%lld %lld\n" , ned , cnt );
	//printf ( "\n" );
	ans = (ans + dp[ned][cnt]-dp[ned][cnt-1]+mod) % mod;
}
