	long long i , cnt , t;
	scanf ( "%lld" , &n );
	for ( i = 1 ; i <= n ; i++ ) {
		scanf ( "%lld" , &a[i] );
		tot ^= a[i];
		a[i] ^= a[i-1];
		x[tot]++;
		if ( tot == 0 ) {
			zero[i] = 1;
		}
		v[tot].push_back ( i );
