		for ( i = 1 ; i < (1<<20) ; i++ ) {
			if ( x[i] ) {
				solve ( i , 0 );
			}
		}
		ans = (ans + ksm ( 2 , x[0]-1)) % mod;
	}
	else { 
		solve ( tot , 1 );
	}
	printf ( "%lld\n" , ans );
}
