VI dp;

int solve(VI& v, bool OK)
{
	if (SZ(v) == 1)
		return 1;

	int sz = SZ(v);
	VI nuli(sz, 0);
	FOR(i, 0, sz)
		nuli[i] = cnt0[v[i]];

	dp.assign(sz, 0);

	dp.back() = 1;
	int suma = 1, suma_cnt = nuli.back();
	RFOR(i, sz - 1, 0)
	{
		dp[i] = add(dp[i + 1], suma_cnt);
		dp[i] = sub(dp[i], mult(suma, nuli[i]));	
		if (OK)
			dp[i] = add(dp[i], 1);

		suma = add(suma, dp[i]);
		suma_cnt = add(suma_cnt, mult(dp[i], nuli[i]));	
	}

	return dp[0];
}

