int n, v[500002], sxor[500002];
struct xorin
{
    int poz, val;
};
xorin v2[500002];
bool cmp(xorin a, xorin b)
{
    if(a.val == b.val)
        return a.poz < b.poz;
    return a.val < b.val;
}
int pr0[500002];
long long ans = 0;
vector<int>poz;
void solvedp()
{
    if(sxor[poz[0]] == 0)
    {
        long long a = 1;
        for(int i = 1; i < poz.size(); ++i)
            a = (a * 2) % mod;
        if(poz.back() == n || (sxor[poz.back()] ^ sxor[n]) == sxor[poz[0]])
            ans = (ans + a) % mod;
        return;
    }
    if(poz[0] == n || (sxor[poz[0]] ^ sxor[n]) == sxor[poz[0]])
        ans = (ans + 1) % mod;
    long long sumM = 1, sum0 = 0;
    for(int i = 1; i < poz.size(); ++i){
        int nr0 = pr0[poz[i]] - pr0[poz[i-1]];
        sum0 = (sum0 + 1LL * nr0 * sumM) % mod;
        if(poz.back() == n || (sxor[poz[i]] ^ sxor[n]) == sxor[poz[0]])
            ans = (ans + sum0 + 1) % mod;
        sumM = (sumM + sum0 + 1) % mod;
    }
}
