{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> n;
    for(int i = 1; i <= n; ++i)
        cin >> v[i];
    for(int i = 1; i <= n; ++i){
        sxor[i] = sxor[i-1] ^ v[i];
        v2[i] = {i, sxor[i]};
    }
    sort(v2 + 1, v2 + n + 1, cmp);
    for(int i = 1; i <= n; ++i)
        pr0[i] = pr0[i-1] + (sxor[i] == 0);
    for(int i = 1; i <= n; ++i){
        int j = i;
        poz.clear();
        while(j <= n && v2[i].val == v2[j].val)
            poz.push_back(v2[j].poz), ++j;
        solvedp();
        i = j-1;
    }
    cout << ans;
    return 0;
}

