int getNextX(int at, int tarX){
	vector<int> target = xat[tarX];
	vector<int>::iterator position = lower_bound(target.begin(), target.end(), at);
	if(position == target.end())return -1;
	return *position;
}

int getXnum(int l, int r, int tarX){
	vector<int> target = xat[tarX];
	vector<int>::iterator posA = lower_bound(target.begin(), target.end(), l);
	vector<int>::iterator posB = lower_bound(target.begin(), target.end(), r);
	return posB-posA;
}

int X;
int dfs(int at, int before){
	if(at == n-1){
		if(before == 0){
			return 1;
		}else{
			return 0;
		}
	}
	pair<int,int> key = make_pair(at,before);
	map<pair<int,int>,int>::iterator it = dp[X].find(key);
	if(it != dp[X].end()){
		return it->second;
	}

	ll sum = 0;
	if(b[at] == 0){
		sum += dfs(at+1, before);
		if(before == 1)
			sum += dfs(at+1, 0);

	}else if(b[at] == X){
		sum += dfs(at+1, before);
		if(before == 0)
			sum += dfs(at+1, 1);

	}else{
		sum += dfs(at+1, before);

	}
	sum%=MOD;
	return dp[X][key] = (int)sum;
}

int dfs2(int at, int before){
	if(at == n-1){
		if(before == 1){
			return 1;
		}else{
			return 0;
		}
	}
	pair<int,int> key = make_pair(at,before);
	map<pair<int,int>,int>::iterator it = dp[X].find(key);
	if(it != dp[X].end()){
		return it->second;
	}

	ll sum = 0;
	if(b[at] == 0){
		int nextX = getNextX(at,X);
		// cout << "nextX:" << nextX << endl;
		if(nextX == -1){
			sum = dfs2(n-1, before);
			sum%=MOD;
			return (int)sum;
		}
		int num_0 = getXnum(at,nextX,0);
		// cout << "num_0:" << num_0 << endl;
		// cout << "nextX:" << nextX << " num_0:" << num_0 << endl;
		sum += dfs2(nextX, before);
		if(before == 1)
			sum += (dfs2(nextX, 0)*num_0)%MOD;

	}else if(b[at] == X){//今Xを見てる
		int nextzero = getNextX(at,0);
		int Xnum = getXnum(at,nextzero,X);
		// cout << "nextzero:" << nextzero << " Xnum:" << Xnum << endl;
		sum += dfs2(nextzero, before);
		if(before == 0)
			sum += (dfs2(nextzero, 1)*Xnum)%MOD;

	}
	sum%=MOD;
	return dp[X][key] = (int)sum;
}

