//ModInt
template <int mod>
struct ModInt {
    int x;
    ModInt() : x(0) {}
    ModInt(ll x_) {
        if ((x = x_ % mod + mod) >= mod) x -= mod;
    }
    ModInt& operator+=(ModInt rhs) {
        if ((x += rhs.x) >= mod) x -= mod;
        return *this;
    }
    ModInt& operator-=(ModInt rhs) {
        if ((x -= rhs.x) < 0) x += mod;
        return *this;
    }
    ModInt& operator*=(ModInt rhs) {
        x = (unsigned long long)x * rhs.x % mod;
        return *this;
    }
    ModInt& operator/=(ModInt rhs) {
        x = (unsigned long long)x * rhs.inv().x % mod;
        return *this;
    }

    ModInt operator-() const { return -x < 0 ? mod - x : -x; }
    ModInt operator+(ModInt rhs) const { return ModInt(*this) += rhs; }
    ModInt operator-(ModInt rhs) const { return ModInt(*this) -= rhs; }
    ModInt operator*(ModInt rhs) const { return ModInt(*this) *= rhs; }
    ModInt operator/(ModInt rhs) const { return ModInt(*this) /= rhs; }
    bool operator==(ModInt rhs) const { return x == rhs.x; }
    bool operator!=(ModInt rhs) const { return x != rhs.x; }
    ModInt inv() const { return pow(*this, mod - 2); }

    friend ostream& operator<<(ostream& s, ModInt<mod> a) {
        s << a.x;
        return s;
    }
    friend istream& operator>>(istream& s, ModInt<mod>& a) {
        s >> a.x;
        return s;
    }
};
using mint = ModInt<MOD>;

//二項定理計算

const int MAX = 1000010;
mint fac[MAX],finv[MAX],inv[MAX];
//テーブル作成
void COMinit(){
    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;
    for(int i=2;i<MAX;i++){
        fac[i]=fac[i-1]*(mint)i;
        inv[i]=(mint)MOD-inv[MOD%i]*(mint)(MOD/i);
        finv[i]=finv[i-1]*inv[i];
    }
}

//nCkを求める
mint COM(int n,int k){
    if(n < k or n < 0 or k < 0)return 0;
    return fac[n]*finv[k]*finv[n-k];
}

//nPkを求める
mint PER(int n, int k){
    if(n < k or n < 0 or k < 0) return 0;
    return fac[n] / fac[n-k];
}

//nHkを求める
mint HOM(int n, int k) {return COM(n+k-1, k);};

const int MA = 1048577;

mint dp[MA][2], res;
int zerosum, zc[MA];



int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n; cin >> n;
    ll a[n], r[n];
    V<bool> exi(MA,false);
    REP(i,n) cin >> a[i];
    REP(i,n) r[i] = (i ? r[i-1] ^ a[i] : a[i]);
    REP(i,n) exi[r[i]] = true;
    //dp[s][bit]はsをbit = 0なら0をとっている、1ならsをとっている場合の数
    REPS(i,MA) dp[i][0] = 1;
    REP(i,n){   
        if(!r[i]) zerosum++;
        else{
            dp[r[i]][0] += dp[r[i]][1] * (mint)(zerosum - zc[r[i]]);
            dp[r[i]][1] += dp[r[i]][0];
            zc[r[i]] = zerosum;
        }
    }
    if(!r[n-1]){
        REPS(i, MA) if(exi[i]) res += dp[i][0] + dp[i][1];
        res += pow((mint)2, zerosum - 1);
    }
    else res = dp[r[n-1]][1];
    cout << res << '\n';
}

