int N, A[MAXN+10], zero[MAXN+10];
vector<int> pos[MAXV+10];

ll solve(int x, int t)
{
    int i, j;
    ll dp[2]={1, 0};
    for(i=1; i<pos[x].size(); i++)
    {
        ll now=pos[x][i], gap=zero[pos[x][i]]-zero[pos[x][i-1]];
        dp[0]+=gap*dp[1]%MOD;
        dp[1]+=dp[0];
        dp[0]%=MOD; dp[1]%=MOD;
    }
    return dp[t];
}

