        for (int i = 1; i < rl.size(); ++i) {
            if (rl[i].first == 0) {
                dp[i].first = (dp[i - 1].first + dp[i - 1].second * rl[i].second) % MOD;
                dp[i].second = (dp[i - 1].second) % MOD;
            } else {
                dp[i].first = dp[i - 1].first % MOD;
                dp[i].second = (dp[i - 1].first * rl[i].second + dp[i - 1].second) % MOD;
            }
        }

        ll f = dp[dp.size() - 1].first;
        ll s = dp[dp.size() - 1].second;
        return make_pair(f, s);

