const int MAXN = 1050005;
const int mod = 1e9 + 7;

int n, a[MAXN], b[MAXN], w[MAXN];
vector<int> nxt[MAXN];

lint ipow(int x, int p){
	lint ret = 1, piv = x;
	while(p){
		if(p & 1) ret = ret * piv % mod;
		piv = piv * piv % mod;
		p >>= 1;
	}
	return ret;
}

lint dp[MAXN];
lint count(int xv){
	if(nxt[xv].empty()) return 0;
	for(int i=1; i<nxt[xv].size(); i++){
		int s = nxt[xv][i-1];
		int e = nxt[xv][i];
		int cnt = lower_bound(nxt[0].begin(), nxt[0].end(), e) - 
		lower_bound(nxt[0].begin(), nxt[0].end(), s);
		w[i] = w[i-1] + cnt;
	}
	dp[0] = 1;
	lint ret = 1;
	lint sum = dp[0];
	lint dpjwj = dp[0] * -w[0];
	for(int i=1; i<nxt[xv].size(); i++){
		dp[i] = 1 + w[i] * sum + dpjwj;
		sum += dp[i];
		dpjwj += dp[i] * -w[i];
		sum %= mod;
		dpjwj %= mod;
		dpjwj += mod;
		dpjwj %= mod;
		dp[i] %= mod;
		ret += dp[i];
	}
	return ret % mod;
}


