            sumOf0 %= MOD;
            dp1[i] = sumOf0;
            sumOf1 += dp1[i] * x1.at(i-1);
            sumOf1 %= MOD;
        }
        res += dp1[n];

    }else{
        //まだ作ってないよ

    }
    cout << res << endl;
}


int main(void){
    solve();
}

