const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;

LL powm(LL a, LL b){
  if(!b) return 1;
  return powm(a*a%MOD, b/2) * (b%2 ? a : 1ll) % MOD;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;
  VI xs(N);
  cin >> xs;

  VI acc(N+1);
  REP(i,N) acc[i+1] = acc[i] ^ xs[i];

  unordered_map<LL,PLL> dp;
  FOR(i,1,N+1){
    LL a = acc[i];

    if(a){
      if(!dp.count(a)){
        dp[a] = MP(0, 0);
        //continue;
      }
      (dp[a].SS += dp[a].FF + 1) %= MOD;
    }
    else{
      for(auto& p: dp){
        (p.SS.FF += p.SS.SS) %= MOD;
      }
    }
  }

  LL ans = 0;
  if(acc.back()){
    (ans += dp[acc.back()].FF + 1) %= MOD;
  }
  else{
    for(auto& p: dp){
      (ans += p.SS.SS) %= MOD;
    }

    LL z = 0;
    FOR(i,1,N) if(!acc[i]) ++z;
    ans += powm(2, z);
  }
  cout << ans << endl;

  return 0;
}

