int add(int x,int y) {
    return (x+y)%mod;
}
int mul(int x,int y) {
    return (ll)x*y%mod;
}

int dp[M];
int sum[M],X[M];

void solve() {
    int n;
    scanf("%d",&n);
    int g = 0;
    for(int i=0;i<n;++i) {
        scanf("%d",&A[i]);
        g^= A[i];
    }
    int c = 0;
    int ret = 0;
    ++dp[0];
    if(g>0) {
        int k = 0;
        for(int i=0;i<n-1;++i) {
            c^= A[i];
            if(c==0) {
                int x = k- sum[0];
                int v = mul(x,dp[0]);
                dp[0] = add(dp[0],v);
                sum[0]= k;
                ret = add(ret,v);
            } else if(c==g) {
                ++k;
            }
        }
        ret = add(ret,1);
    } else {
        int k = 0;
        for(int i=0;i<n-1;++i) {
            c^= A[i];
            if(c==0) {
                ret= add(ret,dp[0]);
                dp[0] = add(dp[0],dp[0]);
                ++k;
            } else {
                //우선 생각해볼건, dp[c] 의 값이 뭘 의미하냐는 거지.
                int x = k - sum[c];
                sum[c] = k;
                int v = mul(x,X[c]);
                dp[c] = add(dp[c],v);
                X[c] = add(1,add(X[c],dp[c]));
                ret = add(1,add(ret,dp[c]));
            }
        }
        ret = add(ret,1);
    }
    printf("%d\n", ret);
}

