int main() {

	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> n;
	for(int i = 1; i <= n; ++i) {
		cin >> a[i];
		x ^= a[i];
	}
	for(int i = 1; i < n; ++i) {
		y ^= a[i];
		if(y == 0) {
			++sett;
			dp[y][0] *= 2;
			++dp[y][0];
			dp[y][0] %= mod;
			lazy[i] = sett;
		}
		else {
			if(lazy[y] < sett) {
				dp[y][0] += (1LL * dp[y][1] * (sett - lazy[y])) % mod;
				dp[y][0] %= mod;
				lazy[y] = sett;
			}
			dp[y][1] += dp[y][0] + 1;
			dp[y][1] %= mod;
		}
	}
	for(int i = 0; i < MAXM; ++i) {
		dp[i][0] += (1LL * dp[i][1] * (sett - lazy[i])) % mod;
		dp[i][0] %= mod;		
	}
	if(x == 0) {
		for(int i = 0; i < MAXM; ++i) {
			ans += dp[i][1];
			ans %= mod;
		}
		ans += dp[0][0] + 1;
		ans %= mod;
	}
