const int all = 1 << 4;
mint zero[all];
mint nonzero[all];
int last[all];

int main(void){
	int n;
	cin >> n;

	makeFact(n + 1);

	vector<int> a(n);
	rep(i, n) cin >> a[i];

	int k = 0;
	rep(i, n) k ^= a[i];

	mint ans = ZERO;

	int seg = 0, cur = 0;
	set<int> memo;

	rep(mask, 1, all){
		zero[mask] = ONE;
		nonzero[mask] = ZERO;
		last[mask] = 0;
	}

	rep(i, n){
		cur ^= a[i];
		if(cur == 0) {
			seg++;
			for(auto &tar: memo){
				zero[tar] += mint(seg - last[tar]) * nonzero[tar];
				last[tar] = seg;
			}
			memo.clear();
		} else {
			nonzero[cur] += zero[cur];
			memo.insert(cur);
		}
	}

	if(k == 0) {
		rep(tar, 1, all) ans += nonzero[tar];
		ans += TWO.power(seg - 1);
	} else {
		ans += zero[k];
	}

	cout << ans << endl;

	return 0;
}

