  if(x!=0){
    ll tmp=0;
    vector<ll>z;
    ll f=0;
    for(ll i=0;i<n;i++){
      tmp=tmp^v[i];
      if(tmp==0&&f==1)z.push_back(0);
      if(tmp==x){
        f=1;
        z.push_back(1);
        tmp=0;
      }
    }
    vector<vector<ll> >p(2,vector<ll>(z.size(),0));
    if(z.size()==1){
      cout<<1<<endl;
      return 0;
    }
    p[0][0]=1;
    p[1][0]=1;
    for(ll i=1;i<(ll)z.size();i++){
      if(z[i]==0){
        p[0][i]=(p[0][i-1]+p[1][i-1])%MOD;
        p[1][i]=p[1][i-1]%MOD;
      }
      else{
        p[0][i]=(p[0][i-1]+p[1][i-1])%MOD;
        p[1][i]=p[0][i-1]%MOD;
      }
    }
    ans=p[1][z.size()-1];
    cout<<ans<<endl;
  }
  else{
    ll tmp=0;
    vector<ll>z;
    for(ll i=0;i<n;i++){
      tmp=tmp^v[i];
      if(tmp==0)z.push_back(0);
    }
    vector<vector<ll> >p(2,vector<ll>(z.size(),0));
    if(z.size()==1){
      ans+=1;
    }
    else if(z.size()==2){
      ans+=3;
    }
    else{
      p[0][0]=1;
      p[1][0]=1;
      for(ll i=1;i<(ll)z.size();i++){
        p[0][i]=(p[0][i-1]+p[1][i-1])%MOD;
        p[1][i]=(p[0][i-1]+p[1][i-1])%MOD;
      }
      ans+=p[1][z.size()-1];
    }

    map<ll,vector<ll>>mp;
    map<ll,ll>mp2;
    set<ll>st;
    tmp=0;
    ll zz=0;
    for(ll i=0;i<n;i++){
      tmp=tmp^v[i];
      if(tmp==0){
        for(auto itr = st.begin(); itr != st.end(); ++itr){
          mp[*itr].push_back(zz+mp2[*itr]);
        }
        st.clear();
        zz++;
      }
      else{
        if(st.count(tmp)){}
        else mp[tmp].push_back(zz+mp2[tmp]);
        mp2[tmp]++;
        st.insert(tmp);
      }
    }
    for(auto itr = mp.begin(); itr != mp.end(); ++itr){
      z=(itr->second);
      if(z.size()==1){
        ans=(ans+1)%MOD;
        ans%=MOD;
        continue;
      }
      ll p0=1;
      ll p1=1;
      ll pp0,pp1;
      for(ll i=1;i<(ll)z.size();i++){
        pp0=(p0+(z[i]-z[i-1])*p1%MOD)%MOD;
        pp1=(p0+(z[i]-z[i-1]-1)*p1%MOD)%MOD;
        p0=pp0;
        p1=pp1;
      }
      ans=(ans+p1)%MOD;
    }
    cout<<ans<<endl;
  }
}

