int main(void) {
  long N;
  cin >> N;
  vector<long> a(N);
  rep (i, N) cin >> a[i];

  vector<long> ruiseki(N+1, 0);
  rep (i, N) {
    ruiseki[i+1] = (ruiseki[i] ^ a[i]);
  }
  // rep (i, N+1) cerr << ruiseki[i] << endl;

  // 最後に切れ目を入れた位置 / 美しさ / 個数
  map<pair<long, long>, long> mp;

  mp[make_pair(0, 0)] = 1;

  long result = 0;

  for (long i = 1; i < N+1; i++) {
    auto next_mp = mp;
    for (auto it: mp) {
      long last = it.first.first;
      long beauty = it.first.second;
      long num = it.second;
      if (last == 0) {
        next_mp[make_pair(i, ruiseki[i])] += num;
        next_mp[make_pair(i, ruiseki[i])] %= MOD;
        //cerr << "last: " << last << ", beauty: " << ruiseki[i] << ", num: " << num << ", i: " << i << endl;
        if (i == N) {
          result += num;
          result %= MOD;
        }
        continue;
      }
      if (beauty != (ruiseki[i] ^ ruiseki[last])) continue;
      next_mp[make_pair(i, beauty)] += num;
      next_mp[make_pair(i, beauty)] %= MOD;
      //cerr << "last: " << last << ", beauty: " << beauty << ", num: " << num << ", i: " << i << endl;
      if (i == N) {
        result += num;
        result %= MOD;
      }
    }
    mp = next_mp;
  }

