void solve(){
  ll XOR = 0;
  ll cnt = 0;
  rep(i, N) XOR ^= A[i];
  if(XOR == 0){
    ll x = 0;
    vector<ll> B;
    ll now = 0;
    rep(i, N){
      now ^= A[i];
      B.pb(now);
      if(now == 0){
        add(i, 1);
        cnt++;
      }
    }
    ll X = *max_element(B.begin(), B.end());
    vector<ll> L[X+1];
    rep(i, N){
      if(B[i] == 0) continue;
      L[B[i]].pb(i);
