struct RangeSum {
  using T = vector<vector<Modint<>>>;
  T operator()(const T &a, const T &b) {
    vector<vector<Modint<>>> ret(2, vector<Modint<>>(2));
    for (int i = 0; i < 2; ++i) {
      for (int j = 0; j < 2; ++j) {
        for (int k = 0; k < 2; ++k) {
          ret[i][j] += b[i][k] * a[k][j];
        }
      }
    }
    return ret;
  }
  static T id() { return T{{Modint<>(1), Modint<>(0)}, {Modint<>(0), Modint<>(1)}}; };
};

