const Int MOD = 1000000007;
Int modpow(Int x, Int y) {
    if (y == 0) return 1;
    if (y % 2 == 0) return modpow(x * x % MOD, y / 2);
    return x * modpow(x, y - 1) % MOD;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N; cin >> N;
    vector<int> A(N); for (auto &a : A) cin >> a;
    vector<int> S(N + 1); for (int i = 0; i < N; i++) S[i + 1] = S[i] ^ A[i];
    vector<int> Z(N + 1); for (int i = 0; i < N; i++) Z[i + 1] = Z[i] + (S[i + 1] == 0);
    vector<int> prev(N + 1);
    map<int, int> M;
    for (int i = 0; i <= N; i++) {
        prev[i] = M[S[i]];
        M[S[i]] = i;
    }
    auto f = [&](int i, bool sum) {
        vector<Int> A;
        for (;;) {
            A.push_back(i);
            i = prev[i];
            if (i == 0) break;
        }
        reverse(begin(A), end(A));
        vector<Int> B(A.size()), C(A.size());
        B[0] = C[0] = 1;
        for (int i = 1; i < A.size(); i++) {
            B[i] = C[i - 1] * (Z[A[i]] - Z[A[i - 1]]) + B[i - 1];
            B[i] %= MOD;
            C[i] += C[i - 1] + B[i];
            C[i] %= MOD;
        }
        if (!sum) return B.back();
        else return accumulate(begin(B), end(B), 0LL) % MOD;
    };
    Int ans = 0;
    if (S[N] != 0) {
        ans = f(N, false);
    } else {
        ans = modpow(2, Z[N] - 1);
        for (auto &p : M) if (p.first != 0) ans = (ans + f(p.second, true)) % MOD;
    }
    cout << ans << endl;
    return 0;
}

