        while (j < w[i].size())
        {
            int cnt = 1;
            while (j < w[i].size() && reiwa[w[i][j + 1]] - reiwa[w[i][j]] == 0)
            {
                cnt++;
                j++;
            }
            if (j == w[i].size())
                j--;
            p.push_back(cnt);

            if (j == w[i].size() - 1)
                p.push_back(1);
            else
                p.push_back(reiwa[w[i][j + 1]] - reiwa[w[i][j]]);

            j++;
        }

        ll dp[2][2];

        auto cur = dp[0];
        auto nex = dp[1];

        cur[0] = 1;
        cur[1] = 0;

        for (int j = 1; j < p.size(); j++)
        {
            nex[0] = j == p.size() - 1 ? 0 : cur[0];
            nex[1] = cur[1];

            if (j % 2)
                (nex[1] += cur[0] * p[j]) %= MOD;
            else
                (nex[0] += cur[1] * p[j]) %= MOD;

            swap(cur, nex);
        }

        (res += cur[0]) %= MOD;
    }

    (res += fastPow(2, reiwa[v.size()] - 2)) %= MOD;

    cout << res << endl;

    return 0;
}

