int cnt[max_n];
int dp[max_n][2];
int solve(int x)
{
    dp[0][0]=1;dp[0][1]=1;
    for(int i=1;i<v[x].size();i++)
    {
        int c=cnt[v[x][i]-1]-cnt[v[x][i-1]];
        dp[i][0]=Add(dp[i-1][0],1ll*c*dp[i-1][1]%mod);
        dp[i][1]=Add(dp[i-1][1],dp[i][0]);
    }
    return dp[v[x].size()-1][1];
}
