T power(T x,T n,long long MOD = MOD){
    T ret = 1;
    while(n>0){
        if(n%2==1) ret*=x;
        n/=2,x*=x;
        if(MOD!=0) x%=MOD,ret%=MOD;
    }
    return ret;
}
