int main() {
    int n;
    constexpr i64 mod = 1000000007;
    std::cin >> n;
    std::vector<int> s(n + 1), prev(n + 1), z(n + 1);
    std::map<int, int> pos;
    for (int i = 1; i <= n; i++) {
        int in;
        std::cin >> in;
        s[i] = s[i - 1] ^ in;
        z[i] = z[i - 1] + !s[i];
        prev[i] = pos[s[i]];
        pos[s[i]] = i;
    }
    i64 ret = 0;

    if (s[n] == 0) {
        ret = 1;
        for (int i = 1; i < z[n]; i++) ret = ret * 2ll % mod;
    }

    // std::cerr << ret << std::endl;
    // for (int i = 1; i <= n; i++) std::cerr << s[i] << " ";
    // std::cerr << std::endl;

    std::map<int, i64> t, p;
    for (int i = 1; i <= n; i++) {
        if (s[i] == 0) {
            if (s[n] > 0) ret = (ret + p[s[n]]) % mod;
            continue;
        }

        if (t[s[i]]) t[s[i]] = (t[s[i]] + p[s[i]] * (z[i] - z[prev[i]]) % mod) % mod;
        else t[s[i]] = 1;

        if (s[n] == 0) ret = (ret + t[s[i]]) % mod;
        p[s[i]] = (p[s[i]] + t[s[i]]) % mod;
    }
    std::cout << (ret + (s[n] > 0)) << std::endl;

    return 0;
}

