//x^nをmodのもとで計算する
ll mod_pow(ll x, ll n, ll mod) {
  if (n == 0) return 1;
  ll res = mod_pow((x*x) % mod, n/2, mod);
  if (n & 1) res = (res*x) % mod;
  return res;
}

int main() {
  std::ios::sync_with_stdio(false);std::cin.tie(0);

  cin >> N;
  rep(i, 1, N) cin >> A[i];

  rep(i, 1, N) {
    B[i] = B[i-1] ^ A[i];
  }

  ll ans = 0;
  if (B[N] != 0) {
    int X = B[N];
    dp[1] = 1;
    for (int i = N-1; i >= 0; --i) {
      if (B[i] == 0) {
        dp[0] = mod(dp[0]+dp[1], MOD);
      }
      if (B[i] == X) {
        dp[1] = mod(dp[0]+dp[1], MOD);
      }
    }
    ans = dp[1];
  } else {
    vector<Pii> vp;
    acum[0] = 1;
    for (int i = 1; i <= N; ++i) {
      if (B[i] != 0) {
        vp.push_back(Pii(B[i], i));
        acum[i] = acum[i-1];
      } else {
        acum[i] = acum[i-1] + 1;
      }
    }
    sort(all(vp));

    for (int i = 0; i < len(vp); ++i) {
      vector<int> v;
