      while (i+1 < len(vp) && vp[i].fi == vp[i+1].fi) {
        v.push_back(vp[i+1].sc);
        ++i;
      }

      dp[0] = 1; dp[1] = 0;
      for (int j = len(v)-1; j >= 0; --j) {
        dp[1] = mod(dp[1]+dp[0], MOD);
        ll lb = (j == 0 ? 0 : v[j-1]);
        ll ub = v[j];
        ll zeroNum = acum[ub] - acum[lb];
        dp[0] = mod(dp[0] + dp[1]*zeroNum, MOD);
      }

      ans = mod(ans+dp[1], MOD);
    }

    ans += mod_pow(2, acum[N]-2, MOD);
  }


  cout << mod(ans, MOD) << endl;

  return 0;
}

