int prefix[500005];
int zerosum[500005]; // number of zeroes <= index
vector<int> found[1 << 20];
const int MOD = 1000000007;
int n;

ll solve(int xorAmt, bool wantZero) {
  assert(found[xorAmt].size());
  ll zeros = 1;
  ll other = 1;
  for(int i = 1; i < found[xorAmt].size(); i++) {
    int zeroInbetween = zerosum[found[xorAmt][i]] - zerosum[found[xorAmt][i-1]];
    zeros += other * zeroInbetween;
    zeros %= MOD;
    other += zeros;
    other %= MOD;
  }
  if(wantZero) return zeros;
  else return other;
}

void solve() {
  cin >> n;
  for(int i = 1; i <= n; i++) {
    cin >> prefix[i];
    prefix[i] ^= prefix[i-1];
    zerosum[i] = zerosum[i-1];
    if(prefix[i] == 0) zerosum[i]++;
    else found[prefix[i]].push_back(i);
  }
  ll ret = 0;
  if(prefix[n] != 0) {
    ret += solve(prefix[n], true);
  }
  else {
    int amt = zerosum[n]-1;
    {
      ll curr = 1;
      while(amt--) {
        curr *= 2;
        curr %= MOD;
      }
      ret += curr;
    }
    for(int i = 1; i < (1<<20); i++) {
      if(found[i].size()) ret += solve(i, false);
    }
  }
  cout << ret << "\n";
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  solve();
}

