MInt Zero() {
	int cnt = 0;
	REP(i, 1, N + 1) {
		if (P[i] == 0) {
			++cnt;
		}
	}
	return 2_m[cnt - 1];
}
MInt Sub(int K, bool bs) {
	MInt DP = 0;
	MInt G = 0;
	MInt P = 0;
	REP(w, 0, st[K].size()) {
		int p = st[K][w];
		DP = Q[p] * P - G + 1;
		P += DP;
		G += DP * Q[p];
	}
	return bs ? P : DP;
}

