int expo(int b, int p) {
    if (p == 0) return 1;
    if (p == 1) return b;

    int x = expo(b, p/2);
    x = (int) (((ll)x*x) % mod);
    if (p&1) x = (int) (((ll)x*b) % mod);
    return x;
}

