const int mod=1000000007,MAX=(1<<20)+3,INF=1<<28;
vector<pair<int,int>> G[MAX];//firstのタイミングでsecond個
int cnt0[MAX];

ll rui(ll a,ll b){
    ll ans=1;
    while(b>0){
        if(b&1) ans=ans*a%mod;
        a=a*a%mod;
        b/=2;
    }
    return ans;
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;cin>>N;
    vector<int> A(N+1);
    for(int i=0;i<N;i++){
        cin>>A[i+1];
        A[i+1]^=A[i];
        cnt0[i+1]=cnt0[i];

        if(A[i+1]==0){
            cnt0[i+1]++;
        }else{
            if(G[A[i+1]].size()==0) G[A[i+1]].push_back({i+1,1});
            else{
                G[A[i+1]].push_back({-1,cnt0[i+1]-cnt0[G[A[i+1]].back().first]});
                G[A[i+1]].push_back({i+1,1});
            }
        }
    }

    if(A[N]!=0){
        int X=A[N];

        vector<vector<ll>> dp(G[X].size()+1,vector<ll>(2));
        dp[0][0]=1;

        for(int i=1;i<=G[X].size();i++){
            if(G[X][i-1].first!=-1){
                dp[i][0]=dp[i-1][0];
                dp[i][1]=dp[i-1][0]+dp[i-1][1];
            }else{
                dp[i][0]=dp[i-1][0]+dp[i-1][1]*G[X][i-1].second;
                dp[i][1]=dp[i-1][1];

                if(G[X][i-1].second==0) dp[i][0]=0;
            }

            dp[i][0]%=mod;
            dp[i][1]%=mod;
        }

        cout<<dp[G[X].size()][1]<<endl;
    }else{
        ll ans=0;
        ans+=rui(2,cnt0[N]-1);

        for(int X=1;X<(1<<20);X++){
            if(G[X].size()==0) continue;

            vector<vector<ll>> dp(G[X].size()+1,vector<ll>(2));
            dp[0][0]=1;

            for(int i=1;i<=G[X].size();i++){
                if(G[X][i-1].first!=-1){
                    dp[i][0]=dp[i-1][0];
                    dp[i][1]=dp[i-1][0]+dp[i-1][1];
                }else{
                    dp[i][0]=dp[i-1][0]+dp[i-1][1]*G[X][i-1].second;
                    dp[i][1]=dp[i-1][1];
                }

                dp[i][0]%=mod;
                dp[i][1]%=mod;
            }

            ans+=dp[G[X].size()][1];
            ans%=mod;
        }

        cout<<ans<<endl;
    }
}

