#define FOR(k,m,n) for(ll (k)=(m);(k)<(n);(k)++)
#define REP(i,n) FOR((i),0,(n))
#define WAITING(str) int str;std::cin>>str;
#define DEBUGING(str) cout<< #str << " " str<<endl

constexpr int INF = (1 << 30);
constexpr ll INFL = (1ll << 60);
constexpr ll MOD = 1000000007;// 10^9+7



int main()
{
	int n;
	cin >> n;
	vector<ll> a(n);
	REP(i, n)cin >> a[i];
	REP(i, n - 1)a[i + 1] ^= a[i];
	if (a.back() != 0) {
		cout << 1 << endl;
		return 0;
	}

	vector<ll> len;
	map<ll, map<ll, ll>> mmp;
	ll bef = -1;
	REP(i, n) {
		if (a[i] == 0) {
			len.push_back(i - bef);
			bef = i;
		}
		mmp[a[i]][len.size()]++;
	}

	// 0-way
	ll res = 1;
	REP(i, (ll)len.size() - 1)res = (res * 2) % MOD;

	// some-way
	for (auto itr = mmp.begin(); itr != mmp.end(); ++itr) {
		if (itr->first == 0)continue;
		vector<pair<ll, ll>> way;
		for (auto itr2 = itr->second.begin(); itr2 != itr->second.end(); ++itr2) {
			way.push_back({ itr2->first,itr2->second });
		}
		vector<ll> tres;
		auto start = way.front();

		// 自分より前の場所より流入する有効辺の最寄と本数と場合数
		ll now = start.first;
		ll edge = start.second;
		ll how = edge;
		tres.push_back(edge);

		FOR(i, 1, way.size()) {
			ll dist = way[i].first - way[i - 1].first;
			how += edge * (dist - 1); // feed
			how++;              // new in
			edge++;             // new in
			how %= MOD;
			edge %= MOD;

			how *= way[i].second; // duplicate
			edge *= way[i].second; // duplicate
			how %= MOD;
			edge %= MOD;
			tres.push_back(how);
		}

		//cerr << "tmp" << endl;
		// 各ノードから、最後まで一直線
		ll tsum = 0;
		for (auto num : tres) {
			tsum = (tsum + num) % MOD;
		}
		res += tsum;
	}
	cout << res << endl;
	return 0;
}

