class SEGTREE {
	public:
	int n;
	vector<int> st, en; vector<LL> sum, lazy;
	SEGTREE(){}
	SEGTREE(int _n) {
		n = 1 << (int)ceil(log2(_n)); int nb = n << 1;
		st.assign(nb, 0); en.assign(nb, 0);
		sum.assign(nb, 0); lazy.assign(nb, 0);
		build(1, 1, n);
	}
	inline LL value(int i) { return (sum[i] + lazy[i] * (en[i] - st[i] + 1)) %MOD; }
	inline void updateUP(int i) { sum[i] = (value(i << 1) + value(i << 1 | 1)) %MOD; }
	inline void propagateDOWN(int i) {
		lazy[i << 1] = (lazy[i << 1]+lazy[i]) %MOD;
		lazy[i << 1 | 1] = (lazy[i << 1 | 1]+lazy[i]) %MOD;
		lazy[i] = 0;
	}
	inline void build(int i, int start, int end) {
		st[i] = start, en[i] = end, lazy[i] = 0;
		if (start == end) { sum[i] = 0; return; }
		int mid = (start + end) >> 1;
		build(i << 1, start, mid); build(i << 1 | 1, mid + 1, end);
		updateUP(i);
	}
	inline LL query(const int& qL, const int& qR, int i = 1) {
		if (en[i] < qL || qR < st[i]) return 0;
		if (qL <= st[i] && en[i] <= qR) return value(i);
		propagateDOWN(i);
		LL ans = (query(qL,qR,i << 1) + query(qL,qR,i << 1 | 1)) %MOD;
		updateUP(i);
		return ans;
	}
	inline void add(const int& qL,const int& qR,const int& qVal,int i = 1) {
		if (en[i] < qL || qR < st[i]) return;
		if (qL <= st[i] && en[i] <= qR) { lazy[i] = (lazy[i]+qVal) %MOD; return; }
		propagateDOWN(i);
		add(qL,qR,qVal,i << 1);
		add(qL,qR,qVal,(i << 1) | 1);
		updateUP(i);
	}
};

