				ll pr1 = dp[0], pr2 = dp[1];
				if (cur == 0) {
					dp[1] = pr2 + pr1;
					dp[0] = pr2;
					pr = 0;
				}
				else {
					dp[0] = pr1 + pr2 * cur;
				}
			}

			ans += dp[1];
			ans %= MOD;
		}

		return ans;
	}
	else {
		ll curX = 0, cnt = 0, cnt2 = 0;
		vector<ll> vals;
		for (int i = 0; i < n; i++) {
			curX ^= vec[i];
			if (curX == 0) {
				cnt2++;
				vals.push_back(0);
			}
			else if (curX == x) {
				cnt++;
				vals.push_back(1);
				curX = 0;
			}
		}

		ll dp[2];
		dp[0] = 1;
		dp[1] = 0;
		ll pr = 0;
		for (auto cur : vals) {
			ll pr1 = dp[0], pr2 = dp[1];
			if (cur == 0) {
				dp[0] = pr1 + pr2;
			}
			else {
				dp[1] = pr2 + pr1;
				dp[0] = pr2;
				pr = 0;
			}
			dp[0] %= MOD;
			dp[1] %= MOD;
		}

		return dp[1];
	}
}

