    if(b.back() == 0){
        for(const auto& p : dp2){
            ans += p.second;
            ans %= MOD;
        }
    }
    else{
        ans += dp2[b.back()];
        ans -= count(b.begin(), b.end(), b.back()) - MOD;
        ans %= MOD;
    }
