    map<ll,ll> M;
    M[0]=1;
    for(auto &I:a){
        cin>>I;
        sum^=I;
        M[sum]++;
    }
    ll ans=0;
    if(sum!=0){
        pll dp(0,1);
        ll z=0;
        for(int i=0;i<n;i++){
            z^=a[i];
            if(z==0){
                dp.S+=dp.F;
                dp.S%=MOD;
            }
            else if(z==sum){
                dp.F+=dp.S;
                dp.F%=MOD;
            }
        }
        ans=dp.S;
    }
    else{
        ans+=C.mod_pow(2,M[0]-2);
        map<ll,pll> M;
        sum=0;
        ll cnt0=0;
        map<ll,ll> bef;
        cnt0++;
        for(auto &I:a){
            sum^=I;
            if(sum==0){cnt0++; continue;}
            if(M.count(sum)==0){
                M[sum]={1,1};
                bef[sum]=cnt0;
                continue;
            }
            else{
                auto I=M.find(sum);
                I->second.S+=(cnt0-bef[sum])*I->S.F%MOD;
                I->second.S%=MOD;
                I->S.F+=I->S.S;
                I->S.F%=MOD;
                bef[sum]=cnt0;
            }
        }
        for(auto I=M.begin();I!=M.end();++I){
            ans+=I->S.F;
            ans%=MOD;
        }
    }
    ans%=MOD;
    if(ans<0){ans+=MOD;}
    cout<<ans<<endl;


    return 0;
}

