class MyPow {
  private:
  typedef long long ll;
  std::unordered_map<ll, ll> memo;
  ll a;

  public:
  ll MOD = LLONG_MAX;

  MyPow ( ll a_ ) : a(a_) {
    memo[0] = 1 % MOD;
    memo[1] = a % MOD;
  }

  ll power ( ll p ) {
    if ( memo.count(p) != 0 ) return memo[p];
    return memo[p] = ((power(p/2)%MOD) * (power(p-p/2)%MOD)) % MOD;
  }
};


ll do_dp ( int X ) {
  std::vector<std::unordered_map<int,ll>> dp(N+1);
  for(int i=0; i<N+1; i++) {
    dp[i][0] = 0;
    dp[i][X] = 0;
  }

  dp[0][0] = 1;
  dp[0][X] = 0;
  for(int i=1; i<=N; i++){
    if ( i == N ) {
      if ( B[i] == 0 ) {
        dp[i][0] = dp[i-1][X];
        dp[i][X] = dp[i-1][X];
      }
      else if ( B[i] == X ) {
        dp[i][X] = dp[i-1][0];
        dp[i][0] = dp[i-1][0];
      }
      continue;
    }
    if ( B[i] == 0 ) {
      dp[i][0] = dp[i-1][0] + dp[i-1][X];
      dp[i][X] = dp[i-1][X];
    }
    else if ( B[i] == X ) {
      dp[i][X] = dp[i-1][0] + dp[i-1][X];
      dp[i][0] = dp[i-1][0];
    }
    else {
      dp[i][X] = dp[i-1][X];
      dp[i][0] = dp[i-1][0];
    }
  }

  return dp[N][B[N]];
}

constexpr ll mod = 1000000007;

int main (void) {
  std::cin >> N;

  A.resize(N);
