  std::set<int> S;
  for(int i=0; i<=N; i++) S.insert(B[i]);

  if ( B[N] != 0 ) std::cout << do_dp(B[N]) << std::endl;
  else {
    ll ans = 0;
    for(auto itr = S.begin(); itr != S.end(); ++itr){
      if ( *itr != 0 ) {
        ans += (do_dp(*itr) % mod) ;
        ans %= mod;
      }
      else {
        int count = 0;
        for(int i=0; i<=N; i++) if ( B[i] == 0 ) count++;
        MyPow p(2); p.MOD = mod;
        ans += p.power(count-2);
        ans %= mod;
      }
    }
    std::cout << ans << std::endl;
  }
  return 0;
}

