template <int MOD>
class ModInt {
    using lint = long long;

public:
    int val;

    // constructor
    ModInt(lint v = 0) : val(v % MOD) {
        if (val < 0) val += MOD;
    };

    // assignment
    ModInt& operator=(const ModInt& x) {
        if (this != &x) { this->val = x.val; }
        return *this;
    }

    // unary operator
    ModInt operator+() const { return ModInt(val); }
    ModInt operator-() const { return ModInt(MOD - val); }
    ModInt operator~() const { return *this ^ (MOD - 2); }

    // increment / decrement
    ModInt& operator++() { return *this += 1; }
    ModInt& operator--() { return *this -= 1; }
    ModInt operator++(int) {
        ModInt before = *this;
        ++(*this);
        return before;
    }
    ModInt operator--(int) {
        ModInt before = *this;
        --(*this);
        return before;
    }

    // arithmetic
    ModInt operator+(const ModInt& x) const { return ModInt(*this) += x; }
    ModInt operator-(const ModInt& x) const { return ModInt(*this) -= x; }
    ModInt operator*(const ModInt& x) const { return ModInt(*this) *= x; }
    ModInt operator%(const ModInt& x) const { return ModInt(*this) %= x; }
    ModInt operator/(const ModInt& x) const { return ModInt(*this) /= x; }
    ModInt operator^(const ModInt& x) const { return ModInt(*this) ^= x; }

    // compound assignment
    ModInt& operator+=(const ModInt& x) {
        if ((val += x.val) >= MOD) val -= MOD;
        return *this;
    }
    ModInt& operator-=(const ModInt& x) {
        if ((val -= x.val) < 0) val += MOD;
        return *this;
    }
    ModInt& operator*=(const ModInt& x) {
        val = lint(val) * x.val % MOD;
        return *this;
    }
    ModInt& operator%=(const ModInt& x) {
        val %= x.val;
        return *this;
    }
    ModInt& operator/=(const ModInt& x) { return *this *= ~x; }
    ModInt& operator^=(const ModInt& x) {
        int n = x.val;
        ModInt b = *this;
        if (n < 0) n = -n, b = ~b;

        *this = 1;
        while (n > 0) {
            if (n & 1) *this *= b;
            n >>= 1;
            b *= b;
        }
        return *this;
    }

    // compare
    bool operator==(const ModInt& b) const { return val == int(b); }
    bool operator!=(const ModInt& b) const { return val != int(b); }
    bool operator<(const ModInt& b) const { return val < int(b); }
    bool operator<=(const ModInt& b) const { return val <= int(b); }
    bool operator>(const ModInt& b) const { return val > int(b); }
    bool operator>=(const ModInt& b) const { return val >= int(b); }

    // I/O
    friend std::ostream& operator<<(std::ostream& os, const ModInt& x) noexcept { return os << x.val; }
    friend std::istream& operator>>(std::istream& is, ModInt& x) noexcept { return is >> x.val; }
};

using mint = ModInt<1000000007>;
using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> S(N + 1);
    S[0] = 0;
    for (int i = 1; i <= N; ++i) {
        int A;
        cin >> A;
        S[i] = S[i - 1] ^ A;
    }

    mint ans = 0;
    if (S.back() != 0) {
        vector<vector<mint>> dp(N, vector<mint>(2, 0));
        // dp[i][b] = S[i]まで見た時点で、(b ? 0 : X)にいる

        dp[0][0] = 1;
        for (int i = 1; i < N; ++i) {
            for (int j = 0; j < 2; ++j) dp[i][j] = dp[i - 1][j];

            if (S[i] == S[N]) dp[i][1] += dp[i - 1][0];
            if (S[i] == 0) dp[i][0] += dp[i - 1][1];
        }

        ans = dp[N - 1][0];  // 一番最後に0->Xの遷移をする

    } else {
        mint zero = 0;

        vector<vector<mint>> cnt(1 << 20);
        // cnt[i] = Sに出現する各iについて、それより前にある0の数
        for (int i = 1; i <= N; ++i) {
            if (S[i] != 0) {
                cnt[S[i]].push_back(zero);
            } else {
                ++zero;
            }
        }

        ans = mint(2) ^ (zero - 1);  // X = 0

        for (int n = 1; n < (1 << 20); ++n) {
            if (cnt[n].empty()) continue;

            vector<mint> dp(2, 1);
            // dp[b] = i個目のXまで見たときに、(b ? 0 : X)にいる

            for (int i = 1; i < cnt[n].size(); ++i) {
                mint z = cnt[n][i] - cnt[n][i - 1];  // 間にある0の数

                dp[0] += dp[1] * z;  // X -> 0
                dp[1] += dp[0];      // 0 -> X
            }
            ans += dp[1];
        }
    }

    cout << ans << endl;
    return 0;
}

