    int sum = 0;
    for(int i = 0; i < N; i++){
        int a;
        scanf("%d", &a);
        sum ^= a;
        index[sum].push_back(i + 1);
        zero_sum[i + 1] = zero_sum[i] + (sum == 0);
    }
    vector<vector<int>> sums(1 << 20);
    for(int i = 1; i < (1 << 20); i++){
        if(index[i].empty()){
            continue;
        }
        for(int j = 1; j < index[i].size(); j++){
            sums[i].push_back(zero_sum[index[i][j]] - zero_sum[index[i][j - 1]]);
        }
    }
    if(sum == 0){
        lint ans = 0;
        for(int i = 1; i < (1 << 20); i++){
