            lint dp_sum = 0, dp_sum_sum = 0;
            for(int i = sz - 1; i >= 0; i--){
                dp_sum_sum = (dp_sum_sum + dp_sum * data[i] % mod) % mod;
                dp_sum = (dp_sum + dp_sum_sum + 1) % mod;
