}

template <typename T = ll>
struct SegmentTreeLazyAdd {
  private:
    using F = function<T(T, T)>;
    int n;
    vector<T> node, lazy;
    vector<bool> lazyFlag;
    F func;
    T UNIT;

  public:
    SegmentTreeLazyAdd(int sz, F func, T UNIT) : func(func), UNIT(UNIT) {
        n = 1;
        while (n < sz)
            n *= 2;
        node.assign(2 * n - 1, UNIT);
        lazy.assign(2 * n - 1, UNIT);
        lazyFlag.resize(2 * n - 1, false);
    }
    SegmentTreeLazyAdd(vector<T> v, F func, T UNIT) : func(func), UNIT(UNIT) {
        int sz = int(v.size());
        n      = 1;
        while (n < sz)
            n *= 2;
        node.resize(2 * n - 1, UNIT);
        lazy.resize(2 * n - 1, UNIT);
        lazyFlag.resize(2 * n - 1, false);

        for (int i = 0; i < sz; i++)
            node[i + n - 1] = v[i];
        for (int i = n - 2; i >= 0; i--)
            node[i] = func(node[i * 2 + 1], node[i * 2 + 2]);
    }
    void lazyEvaluate(int k, int l, int r) {
        if (lazyFlag[k]) {
            node[k] += lazy[k];
            if (r - l > 1) {
                lazy[k * 2 + 1] += lazy[k];
                lazy[k * 2 + 2] += lazy[k];
                lazyFlag[k * 2 + 1] = lazyFlag[k * 2 + 2] = true;
            }
            lazyFlag[k] = false;
            lazy[k]     = 0;
        }
    }
    // add x to nodes in [a, b)
    void add(int a, int b, T x, int k = 0, int l = 0, int r = -1) {
        if (r < 0)
            r = n;
        lazyEvaluate(k, l, r);
        if (b <= l || r <= a) {
            return;
        }
        if (a <= l && r <= b) {
            lazy[k] += x; // +=
            lazyFlag[k] = true;
            lazyEvaluate(k, l, r);
            return;
        } else {
            const int mid = (l + r) / 2;
            add(a, b, x, k * 2 + 1, l, mid);
            add(a, b, x, k * 2 + 2, mid, r);
            node[k] = func(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    void update(int k, T a) {
        query(k, k + 1); // probagate lazy nodes
        // leaves are at index n-1 to 2*n-2
        k += n - 1;
        node[k] = a;
        while (k > 0) {
            // k -> parent node
            k = (k - 1) / 2;
            // func(child nodes)
            node[k] = func(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    // get func() in [a, b)
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0)
            r = n;
        lazyEvaluate(k, l, r);
        if (b <= l || r <= a)
            return UNIT;
        if (a <= l && r <= b)
            return node[k];
        T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return func(vl, vr);
    }
};

int main() {
    int n;
    cin >> n;
    deque<ll> a(n);
    ll tot = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        tot ^= a[i];
    }
    if (tot == 0) {
        int na = a.size();
        for (int i = 1; i < na; ++i) {
            a[i] ^= a[i - 1];
        }
        int zero = 0;
        for (int i = 0; i < na; ++i) {
            if (a[i] == 0)
                zero++;
        }
        mint ret = mint(2).pow(zero - 1);
        vector<ll> pos(1 << 21, 0);
        vector<ll> zeros(1 << 21, 1);
        ll UNIT = 0;
        auto f  = [](ll l, ll r) { return l + r; };
        SegmentTreeLazyAdd<ll> seg(1 << 21, f, UNIT);
        for (int i = 0; i < na - 1; ++i) {
            if (a[i] == 0) {
                seg.add(0, 1 << 21, 1);
            } else {
                if (pos[a[i]] == 0) {
                    pos[a[i]] = 1;
                    seg.update(a[i], 0);
                } else {
                    zeros[a[i]] += seg.query(a[i], a[i] + 1) * pos[a[i]];
                    seg.update(a[i], 0);
                    pos[a[i]] += zeros[a[i]];
                }
            }
        }
        for (auto &p : pos) {
            ret += p;
        }
        cout << ret << "\n";
    } else {
        while (a.front() == 0)
            a.pop_front();
        while (a.back() == 0)
            a.pop_back();
        a.push_front(0);
        mint pos  = 0;
        mint zero = 1;
        int na    = a.size();
        for (int i = 1; i < na; ++i) {
            a[i] ^= a[i - 1];
        }
        for (int i = 1; i < na - 1; ++i) {
            if (a[i] == tot) {
                pos += zero;
            } else if (a[i] == 0) {
                zero += pos;
            }
        }
        cout << zero << "\n";
    }

    return 0;
}

