const lint MOD = 1e9 + 7;

lint power(lint n, lint p) {
    lint res = 1;
    while (p > 0) {
        if (p % 2 == 1) {
            res = res * n % MOD;
        }
        n = n * n % MOD;
        p /= 2;
    }
    return res;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n + 1), zero(n + 1);
    map<int, vector<int>> num;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        a[i] ^= a[i - 1];
        zero[i] = zero[i - 1];
        if (a[i] == 0) {
            zero[i]++;
        } else {
            num[a[i]].push_back(i);
        }
    }

    lint ans = 0;
    if (a[n] == 0) {
        ans = power(2, zero[n] - 1);
    }

    for (auto p: num) {
        int val = p.first;
        if (a[n] == val or a[n] == 0) {
            auto vec = p.second;
            int m = vec.size();

            vector<lint> dp(m), dp_cum(m);
            // dp[i]: 最後 vec[i] を踏んで終わっている
            // dp_cum[i]: 最後 vec[i] までのどこかを踏んで終わっている
            dp[0] = 1;
            dp_cum[0] = 1;
            for (int i = 1; i < m; i++) {
                int z = zero[vec[i]] - zero[vec[i - 1] - 1];
                if (z > 0) {
                    dp[i] = (dp_cum[i - 1] * lint(z) % MOD + 1) % MOD;
                } else {
                    dp[i] = dp[i - 1];
                }
                dp_cum[i] = (dp[i] + dp_cum[i - 1]) % MOD;
            }
            if (a[n] == 0) {
                ans = (ans + dp_cum[m - 1]) % MOD;
            } else {
                ans = (ans + dp[m - 1]) % MOD;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

