    if (acc[n] != 0) {
	// even # of dividers
	// alternating parity of indices
	vector<int> v;
	for (int i=1; i<n; i++) {
	    if (acc[i]==0) {
		v.push_back(0);
	    }
	    if (acc[i]==acc[n]) {
		v.push_back(1);
	    }
	}

	//101010
	//even length, alternate
	vector<ll> dp(2, 0);
	dp[0] = 1;
	for (int x: v) {
	    if (x==0) {
		dp[0]=(dp[0]+dp[1])%mod;
	    } else {
		dp[1]=(dp[1]+dp[0])%mod;
	    }
	}

	out(dp[0]);
    } else {
	for (int i=1; i<n; i++) {
	    inds[acc[i]].push_back(i);
	}
	ll res = 0;
	add(res, pw(2, inds[0].size()));

	for (int x=1; x<maxn; x++) {
	    if (inds[x].empty()) {
		continue;
	    }

	    vector<int> v;
	    int len0 = inds[0].size();
	    int lenx = inds[x].size();

	    for (int i=0,j=0; i<len0 || j<lenx; ) {
		if (i==len0 && j<lenx) {
		    v.push_back(1);
		    j++;
		} else if (j==lenx && i<len0) {
		    v.push_back(0);
		    i++;
		} else if (i<len0 && j<lenx) {
		    if (inds[0][i]<inds[x][j]) {
			v.push_back(0);
			i++;
		    } else {
			v.push_back(1);
			j++;
		    }
		} else {
		    assert(false);
		}
	    }
	    add(res, solve(v));
	}
	cout<<res<<endl;
    }
    return 0;
}

