using namespace std;
long long solve(int first, int N, vector<int>& A, vector<int>& agg){
  if(first==N)
    return 1;
  if(agg[N]!=0 || agg[N]!=unit)
    return 0;
  int unit=agg[first];
  if(unit!=0){
    long long zero = 0;
    long long other = 1;
    for (int i = first+1; i < N; i++)
    {
      if(agg[i]==0){
        zero += other;
        zero %= 1000000007;
      }
      if(agg[i]==unit){
        other += zero;
        other %= 1000000007;
      }
    }
    if(agg[N]==0)
      return other;
    if(agg[N]==unit)
      return zero;
    return 0;
  }else{
    long long zero = 1;
    for (int i = first+1; i < N; i++)
    {
      if(agg[i]==0){
        zero += zero;
        zero %= 1000000007;
      }
    }
    if(agg[N]==0)
      return zero;
    return 0;
  }
}
int main(){
  int N;
  cin >> N;
  vector<int> A(N);
  for(auto& a: A)
  {
    cin >> a;
  }
  vector<int> agg(N+1);
  agg[0] = 0;
  for (int i = 0; i < N; i++)
  {
    agg[i+1] = agg[i] ^ A[i];
  }
  long long sum = 0;
  for (int i = 1;i<=N;i++){
    auto ret=solve(i, N, A, agg);
    // cout<<i<<" "<<agg[i]<<" "<<ret<<endl;
    sum += ret;
    sum %= 1000000007;
  }
  cout << sum << endl;
}

