ll bpow(ll vl, ll pw, ll md = MOD) {
	if (pw == 0) {
		return 1;
	}
	else if (pw % 2 == 1) {
		ll a = bpow(vl, pw - 1, md);
		return (a * vl) % MOD;
	}
	else {
		ll b = bpow(vl, pw / 2, md);
		return (b * b) % MOD;
	}
}

ll sol() {
	ll x = 0, mx = 0;
