				pr = cnt[i][j];
			}
			for (auto cur : vals) {
				ll pr1 = dp[0], pr2 = dp[1];
				if (cur == 0) {
					dp[1] = pr2 + pr1;
					dp[0] = pr2;
					pr = 0;
				}
				else {
					dp[0] = pr1 + (pr2 * cur) % MOD;
				}
			}

			ans += dp[1];
