	for (int i = 0; i < n; i++) {
		int t;
		cin >> t;
		v.push_back(t);

		if (i == 0) {
			cal.push_back(1);
			even = 1;
		}
		else if (i == 1) {
			cal.push_back(1);
			odd = 1;
		}
		else {
			if (i % 2 == 0) {
				cal.push_back(odd);
				even += odd;
			}
			else {
				cal.push_back(even);
				odd += even;
			}
		}
	}
	if (n % 2 == 0) {
		cal.push_back(odd);
		even += odd;
	}
	else {
		cal.push_back(even);
		odd += even;
	}
	long long int res = 1;
	const int mod = 1000000007;
	int target = 0;
	for (int i = 0; i < n; i++) {
		target ^= v[i];
		int segment = 1;
		int temp = 0;
		int final = -1;
		int zeros = 0;
		for (int j = i + 1; j < n; j++) {
			temp ^= v[j];
			if (temp == 0)
				zeros++;
			if (temp == target) {
				temp = 0;
				final = j;
				segment++;
			}
		}
		if (final == n - 1) {
			if (target == 0) {
				cout << segment << "*" << pow(2, segment - 2) << endl;
				res += pow(2, segment - 2);
				res %= mod;
			}
			else {
				res += cal[segment - 1] * pow(2, zeros);
				cout << segment << " " << cal[segment - 1] << endl;
				res %= mod;
			}
		}
	}
	cout << res << endl;
}

