int main(){
	cin >> n;
	for(int i = 0;i < n;i++){
		cin >> a[i];
	}
	b[0] = 0;
	for(int i = 0;i < n;i++){
		b[i+1] = b[i]^a[i];
	}
	n++;
	zerob[0] = 0;
	for(int i = 0;i < n;i++){
		xat[b[i]].push_back(i);
		zerob[i+1] = zerob[i]+(b[i]==0?1:0);
	}

	ll ans = 0;
	map<int,int> fin;
	for(int i = 0;i < n;i++){
		int X = b[i];
		if(X == 0)continue;
		if(fin[X] == 1)continue;
		if(b[n-1] != 0 && b[n-1] != X)continue;
		fin[X] = 1;

		//座標圧縮パート
		vector<pair<int,int> > target;
		int index_last = 0;
		int count = 1;
		if(b[n-1] == 0)xat[X].push_back(n);//番兵
		target.push_back(make_pair(0,1));
		for(int j = 1;j < xat[X].size();j++){//座標圧縮
			int at = xat[X][j];
			int num0 = get0num(xat[X][index_last], at);
			if(num0==0){
				count++;
				continue;
			}
			target.push_back(make_pair(X,count));
			target.push_back(make_pair(0,num0));
			index_last = j;
			count = 1;
		}
		if(b[n-1] != 0)target.push_back(make_pair(X,count));

		//DPパート
		int n2 = target.size();
		dp[0][n2-1] = b[n-1]==0?0:1;
		dp[1][n2-1] = (dp[0][n2-1]+1)%2;
		for(int at = n2-2;at!=-1;at--){
			for(int before = 0;before<2;before++){
				dp[before][at] = 0;
				dp[before][at] += dp[before][at+1];
				int y = target[at].first;
				int len = target[at].second;
				if(y==0 && before==1){
					dp[before][at] += dp[0][at+1]*len%MOD;//選ぶ
				}else if(y!=0 && before==0){
					dp[before][at] += dp[1][at+1]*len%MOD;//選ぶ
				}
				dp[before][at]%=MOD;
			}
		}
		ans+=dp[0][0];
		ans%=MOD;
	}
	if(b[n-1]!=0){
		cout << ans << endl;
		return 0;
	}
	int num0 = get0num(0,n);
	ll ans0 = 1;
	for(int i = 0;i < num0-2;i++){
		ans0*=2;
		ans0%=MOD;
	}
	cout << (ans0+ans)%MOD << endl;
}

