const int SIZE=1<<20;
const ll MOD=1e9+7;
int main(){
    int n;
    cin>>n;
    vector<int> a(n);
    for(int i=0;i<n;i++) cin>>a[i];
    vector<ll> dp0(SIZE,0);
    vector<ll> dp1(SIZE,1);
    vector<int> offset(SIZE,0);
    int cnt=0;
    ll xs=0;
    for(int i=0;i+1<n;i++){
        xs^=a[i];
        if(xs==0){
            cnt++;
            ll tmp=dp0[0];
            dp0[0]+=dp1[0];
            dp0[0]%=MOD;
            dp1[0]+=tmp;
            dp1[0]%=MOD;
        }
        else{
            dp1[xs]+=dp0[xs]*(cnt-offset[xs]);
            dp1[xs]%=MOD;
            offset[xs]=cnt;
            dp0[xs]+=dp1[xs];
            dp0[xs]%=MOD;
        }
    }
    for(int i=1;i<SIZE;i++){
        dp1[i]+=dp0[i]*(cnt-offset[i])%MOD;
        dp1[i]%=MOD;
        offset[i]=cnt;                    
    }
    xs^=a[n-1];
    if(xs==0){
        ll res=accumulate(dp0.begin(),dp0.end(),0LL)+dp1[0];
        cout<<res%MOD<<endl;
    }
    else{
        cout<<dp1[xs]<<endl;
    }

    return 0;
}

#include<iostream>
using namespace std;
typedef long long ll;

ll MOD = 1000000007;
ll A[1048576];
ll C[1048576];
ll arr[1048576][2];
int zero_update[1048576];

ll power_mod(a,n){
	if(n == 0){
		return 1;
	}
	ll x = power_mod(a,n/2);
	x = x*x;
	x %= MOD;
	return (n%2 == 0 ? x : (a*x)%MOD);
}

int main(){
	int zero_cnt = 0;
	int U = 1048576;
	int N;
	cin >> N;
	for(i=0;i<N;i++){
		cin >> A[i];
		if(i == 0){
			C[i] = A[i];
		} else {
			C[i] = C[i-1] ^ A[i];
		}
	}
	for(i=0;i<U;i++){
		arr[i][0] = 1;
	}

	for(i=0;i<N;i++){
		int c = C[i];
		if(c == 0){
			zero_cnt++;
			continue;
		}
		int n = zero_cnt - zero_update[c];
		int a = arr[c][0];
		int b = arr[c][1];
		int x = a + n*b;
		int y = b;
		a = x;
		b = a+b;
		a %= MOD;
		b %= MOD;
		arr[c][0] = a;
		arr[c][1] = b;
	}
	ll answer = 0;
	int final = C[N-1];
	if(final != 0){
		answer = arr[final][0];
	} else {
		answer = 0;
		for(i=1;i<U;i++){
			answer += arr[i,1];
			answer %= MOD;
		}
		answer += power_mod(2,zero_cnt-1);
		answer %= MOD;
	}
	cout << answer << endl;
}

