const int dyx[4][2] = {
    { 0, 1}, {-1, 0}, {0,-1}, {1, 0}
};
const ll A_MAX = 1<<20;

ll modpow(ll a, ll t) {
    if(t < 0) return 0LL;
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

template<typename T>class BIT2D {
    public:
    int n, m;
    vector< vector<T> > bit;

    BIT2D(int n, int m): n(n), m(m) {
        bit.resize(n+1);
        fill(bit.begin(), bit.end(), vector<T>(m+1, 0));
    }

    void add(int y, int x, T a){
        for(int i=y;i<=n;i+=i&-i) {
            for(int j=x;j<=m;j+=j&-j) {
                bit[i][j] += a;
                if(bit[i][j] > MOD) bit[i][j] %= MOD;
            }
        }
    }

    //bit[1][1]からbit[y][x]までの和 (閉区間)
    T sum(int y, int x){
        T ret = (T)0;
        for(int i=y;i>=1;i-=i&-i) {
            for(int j=x;j>=1;j-=j&-j) {
                ret += bit[i][j];
                if(ret > MOD) ret %= MOD;
            }
        }
        return ret;
    }
};


int main() {
    std::ios::sync_with_stdio(0); cin.tie(0);
    int n, zero = 0, a;
    cin >> n;
    vector<int> b(n+1, 0);
    set<int> vs;
    for(int i=1;i<=n;++i) {
        cin >> a;
        b[i] = b[i-1] ^ a;
        if(b[i]) vs.insert(b[i]);
        else ++zero;
    }

    // for(int i=0;i<=n;++i) {
    //     cerr << b[i] <<  " ";
    // }
    // cerr << endl;

    vector<BIT2D<ll>> dp(2, BIT2D<ll>(A_MAX, n+1));
    ll ans = modpow(2, zero-1);

    for(int i=1;i<=n;++i) {
        if(b[i]) {
            dp[0].add(
                b[i], i, 
                (dp[1].sum(b[i], i-1) - dp[1].sum(b[i]-1, i-1) + 1 + MOD) % MOD
            );
        } else {
            for(ll v: vs) {
                dp[1].add(
                    v, i, 
                    (dp[0].sum(v, i-1) - dp[0].sum(v-1, i-1) + MOD) % MOD
                );
            }
        }
    }

    ans += dp[0].sum(A_MAX-1, n) - dp[0].sum(A_MAX-1, n-1) + dp[1].sum(A_MAX-1, n) - dp[1].sum(A_MAX-1, n-1) + MOD;
    ans %= MOD;

    cout << ans << endl;

}

