const int inf = 1e9;
const ll inf64 = 1e18;

const int LOG = 20;
const int X = 1 << LOG;
const int N = 5e5 + 5;
const int mod = inf + 7;

inline int _add(int &x, int y) {
    if ((x += y) >= mod) {
        x -= mod;
    }
}

inline int _sub(int &x, int y) {
    if ((x -= y) < 0) {
        x += mod;
    }
}

inline int _mul(int a, int b) {
    return (1ll * a * b) % mod;
}

int n;
int a[N];
int p[N];
vector<int> arr[X];
int pw2[N];
int cnt0[N];

int main() {

    pw2[0] = 1;
    for (int i = 1; i < N; i++) {
        pw2[i] = (2ll * pw2[i - 1]) % mod;
    }

#ifdef debug
    freopen("input.txt", "r", stdin);
#endif

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;

    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        p[i] = p[i - 1] ^ a[i];
    }

    for (int i = 0; i <= n; i++) {
        arr[p[i]].push_back(i);
    }

    for (int i = 0; i <= n + 2; i++) {
        cnt0[i] = (i ? cnt0[i - 1] : 0) + (p[i] == 0);
    }

    int res = 0;

    if (p[n] == 0) {
        int sz = (int)arr[0].size() - 2;
        _add(res, pw2[sz]);
    }

    for (int x = 1; x < X; x++) {
        if (p[n] != 0 && p[n] != x) continue;
        if (arr[x].empty()) continue;
        auto &ar = arr[x];
        int sz = (int) ar.size();
        vector<int> dp(sz);
        int sum_dp = 0;
        int sum_cnt_dp = 0;
        for (int i = 0; i < sz; i++) {
            dp[i] = 1;
            _add(dp[i], _mul(cnt0[ar[i]], sum_dp));
            _add(dp[i], sum_cnt_dp);
//            for (int j = i - 1; j >= 0; j--) {
//                _add(dp[i], _mul(cnt0[ar[i]] - cnt0[ar[j]], dp[j]));
//            }
            _add(sum_dp, dp[i]);
            _sub(sum_cnt_dp, _mul(cnt0[ar[i]], dp[i]));
        }
        if (p[n] == x) {
            _add(res, dp[sz - 1]);
        } else {
            for (int i = 0; i < sz; i++) {
                _add(res, dp[i]);
            }
        }
    }
    cout << res << "\n";

    return 0;
}

