ll comb(ll n, ll k){
  if(n<0||k<0||n<k) return 0;
  return (((fac[n]*finv[n-k])%P)*finv[k])%P;
}

void init(){
  fac[0] = finv[0] = fac[1] = finv[1] = inv[1] = 1;
  for(int i = 2; i <= N_MAX; i++){
    fac[i] = (fac[i-1]*i)%P;
    inv[i] = ((-(P/i)*inv[P%i])%P+P)%P;
    finv[i] = (finv[i-1]*inv[i])%P;
  }
}
ll pp(ll a, ll b){
  return (a * b)%P;
}

ll mpow(ll a, ll b, ll p = -1){
  ll ret = 1, num = a;
  if(p==-1){
    while(b>0){
      if(b%2) ret *= num;
      num = num * num;
      b /= 2;
    }
  }else{
    while(b>0){
      if(b%2) ret = (ret*num)%p;
      num = (num*num)%p;
      b /= 2;
    }
  }
  return ret;
}

ll solve1(vvl dat){
  ll n = dat.size();
  vll dp(n+1, 0);
  dp[0] = 1;
  for(int i=1;i<=n;i++){
    // そのまま
    ll x = (i==1?1:dat[i-1][0]-dat[i-2][0]);
    dp[i] = (dp[i] + (dp[i-1] * x)%P)%P;
    if(i>=3) dp[i] = (dp[i] + dp[i-2])%P;
  }
  return dp[n];
}

ll solve2(vvl dat){
  ll n = dat.size();
  vvl dp(n+1);
  return 1;
}


