vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}
ll N;
vector<ll> A;

void solve(){
  ll XOR = 0;
  ll cnt = 0;
  rep(i, N) XOR ^= A[i];
  if(XOR == 0){
    set<ll> B;
    ll now = 0;
    rep(i, N){
      now ^= A[i];
      B.insert(now);
      if(now == 0) cnt++;
    }
    mint ans = 0;
    for(auto itr = B.begin(); itr != B.end(); itr++){
      ll a = *itr;
      if(a == 0) continue;
      ll b = 0;
      ll now = 0;
      mint s = 0, t = 0;
      rep(i, N){
        now ^= A[i];
        if(now == a){
          s += t + 1;
        }
        if(now == b && s != 0){
          t += s;
        }
      }
      ans += s;
    }
    ans += pow_mod(2, cnt-1);
    ans.get();
  }else{
    ll a = XOR;
    ll b = 0;
    ll now = 0;
    mint s = 0, t = 0;
    rep(i, N){
      now ^= A[i];
      if(now == a){
        s += t + 1;
      }
      if(now == b){
        t += s;
      }
      if(t == 0) s = 1;
    }
    s.get();
  }
}

