constexpr int MAX_N = 512345;
int N;
int A[MAX_N];
int AS[MAX_N];
vector<int> ids[1123456];
ModInt ret[(1 << 20) + 1];
int get_prv_id(int x, int cur) {
    auto pos = distance(ids[x].begin(), lower_bound(ALL(ids[x]), cur));
    if (pos == 0) {
        return -1;
    }
    else {
        return ids[x][pos - 1];
    }
}

int c[MAX_N];
int cs[MAX_N];
int get_zero_cnt(int bg, int ed) { return cs[ed] - cs[bg]; }


int main() {
    for (int i : range(1 << 20)) ret[i] = 0;
    cin >> N;
    for (int i : range(N)) cin >> A[i];
    for (int i : range(N)) {
        AS[i + 1] = AS[i] ^ A[i];
        if (AS[i + 1] == 0) c[i] = 1;
        ids[AS[i + 1]].push_back(i);
        cs[i + 1] = cs[i] + c[i];
    }
    const int last = AS[N];
    // if (last == 0) return -1;
    ModInt ans = 0;
    // non zero
    for (const int i : range(N - 1)) {
        const int xor_value = AS[i + 1];
        if (xor_value == 0) continue;
        const int pi = get_prv_id(xor_value, i);

        if (pi != -1) {
            const int zc   = get_zero_cnt(pi, i);
            ret[xor_value] = ret[xor_value] * (zc + 1);
        }
        ret[xor_value] = ret[xor_value] + 1;
        // cerr << i << " " << *ret[xor_value] << endl;
    }
    if (last != 0) {
        const int i         = N - 1;
        const int xor_value = AS[i + 1];
        const int pi        = get_prv_id(xor_value, i);
        if (pi != -1) {
            const int zc = get_zero_cnt(pi, i);
            ans          = ans + ret[xor_value] * zc;
            ans          = ans + 1;
        }
    }
    else {
        cerr << *ans << endl;
        for (int i : range(1, 1 << 20)) {
            ans = ans + (*ret[i]);
            // cerr << i << " " << *ret[i] << " " << *ans << endl;
        }
        cerr << *ans << endl;
        const int all_zero = get_zero_cnt(0, N) - 1;
        ModInt zero_use    = 1;
        for (int i : range(all_zero)) {
            zero_use = zero_use + zero_use;
        }
        ans = ans + zero_use;
        cerr << *zero_use << endl;
    }
    cout << *ans << endl;
    return 0;
}

