#include<bits/stdc++.h>
#define double long double
#define debug(x)  cerr << #x << " = " << x << endl
typedef long long ll;
const ll MAX_N = 5e5+100;
const ll MOD = 1e9+7;
using namespace std;

ll fc[MAX_N];
ll rf[MAX_N];
int a[MAX_N];
int n;

ll pw(ll a,ll b)
{
    if (!b)
        return 1;
    ll ans = pw(a,b/2);
    ans *= ans;
    ans %= MOD;
    if (b&1)
        ans *= a;
    return (ans%MOD);
}

void prec()
{
    fc[0] = rf[0] = 1;
    for(int i = 1;i<MAX_N;++i)
        fc[i] = (fc[i-1]*i)%MOD;
    for(int i = 1;i<MAX_N;++i)
        rf[i] = pw(fc[i],MOD-2);
}

ll C(int n,int k)
{
    if (k>n)
        return 0;
    return (((fc[n]*rf[k])%MOD)*rf[n-k])%MOD;
}

int main()
{
    prec();
    cin >> n;
    for(int i = 1;i<=n;++i)
        scanf("%d",&a[i]);
    int xorr = 0;
    for(int i = 1;i<=n;++i)
        xorr ^= a[i];
    if (xorr != 0)
    {
        int cnt = 0;
        int now = 0;
        for(int i = 1;i<=n;++i)
        {
            now ^= a[i];
            if (now==xorr)
                cnt++,now = 0;
        }
        ll ans = 0;
        for(int i = 1;i<=cnt;++i)
        {
            if ((cnt-i)%2==0)
            {
                ans += C((cnt-i)/2+i-1,i-1);
                ans %= MOD;
            }
        }
        cout << ans;
        return 0;
    }
    exit(1);
    return 0;
}

