using namespace std;

ll mod = 1000000007;
int t20 = 1048576;
ll po(ll k, ll x) {
  if (x == 0) {
    return 1;
  }
  if (x == 1) {
    return k % mod;
  }
  ll y = po(k, x/2);
  y = y * y % mod;
  if (x % 2 == 1) {
    y = y * k % mod;
  }
  return y;
}

ll po2(ll x) {
  return po(2, x);
}

int main() {
  int n;
  scan(n);
  vi a(n);
  scan(a);

  vi beauty(n+1, 0);
  rep (i, n) {
    beauty[i+1] = beauty[i] ^ a[i];
  }
  vvi ind(t20, vi());
  rep (i, n+1) {
    ind[beauty[i]].push_back(i);
  }
  vi zacc(n+2, 0);
  rep (i, n+1) {
    zacc[i+1] = zacc[i];
    if (beauty[i] == 0) {
      zacc[i+1] += 1;
    }
  }

  ll ans = 0;
  if (beauty[n] != 0) {
    int sz = ind[beauty[n]].size();

    vll dp(2, 0);
    dp[0] = 1;
    rep (i, sz-1) {
      int znum = zacc[ind[beauty[n]][i+1]] - zacc[ind[beauty[n]][i]];
      vll next_dp(2, 0);
      next_dp[0] = (dp[0] * (znum + 1) + dp[1] * znum) % mod;
      next_dp[1] = (dp[0] * 1 + dp[1] * 1) % mod;
      swap(dp, next_dp);
    }
    ans = dp[0];
  } else {
    ans = po2((int)ind[0].size() - 2);
    FOR (i, 1, t20) {
      int sz = ind[i].size();
      if (sz == 0) {
        continue;
      }

      vll dp(2, 0);
      dp[0] = 1;
      rep (j, sz-1) {
        int znum = zacc[ind[i][j+1]] - zacc[ind[i][j]];
        vll next_dp(2, 0);
        next_dp[0] = (dp[0] * (znum + 1) + dp[1] * znum) % mod;
        next_dp[1] = (dp[0] * 1 + dp[1] * 1) % mod;
        swap(dp, next_dp);
      }
      ll add = (dp[1] + dp[0]) % mod;
      ans = (ans + add) % mod;
    }
  }
  print(ans);

  return 0;
}

