ll zs(int l, int r) {
    int L = lower_bound(occ[0].begin(), occ[0].end(), l) - occ[0].begin();
    int R = lower_bound(occ[0].begin(), occ[0].end(), r) - occ[0].begin();
    return R - L;
}

