const ll mod = 1000 * 1000 * 1000 + 7;

ll power(ll x, ll n) {
    ll res = 1;
    while (n) {
        if (n & 1)
            res = (res * x) % mod;
        x = (x * x) % mod;
        n /= 2;
    }
    return res;
}


pll solve(int n, const vector<int>& pr, vector<int>& pos, const vector<int>& pr0) {
    ll res0 = 1, res1 = 0;
    //cerr << "start\n";
    vector<int> d;
    for (int i = 1; i < pos.size(); ++i) {
        ll x = pr0[pos[i]] - pr0[pos[i - 1]];
        d.push_back(x);
    }
    d.push_back(0);
    for (int i = 0; i < d.size(); ++i) {
        ll z = res0;
        ll x = d[i];
        res0 = (res0 * (x + 1) + res1 * x) % mod;
        res1 = (res1 + z) % mod;
        //cerr << x << " ";
    }
    //cerr << endl;
    return pll(res0, res1);

}


