map<tuple<int, int, int>, long long> dp;

long long dfs(int now, int score, int checkbin) {
	if (now == n) return score == checkbin || checkbin == -1;
	auto status = make_tuple(now, score, checkbin);
	if (dp.count(status)) return dp[status];
	long long res;
	if (checkbin == -1 && now) {
		res = dfs(now + 1, score ^ a[now], checkbin) + dfs(now + 1, a[now], score);
		res %= INF;
	}
	else if (score == checkbin) {
		res = dfs(now + 1, 0, checkbin) + dfs(now + 1, score xor a[now], checkbin);
		res %= INF;
	}
	else {
		return dp[status] = dfs(now + 1, score xor a[now], checkbin);
	}
	return dp[status] = res;
}

