ll fac(ll n)
{
	if (n == 0)
	{
		return 1;
	} else
	{
		return (n - 1) * fac(n - 2) % MOD;
	}
}

ll deg(ll n)
{
	ll ans = 1;
	for (int i = 0; i < n; ++i)
	{
		ans *= 2;
		ans %= MOD;
	}
	return ans;
}

