{
	ll cnt = 0;
	ll temp = 0;
	for (int i = l; i <= r; ++i)
	{
		temp ^= a[i];
		if (temp == xs)
		{
			++cnt;
			temp = 0;
		}
	}
	return fac(cnt - 1);
}

