// F_mod 上でのべき乗, 蟻本p115
ll modPow(ll x, ll n) {
    ll res = 1;
    while(n > 0){
        if(n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

#define MAX_a 1050000

int main() {
    int N;
    cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; ++i) {
      cin >> a[i];
    }

    // 累積XORと累積0の個数
    vector<int>cuXOR(N);
    vector<int>zero(N, 0);
    cuXOR[0] = a[0];
    if(a[0] == 0) zero[0]++;
    for (int i = 1; i < N; ++i) {
        zero[i] = zero[i-1];
        cuXOR[i] = cuXOR[i-1] ^ a[i];
        if(cuXOR[i] == 0) zero[i]++;
    }

    // 美しさbで現在の区間より前のxorが0ならdp[b][0], bならdp[b][1]が場合の数
    ll dp[MAX_a][2] = {};
    for (int i = 0; i < MAX_a; ++i) {
        dp[i][0] = 1;
    }
    ll prev[MAX_a] = {};
    for (int i = 0; i < N; ++i) {
        int cur = cuXOR[i];
        if(cur != 0){
            dp[cur][0] += dp[cur][1] * (zero[i] - zero[prev[cur]]);
            dp[cur][0] %= mod;
            dp[cur][1] += dp[cur][0];
            dp[cur][1] %= mod;
            prev[cur] = i;
        }
    }

    ll ans = 0;
    if(cuXOR[N-1] == 0){
        ans += modPow(2, zero[N-1]);
        for (int i = 1; i < MAX_a; ++i) {
            ans += dp[i][1];
            ans %= mod;
        }
    } else{
        ans += dp[cuXOR[N-1]][0];
        ans %= mod;
    }
    cout << ans;
    return 0;
}

