// x^y
inline li njo(li x, li y) {
    if (y == 0) return 1;
    if (y == 1)return x;
    li res = njo(x * x % MOD, y / 2);
    if (y % 2 > 0) {
        res = (res * x) % MOD;
    }
    return res;
}

inline li solve(vector<li>& p) {
    //
    li prev[2] = {0};
    li now[2] = {0};
    prev[0] = 1;
    prev[1] = 0;
    li prev_pos = 0;
    for (auto && pos : p) {
        li zero_num = zeros[pos] - zeros[prev_pos];
        now[0] = (prev[0] + prev[1] * zero_num) % MOD;
        now[1] = (now[0] + prev[1]) % MOD;
        prev_pos = pos;
        //p7(pos, zero_num, prev[0], prev[1], " -> " , now[0], now[1]);
        prev[0] = now[0];
        prev[1] = now[1];
    }
    return now[1] % MOD;
}


inline li solve1(vector<li>& p) {
    //
    li prev[2] = {0};
    li now[2] = {0};
    prev[0] = 1;
    prev[1] = 0;
    li prev_pos = 0;
    for (auto && pos : p) {
        if (pos == p.back()) break;
        li zero_num = zeros[pos] - zeros[prev_pos];
        now[0] = (prev[0] + prev[1] * zero_num) % MOD;
        now[1] = (now[0] + prev[1]) % MOD;
        prev_pos = pos;
        prev[0] = now[0];
        prev[1] = now[1];
    }
    li zero_num = zeros[n + 1] - zeros[prev_pos];
    return (prev[0] + prev[1] * zero_num) % MOD;
}

inline li solve0() {
    li cnt_0 = 0;
    repp(i, 1, n + 1) {
        if (sum[i] == 0) {
            cnt_0++;
        }
    }
    return njo(2, cnt_0 - 1);
}

