    REP(i, N) S[i+1] = S[i]^A[i];
    //cerr << S << endl;

    vector<ll> SZ(N+2, 0);
    REP(i, N+1) SZ[i+1] = SZ[i] + (S[i]==0);

    // compress
    set<ll> st;
    REP(i, N+1){
        st.insert(S[i]);
    }
    map<ll, ll> mp;
    ll cnt = 0;
    for(auto x: st){
        mp[x] = cnt;
        cnt++;
    }

    vector<vector<ll>> kan(cnt);
    vector<ll> prev(cnt, -1);

    REP(i, N+1){
