            ll zz = 1, xx = 1;
            REP(j, kan[i].size()){
                if(j==0)continue;
                zz += (xx*kan[i][j])%mod;
                zz %= mod;
                xx += zz;
                xx %= mod;
            }

            res += xx;
            res %= mod;
        }
    }else{
        REP(i, cnt){
            if(mp[S.back()] != i) continue;

            ll zz = 1, xx = 1;
            REP(j, kan[i].size()){
