int pow(int a, int b, int m)
{
	int ans=1;
	while(b)
	{
		if(b&1)
			ans=(ans*a)%m;
		b/=2;
		a=(a*a)%m;
	}
	return ans;
}

int dp(int idx, int cur)
{
	if(idx == n + 1)
		return (cur == 1);
	int &ans = cache[idx][cur];
	if(ans != -1)
		return ans;
	ans = dp(idx + 1, cur);
	if(cur == 0 && pref[idx] == 0)
		ans += dp(idx + 1, cur ^ 1);
	if(cur == 1 && pref[idx] == x)
		ans += dp(idx + 1, cur ^ 1);
	ans %= MOD;
	return ans;
}	

