ll solve(vector<pair<int,int>> a) {
    // count odd length subsequences that alternate: 101..0101, must start and end with 1
    vector<ll> dp(2, 0);
    dp[0] = 1;
    for (auto p: a) {
	int x=p.first;
	ll cnt=p.second;
	if (x==0) {
	    dp[0]=(cnt*dp[1]%mod+dp[0])%mod;
	} else {
	    dp[1]=(cnt*dp[0]%mod+dp[1])%mod;
	}
    }
    return dp[1];
}

