#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;

const ll MOD = 1e9 + 7;

void makeNextLink(vector<int> &nxt, const vector<int> &a) {
    map<int, int> memo;
    for (size_t i = nxt.size() - 1; 1 <= i; --i) {
        if (memo.count(a[i]) != 0) nxt[i] = memo[a[i]];
        memo[a[i]] = i;
    }
}

ll Solve() {
    ll n;
    cin >> n;

    vector<ll> pow2(n + 1, 1);
    for (int i = 1; i <= n; ++i) (pow2[i] = 2 * pow2[i - 1]) %= MOD;

    vector<int> a(n + 1), cnt_zero(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        a[i] ^= a[i - 1];
        if (a[i] == 0) ++cnt_zero[i];
        cnt_zero[i] += cnt_zero[i - 1];
    }

    vector<int> nxt(n + 1, -1);
    makeNextLink(nxt, a);

    // for (int i = 0; i < n; ++i)
    //     cout << "nxt[" << i << "] = " << nxt[i] << endl;
    // for (int i = 0; i <= n; ++i)
    //     cout << "cnt_zero[" << i << "] = " << cnt_zero[i] << endl;
    // for (int i = 0; i < n; ++i)
    //     cout << "a[" << i << "] = " << a[i] << endl;
    // cout << "a.back() = " << a.back() << endl;

    ll sum = 1;
    if (a.back() != 0) {
        int idx = 1;
        while (a[idx] != a.back()) ++idx;

        ll sum_a = 1, sum_b = 0;
        while (nxt[idx] != -1) {
            ll num_zero = cnt_zero[nxt[idx]] - cnt_zero[idx - 1];
            (sum_b += num_zero * sum_a) %= MOD;
            (sum_a += sum_b + 1) %= MOD;
            idx = nxt[idx];
        }
        sum += sum_b;
    }
    else {
        set<int> used;
        for (int i = 1; i + 1 <= n; ++i) {
            if (used.count(a[i]) != 0) continue;
            used.insert(a[i]);
            // cout << "start: i = " << i << ", sum = " << sum << endl;

            if (a[i] == 0) {
                // cout << "i = " << i << ": " << sum;
                int num_zero = cnt_zero[n] - cnt_zero[i - 1];
                (sum += pow2[num_zero - 1] - 1 + MOD) %= MOD;
                // cout << " -> " << sum << ", num_zero = " << num_zero << endl;
            }
            else {
                ll sum_a = 1, sum_b = 0, idx = i;
                while (nxt[idx] != -1) {
                    ll num_zero = cnt_zero[nxt[idx]] - cnt_zero[idx - 1];
                    (sum_b += num_zero * sum_a) %= MOD;
                    (sum_a += sum_b + 1) %= MOD;
                    idx = nxt[idx];
                }
                (sum += sum_a) %= MOD;
            }
            // cout << "end: i = " << i << ", sum = " << sum << endl;
        }
    }

    return sum % MOD;
}

