u6 pow2(u6 n) {
	if (n < 64)return (u6(1) << n)% moduloNo;
	else if (n == 64)return (u6(0) - moduloNo) % moduloNo;
	u6 tmp = pow2(n / 2);
	tmp=tmp * tmp;
	if (n & 1)tmp *= 2;
	return tmp % moduloNo;
}
struct Matrix {
	array<unsigned char, 4> buf;

};
std::ostream & operator<<(std::ostream & out, const Matrix & mat) {
