ll quick_pow(ll x, ll n)
{
    ll ans = 1;
    while(n) {
        if(n&1) {
            ans *= x;
            ans %= mod;
        }
        x *= x;
        x %= mod;
        n >>= 1;
    }
    return ans;
}

const int MAXN = 5e5+10;
ll dp[MAXN];

ll solve(ll n)
{
    if(dp[n] != 0) return dp[n];
    if(n == 1 || n == 2) return dp[n] = 1;
    return dp[n] = (solve(n-1) + solve(n-2))%mod;
}

ll dp2[MAXN][2];
ll solve1(ll n, int flg, ll X, vector<ll> &B)
{
    if(dp2[n][flg] != 0) return dp2[n][flg];
    if(n == 0) return dp2[n][flg] = (flg==0);
    if(flg == 0) {
        if(B[n-1] == 0) {
            return dp2[n][flg] = (solve1(n-1, 0, X, B) + solve1(n-1, 1, X, B))%mod;
        }else {
            return dp2[n][flg] = solve1(n-1, 0, X, B);
        }
    }else {
        if(B[n-1] == X) {
            return dp2[n][X>0] = (solve1(n-1, 0, X, B) + solve1(n-1, 1, X, B))%mod;
        }else {
            return dp2[n][X>0] = solve1(n-1, 1, X, B);
        }
    }
}

