            P.pb(i + 1);
        }
        map<ll, ll> T;
        rep(i, M) {
            inc(j, P[i] + 1, P[i + 1] - 1) {
                if ((S[j] ^ S[P[i]]) == (S[j] ^ S[P[i + 1]])) {
                    T[S[j] ^ S[P[i]]]++;
                }
            }
        }
        res = 1;
        each(i, T) {
            if (i.fi == (S[P.back()] ^ S[N]))
                res += mod_pow(2, i.se - 1), res %= MOD;
        }
        cout << res << endl;
    }
}

