int main() {
    cin >>N;
    A.resize(N);
    S.resize(N+1);
    numZ.resize(N+2);
    REP(i,N)
        cin>>A[i];
    S[0]=0;
    REP(i,N)
        S[i+1]=S[i]^A[i];
    REP(i,N+1)
        V.insert(S[i]);
    numZ[0]=0;
    REP(i,N+1)
        numZ[i+1]=numZ[i]+(S[i]==0?1:0);
    //DumpArray(S,0,N+1);
    //DumpArray(numZ,0,N+2);
    ll ans=0;
    if (S[N]!=0) {
        V=set<int>();
        V.insert(S[N]);
    } else {
        // when 0
        ans+=pow2(numZ[N+1]-2);
    }

    //
    for(int i=0;i<N+1;++i) {
        if (indices.find(S[i])!=indices.end()) {
            indices[S[i]].pb(i);
        } else {
            indices[S[i]]=vector<int>();
            indices[S[i]].pb(i);
        }
