        ll sb=1,st=0;
        for(int i=1;i<indexs.size();++i) {
            ll zeros=numZ[indexs[i]]-numZ[indexs[i-1]];
            ll psb=sb;
            sb=AS_MOD(AS_MOD(sb*zeros,mod)+AS_MOD(1+st+sb,mod),mod);
            st=AS_MOD(st+AS_MOD(psb*zeros,mod),mod);
        }
        //cout << sb << endl;
        ans+=sb;
        ans=AS_MOD(ans,mod);
    }
    cout << ans << endl;
    return 0;
}

