int mod=1e9+7;	
LL f_pow(LL a,LL b){
	LL res=1,temp=a;
	while(b){
		if(b&1)res=res*temp%mod;
		temp=temp*temp%mod;
		b>>=1;
	}
	return res;
}
int main(){
	int n;
	scanf("%d",&n);
	int a[500005];
	int tot=0;
	for(int i = 0;i<n;i++){
		scanf("%d",&a[i]);
		tot^=a[i];
	}
	int cnt=0;
	int now=0;
	map<int,int> m;
	//v.pb(map<int,int>());
	int lev=0;
	map<int,vector<pii> > ans;
	for(int i = 0;i<n;i++){
		now^=a[i];
		m[now]++;
		if(now==tot){
			cnt++;
			now=0;
			lev++;
			//v.pb(map<int,int>());
			for(auto it:m){
				if(it.x==0)
				continue;
				ans[it.x].pb(mp(it.y,lev));
			}
			m.clear();
		}
	}
//	printf("%lld\n",tot);
	if(tot==0){
		LL myans=0;

		for(auto it:ans){
			LL lastlev = 0;
			LL last=0;
			LL sum = 0;
			LL add=0;
			for(auto p :it.y){
				sum+=(p.y-lastlev-1)*last%mod;
			//	printf("%d ",sum);
				sum%=mod;
				last = ((sum+1)*p.x + last)%mod;
				lastlev = p.y;
				sum+=last;
				add+=last;
				//printf("%lld ",last);
			//	printf("%d %d %d  ",p.x,p.y,sum);
			}
			//printf(" %d %d %d\n",last,sum,add);
			sum--;
			myans+=last;
		}
		printf("%lld\n",(f_pow(2,cnt-1)+myans)%mod);
	}
	else{
		LL temp[500005];
		temp[0]=1;
		LL odd=0,even=1;
		for(int i =1;i<=cnt;i++){
			if(i&1){
				temp[i]=even;
				odd+=temp[i];
				odd%=mod;
			}
			else{
				temp[i]=odd;
				even+=temp[i];
				even%=mod;
			}
		}
		printf("%lld\n",temp[cnt]);
	}
	return 0;
}
