void solve(){
	vector<int> zero_count(N+1);
	uint s = 0;
	unordered_map<uint,vector<int> > a;
	zero_count[0] = 1;
	a[s].push_back(-1);
	for(int i = 0;i < A.size();i++){
		s ^= A[i];
		zero_count[i+1] = zero_count[i];
		if(s==0)zero_count[i+1]++;
		a[s].push_back(i);
	}
	mod_int ans = 0;
	for(auto &&p:a){
		auto &v = p.second;
		if(p.first==0){
			if(s==0){
				ans += mod_pow((mod_int)2,(int)v.size()-2);
			}
		}else{
			if(s==0 or (s!=0 and p.first==s)){
				int cur_zero = 0;
				mod_int sum0 = 1, dpk = 0;//sum0: ends with 0, dpk: ends with k
				for(int i = 0;i < v.size();i++){
					int zc = zero_count[v[i] + 1], zd = zc - cur_zero;
					sum0 += dpk * zd;
					dpk += sum0;
					cur_zero = zc;
				}
				if(s==0){
					ans += dpk;
				}else{
					ans += sum0;
				}
			}
		}
	}
	cout<<ans<<endl;
}
