    //for(int x = 0; x < (1<<20); ++x) dp1[x] = 1;

    for(int i = 1; i <= n-1; ++i){
        if(a[i] == 0) nb.add(0, (1<<20)-1, 1);
        else{
            dp0.add(a[i], a[i], ((LL)nb.query(a[i],a[i]) * dp1[a[i]]) %MOD);
            nb.add(a[i], a[i], -nb.query(a[i], a[i]));
            dp1[a[i]] = ((LL)dp1[a[i]] + dp0.query(a[i],a[i])) %MOD;
        }
    }

    int ans = 0;
    if(a[n] > 0) ans = dp1.query(a[n], a[n]);
    else{
