		int tmp = count(a+1, a+1 + n, 0);
		int extra = 1; for(int i = 1; i <= tmp - 1; ++i) extra = ((LL)extra * 2) %MOD;
		ans = (ans + extra) %MOD;
	}

    write(ans, "\n");

    return 0;
}

