constexpr int kMod = 1'000'000'000 + 7;

int main() {
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(nullptr);
  int n;
  std::cin >> n;
  std::vector<int> a(n), s(n + 1);
  for (int i = 0; i < n; ++i) {
    std::cin >> a[i];
    s[i + 1] = s[i] ^ a[i];
  }
  if (s[n] != 0) {
    std::vector<int> dp(n + 1);
    std::vector<int> sum(1 << 20);
    sum[0] = 1;
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
      dp[i] = sum[s[i] ^ s[n]];
      (sum[s[i]] += dp[i]) %= kMod;
    }
    std::cout << dp[n] << "\n";
    return 0;
  }
  std::vector<std::vector<int>> pos(1 << 20);
  for (int i = 1; i <= n; ++i) pos[s[i]].push_back(i);
  std::vector<int> zeros(n + 1);
  zeros[0] = 1;
  for (int i = 1; i <= n; ++i) {
    zeros[i] = zeros[i - 1];
    if (s[i] == 0) zeros[i]++;
  }
  int cut = 0;
  for (int i = 0, v = 0; i < n; ++i) {
    v ^= a[i];
    if (v == 0) cut++;
  }
  int ans = 1;
  for (int i = 0; i < cut - 1; ++i) ans = (ans + ans) % kMod;
  for (int v = 1; v < (1 << 20); ++v) {
    if (pos[v].empty()) continue;
    std::vector<int> dp(pos[v].size());
    int sum = 0, prod = 0;
    for (int i = 0; i < pos[v].size(); ++i) {
      dp[i] = (1 + 1LL * zeros[pos[v][i]] * sum % kMod + prod) % kMod;
      sum = (sum + dp[i]) % kMod;
      prod = (prod + 1LL * (kMod - dp[i]) * zeros[pos[v][i]]) % kMod;
    }
    ans = (ans + sum) % kMod;
  }
  std::cout << ans << "\n";
  return 0;
}

