template<class T> inline vector<T> ruimi(vector<T> &a) {
    int n = sz(a);
    vector<T> ret(n + 1);
    rep(i, 1, n) {
        ret[i] = a[i - 1];
        chmi(ret[i + 1], ret[i]);
    }
    return ret;
}
