    for(int i = 1; i <= n; i++){
        int col = -1;
        if(a[i] == 0)col = 0;
        else if(a[i] == val)col = 1;
        if(~col){
            x = ans[col^1];
            ans[col] += x;
            if(ans[col] >= MOD)ans[col] -= MOD;
        }
    }
    return x;
}
int acc[N];
vector<int> go[1<<20];
int hard(int val){
    if(val == 0){
        int ret = 1;
        for(int j = 0; j + 1 < acc[n]; j++){
            ret = ret + ret;
            if(ret >= MOD)ret -= MOD;
        }
        return ret;
    }
    int ret = 0;
    vector<int> v = go[val];
    int ans[2] = {};    ans[0] = 1;
    for(int i = 0; i < v.size(); i++){
