        if(ans[1] >= MOD)ans[1] -= MOD;
        ////update ans[0]
        if(i + 1 != v.size()){
            int toNxt = acc[v[i+1]] - acc[v[i]];
            ans[0] += 1ll * ans[1] * toNxt % MOD;
            if(ans[0] >= MOD)ans[0] -= MOD;
        }
    }
    return ans[1];
}
