                    zid = *lower_bound(st[0].begin(),st[0].end(),kid);  
                }else{
                    zid = n;
                }
                int cnt = lower_bound(st[bit].begin(),st[bit].end(),zid)-lower_bound(st[bit].begin(),st[bit].end(),id);
                id = kid;
                p.push_back(cnt);
                flag = 0;
            }else{
                int zid = 0;
                    if(lower_bound(st[0].begin(),st[0].end(),id)!=st[0].end()){
                    zid = *lower_bound(st[0].begin(),st[0].end(),id);
                }else{
                    break;
                }
                int kid = 0;
                if(lower_bound(st[bit].begin(),st[bit].end(),zid)!=st[bit].end()){
                    kid = *lower_bound(st[bit].begin(),st[bit].end(),zid);  
                }else{
                    kid = n;
                }
                int cnt = lower_bound(st[0].begin(),st[0].end(),kid)-lower_bound(st[0].begin(),st[0].end(),id);

                id = zid;
                p.push_back(cnt);
                flag = 1;
            }
        }
        int m = p.size();
        if(m==1)res = 1;
        else{
            vector<ll > dp(m);
            vector<ll> dp2(m);
            rep(i,m){
                if(i==0){
                    dp[i] = p[i];
                    dp2[i] = p[i];
                }else if(i==1){
                    dp[i] = dp2[i-1]*p[i]%mod;
                    dp2[i] = dp[i];
                }else{
                    if(i%2==0){
                        dp[i] = p[i]*(dp2[i-1]+1)%mod; 
                    }else{
                        dp[i] = p[i]*(dp2[i-1])%mod; 
                    }
                    dp2[i] = dp2[i-2]+dp[i];
                    dp2[i]%=mod;
                }
            }
            // for(auto x:p){
            //     cerr << x << " ";
            // }
            // cerr << endl;
            res += dp[m-1];
            res %= mod;
        }
    }
    cout << res << endl;
    return 0;
}

