            if(pos[c].size() == 0) continue;
            mint sum(0);

            for(size_t i=0; i<pos[c].size(); i++) {
                int r = pos[c][i] + 1;
                int l = (i ? pos[c][i-1] : 0);
                int s = zero[r] - zero[l]; // 区間内に 0 は何個？
                mint val = sum * mint(s) + mint(1);
                sum += val;
            }
            ans += sum;
        }
        cout << ans << endl;
    }
    return 0;
}

