mll solve(ll n, vll &a)
{
	vll cml(n+1);
	rep(i, 1, n){
		cml[i]=cml[i-1]^a[i-1];
	}
	vll cmr(n+1);
	dep(i, n-1, 0){
		cmr[i]=cmr[i+1]^a[i];
	}

	if (cml[n]!=0){
		vpll buf;
		rep(i, 0, n){
			if (cml[i]==0){
				buf.emplace_back(i, 1);//黒
			}
		}
		rep(i, 0, n){
			if (cmr[i]==0){
				buf.emplace_back(i, 0);//白
			}
		}
		sort(ALL(buf));

		ll m=sz(buf);
		vmll dp(m);
		auto Dp = [&](ll i)->mll&{
			return dp[i];
		};
		Dp(0)=1;
		vmll bl(m);
		auto Bl = [&](ll i)->mll&{
			return bl[i];
		};
		Bl(0)=1;
		vmll wh(m);
		auto Wh = [&](ll i)->mll&{
			return wh[i];
		};

		rep(i, 1, m-1){
			if (buf[i].second==0){//白
				Dp(i)=Bl(i-1);
				Wh(i)+=Wh(i-1)+Dp(i);
				Bl(i)+=Bl(i-1);
			}
			else{
				Dp(i)=Wh(i-1);
				Bl(i)+=Bl(i-1)+Dp(i);
				Wh(i)+=Wh(i-1);
			}
		}
		mll ans=Dp(m-1);
		return ans;
		//cout << ans << '\n';
	}

	/////////////////////////////全和が0の時

	else{
		map<ll, vll> mp;
		rep(i, 0, n){
			ll v=cml[i];
			if (v==0)continue;
			mp[v].push_back(i);
		}
		vll b(n+1);
		rep(i, 0, n){
			if (cml[i]==0) b[i]=1;
		}
		CumulativeSum cmb(b);

		mll ans=0;
		each(e, mp){
			vll &buf=e.second;
			ll m =sz(buf);
			vmll dp(m);
			auto Dp = [&](ll i)->mll&{
				return dp[i];
			};
			Dp(0)=1;
			vmll sm(m);
			auto Sm = [&](ll i)->mll&{
				return sm[i];
			};
			Sm(0)=1;

			rep(i, 1, m-1){
				ll idx=buf[i];
				ll pre=buf[i-1];
				//Dp(i)=Dp(i-1)+Sm(i-1)*cmb(pre, idx)+1;
				Dp(i)=Sm(i-1)*cmb(pre, idx)+1;
				Sm(i)=Sm(i-1)+Dp(i);
			}
			ans+=Sm(m-1);
		}

		ll mm=cmb(0, n)-2;
		ans+=POW(mll(2), mm);
		return ans;
		//cout << ans << '\n';
	}
}


