void upd(int x,long long y)
{
	(sum2[x]+=sum[x]*y)%=mod;
	tag[x]+=y;if (tag[x]>=mod) tag[x]-=mod;
}
void pushdo(int x)
{
	if (tag[x])
	{
		upd(x*2,tag[x]);
		upd(x*2+1,tag[x]);
		tag[x]=0;
	}
}
void pushup(int x)
{
	sum[x]=sum[x*2]+sum[x*2+1];if (sum[x]>=mod) sum[x]-=mod;
	sum2[x]=sum2[x*2]+sum2[x*2+1];if (sum2[x]>=mod) sum2[x]-=mod; 
}
void update(int x,int l,int r,int y,int c)
{
	if (l==r){
		(sum[x]+=c)%=mod;return;
	}
	pushdo(x);int mid=(l+r)/2;
	if (y<=mid) update(x*2,l,mid,y,c); else update(x*2+1,mid+1,r,y,c);
	pushup(x);
}
int query(int x,int l,int r,int y)
{
	if (l==r) return sum2[x];
	pushdo(x);int mid=(l+r)/2;
	if (y<=mid) return query(x*2,l,mid,y); else query(x*2+1,mid+1,r,y);
}
