struct seg{
	int siz;
	int s[1<<21];
	void init(){
		siz = 1<<20;
		for(int i = 0 ; i < 2*siz-1 ; i ++){
			s[i] = 0;
		}
	}
	void add(int a,int b,int x,int k,int l,int r){
		if(b <= l || r <= a)return;
		if(a <= l && r <= b){
			s[k] += x;
			return;
		}
		add(a,b,x,2*k+1,l,(l+r)/2);
		add(a,b,x,2*k+2,(l+r)/2,r);
	}
	int query(int a,int k,int l,int r){
		if(a+1 <= l || r <= a)return 0;
		if(l == a && r == a+1){
			int ret = s[k];
			s[k] = 0;
			return ret;
		}
		if(s[k] != 0){
			add(l,r,s[k],2*k+1,l,(l+r)/2);
			add(l,r,s[k],2*k+2,(l+r)/2,r);
			s[k] = 0;
		}
		return query(a,2*k+1,l,(l+r)/2)+query(a,2*k+2,(l+r)/2,r);
	}
}seg;

ll f(ll n){
	if(n == 0)return 1;
	ll ret = f(n-1);
	ret *= 2;
	if(ret >= MOD)ret -= MOD;
	return ret;
}

