        auto f    = [](mint l, mint r) { return l + r; };
        SegmentTreeLazyAdd<mint> seg(1 << 22, f, UNIT);
        for (int i = 0; i < na - 1; ++i) {
            if (a[i] == 0) {
                seg.add(0, 1 << 22, 1);
            } else {
                if (pos[a[i]] == 0) {
                    pos[a[i]] = 1;
                    seg.update(a[i], 0);
                } else {
                    zeros[a[i]] += seg.query(a[i], a[i] + 1) * pos[a[i]];
                    seg.update(a[i], 0);
                    pos[a[i]] += zeros[a[i]];
                }
            }
        }
        for (auto &p : pos) {
            ret += p;
        }
        cout << ret << "\n";
    } else {
        while (a.front() == 0)
            a.pop_front();
        while (a.back() == 0)
            a.pop_back();
        a.push_front(0);
        mint pos  = 0;
        mint zero = 1;
        int na    = a.size();
        for (int i = 1; i < na; ++i) {
            a[i] ^= a[i - 1];
        }
        for (int i = 1; i < na - 1; ++i) {
            if (a[i] == tot) {
                pos += zero;
            } else if (a[i] == 0) {
                zero += pos;
            }
        }
        cout << zero << "\n";
    }

    return 0;
}

