}

int getXnum(int l, int r, int tarX){
	vector<int> target = xat[tarX];
	vector<int>::iterator posA = lower_bound(target.begin(), target.end(), l);
	vector<int>::iterator posB = lower_bound(target.begin(), target.end(), r);
