}

int X;
ll dfs(int at, int before){
	if(at == n-1){
		if(before == 0){
		// if(before == 1){
			return 1;
		}else{
			return 0;
		}
	}
	pair<int,int> key = make_pair(at,before);
	map<pair<int,int>,ll>::iterator it = dp[X].find(key);
	if(it != dp[X].end()){
		return it->second;
	}

	ll sum = 0;
	if(b[at] == 0){
		sum += dfs(at+1, before);
		if(before == 1)
			sum += dfs(at+1, 0);

	}else if(b[at] == X){
		sum += dfs(at+1, before);
		if(before == 0)
			sum += dfs(at+1, 1);

	}else{
		sum += dfs(at+1, before);

	}
	return dp[X][key] = sum%MOD;
}

ll dfs2(int at, int before){
	// cout << X << " " << at << " " << before << endl;
	if(at == n-1){
