constexpr u64 kMod = 1000000007;
int main() {
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(nullptr);
  u64 n, cnt = 0;
  std::cin >> n;
  std::vector<u64> a(n, 0), pxor(n, 0);
  for (u64 i = 0; i < n; ++i) std::cin >> a[i];
  pxor[0] = a[0];
  for (u64 i = 1; i < n; ++i) pxor[i] = pxor[i - 1] ^ a[i];
  std::set<u64> lasts;
  lasts.insert(pxor.back());
  if (pxor.back() == 0) {
    lasts.insert(pxor.begin(), pxor.end());
  }
  std::vector<u64> zo;
  for (u64 i = 0; i < n; ++i) {
    if (pxor[i] == 0) zo.push_back(i);
  }
  std::map<u64, std::vector<u64>> los;
  for (u64 i = 0; i < n; ++i) {
    los[pxor[i]].push_back(i);
  }
  for (auto &last: lasts) {
    u64 cd1sum=0, cd2sum=0;
    std::vector<u64> &lo=los[last];
    std::vector<u64> dp1(n, 0), dp2(n, 0);
    for (u64 j=0,k=0; j<zo.size() || k<lo.size();) {
      u64 i;
      if (j<zo.size()  && zo[j]<lo[k]) {
        i = zo[j];
        ++j;
      }
      else {
        i = lo[k];
        ++k;
      }
      if (pxor[i] == last) {
        dp2[i] = 1+cd1sum;
        dp2[i]%=kMod;
      }
      if (pxor[i] == 0) {
        dp1[i] = cd2sum;
        dp1[i]%=kMod;
        cd1sum+=dp1[i];
        cd1sum%=kMod;
      }
      if (pxor[i] == last) {
        cd2sum+=dp2[i];
        cd2sum%=kMod;
      }
    }
    cnt += (dp2.back() + dp1.back()) % kMod;
    cnt %= kMod;
  }
  std::cout << cnt << std::endl;
  return 0;
}

