            sumx[tar] = 1;
        } else {
            ll cnt = cnt0[i] - cnt0[prv[tar]];
            (sumx[tar] += (cnt * sum0[tar] % MOD + cnt * (cnt + 1) / 2 % MOD * sumx[tar] % MOD)) %= MOD;
        }

        (sum0[tar] += sumx[tar]) %= MOD;

