int get (int x) {
	int res = 0;
	for (; x; x -= x&-x)
		res += fen[x];
	return res;
}

int solve1 (int x) {
	int f1 = 1, f2 = 0;
	for (int i = v[x][0] + 1; i < n; i++) {
		int c1 = f1, c2 = f2;
		if (pr1[i] == x)
			f1 = (f1 + c2) % MO;
		if (pr1[i] == 0) 
			f2 = (c1 + f2) % MO;
	}
	int res = 0;
	if (pr1[n - 1] == x)
		res = (res + f2) % MO;
	if (pr1[n - 1] == 0)
		res = (res + f1) % MO;
	return res;
}

int solve2 (int x) {
	fill(dp, dp + 800, 1);
	int res = 0;
	if (v[x][0] == n - 1 || pr2[v[x][0] + 1] == x)
		res = (res + dp[0]) % MO;		
	for (int i = 1; i < sz(v[x]); i++) {
