		for (int t = 0; t < i; t++) {
			int cnt = get(p) - get(v[x][t] + 1);
			int f = 1LL * dp[t] * cnt % MO;
			dp[i] = (dp[i] + f) % MO;
		}
		if (p == n - 1 || pr2[p + 1] == x)
			res = (res + dp[i]) % MO;
	}
	return res;
}

