        if(i) X[i] ^= X[i - 1];
        if(X[i] == 0) zeros[i]++;
        if(i) zeros[i] += zeros[i - 1];
    }

    // 値v -> (最終位置, 最後に取ったのが0の場合の数, 最後に取ったのがvの場合の数)
    map<i64, tuple<int, int_m, int_m>> m;

    for (int i = 0; i < N; i++) {
        if (X[i] == 0) continue;
        if (!m.count(X[i])) {
            m[X[i]] = make_tuple(i, 1, 1);
        } else {
            int j;
            int_m n0, nv;
            tie(j, n0, nv) = m[X[i]];
            m[X[i]] = make_tuple(i,
                n0 + nv * (zeros[i] - zeros[j]),        // そのまま + 0取る
                n0 + nv * (zeros[i] - zeros[j]) + nv);  // そのまま + V取る + 0取りV取る
        }
    }

    int_m ans = 0;
    if(X[N - 1] == 0) {
        int num = -1;
        for(int i = 0; i < N; i++) {
            if(X[i] == 0) num++;
        }
        ans += powmod(2, num);

        for(auto x : m) {
            int j;
            int_m n0, nv;
            tie(j, n0, nv) = x.second;
            ans += nv;
        }

    } else {
        int j;
        int_m n0, nv;
        tie(j, n0, nv) = m[X[N - 1]];
        ans += n0 + nv * (zeros[N - 1] - zeros[j]);
    }
    cout << ans << endl;
    return 0;
}

