using namespace std;

using mint = ModInt<1000000007>;

int main() {
    int N;
    cin >> N;

    vector<int> S(N + 1);
    S[0] = 0;
    for (int i = 1; i <= N; ++i) {
        int A;
        cin >> A;
        S[i] = S[i - 1] ^ A;
    }
    cerr << S << endl;

    mint ans = 0;
    if (S.back() != 0) {
        vector<vector<mint>> dp(N, vector<mint>(2, 0));
        // dp[i][b] = S[i]まで見た時点で、(b ? 0 : X)にいる

        dp[0][0] = 1;
        for (int i = 1; i < N; ++i) {
            for (int j = 0; j < 2; ++j) dp[i][j] = dp[i - 1][j];

            if (S[i] == S[N]) dp[i][1] += dp[i - 1][0];
            if (S[i] == 0) dp[i][0] += dp[i - 1][1];
        }

        ans = dp[N - 1][1];

    } else {
        terminate();
        mint zero = 0;

        vector<vector<mint>> cnt(1 << 20);
        for (int i = 1; i <= N; ++i) {
            if (S[i] != 0) {
                cnt[S[i]].push_back(zero);
            } else {
                ++zero;
            }
        }

        // X = 0
        ans = mint(2) ^ (zero - 1);

        for (int n = 1; n < (1 << 20); ++n) {
            if (cnt[n].empty()) continue;

            vector<mint> dp(2, 1);
            // dp[b] = i個目のXまで見たときに、(b ? 0 : X)にいる

            for (int i = 1; i < cnt[n].size(); ++i) {
                mint z = cnt[n][i] - cnt[n][i - 1];  // 0の数

                dp[0] += dp[1] * z;  // X -> 0
                dp[1] += dp[0];      // 0 -> X
            }
            ans += dp[1];
        }
    }

    cout << ans << endl;
    return 0;
}

