typedef long long ll;

ll MOD = 1000000007;
ll A[1048576];
ll C[1048576];
ll arr[1048576][2];
int zero_update[1048576];

ll power_mod(a,n){
	if(n == 0){
		return 1;
	}
	ll x = power_mod(a,n/2);
	x = x*x;
	x %= MOD;
	return (n%2 == 0 ? x : (a*x)%MOD);
}

int main(){
	int zero_cnt = 0;
	int U = 1048576;
	int N;
	cin >> N;
	for(i=0;i<N;i++){
		cin >> A[i];
		if(i == 0){
			C[i] = A[i];
		} else {
			C[i] = C[i-1] ^ A[i];
		}
	}
	for(i=0;i<U;i++){
		arr[i][0] = 1;
	}

	for(i=0;i<N;i++){
		int c = C[i];
		if(c == 0){
			zero_cnt++;
			continue;
		}
		int n = zero_cnt - zero_update[c];
		int a = arr[c][0];
		int b = arr[c][1];
		int x = a + n*b;
		int y = b;
		a = x;
		b = a+b;
		a %= MOD;
		b %= MOD;
		arr[c][0] = a;
		arr[c][1] = b;
	}
	ll answer = 0;
	int final = C[N-1];
	if(final != 0){
		answer = arr[final][0];
	} else {
		answer = 0;
		for(i=1;i<U;i++){
			answer += arr[i,1];
			answer %= MOD;
		}
		answer += power_mod(2,zero_cnt-1);
		answer %= MOD;
	}
	cout << answer << endl;
}

