const long long MOD = 1e9 + 7;

ll n;
ll a[500001];
ll p[500001];
ll s[500001];

ll inq(ll x, ll q)
{
    if (q == 0)
        return 1;
    ll l = inq(x, q / 2);
    if (q % 2)
    {
        return l * l % MOD * x % MOD;
    }
    else
    {
        return l * l % MOD;
    }
}

ll dp[500001];

int main()
{
    cin >> n;
    int x = 0;
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
        x = (x ^ a[i]);
        p[i] = x;
    }
    cout << x << endl;
    ll y = 0;
    for (int i = n - 1; i >= 0; i--)
    {
        y = (y ^ a[i]);
        s[i] = y;
    }
    ll ans = 0;
    ll r = 0;
    for (int i = 0; i < n; i++)
    {
        cout << p[i] << " ";
    }
    cout << endl;
    for (int i = 0; i < n; i++)
    {
        cout << s[i] << " ";
    }
    cout << endl;

    for (int i = 0; i < n; i++)
    {
        if (p[i] == 0)
        {
            dp[i] = inq(2, r);
            r++;
        }
    }

    for (int i = 0; i + 1 < n; i++)
    {
        if (s[i + 1] == x)
        {
            ans += dp[i];
        }
    }
    if (x != 0)
        cout << (ans + 1) % MOD;
}

