int buc[N];
int dp[N],s1[N],s2[N];
int solve(vector<int> &p) {
	int m=p.size()-1,ans=0;
	for(int i=0;i<=m;++i) dp[i]=s1[i]=s2[i]=0;
	for(int i=1;i<=m;++i) {
		dp[i]=((buc[p[i]]*(ll)s1[i-1]-s2[i-1]+1)%mod+mod)%mod;
		s1[i]=(s1[i-1]+dp[i])%mod;
		s2[i]=(s2[i-1]+dp[i]*(ll)buc[p[i]]%mod)%mod;
		Add(ans,dp[i]);
	}
	return ans;
}
