ll solve22() {
  while (a.size() > 0 && a.back() == 0) a.pop_back();
  reverse(all(a));
  while (a.size() > 0 && a.back() == 0) a.pop_back();
  reverse(all(a));

  n = a.size();
  if (n == 0) return 0;

  vi b(n + 1);
  rep (i, n) {
    b[i + 1] = b[i] ^ a[i];
  }

  const int log = 20;

  vll dp(1 << log, vl(2));
  rep (i, 1 << log) {
    dp[i][0] = 1;
  }
  vi al(1 << log);

  int cnt = 0;
  rep1 (i, n) {
    if (b[i] == 0) {
      cnt++;
    }
    else {
      int x = b[i];
      (dp[x][0] += (cnt - al[x]) * dp[x][1] % MOD) %= MOD;
      (dp[x][1] += dp[x][0]) %= MOD;
      al[x] = cnt;
    }
  }

  ll res = 0;
  rep (i, 1 << log) {
    if (i == 0) continue;
    (res += dp[i][1]) %= MOD;
  }
  return (res + MOD) % MOD;
}

