constexpr int64_t mod = 1'000'000'007; //'

int64_t mmod(int64_t x, int64_t y){
    if(y==0) return 1;
    if(y==1) return x%mod;
    if(y%2==0) return mmod(x*x%mod, y/2)%mod;
    return mmod(x*x%mod, y/2)%mod * x % mod;
}
int64_t pinv(int64_t x){
    return mmod(x, mod-2);
}

int main(){
    int N;
    cin >> N;
    static int a[500000];
    for(int i=0;i<N;i++) cin >> a[i];

    static int sxor[500001];
    sxor[0] = 0;
    for(int i=1;i<=N;i++) sxor[i] = sxor[i-1] ^ a[i-1];
    for(int i=1;i<=N;i++) cerr << sxor[i] << " ";
    cerr << endl;

    unordered_multimap<int, int> x;
    for(int i=1;i<=N;i++) x.emplace(sxor[i], i);

    auto zeros = x.equal_range(0);

    uint64_t ans = 0;
    for(int xx=0;xx<(2<<20);xx++){
        if(x.count(xx)==0) continue;
        if(sxor[N]!=0 && sxor[N]!=xx) continue;

        if(xx==0){
            int cnt = x.count(0);
            ans += (1LL<<(cnt-1)) % mod;
            ans %= mod;
        }else{
            auto idxs = x.equal_range(xx);

            queue<int> cnt;
            int64_t add = 1;
            vector<pair<int,bool>> q;
            for(auto itz = zeros.first;itz!=zeros.second;++itz){
                q.push_back({itz->second, 0});
            }
            for(auto itx = idxs.first;itx!=idxs.second;++itx){
                q.push_back({itx->second, 1});
            }
            sort(q.begin(), q.end());
            int c=1, prev = 0;
            bool first = true;
            vector<int> cs;
            for(auto qq : q){
                if(qq.second == prev) c++;
                else{
                    if(first && prev==0){
                        c=1;
                        first=false;
                        prev=qq.second;
                    }else{
                        first=false;
                        cs.push_back(c);
                        add *= c;
                        add %= mod;
                        c=1;
                        prev=qq.second;
                    }
                }
            }
            if(cs.size()>=2){
            vector<int64_t> pros;
            int64_t add_orig = add;
            pros.push_back(1);
            for(auto c : cs) pros.push_back(pros.back()*c%mod);
            for(int sk=2;sk<cs.size();sk+=2){
                for(int ss=0;ss+sk<=cs.size();ss++){
                    if(xx==2)
                    cerr << add_orig << " " <<  pros[ss+sk] << " " << pros[ss] << endl;

                    add += add_orig * pros[ss] %mod * pinv(pros[ss+sk]) %mod;
                    add %= mod;
                }
            }}
            ans += add;
            ans %= mod;
        }
    }

    cout << ans << endl;

    return 0;
}

