	EFOR(i,1, N) ruiseki[i]=ruiseki[i-1]^A[i];
	EFOR(i, 1, N) B[ruiseki[i]].pb(i);
	REP(i, B[0].size()) add(B[0][i],1);
	LL ans = 0;
	//EFOR(i, 1, N) cout << ruiseki[i] << " ";
	FOR(i,1, INF) {
		ans += solve2(B[i]);
		ans %= p;
	}
	LL ans2 = 1;
	FOR(i,1, B[0].size()) ans2 = (ans2 * 2) % p;
	if (ruiseki[N]) ans2--;
	//cout << ans << " " << ans2 << endl;
	ans += ans2;
	ans %= p;
	cout << ans << endl;
	return 0;
}
signed main() {

	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(10);
	solve();
	//	cin >> N;
	return 0;
}

