ll solve(const V<ll> &segments, ll segment_cnt, bool lastcut)
{
    M<ll, ll> segcnts;
    set<ll> segset;

    for (auto segment : segments) {
        if (segcnts.find(segment) == segcnts.end()) segcnts[segment] = 0LL;
        segcnts[segment]++;
        segset.insert(segment);
    }

    M<ll, ll> ansm;
    ll prev_incr = 0LL;
    ll prev_cnt = 0LL;
    ll prev_seg = *(segset.begin());

    for (auto segment : segset) {
        ll cnt = segcnts[segment];
        ansm[segment] = cnt;
        ll pp_incr = prev_cnt * (segment - prev_seg);
        pp_incr %= MOD;
        prev_incr += pp_incr;
        prev_incr %= MOD;
        prev_cnt += cnt;
        prev_cnt %= MOD;
        prev_seg = segment;
        ansm[segment] += cnt * prev_incr;
        ansm[segment] %= MOD;
    }

    ll ret = 0LL;
    for (auto am : ansm) {
        ll lastseg = am.first;
        ll incr = am.second;
        if (lastcut) {
            incr *= (segment_cnt - lastseg);
            incr %= MOD;
        }
        ret += incr;
        ret %= MOD;
    }

    return ret;
}

