        ++cnt[pre[i]];
        last[pre[i]] = i;
      } else {
        for (auto it = cnt.begin(); it != cnt.end(); ++it) {
          dp[it->first].push_back(it->second);
        }
        cnt.clear();
      }
    }
  }

  int ans = 1; {
    for (int i = 1; i + 1 < pre.size(); ++i) {
      if (pre[i] == 0) ans = 2LL * ans % M;
