      dpdp[0] = 1;
      for (int i = 0; i < s.size(); ++i) {
        (dpdp[~i & 1] += 1LL * s[i] * dpdp[i & 1] % M) %= M;
      }
      (ans += dpdp[1]) %= M;
    }
  }

  cout << ans << endl;

  return 0;
}

