struct Matrixs {
	Matrix buf[tblsize];
	constexpr Matrixs() :buf{ 0 } {
		Matrix tmp[tblbitcount+1] = { {1,1,0,1} };
		tmp[tblbitcount] = Matrix{1,0,0,1};
		u3 previ = tblsize-1;
		for (u3 i = 0; i < tblsize; ++i) {
			u3 t = i ^ previ;
			t = ((t >> 1) & 0x55555555) + (t & 0x55555555);
			t = ((t >> 2) & 0x33333333) + (t & 0x33333333);
			t = ((t >> 4) & 0xffffffff) + (t & 0xffffffff);
			t = ((t >> 8) & 0x0f0f0f0f) + (t & 0x0f0f0f0f);
			t &= 0x0f;
			for (; t > 0; --t) {
				tmp[t-1] = tmp[t]*mats[(i>>(t-1)) &1]  ;
			}
			buf[i] = tmp[0];
		}
	}
};

constexpr Matrixs tbl;
struct Calc {
	u6 N;

	unordered_map<u3, vector<u3> > stmap;
	vector<u3> zeromap;
	Calc() {
		in >> N;
		//result = 0;
	}
	u6 calcdata(u3 vecindex, vector<u3> & xvec) { 
		auto xite = xvec.begin();
		auto zite = zeromap.begin();
		size_t s = zeromap.size() + xvec.size();
		size_t singleexecuteindex = s-(s % tblbitcount);
		vec state{ 1,0 };
		int matindex=0;
		u3 bit=0;
		u3 bitpat = 0;
		for (size_t i = 0; i < s; ++i) {
			if     (xite == xvec.end()) matindex=1;
			else if(zite == zeromap.end()) matindex = 0;
			else if(*xite < *zite) matindex = 0;
			else matindex = 1;
			if (matindex) { ++zite; bitpat |= 1 << bit; }
			else { ++xite; }
			++bit;
			if (bit == tblbitcount) {
				state *= tbl.buf[bitpat];
				bitpat = 0; bit = 0;
			}else if (i >= singleexecuteindex) {
				state *=  mats[matindex];
			}
		}
		return state.buf[vecindex];
	}
	u6 calc() {
		u3 st = 0;
		u3 tmp;
		for (u3 index = 0; index < N; ++index) {
			in >> tmp;
			st ^= tmp;
			if (!st) {
				zeromap.push_back(index);
			}
			else {
				stmap[st].push_back(index);
			}
		}
		if (st != 0) {
			return calcdata(0, stmap[st]);
		}
		else {
			zeromap.pop_back();
			u6 result = pow2(zeromap.size());
			for (auto & stv: stmap) {
				result = (result + calcdata(1, stv.second))%moduloNo;
			}
			return result;
		}
	}
};

