template <std::uint_fast64_t Modulus> class modint {
  using i64 = std::int_fast64_t;
  using u64 = std::uint_fast64_t;

  static_assert(Modulus < static_cast<u64>(1) << 32,
                "Modulus must be less than 2^32");

  static constexpr u64 normalize(i64 x) noexcept {
    x %= Modulus;
    if (x < 0) {
      x += Modulus;
    }
    return x;
  }

  u64 a;

  constexpr modint &negate() noexcept {
    if (a != 0) {
      a = Modulus - a;
    }
    return *this;
  }

public:
  constexpr modint(const i64 x = 0) noexcept : a(normalize(x)) {}

  constexpr u64 &value() noexcept { return a; }
  constexpr u64 value() const noexcept { return a; }

  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    assert(("modint division by zero", rhs != 0));
    u64 exp = Modulus - 2;
    while (exp != 0) {
      if (exp % 2 == 1) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }

  constexpr modint operator++() noexcept {
    ++a;
    if (a == Modulus) {
      a = 0;
    }
    return *this;
  }
  constexpr modint operator--() noexcept {
    if (a == 0) {
      a = Modulus;
    }
    --a;
    return *this;
  }
  constexpr modint operator++(int) noexcept {
    modint old = *this;
    ++*this;
    return old;
  }
  constexpr modint operator--(int) noexcept {
    modint old = *this;
    --*this;
    return old;
  }

  constexpr modint operator+() const noexcept { return *this; }
  constexpr modint operator-() const noexcept { return modint(*this).negate(); }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }

  constexpr bool operator==(const modint rhs) const noexcept {
    return a == rhs.a;
  }
  constexpr bool operator!=(const modint rhs) const noexcept {
    return a != rhs.a;
  }
};

