	for(int i = 1; i <= N; i += 1){
		if(B[i]){
			SSS[B[i]] = (SSS[B[i]] + 1LL* SS[B[i]] * (S0[i] - S0[L[B[i]]]) % mod) % mod;
			DP[i] = SSS[B[i]] + 1;
			SS[B[i]] = (SS[B[i]] + DP[i]) % mod;
		}
		else{
			if(L[B[i]]) DP[i] = DP[L[B[i]]] * 2 % mod;
			else DP[i] = 1;
		}
		L[B[i]] = i;
	}
	//for(int i = 1; i <= N; i += 1) cout << setw(3) << B[i] << " ";
	//cout << endl;
	//for(int i = 1; i <= N; i += 1) cout << setw(3) << DP[i] << " ";
	//cout << endl;
	ans = DP[N];
	if(B[N] == 0) for(int i = 1; i <= N; i += 1) if(B[i]) add(ans, DP[i]);
	cout << ans;
}

