const int N = (1 << 20), MOD = 1e9 + 7;
int n, a[N], last[N], pr[N], z[N], used[N];
int fact[N], inv[N], rev[N];

void add(int & x, int y) {
	x += y;
	if (x >= MOD) {
		x -= MOD;
	}
}

vi vec, val, dp;

int get(int pos, bool flag) {
	vec.clear();
	while (pos != -1) {
		vec.pb(pos);
		pos = pr[pos];
	}
	reverse(all(vec));
	int m = vec.size();
	val.clear();
	val.pb(0);
	for (int i = 1; i < m; i++) {
		val.pb(z[vec[i] - 1] - z[vec[i - 1]]);
		val[i] += val[i - 1];
	}
	dp.clear();
	dp.resize(m);
	int s = 0, sw = 0, res = 0;
	for (int i = 0; i < m; i++) {
		dp[i] = 1;
		add(dp[i], (ll)s * val[i] % MOD);
		add(dp[i], sw);
		add(res, dp[i]);

		add(s, dp[i]);
		int x = (ll)dp[i] * val[i] % MOD;
		x = (-x + MOD) % MOD;
		add(sw, x);
	}
	if (flag) {
		return dp[m - 1];
	}
	return res;
}

int c(int x, int y) {
	if (x > y) {
		return 0;
	}
	return ((ll)fact[y] * rev[x] % MOD) * rev[y - x] % MOD;
}

