	#ifdef LOCAL
		freopen("input.txt", "r", stdin);
	#endif

	fact[0] = rev[0] = inv[1] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = (ll)fact[i - 1] * i % MOD;
		int r = (i - MOD % i) % i;
		if (i > 1) {
			inv[i] = (ll)inv[r] * ((MOD + r) / i) % MOD;
		}
		rev[i] = (ll)rev[i - 1] * inv[i] % MOD;
	}
	cin >> n;
	memset(& last, -1, sizeof(last));
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		a[i] ^= a[i - 1];
		pr[i] = last[a[i]];
		last[a[i]] = i;
		z[i] = z[i - 1] + (a[i] == 0);
	}
	if (a[n] > 0) {
		cout << get(n, true);
		return 0;
	}
	int res = 0;
	for (int i = n - 1; i >= 1; i--) {
		if (a[i] == 0 || used[a[i]]) {
			continue;
		}
		used[a[i]] = 1;
		add(res, get(i, false));
	}
	for (int i = 1; i <= z[n]; i += 2) {
		add(res, c(i, z[n]));
	}
	cout << res;
}

