template <typename T>
struct bit {
    vector<T> a;
    function<T(T,T)> bin_op;
    explicit bit(int n,
                 function<T(T,T)> bin_op,
                 T init):bin_op(bin_op) {
        a.resize((size_t)n + 1);
        for (int i = 1; i <= n; ++i) a[i] = init;
    }

    T prefix(T x, T init) {
        while (x) {
            init = bin_op(a[x], init);
            x -= x & -x;
        }
        return init;
    }

    T sum(int l, int r) {
        if (l > r) return 0;
        return sum(r) - sum(l - 1);
    }

    void modify(int x, T v) {
        while (x < a.size()) {
            a[x] = bin_op(a[x], v);
            x += x & -x;
        }
    }
    void clear(){
        fill(a.begin(), a.end(), 0);
    }
};

template <typename T>
struct r_bit {
    vector<T> a;
    function<T(T,T)> bin_op;
    explicit r_bit(int n,
                   function<T(T,T)> bin_op,
                   T init):bin_op(move(bin_op)) {
        a.resize((size_t) n + 1);
        for (int i = 1; i <= n; ++i) a[i] = init;
    }

    T suffix(int x, T init) {
        while (x < SZ(a)) {
            init = bin_op(init, a[x]);
//            res += a[x];
            x += x & -x;
        }
        return init;
    }

    T sum(int l, int r) {
        if (l > r) return 0;
        return sum(r) - sum(l - 1);
    }

    void modify(int x, T v) {
        while (x > 0) {
            a[x] = bin_op(a[x], v);
            x -= x & -x;
        }
    }
    void clear(){
        fill(a.begin(), a.end(), 0);
    }
};



vi get_prime(int n) {
    vi minp((ul)n + 1), p;
    for (int i = 2; i <= n; i++) {
        if (!minp[i]) {
            minp[i] = i;
            p.pb(i);
        }
        FOR(x, p) {
            if (x <= minp[i] && x * i <= n)
                minp[x * i] = x;
            else break;
        }
    }
    return p;
}

