int main() {
    FAST_READ
    cout << fixed << setprecision(4);
#ifdef LOCAL
    ifstream in("main.in");
    cin.rdbuf(in.rdbuf());
//    ofstream out("main.out");
//    cout.rdbuf(out.rdbuf());
#endif

    // f[i][j]: number of partitions of a[0..i] s.t. the prefix xor sum is 0, j, 0, j, ..., 0, j; s[i] == j
    // g[i][j]: number of partitions of a[0..i] s.t. the prefix xor sum is 0, j, 0, j, ..., j, 0; s[i] == 0

    // s[i] == j :
    // f[i][j] = sum g[0..i-1][j]
    // s[i] == 0 :
    // g[i][j] = sum f[k][j], k = 0..i-1

    // sf[i][j] := sum f[0..i][j]
    // sg[i][j] := sum g[0..i][j]
    using num = modnum<mod>;
    int n; scan(n);
    vi a(n + 1); up (i, 1, n) scan(a[i]), a[i] ^= a[i-1];

    vi c0(n + 1); rng (i, 1, n + 1) c0[i] = c0[i-1] + (a[i] == 0);


    debug(a[n]);

    vv<num> dp(n + 1, vector<num>(2));
    dp[0][0] = 1;
    num ans = 0;
    // 跳格子
    if (a[n] == 0) {
        debug(a);
        // x = 0
        num tmp = 1;
        rng (i, 1, n) {
            if (a[i] == 0) tmp *= 2;
        }
        ans += tmp;

        // x != 0
        map<int,vi> pos;

        up (i, 1, n) {
            if (a[i] != 0) {
                pos[a[i]].pb(i);
            }
        }

        // run-length encoding
        FOR (x, pos) {
            vpii rle;
            rle.eb(0, 1);
            auto &p = x.second;

//            println(p);

            for (int i = 0; i < SZ(p); ) {
                int j = i; ++i;
                while (i < SZ(p) && c0[p[i]] - c0[p[j]] == 0) ++i;
                rle.eb(1, i - j);
                if (i < SZ(p)) {
                    rle.eb(0, c0[p[i]] - c0[p[j]]);
                }
            }

            rng (i, 1, SZ(rle)) {
                int t = rle[i].first;
                dp[i][t] = dp[i-1][t] + dp[i-1][1-t] * rle[i].second;
                dp[i][1-t] = dp[i - 1][1-t];
            }
            ans += dp[SZ(rle)-1][1];

        }

    }
    else {
        rng (i, 1, n) {
            if (a[i] == a[n]) {
                dp[i][1] = dp[i-1][1] + dp[i-1][0];
                dp[i][0] = dp[i-1][0];
            }
            else if (a[i] == 0) {
                dp[i][1] = dp[i-1][1];
                dp[i][0] = dp[i-1][0] + dp[i-1][1];
            }
            else {
                dp[i] = dp[i-1];
            }
        }
        ans += dp[n - 1][0];
    }

    println(ans);





#ifdef LOCAL
    cout << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
#endif

    return 0;
}

