template <typename T>
T mod_pow(T x, T n, T mod)
{
	T res = 1;
	while (n > 0)
	{
		if (n & 1)
			res = (res * x) % mod;
		x = (x * x) % mod;
		n >>= 1;
	}
	return res;
}

int main()
{
	memset( pool0, 0, sizeof( pool0 ) );
	memset( pool1, 0, sizeof( pool1 ) );
	memset( poolCount, 255, sizeof( poolCount ) );

	ll n;
	cin >> n;
	vector<ll> v(n,0);

	ll sum = 0;
	REP(i,n)
	{
		cin >> v[i];
		sum ^= v[i];
	}

	if( sum != 0 )
	{
		ll left = 0;
		ll count = 0;
		REP(i,n)
		{
			left ^= v[i];
			if( left == sum )
			{
				++count;
				left = 0;
			}
		}

		cout << fib(count) << endl;
	}
	else
	{
		ll left = 0;
		ll count = 0;
		REP(i,cN) pool0[i] = 1;
		REP(i,n)
		{
			left ^= v[i];
			if( left == 0 )
			{
				++count;
			}
			else
			{
				if( poolCount[left] >= 0 )
				{
					pool0[left] = ( pool0[left] + pool1[left] * ( count - poolCount[left] ) ) % cMOD;
				}
				poolCount[left] = count;
				pool1[left] = ( pool1[left] + pool0[left] ) % cMOD;
			}
		}

		ll ans = mod_pow( 2ll, count - 1, cMOD );
		REP(i, cN)
		{
			if( i == 0 ) continue;
			ans = ( ans + pool1[i] ) % cMOD;
		}
		cout << ans << endl;
	}

	return 0;
}

