using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	static const ULL M = 1000000007;

	struct V { ULL Z = 1, U = 0, zp = 0; };

	void Solve() {
		UL N; cin >> N;
		vector<UL> A(N); rep(i, N) cin >> A[i];
		vector<UL> S(N + 1); rep(i, N) S[i + 1] = S[i] ^ A[i];
		if (S[N] != 0) {
			ULL Z = 1, U = 0;
			ULL u = 0;
			rep(i, N) {
				if (S[i + 1] == 0) { Z += U; Z %= M; }
				if (S[i + 1] == S[N]) { u = Z; U += Z; U %= M; }
			}
			cout << u << endl;
		}
		else {
			ULL zn = 0;
			vector<V> Q(1 << 20);
			rep(i, N) {
				if (S[i + 1] == 0) {
					zn++;
				}
				else {
					UL p = S[i + 1];
					Q[p].Z += Q[p].U * (zn - Q[p].zp); Q[p].Z %= M;
					Q[p].U += Q[p].Z; Q[p].U %= M;
					Q[p].zp = zn;
				}
			}
			ULL ans = 0;
			for (V &v : Q) ans += v.U;
			ans %= M;
			ULL ansbuf = 1; rep(i, zn - 1) ansbuf = ansbuf * 2 % M;
			ans += ansbuf;
			ans %= M;
			cout << ans << endl;
		}
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

