      if(x==X || x==0) v[x].pb(x);
    }
    ll p = 0, sx = 0, s0 = 1;
    for(int a:v[X]){
      if(a==x){
        sx = (sx + s0) % MOD;
      }else{
        s0 = (s0 + sx) % MOD;
      }
    }
    cout << s0 << endl;
    return 0;
  }
  X = 0;
  FOR(i, 0, n-1){
    X ^= A[i];
    v[X].pb(i);
  }
  ll ans = 0;
  FOR(i, 1, N){
    if(v[i].empty()) continue;
    int p = -1;
    ll sx = 0, s0 = 1;
    for(int a:v[i]){
      int d = lower_bound(all(v[0]), a) - lower_bound(all(v[0]), p);
      p = a;
      s0 = (s0+sx*d) % MOD;
      sx = (sx + s0) % MOD;
    }
    ans += sx;
  }
  ans = (ans % MOD + modPow(2, sz(v[0]), MOD)) % MOD;
  cout << ans << endl;
}

