        vector<ll> pos(1 << 22, 0);
        vector<ll> zeros(1 << 22, 1);
        ll UNIT = 0;
        auto f  = [](ll l, ll r) { return l + r; };
        SegmentTreeLazyAdd<ll> seg(1 << 22, f, UNIT);
        for (int i = 0; i < na - 1; ++i) {
            if (a[i] == 0) {
                seg.add(0, 1 << 21, 1);
            } else {
                if (pos[a[i]] == 0) {
                    pos[a[i]] = 1;
                    seg.update(a[i], 0);
                } else {
