vector<vector<pair<long long,long long>>> make_vector(vector<long long> C) {
    vector<vector<pair<long long,long long>>> V(1<<20);
    vector<long long> cnt(1<<20,0);
    long long zero = 0;
    for (int i=0;i<C.size();i++) {
        if (C[i] == 0) zero++;
        else {
            long long K = C[i];
            long long t = zero - cnt[K];
            if (t>0) {
                V[K].push_back(make_pair(0,t));
            }
            V[K].push_back(make_pair(K,1));
            cnt[K] = zero;
        }
    }
    for (int K=1;K<(1<<20);K++) {
        long long t = zero - cnt[K];
        if (t>0) V[K].push_back(make_pair(0,t));
    }
    V[0].push_back(make_pair(0,zero));
    return V;
}

pair<long long,long long> dp(vector<pair<long long,long long>> V) {
    vector<pair<long long,long long>> D(V.size()+1, make_pair(0,0));
    D[0].first = 1; D[0].second = 0;
    for (int i=1;i<=V.size();i++) {
        if (V[i-1].first == 0) {
            D[i].first = (D[i-1].first + (D[i-1].second)*(V[i-1].second)) % MOD;
            D[i].second = D[i-1].second;
        } else {
            D[i].first = D[i-1].first;
            D[i].second = (D[i-1].first + D[i-1].second) % MOD;
        }
    }
    return D[V.size()];
}

