			}//这个z是以0结尾，但是前面必须要有x的，故只用z来计算结果，是错误的。我们可以考虑在最后再加一个x，这个x是必取的。然后计算这个x的方案数即可 
			(ret+=o)%=mod;//对于每一个x， 
		}
		(ret+=power(2,zero_cnt[N]-1))%=mod;
		return 0; 
	}
	else
	{
		int tgt=rui.back();ll z=1,o=0;
		for(int i=1;i<N;i++)
		{
			if(rui[i]==0) (z+=o)%=mod;
