	REP(i, n) DEBUG("%2d ", i); DEBUG("\n");
	REP(i, n) DEBUG("%2d ", a[i]); DEBUG("\n");

	ll ans = 0;
	if(a[n-1]){
		ans+=chk(a[n-1], 0);
		ans%=MOD;
	}else{
		REP(i, n) if(a[i]) s.insert(a[i]);
		for(int i:s){
			ans+=chk(i, 1);
			ans%=MOD;
		}
		ll pw = 1;
		REP(i, b[n]-1) pw*=2, pw%=MOD;
		ans+=pw;
		ans%=MOD;
	}
	printf("%lld\n", ans);
}

