void add(ll& x, ll y) {
    if (x>=mod) x%=mod;
    if (y>=mod) y%=mod;
    x += y;
    if (x>=mod) x%=mod;
}

ll pw(ll x, ll y) {
    ll res=1;
    while (y) {
	if (y%2) res=res*x%mod;
	x=x*x%mod;y=y/2;
    }
    return ((res%mod)+mod)%mod;
}


int n;
int a[maxn];
int acc[maxn];


vector<int> inds[maxn];




ll solve(vector<int> a) {
    // count odd length subsequences that alternate: 101..0101, must start and end with 1
    vector<ll> dp(2, 0);
    dp[0] = 1;
    for (int x: a) {
	if (x==0) {
	    dp[0]=(dp[0]+dp[1])%mod;
	} else {
	    dp[1]=(dp[1]+dp[0])%mod;
	}
    }
    return dp[1];
}

