    if(dat[i].size()==0) continue;
    vvl tmp;
    for(auto e:dat[i]) tmp.push_back(vll{e.first, e.second});
    ans = (ans + solve2(tmp))%P;
  }
  std::cout << ans << '\n';
  return 0;
}

