    mint ans = 0;
    for(int i = n;i >= 0;i--){
        if(i == 0)ans += zero;

        if(b[i] == b[n-1]){
            zero += posi;
        }else if(b[i] == 0){
            posi += zero;
        }else{
            continue;
        }
    }
    if(b[n] == 0)ans = (mint)0;
    else{cout << ans.x << '\n';return 0;}

    vector<int> cum(n+1,0);
    for(int i = 0;i <= n;i++){
