                run.emplace_back(i,1);
            }
            run.eb(0,1);
            int m = run.size();
            zero = (mint)1,posi = (mint)0;
            for(int i = m-2;i >= 1;i--){
                if(run[i].first != 0){
                    posi += zero;
                }else{
                    zero += (mint)run[i].second * posi;
                }
            }
            ans += posi;
        }
    }
    cout << ans.x << '\n';
}
