#define BUFSZ   1048586LL
#define MOD     ((ll)(1e9)+7LL)

ll make_acum_seg(V<ll> acum_seg[BUFSZ], ll &total, ll &segment_cnt,
                 const V<ll> &alist, ll n)
{
    ll acum = 0LL;
    ll segment = 0LL;

    for (auto a : alist) {
        acum ^= a;
        if (acum) acum_seg[acum].pb(segment);
        else segment++;
    }

    rep (i, 8) {
        debug_printf("---- acum_seg %lld\n", i);
        debug_print(acum_seg[i]);
    }

    total = acum;
    segment_cnt = segment;

    debug_printf("---- total %lld\n", total);
    debug_printf("---- segment_cnt %lld\n", segment_cnt);
}

ll solve(const V<ll> &segments, ll segment_cnt, bool lastcut)
{
    M<ll, ll> segcnts;
    set<ll> segset;

    for (auto segment : segments) {
        if (segcnts.find(segment) == segcnts.end()) segcnts[segment] = 0LL;
        segcnts[segment]++;
        segset.insert(segment);
    }

    M<ll, ll> ansm;
    ll prev_incr = 0LL;
    ll prev_cnt = 0LL;
    ll prev_seg = -1LL;

    for (auto segment : segset) {
        ll cnt = segcnts[segment];
        ansm[segment] = cnt;
        ll pp_incr = prev_cnt * (segment - prev_seg);
        pp_incr %= MOD;
        prev_incr += pp_incr;
        prev_incr %= MOD;
        debug_printf("prev_incr=%lld pp_incr=%lld\n", prev_incr, pp_incr);
        prev_seg = segment;
        ansm[segment] += cnt * prev_incr;
        ansm[segment] %= MOD;
        prev_cnt += ansm[segment];
        prev_cnt %= MOD;
    }

    ll ret = 0LL;
    for (auto am : ansm) {
        ll lastseg = am.first;
        ll incr = am.second;
        if (lastcut) {
            incr *= (segment_cnt - lastseg);
            incr %= MOD;
        }
        ret += incr;
        ret %= MOD;
    }

    return ret;
}

int _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);

    static V<ll> acum_seg[BUFSZ];
    ll total;
    ll segment_cnt;
    make_acum_seg(acum_seg, total, segment_cnt, alist, n);

    if (total) {
        ll ans = solve(acum_seg[total], segment_cnt, true) + 1LL;
        ans %= MOD;
        cout << ans << endl;
        return 0;
    }

    ll ans = (ll)mod_pow(2LL, segment_cnt - 1LL, MOD);

    rep (divval, BUFSZ) {
        if (acum_seg[divval].empty()) continue;
        ans += solve(acum_seg[divval], segment_cnt, false);
        ans %= MOD;
