template<int MOD> struct Fp {
    long long val;
    constexpr Fp(long long v = 0) noexcept : val(v % MOD) {
        if (val < 0) v += MOD;
    }
    constexpr int getmod() { return MOD; }
    constexpr Fp operator - () const noexcept {
        return val ? MOD - val : 0;
    }
    constexpr Fp operator + (const Fp& r) const noexcept { return Fp(*this) += r; }
    constexpr Fp operator - (const Fp& r) const noexcept { return Fp(*this) -= r; }
    constexpr Fp operator * (const Fp& r) const noexcept { return Fp(*this) *= r; }
    constexpr Fp operator / (const Fp& r) const noexcept { return Fp(*this) /= r; }
    constexpr Fp& operator += (const Fp& r) noexcept {
        val += r.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    constexpr Fp& operator -= (const Fp& r) noexcept {
        val -= r.val;
        if (val < 0) val += MOD;
        return *this;
    }
    constexpr Fp& operator *= (const Fp& r) noexcept {
        val = val * r.val % MOD;
        return *this;
    }
    constexpr Fp& operator /= (const Fp& r) noexcept {
        long long a = r.val, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b; swap(a, b);
            u -= t * v; swap(u, v);
        }
        val = val * u % MOD;
        if (val < 0) val += MOD;
        return *this;
    }
    constexpr bool operator == (const Fp& r) const noexcept {
        return this->val == r.val;
    }
    constexpr bool operator != (const Fp& r) const noexcept {
        return this->val != r.val;
    }
    friend constexpr ostream& operator << (ostream &os, const Fp<MOD>& x) noexcept {
        return os << x.val;
    }
    friend constexpr istream& operator >> (istream &is, Fp<MOD>& x) noexcept {
        return is >> x.val;
    }
    friend constexpr Fp<MOD> modpow(const Fp<MOD> &a, long long n) noexcept {
        if (n == 0) return 1;
        auto t = modpow(a, n / 2);
        t = t * t;
        if (n & 1) t = t * a;
        return t;
    }
};
const int MOD = 1000000007;
using mint = Fp<MOD>;

int n;
vector<int> a, s; //sはaのxorの累積
vector<int> zs; //累積を考えて、[0, i)なるs_k = 0の個数
vector<vector<int>> inds; //s_i == dなるindex

mint subsolve(int d, bool iszero = 1) { //d != 0
    auto p = inds[d];
    int k = (int)p.size();
    vector<int> q(k + 1, 0);
    rep(i, k) {
        q[i] = zs[p[i]] - zs[p[0]];
    }

    vector<mint> dp(k, 0), sdp(k + 1, 0), sdp2(k + 1, 0);
    dp[0] = 1;
    sdp[1] = sdp[0] + dp[0];
    sdp2[1] = sdp2[0] + dp[0] * q[0];
    rep(i, k - 1) {
        dp[i + 1] = 1 + q[i + 1] * sdp[i + 1] - sdp2[i + 1];
        sdp[i + 2] = sdp[i + 1] + dp[i + 1];
        sdp2[i + 2] = sdp2[i + 1] + q[i + 1] * dp[i + 1];
    }
    mint res = 0;
    if(iszero) {
        rep(i, k) {
            res += dp[i];
        }
    } else {
        res = dp.back();
    }

    return res;
}

void solve() {
	cin >> n;
    a.resize(n);
    rep(i, n) {
        cin >> a[i];
    }
    s.assign(n + 1, 0);
    rep(i, n) {
        s[i + 1] = s[i] ^ a[i];
    }
    zs.assign(n + 2, 0);
    rep(i, n + 1) {
        zs[i + 1] = zs[i] + (s[i] == 0);
    }
    inds.assign((1<<20) + 1, vector<int>());
    rep(i, n + 1) {
        inds[s[i]].push_back(i);
    }

    mint ans = 0;
    if(s.back() == 0) {
        int zeronum = (int)inds[0].size() - 2;
        ans += modpow(mint(2), zeronum);
        for(int d = 1; d <= (1<<20); ++d) {
            if(inds[d].empty()) continue;
            ans += subsolve(d);
        }
    } else {
        ans = subsolve(s.back(), 0);
    }

    cout << ans << endl;
}

