const int mod = 1000000007;

map <int, vector <int> > mp;
int sum[100010];

long long power(long long a, long long b){
	if (!b) return 1;
	long long t = power(a, b >> 1);
	return b & 1 ? t * t % mod * a % mod : t * t % mod;
}

int main(){
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; i++){
		int x; scanf("%d", &x);
		sum[i] = sum[i - 1] ^ x;
		mp[sum[i]].push_back(i);
	}
	if (sum[n] != 0){
		vector <int> a = mp[0], b = mp[sum[n]];
		int tot = 1, now = b[0];
		while (1){
			int pos = lower_bound(a.begin(), a.end(), now) - a.begin();
			if (pos == a.size()) break;
			tot++;
			now = a[pos];
			pos = lower_bound(b.begin(), b.end(), now) - b.begin();
			if (pos == b.size()) break;
			tot++;
			now = b[pos];
		}
		printf("%lld\n", power(2, tot - 1));
		return 0;
	}
	long long ans = 0;
	vector <int> a = mp[0];
	for (map <int, vector <int> > :: iterator it = mp.begin(); it != mp.end(); it++){
		if (it->fi == 0){
			ans = (ans + power(2, it->se.size() - 1)) % mod;
			continue;
		}
		vector <int> b = it->se;
		int m = b.size() * 2;
		b.push_back(0x3f3f3f3f);
		vector <long long> sum1(m + 1, 0), sum2(m + 1, 0), dp(m + 1, 0);
		dp[0] = 1, sum2[0] = 1;
		long long res = 0;
		for (int i = 1; i <= m; i++){
			int cnt;
			if (i & 1) cnt = 1;
			else {
				vector <int> :: iterator pos1 = lower_bound(a.begin(), a.end(), b[i + 1 >> 1]);
				cnt = pos1 - lower_bound(a.begin(), a.end(), b[i - 1 >> 1]);
			}
			if (i & 1){
				dp[i] = sum2[i - 1] * cnt % mod;
				sum2[i] = sum2[i - 1];
				sum1[i] = (sum1[i - 1] + dp[i]) % mod;
			} else {
				dp[i] = sum1[i - 1] * cnt % mod;
				sum1[i] = sum1[i - 1];
				sum2[i] = (sum2[i - 1] + dp[i]) % mod;
			}
			if (i == m) res = dp[i] / cnt;
		}
		ans = (ans + res) % mod;
	}
	printf("%lld\n", ans);
	return 0;
}

