	if(PX) cout<<D[PX]<<'\n';
	else {
		int ans=1;
		for(int i=2;i<PS[N];i++) ans=(2*ans)%MOD;
		for(int i=(1<<20)-1;i;i--) ans=(ans+Dsum[i])%MOD;
		cout<<ans<<'\n';
	}
	return 0;
}

