typedef long long ll;

const ll MOD = 1000000007;

int cumsum[500001];
vector<int> idx[1<<20];

ll pow2[500001];
ll cnt0[500001];
ll dp[500000];

void init(){
    pow2[0] = 1;
    for(int i = 1; i <= 500000; i++){
        pow2[i] = pow2[i-1]*2;
        pow2[i]%=MOD;
    }
}

int zeros(int l, int r){
    return cnt0[r+1]-cnt0[l];
}

int main(){
    init();
    int N;
    cin >> N;
    for(int i = 0; i < N; i++){
        int a;
        cin >> a;
        cumsum[i+1] = cumsum[i]^a;
        idx[cumsum[i+1]].push_back(i);
        if(cumsum[i+1] == 0){
            cnt0[i+1] = cnt0[i]+1;
        }else{
            cnt0[i+1] = cnt0[i];
        }
    }

    ll ans = 0;
    if(cumsum[N] == 0){
        ans = pow2[cnt0[N]-1];
        for(int i = 1; i < (1<<20); i++){
            for(int j = 0; j < idx[i].size(); j++) dp[j] = 0;
            dp[0] = 1;
            ll add = 0;
            ll sum_dp = 1;
            for(int j = 1; j < idx[i].size(); j++){
                add += sum_dp*zeros(idx[i][j-1], idx[i][j]);
                add %= MOD;
                //add += dp[j-1]*zeros(idx[i][j-1], idx[i][j]);
                //add %= MOD;
                dp[j] = add+1;
                sum_dp += dp[j];
                sum_dp %= MOD;
            }
            for(int j = 0; j < idx[i].size(); j++) {
                ans += dp[j];
                ans %= MOD;
            }
        }
    }else{
        int i = cumsum[N];
        for(int j = 0; j < idx[i].size(); j++) dp[j] = 0;
            dp[0] = 1;
            ll add = 0;
            ll sum_dp = 1;
            for(int j = 1; j < idx[i].size(); j++){
                add += sum_dp*zeros(idx[i][j-1], idx[i][j]);
                add %= MOD;
                //add += dp[j-1]*zeros(idx[i][j-1], idx[i][j]);
                //add %= MOD;
                dp[j] = add+1;
                sum_dp += dp[j];
                sum_dp %= MOD;
            }
            for(int j = 0; j < idx[i].size(); j++) {
                if(idx[i][j] != N-1) ans += (dp[j]*zeros(idx[i][j], N-1));
                else ans += dp[j];
                ans %= MOD;
        }
    }
    cout << ans << endl;
}

