using namespace std;
int n,a[10005],k,j,s,p;
long long g,i,t[10005],ans[10005];
int gcd(int a,int b)
{
	if(b==0)
		return a;
	return gcd(b,a%b);
}
int main()
{
	scanf("%d",&n);
	for(i=n;i>=0;--i)
	{
		scanf("%d",&a[i]);
		g=gcd(a[i],g);
	}
	for(i=2;i*i<=g;++i)
		if(g%i==0)
		{
			while(g%i==0)
				g/=i;
			ans[++k]=i;
		}
	if(g!=1)
		ans[++k]=g;
	if(a[0]==0)
	{
		for(i=0;i<=n;++i)
			g+=a[i];
	}
	else	
		g=a[0];
	for(i=2;i*i<=g;++i)
		if(g%i==0)
		{
			while(g%i==0)
				g/=i;
			t[++p]=i;
		}
	if(g!=1)
		t[++p]=g;
	for(i=1;i<=p;++i)
	{
		for(j=1;j<=k;++j)
			if(ans[j]==t[i])
				break;
		if(j<=k)
			continue;
		s=0;
		for(j=0;j<n;++j)
		{
			for(int m=n;m>=0;--m)
				s=(1ll*s*j+a[m])%t[i];
			if(s)
				break;
		}
		if(j==n)
			ans[++k]=t[i];
	}
	sort(ans+1,ans+1+k);
	for(i=1;i<=k;++i)
		cout<<ans[i]<<endl;
}

