	for (int i = 0; i < N; ++i) {
		cin >> SA[i + 1];
		SA[i + 1] ^= SA[i];
		G[SA[i]].push_back(i);
	}
	int sz = 1;
	while (sz < N) sz *= 2;
	vector<matrix<modulo> > seg(sz * 2, unit<modulo>(2));
	function<void(int, matrix<modulo>)> update = [&](int pos, matrix<modulo> d) {
		pos += sz;
		seg[pos] = d;
		while (pos > 1) {
			pos >>= 1;
			seg[pos] = seg[pos * 2] * seg[pos * 2 + 1];
		}
	};
	int cnt = 0;
	for (int i = 0; i < N; ++i) {
		if (SA[i] == 0) {
			matrix<modulo> mat(2);
			if (i != 0) mat = unit<modulo>(2);
			mat.entry(0, 1) = modulo(1);
			update(i, mat);
			++cnt;
		}
	}
	modulo ans = 0;
	if (SA[N] == 0) ans += modulo(2).pow(cnt - 1);
	for (int i = 1; i < limit; ++i) {
