                    dp[i] = p[i];
                    dp2[i] = p[i];
                }else if(i==1){
                    dp[i] = dp2[i-1]*p[i]%mod;
                    dp2[i] = dp[i];
                }else{
                    if(i%2==0){
                        dp[i] = p[i]*(dp2[i-1]+1)%mod; 
                    }else{
                        dp[i] = p[i]*(dp2[i-1])%mod; 
                    }
                    dp2[i] = dp2[i-2]+dp[i];
                    dp2[i]%=mod;
                }
            }
            // for(auto x:p){
            //     cerr << x << " ";
            // }
            // cerr << endl;
            res += dp2[m-1];
            res %= mod;
        }
    }

    cout << res << endl;
    return 0;
}

