            //cout << i << " " << u[i] << " " << dp[i] << endl;;
            if ((i+1) & 1) {
                dp[i+1] = (sumodd) * (u[i]+1) % mod;
                sumeven = (sumeven + dp[i+1]) % mod;
            } else {
                dp[i+1] = (sumeven * (u[i]+1)) % mod;
                sumodd = (sumodd + dp[i+1]) % mod;
            }
        }
        //cout << endl;
        cout << dp[u.size()] << endl;
    }
    return 0;
}

