const int MAX_N=1e6+1;
int A[MAX_N],cum[MAX_N];
int N;

const int MAX_V=(1<<20)+1;
vector<int> P[MAX_V];
ModInt f(int X, int sum) {
  int L=SZ(P[X]);
  if(L==0) return 0;
  ModInt cum2[2]={1,1};
  FOR(i,1,L) {
    int p=P[X][i],cnt0=cum[p]-cum[P[X][i-1]];
    cum2[0]+=cum2[1]*cnt0;
    cum2[1]+=cum2[0];
  }
  return sum==0?cum2[1]:cum2[0];
}
void solve() {
  int sum=0;
  cum[0]=1;
  REP(i,N) {
    sum^=A[i];
    cum[i+1]=cum[i]+(sum==0);
    if(sum!=0) P[sum].push_back(i);
  }
//  dump(sum,cum[N]);
  if(sum!=0) {
    ModInt res=f(sum,sum);
    cout<<res<<endl;
  } else {
    ModInt res=ModInt(2).pow(cum[N]-2);
    FOR(v,1,MAX_V) {
      ModInt x=f(v,sum);
      if(x.val!=0) {
//        dump(v,x);
//        dumpc(P[v]);
      }
      res+=x;
    }
    cout<<res<<endl;
  }
}

