using namespace std;
template <class T> void rd(T &x){
  x = 0; int f = 1; char ch = getchar();
  while(ch < '0' || ch > '9'){ if(ch == '-') f = -1; ch = getchar(); }
  while(ch >= '0' && ch <= '9') x = (x << 1) + (x << 3) + ch - '0', ch = getchar();
  x *= f;
}

typedef long long ll;
const int mod = 1e9 + 7;
const int maxn = 5e5 + 5;
int n;
int a[maxn], c[maxn];
ll ans;
vector <int> st[1048576 + 5];

void add(ll &a, ll b){ a = (a + b) % mod; }

ll qpow(ll x, ll n){ ll y = 1;
  for(; n; n >>= 1, x = x * x % mod)
	if(n & 1) y = y * x % mod;
  return y;
}

void work(int x, int op){
  if(!st[x].size()) return ;
  ll s0, s1;
  s0 = s1 = 0;
  for(int i = 0; i < st[x].size(); ++ i){
	int p = st[x][i];
	add(s1, s0 + 1);
	if(i < st[x].size() - 1){
	  add(s0, (c[st[x][i + 1]] - c[p]) * s1);
	}
  } 
  if(op) add(ans, s1);
  else add(ans, s0 + 1);
}

int main(){
  rd(n);
  rep(i, 1, n){
	rd(a[i]), a[i] ^= a[i - 1];
	st[a[i]].push_back(i);
	if(a[i] == 0) c[i] ++;
	c[i] += c[i - 1];
  }
  if(a[n]) work(a[n], 0);
  else{
	int all = (1 << 20) - 1;
	rep(i, 1, all) work(i, 1);
	ans = (ans + qpow(2, c[n] - 1)) % mod;
  }
  printf("%lld\n", ans);
  return 0;
}

