    dp0.add(1, (1<<21), 1);

    for(int i = 1; i <= n-1; ++i){
        if(a[i] == 0) nb.add(1, (1<<21), 1);
        else{
			int nbqu = nb.query(a[i]+1, a[i]+1);
            dp0.add(a[i]+1, a[i]+1, ((LL)nbqu * dp1[a[i]]) %MOD);
            nb.add(a[i]+1, a[i]+1, -nbqu);

            dp1[a[i]] = ((LL)dp1[a[i]] + dp0.query(a[i]+1, a[i]+1)) %MOD;
        }
    }

    int ans = 0;
    if(a[n] > 0) ans = dp1[a[n]];
    else{
		for(int x = 0; x < (1<<21); ++x) ans = (ans + dp1[x]) %MOD;

		int tmp = 0;
		for(int i = 1; i <= n-1; ++i) tmp+=(a[i]==0);

		int extra = 1;
		for(int i = 1; i <= tmp; ++i) extra = ((LL)extra * 2) %MOD;
		ans = (ans + extra) %MOD;
	}
    write(ans, "\n");

    return 0;
}

