#define MOD 1000000007

ll calc(ll xor_value, ll start, ll N)
{
    ll ret = 0;
    if (start == N) {
        return 0;
    }
    if (start == N - 1) {
        if (xor_value == A[start])
        return 1;
    }
    ll xor1 = C[N] ^ C[start];
    if (xor1 == xor_value) {
        ret = (ret + 1) % MOD;
    }
    for (ll i = start + 1; i < N; ++i) {
        xor1 = C[i] ^ C[start];  // [0,i)
        if (xor1 == xor_value) {
            ret = (ret + calc(xor_value, i + 1, N)) % MOD;
        }
    }
    return ret;
}

ll solve()
{
    ll N;
    ll ans = 0;
    cin >> N;
    for (ll i = 0; i < N; ++i) {
        cin >> A[i];
    }
    C[0] = 0;
    for (ll i = 0; i < N; ++i) {
        C[i+1] = C[i] ^ A[i];
    }
    ans = 1;
    for (ll i = 1; i < N; ++i) {
        ll xor_value = C[i] ^ C[0]; // [0,i)
        ans = (ans + calc(xor_value, i, N)) % MOD;
    }

    return ans;
}

