		if(A[n-1]!=0&&A[n-1]!=i) continue;
		ll odd=0,even=1;
		int bef=0;
		for(int j=0;j<pos[i].size();j++)
		{
			int to=pos[i][j];
			even+=odd*(ll) get(bef,to-1)%MOD;
			if(even>=MOD) even-=MOD;
			odd+=even;
			if(odd>=MOD) odd-=MOD;
			bef=to+1;
		}
		//printf("%lld %lld\n",odd,even);
		if(A[n-1]==0)
		{
			ret+=odd;
			ret%=MOD;
		}
		else
		{
			ret+=even;
			ret%=MOD;
		}
	}
	printf("%lld\n",ret);
	return 0;
}

