const int LOGN    =  16              + 1;
const int MAXN1   =  (1<<20)            + 3;
const int MAXN2   =  5e5            + 3;
int dp1[MAXN1];
int a[MAXN2];
SEGTREE dp0(MAXN1), nb(MAXN1);
// ------------------------------------------------- Fs
int32_t main() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0); write(fixed, setprecision(12));
    int n; read(n);
    for(int i = 1; i <= n; ++i){ read(a[i]); a[i] ^= a[i-1]; }

    dp0.add(1, (1<<20), 1);

    for(int i = 1; i <= n-1; ++i){
        if(a[i] == 0) nb.add(1, (1<<20), 1);
        else{
			int nbqu = nb.query(a[i]+1,a[i]+1);
            dp0.add(a[i]+1, a[i]+1, ((LL)nbqu * dp1[a[i]]) %MOD);
            nb.add(a[i]+1, a[i]+1, (-nbqu+MOD) %MOD);

            dp1[a[i]] = ((LL)dp1[a[i]] + dp0.query(a[i]+1,a[i]+1)) %MOD;
        }
    }

    int ans = 0;
    if(a[n] > 0) ans = dp0.query(a[n]+1, a[n]+1);
    else{
		for(int x = 0; x < (1<<20); ++x) ans = (ans + dp1[x]) %MOD;

		int tmp = 0;
		for(int i = 1; i <= n-1; ++i) tmp+=(a[i]==0);

		int extra = 1;
		for(int i = 1; i <= tmp; ++i) extra = ((LL)extra * 2) %MOD;
		ans = (ans + extra) %MOD;
	}
    write(ans, "\n");

    return 0;
}

