    for (int j = M - 1; j >= 0; --j) {
      bits.push_back((i >> j) & 1);
    }

    vector<int> sums;
    int sum = A[0];
    for (int j = 0; j < M; ++j) {
      if (bits[j] == 0) {
    	sum ^= A[j + 1];
      } else {
    	sums.push_back(sum);
    	sum = A[j + 1];
      }
    }
    sums.push_back(sum);

    bool happy = true;
    for (int j = 1; j < (int)sums.size(); ++j) {
      if (sums[j - 1] != sums[j]) {
    	happy = false;
    	break;
      }
    }
    if (happy) ++ans;
  }

  cout << ans << endl;

  return 0;
}

