				++count;
			}
			else
			{
				if( poolCount[left] >= 0 )
				{
					pool0[left] = ( pool0[left] + pool1[left] * ( count - poolCount[left] ) ) % cMOD;
				}
				poolCount[left] = count;
				pool1[left] = ( pool1[left] + pool0[left] + 1 ) % cMOD;
			}
		}

		ll ans = mod_pow( 2ll, count - 1, cMOD );
		REP(i, cN)
		{
			if( i == 0 ) continue;
			ans = ( ans + pool1[i] ) % cMOD;
		}
		cout << ans << endl;
	}

	return 0;
}

