ModInt<> solve() {
  // nonzero
  if (s) {
    vector<ModInt<>> dp(n + 1, 1);
    {
      ModInt<> sum[2] = {1, 1};
      for (int i = 2; i <= n; ++i) {
        dp[i] = sum[i & 1 ^ 1];
        sum[i & 1] += dp[i];
      }
    }
    int now = 0, cnt = 0;
    for (int i = 0; i < n; ++i) {
      now ^= a[i];
      if (now == s) {
        now = 0;
        ++cnt;
      }
    }
    return dp[cnt];
  }
  ModInt<> res;
  // zero(zero)
  {
    int now = 0, zero = 0;
    for (int i = 0; i < n; ++i) {
      now ^= a[i];
      if (!now) ++zero;
    }
    res += ModInt<>(2).pow(zero - 1);
  }
  // zero(nonzero)
  {
    int now = 0, zero = 0;
    vector<int> cnt(1 << 21, 0);
    vector<vector<ModInt<>>> dp(2, vector<ModInt<>>(1 << 21, 1));
    dp[1].assign(1 << 21, 0);
    for (int i = 0; i < n; ++i) {
      now ^= a[i];
      if (now) {
        dp[0][now] += dp[1][now] * (zero - cnt[now]);
        dp[1][now] += dp[0][now];
        cnt[now] = zero;
      } else
        ++zero;
    }
    for (auto p : dp[1]) res += p;
  }
  return res;
}

