  }

  vector<int> z(n);
  for(int i=0; i<n; i++){
    if(i) z[i] = z[i-1];
    z[i] += b[i] == 0;
  }

  map<int, vector<int>> d;
  for(int i=0; i<n; i++){
    d[b[i]].push_back(i);
  }

