  rep(i, MAXStir2){
    Bellmemo[i] = 0;
    rep(j,i+1) Bellmemo[i] += Stir2memo[i][j];
  }
}
mint Stir2(ll i, ll j){//区別できるi個をjグループに分ける場合の数
  if(i < 0 || j < 0 || i < j) return 0;
  return Stir2memo[i][j];
}
mint Bell(ll x){//区別できるx個をグループ分けする方法全ての場合の数
  if(x < 0) return 0;
  return Bellmemo[x];
}
mint kai_mod(ll K){
  if(K < 0) return 0;
  if(K == 0) return 1;
  return kai_mod(K-1) * K;
}

//約数の列挙O(√n)
vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}


void compress(vector<ll> &S){
  vector<ll> xs;
  rep(i, S.size()) xs.push_back(S[i]);
  sort(xs.begin(), xs.end());
  xs.erase(unique(xs.begin(), xs.end()), xs.end());
  rep(i, S.size()){
    S[i] = lower_bound(xs.begin(), xs.end(), S[i]) - xs.begin();
  }
}


//Range Sum Query
const ll N_ = (1 << 20);
ll seg[2*N_-1];
void add(ll k, ll x){
  k += N_-1;
  seg[k] += x;
  while(k > 0){
    k = (k-1)/2;
    seg[k] = seg[2*k+1] + seg[2*k+2];
  }
}

ll get_sum(ll x, ll y, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return 0;
  if(x <= left && right <= y) return seg[k];
  ll mid = (left + right) / 2;
  ll l = get_sum(x, y, 2*k+1, left, mid);
  ll r = get_sum(x, y, 2*k+2, mid, right);
  return l + r;
}


ll N;
vector<ll> A;
void solve(){
  ll XOR = 0;
  ll cnt = 0;
  rep(i, N) XOR ^= A[i];
  if(XOR == 0){
    ll x = 0;
    vector<ll> B;
    ll now = 0;
    rep(i, N){
      now ^= A[i];
      B.pb(now);
      if(now == 0){
        add(i, 1);
        cnt++;
      }
    }
    compress(B);
    ll X = *max_element(B.begin(), B.end());
    vector<ll> L[X+1];
    rep(i, N){
      if(B[i] == 0) continue;
      L[B[i]].pb(i);
    }
    rep(i, X+1) L[i].pb(N_);
    mint ans = 0;
    for(ll i = 1; i <= X; i++){
      if(L[i].size() == 1) continue;
      mint s = 0, t = 1;
      for(ll j = 0; j < L[i].size() - 1; j++){
        ll x = get_sum(L[i][j], L[i][j+1]);
        s += t;
        t += s * x;
      }
      ans += s;
    }
    ans += pow_mod(2, cnt-1);
    ans.get();
  }else{
    ll a = XOR;
    ll b = 0;
    ll now = 0;
    mint s = 0, t = 1;
    rep(i, N-1){
      now ^= A[i];
      if(now == a){
        s += t;
      }
      else if(now == b){
        t += s;
      }
    }
    t.get();
  }
}

