            if (j == n - 1 || ((1ll << j) & i)) {
                xs.insert(curX);
                curX = 0;
            }
        }
        ans += (xs.size() == 1);
    }

    return ans;
}

ll bpow(ll vl, ll pw, ll md = MOD) {
    if (pw == 0) {
        return 1;
    } else if (pw % 2 == 1) {
        ll a = bpow(vl, pw - 1, md);
        return (a * vl) % MOD;
    } else {
        ll b = bpow(vl, pw / 2, md);
        return (b * b) % MOD;
    }
}

ll sol() {
    ll x = 0, mx = 0;
    for (int i = 0; i < n; i++) {
        x ^= vec[i];
        mx = max(mx, vec[i]);
    }

    if (x == 0) {
        ll curInd = 0, pr = -1;
        vector<vector<ll>> cnt;
        cnt.resize(mx * 2 + 2);

        ll curX = 0;
        vector<pair<ll, ll>> bls;
        for (int i = 0; i < n; i++) {
            curX ^= vec[i];
            if (curX == 0) {
                bls.push_back({pr + 1, i});
                pr = i;
            }
        }

        ll i = 0;
        for (auto cur : bls) {
            ll curX = 0;
            for (int j = cur.first; j <= cur.second; j++) {
                curX ^= vec[j];
                cnt[curX].push_back(i);
            }
            i++;
        }

        ll ans = 0;
        for (int i = 0; i < cnt.size(); i++) {
            if (cnt[i].size() == 0) {
                continue;
            }
            pair<ll, ll> brd = {INF, -INF};
            for (auto cur : cnt[i]) {
                brd.first = min(brd.first, cur);
                brd.second = min(brd.second, cur);
            }

            ll curn = (brd.second - brd.first + 1);
            ll add = 0, l = 0;
            sort(cnt[i].begin(), cnt[i].end());
            for (int j = cnt[i].size() - 2; j >= 0; j--) {
                l += abs(cnt[i][j] - cnt[i][j + 1]);
                add += l;
            }
            ans += (bpow(2, cnt[i].size()) - 1 + MOD + l) % MOD;
            ans %= MOD;
        }

        return ans;
    } else {
        ll curX = 0, cnt = 0, cnt2 = 0;
        vector<ll> vals;
        for (int i = 0; i < n; i++) {
            curX ^= vec[i];
            if (curX == 0) {
                cnt2++;
                vals.push_back(0);
            }
            else if (curX == x) {
                cnt++;
                vals.push_back(1);
                curX = 0;
            }
        }

        ll dp[2];
        dp[0] = 1;
        dp[1] = 0;
        ll pr = 0;
        for (auto cur : vals) {
            ll pr1 = dp[0], pr2 = dp[1];
            if (cur == 0) {
                dp[0] = pr1 + pr2;
            } else {
                dp[1] = pr2 + pr1;
                dp[0] = pr2;
                pr = 0;
            }
            dp[0] %= MOD;
            dp[1] %= MOD;
        }

        return dp[1];
    }
}

