void stress(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	vector<int> arr(n);

	for (auto &it : arr)
		cin >> it;

	vector<int> px(n + 1);

	for (int i = 1; i < (int) px.size(); i++)
		px[i] = px[i - 1] ^ arr[i - 1];

	vector<vector<int>> pos(1 << 20);

	for (int i = 0; i < (int) px.size(); i++)
		pos[px[i]].push_back(i);

	ll ans = 0;

	for (int x = 0; x < (int) pos.size(); x++)
		if (!pos[x].empty() && (pos[x].back() == n || pos[0].back() == n))
		{
			if (x == 0)
				ans += powmod(2, pos[0].size() - 2);
			else
			{
				int z = 0, y = 0, sz = 1, sy = 0;

				while (z < (int) pos[0].size() || y < (int) pos[x].size())
				{
					if (z < (int) pos[0].size() && (y == (int) pos[x].size() || pos[0][z] < pos[x][y]))
					{
						sz += sy;
						if (sz >= inf)
							sz -= inf;
						z++;
					}
					else
					{
						sy += sz;
						if (sy >= inf)
							sy -= inf;
						y++;
					}
				}

				ans += (pos[0].back() == n ? sy : sz);
			}
		}

	cout << ans % inf << endl;
}


void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	vector<int> arr(n);

	for (auto &it : arr)
		cin >> it;

	vector<int> px(n + 1), pz(n + 2);

	for (int i = 1; i < (int) px.size(); i++)
		px[i] = px[i - 1] ^ arr[i - 1];
	for (int i = 1; i < (int) pz.size(); i++)
		pz[i] = pz[i - 1] + (px[i - 1] == 0 ? 1 : 0);

	vector<vector<int>> pos(1u << 20u);

	for (int i = 0; i < (int) px.size(); i++)
		pos[px[i]].push_back(i);

	ll ans = 0;

	for (int x = 0; x < (int) pos.size(); x++)
		if (!pos[x].empty() && (pos[x].back() == n || pos[0].back() == n))
		{
			if (x == 0)
				ans += powmod(2, pos[0].size() - 2);
			else
			{
				ll z = 0, y = 0, sz = 1, sy = 0;

				while (z < (int) pos[0].size() || y < (int) pos[x].size())
				{
					if (z < (int) pos[0].size() && (y == (int) pos[x].size() || pos[0][z] < pos[x][y]))
					{
						int ny = (y == (int) pos[x].size() ? n + 1 : pos[x][y]);
						int add = pz[ny] - pz[pos[0][z]];

						sz += add * (ll) sy;
						sz %= inf;
						z += add;
					}
					else
					{
						sy += sz;
						if (sy >= inf)
							sy -= inf;
						y++;
					}
				}

				ans += (pos[0].back() == n ? sy : sz);
			}
		}

	cout << ans % inf << endl;
}


