    for(i=1; i<n; i++) {
        if(s[i]!=0) {
            int prev=z[s[i]];
            int num0 = s0[i]-s0[prev];
            {
                dp0[i]=(dp[prev]*(num0+1)+dp0[prev])%MOD;
                dp[i]=(dp[prev]*(num0+1)+dp0[prev])%MOD;
            }
            z[s[i]]=i;
            save.insert(i);
            save.erase(prev);
        }
    }

    ll ans=0;
    if(s[n]==0) {
        ans=1;
        for(i=0; i<s0[n]-2; i++) {
            ans = ans*2%MOD;
        }
        ans--;
    }

    auto it=save.begin();
    for(; it!=save.end(); ++it) {
        if(s[n]==0) {
            ans = (ans + dp[*it])%MOD;
        }
        else if(s[n]==s[*it]) {
            int num0 = s0[n]-s0[*it];
            ans = (ans + dp0[*it] + dp[*it]*num0)%MOD;
        }
