const long long md = 1e9 + 7;
const int CC = 21;

int n;
long long dp[500005];
long long ans;
int a[500005], b[500005];
vector<int> v[(1 << CC) + 5];

void solve(int x) {
    long long res = 0, s = 0, ss = 0;
    long long cur = 0;
    long long xx;
    for (int i = 0; i < (int)v[x].size(); ++i) {
        xx = v[x][i];
        cur = ss * dp[xx];
        cur %= md;
        cur -= s;
        if (cur < 0) cur += md;
        ++cur;
        if (cur == md) cur = 0;
        if (xx == n) {
            ans += cur;
            if (ans >= md) ans -= md;
        } else if (b[n] == 0) {
            ans += cur;
            if (ans >= md) ans -= md;
        }
        ss += cur;
        if (ss >= md) ss -= md;
        s += cur * dp[xx];
        s %= md;
    }
    return;
}

