        if (b[i] == 0) {
            if (i != n)
            c += c;
            if (c >= md) c -= md;
            ++dp[i];
        } else {
            v[b[i]].push_back(i);
            if ((int)v[b[i]].size() == 1) q.push_back(b[i]);
        }
