vector<vector<mint>> Stir2memo(MAXStir2, vector<mint>(MAXStir2, Mint));
vector<mint> Bellmemo(MAXStir2, Mint);
void Stir2init(){
  Stir2memo[0][0] = 1;
  rep(i, MAXStir2-1)rep(j, i+1)Stir2memo[i+1][j+1] = Stir2memo[i][j] + Stir2memo[i][j+1] * (j+1);
  rep(i, MAXStir2){
    Bellmemo[i] = 0;
    rep(j,i+1) Bellmemo[i] += Stir2memo[i][j];
  }
}
mint Stir2(ll i, ll j){//区別できるi個をjグループに分ける場合の数
  if(i < 0 || j < 0 || i < j) return 0;
  return Stir2memo[i][j];
}
mint Bell(ll x){//区別できるx個をグループ分けする方法全ての場合の数
  if(x < 0) return 0;
  return Bellmemo[x];
}
mint kai_mod(ll K){
  if(K < 0) return 0;
  if(K == 0) return 1;
  return kai_mod(K-1) * K;
}

//約数の列挙O(√n)
vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}
ll N;
vector<ll> A;

void solve(){
  ll XOR = 0;
  ll cnt = 0;
  rep(i, N) XOR ^= A[i];
  if(XOR == 0){
    assert(XOR != 0);
    set<ll> B;
    ll now = 0;
    rep(i, N){
      now ^= A[i];
      B.insert(now);
      if(now == 0) cnt++;
    }
    mint ans = 0;
    for(auto itr = B.begin(); itr != B.end(); itr++){
      ll a = *itr;
      if(a == 0) continue;
      ll b = 0;
      ll now = 0;
      mint s = 0, t = 0;
      rep(i, N){
        now ^= A[i];
        if(now == a){
          s += t + 1;
        }
        if(now == b && s != 0){
          t += s;
        }
      }
      ans += s;
    }
    ans += pow_mod(2, cnt-1);
    ans.get();
  }else{
    ll a = XOR;
    ll b = 0;
    ll now = 0;
    mint s = 0, t = 1;
    rep(i, N-1){
      now ^= A[i];
      if(now == a){
        s += t;
      }
      else if(now == b){
        t += s;
      }
    }
    t.get();
  }
}

int main(){
  cin >> N;
  A.resize(N);
  rep(i, N) cin >> A[i];
  solve();

}

