using namespace std;

using ll = long long;

const ll MOD = 1e9 + 7;

vector<int> makeNextLink(const vector<int> &a) {
    vector<int> nxt(a.size(), -1);
    map<int, int> memo;
    for (size_t i = nxt.size() - 1; 1 <= i; --i) {
        if (memo.count(a[i]) != 0) nxt[i] = memo[a[i]];
        memo[a[i]] = i;
    }
    return nxt;
}

ll pow2(ll n) {
    ll p = 1;
    for (int i = 0; i < n; ++i) (p *= 2) %= MOD;
    return p;
}

ll Solve() {
    ll n;
    cin >> n;

    vector<int> a(n + 1), cnt_zero(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        a[i] ^= a[i - 1];
        if (a[i] == 0) ++cnt_zero[i];
        cnt_zero[i] += cnt_zero[i - 1];
    }

    // a[i] = a[nxt[i]]
    vector<int> nxt = makeNextLink(a);

    ll num_partition = 1;
    if (a.back() != 0) {
        int idx = 1;
        while (a[idx] != a.back()) ++idx;

        ll sum_a = 1, sum_b = 0;
        while (nxt[idx] != -1) {
            ll num_zero = cnt_zero[nxt[idx]] - cnt_zero[idx - 1];
            (sum_b += num_zero * sum_a) %= MOD;
            (sum_a += sum_b + 1) %= MOD;
            idx = nxt[idx];
        }
        num_partition += sum_b;
    }
    else {
        set<int> used;
        for (int i = 1; i + 1 <= n; ++i) {
            if (used.count(a[i]) != 0) continue;
            used.insert(a[i]);

            if (a[i] == 0) {
                int num_zero = cnt_zero[n] - cnt_zero[i - 1];
                (num_partition += pow2(num_zero - 1) - 1 + MOD) %= MOD;
            }
            else {
                ll sum_a = 1, sum_b = 0, idx = i;
                while (nxt[idx] != -1) {
                    ll num_zero = cnt_zero[nxt[idx]] - cnt_zero[idx - 1];
                    (sum_b += num_zero * sum_a) %= MOD;
                    (sum_a += sum_b + 1) %= MOD;
                    idx = nxt[idx];
                }
                (num_partition += sum_a) %= MOD;
            }
        }
    }

    return num_partition;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cout << Solve() << endl;

    return 0;
}

