ll inq(ll x, ll q)
{
    if (q == 0)
        return 1;
    ll l = inq(x, q / 2);
    if (q % 2)
    {
        return l * l % MOD * x % MOD;
    }
    else
    {
        return l * l % MOD;
    }
}

ll dp[500001];
vector<int> pos[1500001];

ll run(int x)
{
    vector<int> dp(pos[x].size() + pos[0].size());
    int u1 = 0, u2 = 0;
    ll summ0 = 0, summx = 1;
    for (int i = 0; i < pos[x].size() + pos[0].size(); i++)
    {
        if (u1 < pos[x].size() && pos[x][u1] < pos[0][u2])
        {
            dp[i] = summx;
            summ0 += summx;
            summ0 %= MOD;
            u1++;
        }
        else
        {
            dp[i] = summ0;
            summx += dp[i];
            summx %= MOD;
            u2++;
        }
    }
    return dp[dp.size() - 1];
}

