    int K = (int)p.size();
    vector<int> q(K, 0), sq(K+1, 0);
    for (int i = 1; i < K; ++i) {
        q[i] = zS[p[i]] - zS[p[i-1]];
    }
    for (int i = 0; i < K; ++i) {
        sq[i+1] = sq[i] + q[i];
    }

    //COUT(p); COUT(q); COUT(sq);

    vector<mint> dp(K+1, 0), sdp(K+2, 0), sdp2(K+2, 0);
    dp[0] = 1; sdp[1] = 1; sdp2[1] = sq[0];
    for (int i = 1; i <= K; ++i) {
        dp[i] = ((sdp[i] - sdp[1]) * sq[i]) - (sdp2[i] - sdp2[1]) + 1;
        sdp[i+1] = sdp[i] + dp[i];
        sdp2[i+1] = sdp2[i] + dp[i] * sq[i];

        // cout << i << ": " << dp[i] << endl;
    }

    mint res = 0;
    if (!iszero) {
        for (int i = 1; i <= K; ++i) res += dp[i];
    }
    else {
        res = dp.back();
    }

    //COUT(res);

    return res;
}

mint solve() {
    S.assign(N+1, 0);
    for (int i = 0; i < N; ++i) S[i+1] = S[i] ^ A[i];

    zS.assign(N+2, 0);
    for (int i = 0; i < N+1; ++i) {
        zS[i+1] = zS[i] + (S[i] == 0);
    }
    ma.clear();
    for (int i = 0; i < N+1; ++i) {
        ma[S[i]].push_back(i);
    }


    //COUT(S); COUT(zS); COUT(ma);


    mint res = 0;
    if (S.back() == 0) {
        int zeronum = ma[0].size();
        zeronum -= 2;
        mint first = modpow(mint(2), zeronum);
        res += first;
        for (auto it : ma) {
            if (it.first == 0) continue;
            mint add = subsolve(it.first);
            res += add;
        }
    }
    else {
        int d = S.back();
        res += subsolve(d, true);
    }
    return res;
}

