ll solve(int *sumA,bool *done,int N,int X,bool flag){
    ll dp[500001][2];
    dp[0][0]=1;
    dp[0][1]=0;
    Rep(i,N-1){
        if(sumA[i]==X){
            done[i]=true;
            dp[i][0]=dp[i-1][0];
            dp[i][1]=(dp[i-1][0]+dp[i-1][1])%mod;
        }else if(sumA[i]==0){
            dp[i][1]=dp[i-1][1];
            dp[i][0]=(dp[i-1][0]+dp[i-1][1])%mod;
        }else{
            dp[i][0]=dp[i-1][0];
            dp[i][1]=dp[i-1][1];
        }
    }
    if(flag) return dp[N-1][1];
    else return dp[N-1][0];
}

