            dp[i][0] = dp[i-1][0];
            dp[i][1] = dp[i-1][1];
            if (C[i] == 0) {
                dp[i][0] += dp[i-1][1];
            }
            if (C[i] == X) {
                dp[i][1] += dp[i-1][0];
            }
            dp[i][0] %= MOD;
            dp[i][1] %= MOD;
        }
        ret = dp[N][1] % MOD;
