        vector<int> U(C),Z(500010,0);
        sort(U.begin(),U.end());
        reverse(U.begin(), U.end());
        unique(U.begin(), U.end());
        auto itr = find(U.begin(), U.end(), 0);
        U.erase(itr, U.end());

