            vector<vector<int>> V;
            // cout << X << endl;
            int zero;
            auto itrX = find(C.begin(), C.end(), X);
            auto itrXP = itrX;
            do {
                zero = Z[itrX-C.begin()+1] - Z[itrXP-C.begin()];
                V.push_back(std::vector<int>({0, zero}));
                V.push_back(std::vector<int>({X, 1}));
                itrXP = itrX;
                itrX = find(itrX+1, C.end(), X);
            } while (itrX != C.end());
            // cout << X << endl;
            // cout << V.size() << endl;
            vector<vector<int>> dp(V.size()+1, vector<int>(2,0));
            dp[0][0] = 1; dp[0][1] = 0;
            for (int i=1;i<=V.size();i++) {
                dp[i][0] = dp[i-1][0];
                dp[i][1] = dp[i-1][1];
                if (V[i-1][0] == 0) {
                    dp[i][0] += dp[i-1][1]*V[i-1][1];
                }
                if (V[i-1][0] == X) {
                    dp[i][1] += dp[i-1][0]*V[i-1][1];
                }
                dp[i][0] %= MOD;
                dp[i][1] %= MOD;
            }
            // cout << X << endl;
            ret += dp[V.size()][1];
            ret %= MOD;
        }
        int cnt = 0;
        itr = find(C.begin(), C.end(), 0);
        do {
            cnt++;
            itr = find(itr+1, C.end(), 0);
        } while (itr != C.end());
        ret += (1LL<<(cnt-2)) % MOD;
        ret %= MOD;
    }

    cout << ret << endl;
    return 0;
}

