vector<ll> zaatsu(vector<ll> &list) {
  map<ll, ll> num; for (auto x: list) num[x]++;
  ll p = num.begin()->first==0 ? 0 : 1; for (auto x: num) { num[x.first] = p; p++; }
  vector<ll> result; for (auto x: list) result.push_back(num[x]);
  return result;
}

