int calc(int val) {
	int ret=0;
	if(val==0) {
		assert(nb>=2&&b[0]==0&&b[nb-1]==n);
		int dpsum=1; dp[0]=1;
		FOR(i,1,nb) {
			dp[i]=dpsum;
			dpsum=(dpsum+dp[i])%MOD;
		}
		ret=dp[nb-1];
	} else {
		assert(nb>=1);
		int dpsum=0;
		REP(i,nb) {
			int idx=b[i];
			if(i==0) {
				dp[i]=1;
				dpsum=(dpsum+dp[i])%MOD;
			} else {
				int pidx=b[i-1];
				dp[i]=(dp[i-1]+(ll)dpsum*(zerocnt[idx]-zerocnt[pidx]))%MOD;
				dpsum=(dpsum+dp[i])%MOD;
			}
		}
		ret=asum[n]==val?dp[nb-1]:dpsum;
	}
	//printf("%d = %d\n",val,ret);
	//printf("b:"); REP(i,nb) printf(" %d=%d",b[i],dp[i]); puts("");
	return ret;
}

