		while(r<=n&&ord[r].first==val) ++r;
		if(asum[n]!=0&&asum[n]!=val) continue;
		nb=0; FOR(i,l,r) b[nb++]=ord[i].second;
		ret=(ret+calc(val))%MOD;
	}
	return ret;	
}

void run() {
	scanf("%d",&n);
	REP(i,n) scanf("%d",&a[i]);
	printf("%d\n",solve());
}

