			d1[b]=(d0[b]+d1[b])%mod;
			pre[b]=i;
		}else{
			flg[i]++;
			if(d1[0])d1[0]=(d1[0]*2)%mod;
			else d1[0]++;
		}
		flg[i+1]=flg[i];
	}
	int ans=0;
	if(f[n-1]==0){
		for(int i=0;i<(1<<20);i++)ans=(ans+d1[i])%mod;
	}else{
		ans=d0[f[n-1]];
	}
	cout<<ans<<endl;
	return 0;
}

