const long long mod = 1e9 + 7;

long long mod_pow(long long x, long long k){
  long long ret = 1;
  while(k){
    if(k&1) ret *= x, ret %= mod;
    x *= x, x %= mod;
    k >>= 1;
  }
  return ret;
}

int main(){
  int N;
  cin >> N;
  vector<ll> A(N);
  for(int i = 0; i < N; ++i) cin >> A[i];
  for(int i = 1; i < N; ++i) A[i] ^= A[i-1];
  int M = 1<<10;
  vector<ll> dp(M,1);
  vector<ll> C(M,0), T(M,0);
  ll t = 0;
  for(int i = 0; i < N; ++i){
    int j = A[i];
    if(j){
      if(t != T[j]){
        (dp[j] *= C[j]+1) %= mod;
        C[j] = 0;
        T[j] = t;
      }
      ++C[j];
    }else{
      (dp[0] *= C[0]+1) %= mod;
      C[0] = 1;
      T[0] = t;
      ++t;
    }
  }
  for(int j = 0; j < M; ++j){
    if(t - T[j]){
      (dp[j] *= C[j]) %= mod;
      C[j] = 0;
    }
  }
  ll ans = 0;
  if(A.back()){
    (ans += (dp[A.back()]*C[A.back()]+mod-1)%mod) %= mod;
  }else{
    for(int i = 0; i < M; ++i){
      ans += dp[i] - 1;
    }
  }
  cout << ans << endl;
}

