namespace {
    template <int MODULO>
    struct Fp
    {
        long long val;

        constexpr Fp(long long v = 0) noexcept : val(v % MODULO)
        {
            if (val < 0)
                v += MODULO;
        }
        constexpr Fp operator-() const noexcept
        {
            return val ? MODULO - val : 0;
        }
        constexpr Fp operator+(const Fp &r) const noexcept { return Fp(*this) += r; }
        constexpr Fp operator-(const Fp &r) const noexcept { return Fp(*this) -= r; }
        constexpr Fp operator*(const Fp &r) const noexcept { return Fp(*this) *= r; }
        constexpr Fp operator/(const Fp &r) const noexcept { return Fp(*this) /= r; }
        constexpr Fp &operator+=(const Fp &r) noexcept
        {
            val += r.val;
            if (val >= MODULO)
                val -= MODULO;
            return *this;
        }
        constexpr Fp &operator++(int) noexcept
        {
            val++;
            if (val >= MODULO)
                val -= MODULO;
            return *this;
        }
        constexpr Fp &operator++() noexcept
        {
            val;
            if (val >= MODULO)
                val -= MODULO;
            return *this;
        }
        constexpr Fp &operator-=(const Fp &r) noexcept
        {
            val -= r.val;
            if (val < 0)
                val += MODULO;
            return *this;
        }
        constexpr Fp &operator*=(const Fp &r) noexcept
        {
            val = val * r.val % MODULO;
            return *this;
        }
        constexpr Fp &operator/=(const Fp &r) noexcept
        {
            long long a = r.val, b = MODULO, u = 1, v = 0;
            while (b)
            {
                long long t = a / b;
                a -= t * b;
                swap(a, b);
                u -= t * v;
                swap(u, v);
            }
            val = val * u % MODULO;
            if (val < 0)
                val += MODULO;
            return *this;
        }
        constexpr bool operator==(const Fp &r) const noexcept
        {
            return this->val == r.val;
        }
        constexpr bool operator!=(const Fp &r) const noexcept
        {
            return this->val != r.val;
        }
    };
    template <int MODULO>
    constexpr ostream &operator<<(ostream &os, const Fp<MODULO> &x) noexcept
    {
        return os << x.val;
    }
    template <int MODULO>
    constexpr istream &operator>>(istream &is, Fp<MODULO> &x) noexcept
    {
        return is >> x.val;
    }
    template <int MODULO> // nlogn
    constexpr Fp<MODULO> modpow(const Fp<MODULO> &a, long long n) noexcept
    {
        if (n == 0)
            return 1;
        auto t = modpow(a, n / 2);
        t = t * t;
        if (n & 1)
            t = t * a;
        return t;
    }
