ll power(ll a, int n) {
    ll ans = 1;
    while (n > 0) {
        if (n % 2 == 1)
            ans = ans * a % MOD;
        a = a * a % MOD;
        n /= 2;
    }
    return ans;
}

ll dp[MAX_N + 1];
ll func(int i) {
    if (i == 0)
        return power(2ll, (int)occur[i].size() - 1);
    dp[0] = 0;
    ll sumdp = 0;
    ll sumdp2 = 0;
    for (int j = 1; j <= (int)occur[i].size(); j++) {
        int x = occur[i][j - 1];
        dp[j] = 1;
        if (j > 1)
            sumdp2 = (sumdp2 + sumdp * (zero[x] - zero[occur[i][j - 2]])) % MOD;
        dp[j] = (1 + sumdp2) % MOD;
        sumdp = (sumdp + dp[j]) % MOD;
    }
    if (occur[i].back() == n)
        return dp[(int)occur[i].size()];
    else
        return sumdp;
}

