  std::vector<u64> a(n, 0), pxor(n, 0);
  for (u64 i = 0; i < n; ++i) std::cin >> a[i];
  pxor[0] = a[0];
  for (u64 i = 1; i < n; ++i) pxor[i] = pxor[i - 1] ^ a[i];
  std::set<u64> lasts;
  lasts.insert(pxor.back());
  if (pxor.back() == 0) {
    lasts.insert(pxor.begin(), pxor.end());
  }
  std::vector<u64> zo;
  for (u64 i = 0; i < n; ++i) {
    if (pxor[i] == 0) zo.push_back(i);
  }
  for (auto &last: lasts) {
    u64 cd1sum=0, cd2sum=0;
    std::vector<u64> lo, ao;
    std::vector<u64> dp1(n, 0), dp2(n, 0);
    if (last == 0) {
      ao = zo;
      lo = zo;
    }
    else
      for (u64 i = 0; i < n; ++i) {
        if (pxor[i] == 0 || pxor[i] == last) ao.push_back(i);
        if (pxor[i] == last) lo.push_back(i);
      }
    for (auto &i : ao) {
      if (pxor[i] == last) {
        dp2[i] = 1+cd1sum;
        dp2[i]%=kMod;
      }
      if (pxor[i] == 0) {
        dp1[i] = cd2sum;
        dp1[i]%=kMod;
        cd1sum+=dp1[i];
        cd1sum%=kMod;
      }
      if (pxor[i] == last) {
        cd2sum+=dp2[i];
        cd2sum%=kMod;
      }
    }
    cnt += (dp2.back() + dp1.back()) % kMod;
    cnt %= kMod;
  }
  std::cout << cnt << std::endl;
  return 0;
}

