        sum ^= val;
        if (sum) {
            dp[sum][0] = (dp[sum][0] + dp[sum][1] * (cnt0 - cnt[sum])) % mod;
            dp[sum][1] = (dp[sum][1] + dp[sum][0]) % mod;
            cnt[sum] ++;
        } else cnt0++;
    }
    if (sum) {
        printf("%lld\n", dp[sum][1]);
    } else {
    	long long ret = exp_mod(2, cnt0 - 1);
    	for (int i = 1; i <= 1e6; i++) {
