const ll MOD = 1000000007;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

const int MAXA = (1 << 20) - 1;
const int NONE = -1;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;

    vector<int> a(n);
    vector<int> xor_sum(n + 1, 0);
    vector<int> prv(MAXA + 1, NONE);
    vector<ll> cnt0(n + 1, 0);
    vector<ll> sum0(MAXA + 1, 0), sumx(MAXA + 1, 0);
    prv[0] = 0;
    cnt0[0] = 1;

    for (int i = 0; i < n; i++) {
        cin >> a[i];
        xor_sum[i + 1] = (xor_sum[i] ^ a[i]);
        ll tar = xor_sum[i + 1];

        if (prv[tar] == NONE) {
            sumx[tar] = 1;
        } else {
            ll cnt = cnt0[i] - cnt0[prv[tar]];
            (sumx[tar] += cnt * sum0[tar] % MOD) %= MOD;
        }

        prv[tar] = i + 1;

        (sum0[tar] += sumx[tar]) %= MOD;

        cnt0[i + 1] = cnt0[i] + (xor_sum[i + 1] == 0);
    }

    ll ans = 0;
    if (xor_sum[n] == 0) {
        for (int i = 1; i <= MAXA; i++) {
            (ans += sum0[i]) %= MOD;
        }
        (ans += modpow(2, cnt0[n] - 2)) %= MOD;
    } else {
        ans = sumx[xor_sum[n]];
    }
    cout << ans << endl;
    return 0;
}

