				if (cur == 0) {
					dp[1] = pr2 + pr1;
					dp[0] = pr2;
					pr = 0;
				}
				else {
					dp[0] = pr1 + (pr2 * cur) % MOD;
				}
				dp[0] %= MOD;
				dp[1] %= MOD;
			}

			ans += dp[1];
