class EXORPartitioning {
	class Solver {
	public:
		io::input_reader in;
		io::output_writer out;

		Solver(std::istream &in, std::ostream &out) : in(in), out(out) {}

		map<int, vector<int>> ind;

		vector<pair<int, mi>> dp, dp2;

		template<typename T>
		mi calc_sum(int x, T it, T end, int bx) {
			int i = *it;
			if (dp2[i].first == x) return dp2[i].second;
			mi res = calc(x, *it, bx);
			if (res != 0) {
				it++;
				if (it != end) res += calc_sum(x, it, end, bx);
			} else {
				if (*(end - 1) == n) res = calc(x, n, bx);
			}
			dp2[i] = {x, res};
			return res;
		}

		mi calc(int x, int i, int bx) {
			if (i == n) return 1;
			if (dp[i].first == x) return dp[i].second;
			auto &vc = ind[(bx ^ x)];
			auto next = upper_bound(all(vc), i);
			mi res = 0;
			if (vc.end() != next) {
				res = calc_sum(x, next, vc.end(), bx ^ x);
			}
			dp[i] = {x, res};
			return res;
		}

		mi calc(int x) {
			return calc(x, 0, 0);
		}

		int n;

		void solve() {
			in >> n;
			dp.clear();
			dp.resize(n + 1, {-1, -1});
			dp2.clear();
			dp2.resize(n + 1, {-1, -1});
