			int x = 0;
			fori(i, n) {
				x ^= a[i];
				ind[x].pb(i + 1);
			}

			mi res = 0;
			set<int> op;
			x = 0;
			fori(i, n) x ^= a[i], op.insert(x);
			for (int i : op) {
				res += calc(i);
			}
