LL solvedp(vector<pair<LL, int>>& vec, LL lasval) {
	LL zero = 1, notz = 0;
	LL zpar = 1, npar = 0;
	for (auto p : vec) {
		if (p.second == 0) {
			zpar = (notz * p.first) % MOD;
			zero += zpar;
			zero %= MOD;
		}
		else {
			npar = (zero * p.first) % MOD;
			notz += npar;
			notz %= MOD;
		}
	}
	if (lasval == 0) {
		return zpar;
	}
	return npar;
}

