class fenwick_tree_0 {
 public:
    vector<ll> x;
 public:
    fenwick_tree_0(int n) : x(n,0) { }
    void add(int k, ll a) {
        for (; k<x.size(); k|=k+1) {
            (x[k] += a) %= MOD;
        }
    }
    ll sum(int i, int j) {
        if (i == 0) {
            ll S = 0;
            for (; j>=0; j=(j&(j+1))-1) {
                (S += x[j]) %= MOD;
            }
            return S;
        } else {
            return SUB(sum(0, j), sum(0, i-1));
        }
    }
};



vvi at;

ll solve_p(int p, bool it=false){
    int P = at[p].size(), Z = at[0].size(), L = P+Z;
    unordered_map<int,int> mp, sp;
    vii tmp;
    for (int x: at[p]) tmp.emplace_back(x,p);
    for (int x: at[0]) tmp.emplace_back(x,0);
    sort(ALL(tmp));
    rep(i,L){
        mp[tmp[i].first]=1+i;
        sp[1+i] = tmp[i].second;
    }
    vi yp(P), y0(Z);
    rep(i,P) yp[i] = mp[ at[p][i]] ;
    rep(i,Z) y0[i] = mp[ at[0][i]] ;

    fenwick_tree_0 fp(L+3), f0(L+3);
    fp.add(1, 1);

    for (int i=1; i<=L; ++i) {
        if (sp[i] == p) {
            ll k = fp.sum(0,i);
            f0.add(i+1, k);
        } else {
            ll k = f0.sum(0,i);
            fp.add(i+1, k);
        }
    }
    if (it) {
        return fp.sum(0, L);
    } else {
        return f0.sum(0, L);
    }
}

ll solve(int N, vi& a) {
    vector<unsigned int> ax(N+1, 0);
    rep(i,N) {
        ax[i+1] = ax[i] ^ a[i];
    }
    int xall = ax[N], ant = ~xall;

    int pmax = (1 << 20)-1;
    at.resize(1 << 20);
    for (int i=1; i<=N; ++i) {
        at[ ax[i] ].pb(i);
    }


    ll ans = 0;

    if (xall == 0) {
        {
            int zeros = 0;
            for(int i=1; i<N; ++i) {
                if (ax[i]==0) ++zeros;
            }
            ans = ADD(ans, POW(2, zeros));
        }

        for (int p=1; p<=pmax; ++p){
            if (at[p].empty()) continue;
            ans = ADD(ans, solve_p(p));
        }
    } else {
        ans = ADD(ans, solve_p(xall, 1));
    }

    return ans % MOD;
}

