inline int fastpower(int num,int po){
	fres = 1;
	while(po > 0){
		if(po & 1)
			fres = (long long)fres * num % mod;
		po >>= 1;
		num = (long long)num * num % mod;
	}
	return fres;
}

int l , r , val;

void build(int s,int e,int idx){
	if(s == e){
		if(a[s] == 0){
			num[idx] = 1;
		}
		seg[idx] = lazy[idx] = 0;
		return;
	}
	build(s,((s+e) >> 1),(idx << 1));
	build(((s+e) >> 1) + 1,e,(idx << 1) + 1);
	num[idx] = num[(idx << 1) + 1] + num[(idx << 1)];
	seg[idx] = lazy[idx] = 0;
}

inline void fix(int s,int e,int idx){
	seg[idx] += (long long)lazy[idx] * num[idx] % mod;
	if(seg[idx] >= mod)
		seg[idx] -= mod;
	if(s != e){
		lazy[(idx << 1)] += lazy[idx];
		if(lazy[(idx << 1)] >= mod)
			lazy[(idx << 1)] -= mod;
		lazy[(idx << 1) + 1] += lazy[idx];
		if(lazy[(idx << 1) + 1] >= mod)
			lazy[(idx << 1) + 1] -= mod;
	}
	lazy[idx] = 0;
}

int update(int s,int e,int idx){
	fix(s,e,idx);
	if(s > r || e < l)
		return seg[idx];
	if(s >= l && e <= r){
		lazy[idx] += val;
		if(lazy[idx] >= mod)
			lazy[idx] -= mod;
		fix(s,e,idx);
		return seg[idx];
	}
	return seg[idx] = ((update(s,((s+e) >> 1),(idx << 1)) + update(((s+e) >> 1) + 1,e,(idx << 1) + 1)) % mod);
}

int getsum(int s,int e,int idx){
	fix(s,e,idx);
	if(s > r || e < l)
		return 0;
	if(s >= l && e <= r)
		return seg[idx];
	return ((getsum(s,((s+e) >> 1),(idx << 1)) + getsum(((s+e) >> 1) + 1,e,(idx << 1) + 1)) % mod);
}

