                ll r=lower_bound(v[0].begin(),v[0].end(),ne)-v[0].begin();
                jou+=ka*(r-now);
                jou%=mod;
                ka+=jou;
                ka%=mod;
                now=r;
            }
        if(b[n-1]==b[i]){
            ans=(ans+jou-1+mod)%mod;
            continue;
        }
        if(v[b[i]].size()==1){
            ans=(ans+1)%mod;
            continue;
        }
        ll nee=v[b[i]][v[b[i]].size()-1];
        ll rr=lower_bound(v[0].begin(),v[0].end(),nee)-v[0].begin();
        jou+=ka*(rr-now);
        jou%=mod;
        ka+=jou;
        ka%=mod;
        ans=(ans+ka)%mod;

    }
    ans=(ans+1)%mod;
    cout<<ans<<endl;
}

