const int N = 500005, MX = 1 << 20, MOD = 1E9 + 7;

int n, u, cur, su[N];
long long ans = 0;
vector<int> ve[MX];

long long solve(int u)
{
    if (ve[u].empty())
        return 0;
    long long add = 0, tot = 0;
    for (int i = 0; i < (int)ve[u].size(); i++)
    {
        int occ = su[ve[u][i]] - (i == 0 ? 0 : su[ve[u][i - 1]]);
        (add += tot * occ) %= MOD;
        (tot += add + 1) %= MOD;
    }
    return tot;
}

int main()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        cin >> u;
        cur ^= u;
        su[i] = su[i - 1] + (cur == 0);
        if (cur > 0)
            ve[cur].push_back(i);
    }
    if (cur > 0)
        ans = solve(cur);
    else
    {
        for (int i = 1; i < MX; i++)
            (ans += solve(i)) %= MOD;
        int pw = 1;
        for (int i = 1; i < su[n]; i++)
            (pw *= 2) %= MOD;
        (ans += pw) %= MOD;
    }
    cout << ans;
}

