	int ans = 0;
	int z = 0;
	for (int i = n - 1; i >= 0; i--) {
		int val = sum[i];
		if (val == 0) {
			apply();
			if (sum[n - 1] == 0) {
				int tmp = z; if (i == n - 1) tmp = 1;
				z = add(tmp, z);
				ans = add(ans, tmp);
			}
		}
		else {
			int tmp = get(val);
			if (sum[n - 1] == 0) tmp = add(tmp, 1);
			else if (i == n - 1) tmp = 1;
			ans = add(ans, tmp);
			update(val, tmp);
		}
	}
	cout << ans << endl;
	return 0;
}

