const LL MOD = 1000000007;
int lz[1 << 20];

void solve(int ks) {
	int n, now = 0;
	int cnt = 0;
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		now ^= a[i];
		if (now == 0) cnt++;
	}

	LL ans = 0;
	if (now == 0) {
		ans = 1;
		for (int i = 1; i < cnt; i++) {
			ans = (ans * 2) % MOD;
		}
	}

	for (int i = 1; i < (1 << 20); i++) lz[i] = 0;
	int cur = 0;

	now = 0;
	for (int i = 1; i <= n; i++) {
		now ^= a[i];
		if (now) {
			int last = lz[now];
			dp[1][now] += (cur - last) * dp[0][now];
			dp[1][now] %= MOD;
			dp[0][now] += 1 + dp[1][now];
			dp[0][now] %= MOD;
			lz[now] = cur;
			if (i == n) {
				ans += 1 + dp[1][now];
				ans %= MOD;
			}
		}
		else {
			cur++;
			if (i == n) {
				for (int j = 1; j < 9; j++) {
					ans += dp[0][j];
					ans %= MOD;
				}
			}
		}
	}
	printf("%lld\n", ans);
}

