class mod {
public:
    mod() {m_n = 0;}
    mod(ll n) {if (n >= 0) m_n = n % MOD; else m_n = n % MOD + MOD;}
    friend bool operator== (const mod& a, const mod& b) {return a.m_n == b.m_n;}
    friend bool operator!= (const mod& a, const mod& b) {return !(a == b);}
    friend mod operator+ (const mod& a, const mod& b) {return (a.m_n + b.m_n) % MOD;}
    friend mod& operator+= (mod& a, const mod& b) {return a = a + b;}
    friend mod operator- (const mod& a) {return -a.m_n;}
    friend mod operator- (const mod& a, const mod& b) {return (a.m_n + (-b.m_n)) % MOD;}
    friend mod& operator-= (mod& a, const mod& b) {return a = a - b;}
    friend mod operator* (const mod& a, const mod& b) {return (a.m_n * b.m_n) % MOD;}
    friend mod& operator*= (mod& a, const mod& b) {return a = a * b;}
    friend mod pow(const mod& n, ll r) {
        if (r == 0) {
            return 1;
        } else if (r < 0) {
            return pow(n, (MOD - 2) * (-r));
        } else if (r % 2 == 0) {
            mod tmp = pow(n, r / 2);
            return tmp * tmp;
        } else {
            return n * pow(n, r - 1);
        }
    }
    friend mod operator/ (const mod& a, const mod& b) {return a * pow(b, -1);}
    friend mod& operator/= (mod& a, const mod& b) {return a = a / b;}
    friend ostream& operator<< (ostream& os, const mod& n) {os << n.m_n; return os;}
    friend istream& operator>> (istream& is, mod& n) {ll tmp; is >> tmp; n = mod(tmp); return is;}
private:
    ll m_n;
};

int main(int argc, const char * argv[]) {
    ios_base::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> A(N);
    for (int n = 0; n < N; ++n) {
        cin >> A[n];
    }
    vector<int> B(N);
    B[0] = A[0];
    for (int n = 1; n < N; ++n) {
        B[n] = B[n-1]^A[n];
    }

    set<int> Set;
    if (B[N-1] == 0) {
        for (auto b : B) {
            Set.insert(b);
        }
    } else {
        Set.insert(B[N-1]);
    }

    mod Res;
    for (int s : Set) {
        if (s == 0) {
            Res += pow(mod(2), count(B.begin(), B.end(), 0)-1);
        } else {
            vector<int> Len;
            int prev = 0, nCount = 0;
            for (int n : B) {
                if (n == prev) {
                    ++nCount;
                } else if (n == s-prev) {
                    Len.push_back(nCount);
                    prev = s-prev;
                    nCount = 1;
                }
            }
            Len.push_back(nCount);

            vector<mod> DP0(Len.size()+1, 0), DPs(Len.size()+1, 0);
            DP0[0] = 1; DPs[0] = 0;
            for (int l = 1; l <= Len.size(); ++l) {
                if (l%2 == 0) {
                    DP0[l] = DP0[l-1];
                    DPs[l] = DP0[l-1]*Len[l-1] + DPs[l-1];
                } else {
                    DP0[l] = DP0[l-1] + DPs[l-1]*Len[l-1];
                    DPs[l] = DPs[l-1];
                }
            }

            if (B[N-1] == 0) {
                Res += DPs[Len.size()];
            } else {
                Res += DP0[Len.size()];
            }
        }
    }

    cout << Res << endl;

    return 0;
}

