const int MAX_N = (1 << 21);
int N, A[MAX_N], B[MAX_N]; vector<int>X[MAX_N];
long long dp0[MAX_N], dp1[MAX_N], ans, mod = 1000000007;

long long solve(vector<pair<int, int>> Z) {
	for (int i = 0; i <= Z.size(); i++) { dp0[i] = 0; dp1[i] = 0; }

	long long s0 = 1, s1 = 0; dp0[0] = 1;
	for (int i = 0; i < Z.size(); i++) {
		if (Z[i].first == 0) { dp0[i + 1] = 1LL * s1 * Z[i].second; dp0[i + 1] %= mod; }
		if (Z[i].first == 1) { dp1[i + 1] = 1LL * s0 * Z[i].second; dp1[i + 1] %= mod; }
		s0 += dp0[i + 1]; s0 %= mod;
		s1 += dp1[i + 1]; s1 %= mod;
	}
	return (dp0[Z.size()] + dp1[Z.size()]) % mod;
}

int main() {
	cin >> N;
	for (int i = 1; i <= N; i++) { cin >> A[i]; B[i] = (B[i - 1] ^ A[i]); }
	for (int i = 0; i <= N; i++) X[B[i]].push_back(i);

	for (int i = 1; i < MAX_N; i++) {
		if (X[i].size() == 0) continue;
		if (B[N] != 0 && B[N] != i) continue;

		vector<pair<int, int>> Z; Z.push_back(make_pair(1, 1));
		for (int j = 0; j < X[i].size() - 1; j++) {
			int pos1 = lower_bound(X[0].begin(), X[0].end(), X[i][j]) - X[0].begin();
			int pos2 = lower_bound(X[0].begin(), X[0].end(), X[i][j + 1]) - X[0].begin();
			if (pos2 - pos1 >= 1) Z.push_back(make_pair(0, pos2 - pos1));
			Z.push_back(make_pair(1, 1));
		}
		int pos3 = lower_bound(X[0].begin(), X[0].end(), X[i][X[i].size() - 1]) - X[0].begin();
		int pos4 = lower_bound(X[0].begin(), X[0].end(), N - 1) - X[0].begin();
		if (pos4 - pos3 >= 1) Z.push_back(make_pair(0, pos4 - pos3));

		if (B[N] == 0) Z.push_back(make_pair(0, 1));
		if (B[N] == i) Z.push_back(make_pair(1, 1));

		ans += solve(Z);
	}

	if (B[N] == 0) {
