struct IT {
    struct Node {
        int lf, rg;
        int lz = 0;
    };
    vector<Node> a;

    void init(int n) { a.resize(n * 4 + 2); }

#define md ((l + r) >> 1)
#define nx (i << 1)
    void down(int i) {
        if (a[i].lf == a[i].rg) return;
        a[nx].lz += a[i].lz;
        a[nx + 1].lz += a[i].lz;
        a[i].lz = 0;
    }

    void build(int l, int r, int i = 1) {
        if (l > r) return;
        a[i].lf = l;
        a[i].rg = r;
        if (l == r) return;
        build(l, md, nx);
        build(md + 1, r, nx + 1);
    }

    void inc(int l, int r, int x, int i = 1) {
        if (l > r) return;
        if (a[i].lf > r || a[i].rg < l) return;
        if (l <= a[i].lf && a[i].rg <= r) {
            a[i].lz += x;
            return;
        }
        down(i);
        inc(l, r, x, nx);
        inc(l, r, x, nx + 1);
    }

    void update(int p, int x, int i = 1) {
        if (a[i].lf > p || a[i].rg < p) return;
        if (a[i].lf == p && a[i].rg == p) {
            a[i].lz = 0;
            return;
        }
        down(i);
        update(p, x, nx);
        update(p, x, nx + 1);
    }

    int get(int p, int i = 1) {
        if (a[i].lf > p || a[i].rg < p) return INT_MIN;
        if (a[i].lf == p && a[i].rg == p) return a[i].lz;
        down(i);
        return max(get(p, nx), get(p, nx + 1));
    }
#undef md
#undef nx
} stree;

