using namespace std;

const int maxN = 500000;
const int mod = 1000000007;
const int maxX = 1 << 20;

int N;
int A[maxN];
int X[maxN + 1];
int g[maxN + 1];
int c[maxN + 1];
vector<int> idx[maxX];

template <class T>
inline int remainder(const T & x) {
	if (x < 0)
		return x + mod;
	else if (x < mod)
		return x;
	else
		return x - mod;
}

void initialize() {
	g[0] = 1;
	for (int i = 1; i <= maxN; i++)
		g[i] = remainder(g[i - 1] << 1);
}

int answer() {
	for (int i = 0; i < N; i++) {
		X[i + 1] = X[i] ^ A[i];
		c[i + 1] = c[i] + (X[i + 1] == 0);
		idx[X[i + 1]].push_back(i + 1);
	}

//	for (int i = 0; i < N; i++)
//		cerr << X[i + 1] << ' ';
//	cerr << endl;
//	
//	for (int i = 0; i < N; i++)
//		cerr << c[i + 1] << ' ';
//	cerr << endl;

	vector<int> vtr;
	if (X[N] == 0) {
		for (int i = 1; i <= N; i++)
			vtr.push_back(X[i]);
		sort(vtr.begin(), vtr.end());
		vtr.resize(unique(vtr.begin(), vtr.end()) - vtr.begin());
	} else
		vtr.push_back(X[N]);

	int ans = 0;
	int f[2];
	bool b = X[N];
	for (const auto & x : vtr) {
		if (x == 0)
			ans = remainder(ans + g[idx[0].size() - 1]);
		else {
			f[0] = 1;
			f[1] = 0;
			for (int i = 0; i < idx[x].size(); i++) {
				if (i > 0)
					f[0] = remainder(f[0] + (long long)f[1] * (c[idx[x][i]] - c[idx[x][i - 1]]) % mod);
				f[1] = remainder(f[0] + f[1]);
//				cerr << "f = " << f[0] << ' ' << f[1] << endl;
			}
			f[0] = remainder(f[0] + (long long)f[1] * (c[N] - c[idx[x].back()]) % mod);
			ans = remainder(ans + f[b ^ 1]);
//			cerr << "x = " << x << ", f[0] = " << f[0] << ", f[1] = " << f[1] << endl;
		}
	}

	return ans;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	initialize();

	cin >> N;
	for (int i = 0; i < N; i++)
		cin >> A[i];

	cout << answer() << '\n';

	return 0;
}

