            vector<vector<long>> dp(g+1, vector<long>(2, 0));
            dp[0][0]=1;
            for(int i=0; i<g; ++i){
                dp[i+1][0]=dp[i][0];
                dp[i+1][1]=dp[i][1];
                if(i%2==0) dp[i+1][1]=(dp[i+1][1]+dp[i][0]*itr->second[i])%mod;
                else dp[i+1][0]=(dp[i+1][0]+dp[i][1]*itr->second[i])%mod;
            }
            ans=(ans+dp[g][1])%mod;
        }
        cout << ans << endl;
    }
    return 0;
}

