const long long M = 1000000007;

map<int,vector<int> > loc;
LL g(int a, bool op)
{
	vector<int>& v=loc[a];
	vector<int>& z=loc[0];
	LL ca=1;
	LL cz=1;
	auto it=lower_bound(z.begin(),z.end(),v[0]);
	for(int i=1;i<v.size();i++){
		auto jt=lower_bound(it,z.end(),v[i]);
		cz+=ca*(jt-it)%M;
		cz%=M;
		ca+=cz;
		ca%=M;
		it=jt;
	}
	return op?ca:cz;
}
// powmod p^n%mod
LL powmod(LL p,LL n,LL mod){
	LL q=p%mod;
	LL pow=1;
	while(n){
		if(n&1){
			pow*=q;
			pow%=mod;
		}
		q=q*q;
		q%=mod;
		n/=2;
	}
	return pow;
}
void solve(long long N, std::vector<long long> A){
	int v=0;
	for(int i=0;i<A.size();i++){
		v^=A[i];
		loc[v].push_back(i);
	}
	//cerr << v << endl;
	if(v!=0){
		cout << g(v,false) << endl;
		return;
	}
	LL ret=0;
	for(auto it=loc.begin();it!=loc.end();it++)
	{
		if(it->first==0){
			ret+=powmod(2,it->second.size()-1,M);
			ret%=M;
		}
		else{
			ret+=g(it->first,true);
			ret%=M;
		}
	}
	cout << ret << endl;
}

