ll solve_single(const V<ll> &sumlist, const V<ll> xidxs[], ll n, ll xo)
{
    ll x = xo;
    if (x < 0) x = sumlist[n];

    debug_printf("---- xidxs\n");
    debug_print(xidxs[x]);

    V<ll> array;
    auto prev = xidxs[0].begin();
    for (auto idx : xidxs[x]) {
        auto iter = lower_bound(ALL(xidxs[0]), idx);
        ll cnt = iter - prev;
        if (cnt) array.pb(cnt);
        array.pb(-1LL);
        prev = iter;
    }

    debug_printf("---- array\n");
    debug_print(array);

    ll *dp0 = new ll[array.size()+1];
    ll *dp1 = new ll[array.size()+1];
    memset(dp0, 0, sizeof(ll) * (array.size()+1));
    memset(dp1, 0, sizeof(ll) * (array.size()+1));

    dp0[0] = 1;
    srep (i, 1, array.size()) {
        if (array[i] < 0) {
            dp0[i] = dp0[i-1];
            dp1[i] = (dp0[i-1] + dp1[i-1]) % MOD;
        }
        else {
            dp0[i] = (dp0[i-1] + dp1[i-1] * array[i]) % MOD;
            dp1[i] = dp1[i-1];
        }
    }

    ll ret = ((xo < 0) ? dp0[array.size()-1] : dp1[array.size()-1]);
    delete [] dp0;
    delete [] dp1;
    return ret;
}

ll solve_zeros(const V<ll> &sumlist, const V<ll> xidxs[], ll n)
{
    ll ans = mod_pow(2LL, xidxs[0].size() - 2LL, MOD);

    srep (x, 1, (1LL<<20LL)) {
        if (xidxs[x].empty()) continue;
        ll incr = solve_single(sumlist, xidxs, n, x);
        ans += incr;
        ans %= MOD;
    }

    return ans;
}

