				dp1[i][1] = dp1[i - 1][1];
			dp1[i][1] = dp1[i][1] % MOD;
		}
		cout << (dp1[n][1] - dp1[n - 1][1] + MOD) % MOD << "\n";
	}
	else {
		long long ans = 0;
		ans += quickpow(2, cnt0 - 1);
		for (int i = 1; i <= n; i++) {
			dat0[i] = dat0[i - 1];
			if (b[i] == 0) dat0[i]++;
		}
		for (int i = 1; i <= n; i++) {
			if (b[i] == 0) continue;
			if (st.count(b[i]) == 0) {
				st.insert(b[i]);
				mp[b[i]] = cur;
				cur++;
			}
			int tmp = mp[b[i]];
			if (vec[tmp].empty()) {
				if (i > 1) {
					if (dat0[i] > 0) {
						vec[tmp].pb(make_pair(dat0[i], make_pair(false, i - 1)));
					}
				}
				vec[tmp].pb(make_pair(1, make_pair(true, i)));
			}
			else {
				int sz = (int)vec[tmp].size();
				int pre = vec[tmp][sz - 1].se.se;
				if (dat0[i] - dat0[pre] > 0) {
					vec[tmp].pb(make_pair(dat0[i] - dat0[pre], make_pair(false, i - 1)));
					vec[tmp].pb(make_pair(1, make_pair(true, i)));
				}
				else {
					vec[tmp][sz - 1].fi++;
					vec[tmp][sz - 1].se.se = i;
				}
			}
		}
		for (auto x : st) {
			int ix = mp[x], sz = (int)vec[ix].size();
			vec[ix].pb(make_pair(dat0[n] - dat0[vec[ix][sz - 1].se.se], make_pair(false, n)));
			dp2[0][0] = 1;
			dp2[0][1] = 0;
			int pre = 0;
			for (int j = 0; j < (int)vec[ix].size(); j++) {
				int curr = vec[ix][j].se.se;
				int cnt = vec[ix][j].fi;
				if (vec[ix][j].se.fi == false) {
					dp2[curr][0] = dp2[pre][0] + dp2[pre][1] * cnt;
					dp2[curr][0] = dp2[curr][0] % MOD;
					dp2[curr][1] = dp2[pre][1];
					if (curr == n) {
						dp2[curr - 1][0] = dp2[pre][0] + dp2[pre][1] * (cnt - 1);
						dp2[curr - 1][0] = dp2[curr - 1][0] % MOD;
					}
				}
				else {
					dp2[curr][1] = dp2[pre][0] * cnt + dp2[pre][1];
					dp2[curr][1] = dp2[curr][1] % MOD;
					dp2[curr][0] = dp2[pre][0];
				}
				pre = curr;
			}
			ans += (dp2[n][0] - dp2[n - 1][0] + MOD) % MOD;
			ans = ans % MOD;
		}
		cout << ans << "\n";
	}
	//system("pause");
	return 0;
}

