int n;
vector<int> a, s; //sはaのxorの累積
vector<int> zs; //累積を考えて、[0, i)なるs_k = 0の個数
vector<vector<int>> inds; //s_i == dなるindex

mint subsolve(int d, bool iszero = 1) { //d != 0
    auto p = inds[d];
    int k = (int)p.size();
    vector<int> q(k + 1, 0);
    rep(i, k) {
        q[i] = zs[p[i]] - zs[p[0]];
    }

    vector<mint> dp(k, 0), sdp(k + 1, 0), sdp2(k + 1, 0);
    dp[0] = 1;
    sdp[1] = sdp[0] + dp[0];
    sdp2[1] = sdp2[0] + dp[0] * q[0];
    rep(i, k - 1) {
        dp[i + 1] = 1 + sdp[i + 1] * q[i + 1] - sdp2[i + 1];
        sdp[i + 2] = sdp[i + 1] + dp[i + 1];
        sdp2[i + 2] = sdp2[i + 1] + dp[i + 1] * q[i + 1];
    }
    mint res = 0;
    if(iszero) {
        rep(i, k) {
            res += dp[i];
        }
    } else {
        res = dp.back();
    }

    return res;
}

void solve() {
	cin >> n;
    a.resize(n);
    rep(i, n) {
        cin >> a[i];
    }
    s.assign(n + 1, 0);
    rep(i, n) {
        s[i + 1] = s[i] ^ a[i];
    }
    zs.assign(n + 2, 0);
    rep(i, n + 1) {
        zs[i + 1] = zs[i] + (s[i] == 0);
    }
    inds.assign((1<<20) + 1, vector<int>());
    rep(i, n + 1) {
        inds[s[i]].push_back(i);
    }

    mint ans = 0;
    if(s.back() == 0) {
        int zeronum = (int)inds[0].size() - 2;
        ans += modpow(mint(2), zeronum);
        for(int d = 1; d <= (1<<20); ++d) {
            if(inds[d].empty()) continue;
            ans += subsolve(d);
        }
    } else {
        ans = subsolve(s.back(), 0);
    }

    cout << ans << endl;
}

