void solve() {
    int n; cin >> n;
    vector<int> a(n+1);
    vector<int> pre(n+1);
    vector<int> las(1<<20);
    vector<int> z(n+1);
    for (int i = 1; i <= n; i++) {
        int x; cin >> x;
        a[i] = a[i-1] ^ x;
        z[i] = z[i-1] + !a[i];
        pre[i] = las[a[i]];
        las[a[i]] = i;
    }
    vector<mint> dp(n+1); dp[0] = 1;
    vector<mint> su(n+1);
    for (int i = 1; i <= n; i++) {
        int j = pre[i];
        if (a[i]) {
            dp[i] = dp[j] + su[j] * (z[i]-z[j]);
            su[i] = su[j] + dp[i];
        } else {
            dp[i] = dp[j] * 2;    
        }
    }
    mint res;
    if (a[n]) {
        res = dp[n];
    } else {
        res = dp[n]/2;
        for (int i = 1; i < n; i++) {
            if (a[i]) {
                res += dp[i];
            }
        }
    }
    cout << res;
}

