ll s[500005];
ll last[500005];

int main()
{
    int n;
    cin >> n;
    for(int i = 0; i < n; i++) cin >> a[i];
    ll x = 0;
    for(int i = 0; i < 1050000; i++) dp2[i] = 1;
    for(int i = 0; i < n; i++){
        x ^= a[i];
        s[i + 1] = s[i];
        if(x){
            dp2[x] = (dp2[x] + dp1[x] * (s[i + 1] - s[last[x]]) % MOD) % MOD;
            dp1[x] = (dp1[x] + dp2[x]) % MOD;
            last[x] = i + 1;
        }
        else{
            s[i + 1]++;
        }
    }
    ll ans = 0;
    if(x == 0){
        for(int i = 0; i < 1050000; i++) ans = (ans + dp1[i]) % MOD;
        ll c = 0;
