int main() {
    long N;
    cin>>N;
    vector<long> A(N);
    for (auto& a : A) cin>>a;
    const long MOD = 1e9+7;

    vector<long> ca(N), cz(N);
    ca[0] = A[0];
    cz[0] = A[0] == 0;
    map<long, vector<long>> nx;
    nx[A[0]].push_back(0);
    for (size_t i = 1; i < N; i++) {
        ca[i] = ca[i-1] ^ A[i];
        cz[i] = cz[i-1]+(ca[i] == 0);
        nx[ca[i]].push_back(i);
    }
    auto zeros = [&](long a, long b) {return cz[b] - (a>=0?cz[a]:0);};

    long ans = 0;
    if (ca.back() == 0) {
        ans = 1;
        for (size_t i = 0; i < cz.back()-1; i++) ans = (ans*2)%MOD;
    }
    for (auto xn : nx) {
        auto x = xn.first;
        if (x == 0) continue;
        if (ca.back() != 0 and x != ca.back()) continue;
        long bef = -1;
        long dp[2] = {1, 0};
        for (auto nx : xn.second) {
            dp[0] += dp[1]*zeros(bef, nx);
            dp[0] %= MOD;
            dp[1] += dp[0];
            dp[1] %= MOD;
            bef = nx;
        }
        if (ca.back() == 0) {
            ans += dp[1];
        } else {
            ans += dp[0];
        }
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

