using u6 = std::uint64_t;
using u3 = std::uint32_t;
constexpr u6 moduloNo = 1'000'000'000 + 7; //'
constexpr u3 maxA = 0x10'0000;//'

struct State {
	array<u3, 3> buf;
	//State() :buf{ 1,0,1 } {}
	constexpr State() :buf{1,0,0}{}
	State(u3 zerocount) :buf{ 1,0,zerocount } { addX(zerocount); }
	void addX(u3 zero) {
		if (zero != buf[2]) {
			u6 zerodiff = zero - buf[2];
			buf[0] = (u3)(((u6)buf[0] + zerodiff * buf[1]) % moduloNo);
			buf[2] = zero;

		}

		buf[1] = buf[0] + buf[1];
		buf[1] = (buf[1] >= moduloNo) ? buf[1] - moduloNo : buf[1];
	}
};
u6 pow2(u6 n) {
	if(n<63)return (u6(1) << n) % moduloNo;
	u6 powcount = 0, mod2 = 0;
	while (n >= 64) {
		mod2 += n & 1;
		++powcount;
		n >>= 1;
	}
	u6 result = (u6(1) << n) % moduloNo;
	for (u6 i = 0; i < powcount; ++i) {
		result = (result*result) % moduloNo;
	}
	return (result* pow2(mod2)) % moduloNo;
}

struct Calc {
	u6 N;
	State stmap[maxA];
	u6 calc(u6 N_) {
		N = N_;
		u3 st = 0;
		u3 tmp;
		u3 zerocount = 0;
		for (u3 index = 0; index < N; ++index) {
			in >> tmp;
			st ^= tmp;
			if (!st) {
				++zerocount;
			}
			else {
				stmap[st].addX(zerocount);
			}
		}
		if (st != 0) {
			return stmap[st].buf[0];
		}
		else {
			u6 result = pow2(zerocount - 1);
			for (auto & stv : stmap) {
				result = (result + stv.buf[1]) % moduloNo;
			}
			return result;
		}
	}
};
Calc calc;

