			} else {
				t0 += tx*temp[XOR][i].first.second;
				t0 %= MOD;
			}
			// cout<<temp[XOR][i].first.first<<" "<<temp[XOR][i].first.second<<" "<<t0<<" "<<tx<<endl;
		}
