		for(int i = 1; i < zero[N]; i++){
			po <<= 1;
			po %= MOD;
		}
		// cout<<po<<" "<<zero[N]<<endl;

		ans += po;
		for(int i = 1; i <= max_; i++){
			int t0 = 1, tx = 0;
			for(int j = 0; j < temp[i].size(); j++){
				if(temp[i][j].first.first){
					tx += t0;
					tx %= MOD;
				} else {
					t0 += tx*temp[i][j].first.second;
					t0 %= MOD;
				}

			}
			ans += tx;
			// cout<<i<<" "<<tx<<endl;
			ans %= MOD;
		}
	}

	cout<<ans<<endl;

	return 0;
}

