            flex[cur] = MOD(flex[cur] + cnt, M);

            if (i + 1 == n)
                ans = cnt;
        }

        vpi segs;
        int prev = 0;
        cur = 0;

        for (int i = 0; i < n; ++i)
        {
            cur ^= kek[i];
            if (!cur)
            {
                segs.push_back(mp(prev, i));
                prev = i + 1;
            }
        }

        map<int, vi> vseg;
        map<int, map<int, int>> hui;

        for (int i = 0; i < SZ(segs); ++i)
        {
            auto p = segs[i];

            int l = p.first, r = p.second;
            for (int j = l; j < r; ++j)
                vseg[lel[r] ^ lel[j]].push_back(i),
                hui[lel[r] ^ lel[j]][i]++;
        }

        for (auto p : vseg)
        {
            vi cur = p.second;
            stable_sort(ALL(cur));
            cur.erase(unique(ALL(cur)), cur.end());

            vpi dp(SZ(cur));

            for (int i = 0; i < SZ(dp); ++i)
                dp[i].first = hui[p.first][cur[i]],
                dp[i].second = hui[p.first][cur[i]];

            for (int i = 0; i + 1 < SZ(dp); ++i)
            {
                int d = cur[i + 1] - cur[i];

                {//open - yes

                    {//will close - yes

                        {//next person - block - Yes
                            dp[i + 1].second += dp[i].first * d;
                        }

                        {//next person - block - No
                            dp[i + 1].first += dp[i].first * (d - 1) * hui[p.first][cur[i + 1]];
                            dp[i + 1].second += dp[i].first * (d - 1) * hui[p.first][cur[i + 1]];
                        }
                    }

                    {//will close - no
                        dp[i + 1].first += dp[i].first;
                    }

                }



                {//open - no

                    {//next person - block - Yes
                        dp[i + 1].second += dp[i].second;
                    }

                    {//next person - block - No
                        dp[i + 1].first += dp[i].second * hui[p.first][cur[i + 1]];
                        dp[i + 1].second += dp[i].second * hui[p.first][cur[i + 1]];
                    }
                }
            }

            ans += dp.back().first;
        }
    }

    cout << ans;
}

