template< class T >
struct CumulativeSum {
  vector< T > data;

  CumulativeSum(int sz) : data(sz, 0) {};

  void add(int k, T x) {
    data[k] += x;
  }

  void build() {
    for(int i = 1; i < data.size(); i++) {
      data[i] += data[i - 1];
    }
  }

  T query(int k) {
    if(k < 0) return (0);
    return (data[min(k, (int) data.size() - 1)]);
  }
};


int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;

  vector< int > belong[1 << 20];
  int sum = 0;
  CumulativeSum< int > zero(N);
  for(int i = 0; i < N; i++) {
    sum ^= A[i];
    belong[sum].emplace_back(i);
    if(sum == 0) zero.add(i, 1);
  }
  zero.build();

  modint ret;
  for(int i = 1; i < (1 << 20); i++) {
    modint none = 1, dp0 = 0, dp1 = 0;
    int pv = -1;
    if(belong[i].empty()) continue;

    if(sum == 0) belong[i].emplace_back(N);

    for(auto &p : belong[i]) {

      if(p == N - 1) {
        ret += none + dp0;
        break;
      } else if(p == N) {
        ret += dp1;
        break;
      }

      dp0 += dp1 * (zero.query(p) - zero.query(pv));
      dp1 += none + dp0;
      pv = p;
    }
  }

  if(sum == 0) {
    modint none = 1, dp0 = 0;
    for(auto &p : belong[0]) {
      if(p == N - 1) {
        ret += dp0;
        break;
      }
      dp0 += dp0 + none;
    }
    ret += 1;
  }

  cout << ret << endl;
}

