            }
        }
    if (a[n] == 0) {
        int pw = 1;
        for (int i = 1; i < n; i++)
            if (a[i] == 0) pw = pw * 2 % mod;
            else res = (res + my[i]) % mod;
        res = (res + pw) % mod;
    } else res = my[n];
    printf("%d\n", res);
    return 0;
}

