vector<int> pos[MX];
int find_nxt(int p,int num) {
    auto it = upper_bound(pos[num].begin(), pos[num].end(), p);
    if (it==pos[num].end()) return n+1;
    return *it;
}
int find_cnt(int p1,int p2,int num) {
    auto it1 = upper_bound(pos[num].begin(), pos[num].end(), p1);
    auto it2 = lower_bound(pos[num].begin(), pos[num].end(), p2);
    if (it2 == pos[num].begin()) return 0;
    it2 -= 1;
    if (it1<=it2) return it2-it1+1;
    return 0;
}
