using namespace std;
constexpr int md = 1e9 + 7;
inline void add(int &a, int b) {
  a += b;
  if (a >= md) a -= md;
}
inline void sub(int &a, int b) {
  a -= b;
  if (a < 0) a += md;
}
inline int mul(int a, int b) {
  return (int)((long long)a * b % md);
}
inline int mow(int a, long long b) {
  int res = 1;
  while (b > 0) {
    if (b & 1) {
      res = mul(res, a);
      b--;
    }
    a = mul(a, a);
    b >>= 1;
  }
  return res;
}
inline int inv(int a) {
  a %= md;
  if(a < 0) a += md;
  int b = md, u = 0, v = 1;
  while (a) {
    int t = b / a;
    b -= a * t; swap(a, b);
    u -= v * t; swap(u, v);
  }
  assert(b == 1);
  if(u < 0) u += md;
  return u;
}
int cal (vector<int>& v) {
  if (v.size() <= 1) return 0;
  int k = v.size();
  v.insert(v.begin(), 0);
  vector<int> dp(k + 1, 0), acm(k + 1, 0);
  dp[1] = acm[1] = v[1];
  for (int i = 2; i <= k; i++) {
    dp[i] = mul(v[i], acm[i - 1]);
    acm[i] = acm[i - 2]; add(acm[i], dp[i]);
  }
  return mul(dp[k], inv(mul(v[1], v[k])));
}
