int a[500500];
int sum[500500];

ll solve(int s){
	ll f = 1, g = 0, cnt = 0;
	ll lastf = 0;
	rep(i, n){
		if(sum[i] == s) cnt++;
		if(sum[i] == 0){
			ll nf, ng;
			ng = (f * cnt + g) % Mod;
			nf = (ng + f) % Mod;
			f = nf, g = ng; 
			cnt = 0;
		}
	}
	if(sum[n-1] == 0) return g;
	return f;
}

int main(){
	freopen("b.in", "r", stdin);
	freopen("b.out", "w", stdout);
	ios::sync_with_stdio(false);
	cin >> n;
	rep(i, n) cin >> a[i];
	sum[0] = a[0];
	for(int i = 1; i < n; i++) sum[i] = sum[i-1] ^ a[i];
	if(sum[n-1] == 0){
		ll ans = 1LL;
		rep(i, n-1) if(sum[i] == 0) ans = ans * 2 % Mod;
		for(int s = 1; s < (1 << 10); s++) ans = (ans + solve(s)) % Mod;
		cout << ans << endl;
	} else {
		cout << solve(sum[n-1]) << endl;
	}
	return 0;
}

