unordered_map<long,long> search(const vector<long>& a,int start,int end){
    unordered_map<long,long> ret;
    long te = 0;
    for(int i = start;i < end;++i){
        te ^= a[i];
        ++ret[te];
    }
    return ret;
}

int main() {
    int n;
    cin >> n;
    vector<long> a(n,0);
    for(int i = 0;i < n;++i)cin >> a[i];

    long te = 0;
    for(int i = 0;i < a.size();++i){
        te ^= a[i];
    }
    if(te != 0)cout << 1 << endl;

    vector<unordered_map<long,long>> memo;

    long t = 0;
    int last = -1;
    for(int i = 0;i < a.size();++i){
        t ^= a[i];
        if(t == 0){
            auto au = search(a,last + 1,i + 1);
            memo.push_back(au);
            last = i;
        }
    }


    unordered_map<long,long> res;
    for(int i = 0;i < memo.size();++i){
        unordered_map<long,long> m = memo[i];
        for(auto p = m.begin();p != m.end();++p){
            if(res[(*p).first] == 0)res[(*p).first] = (*p).second + 1;
            else{
                res[(*p).first] *= ((*p).second + 1);
                res[(*p).first] %= BIG;
            }
        }
    }

    long oo = 0;
    for(auto p = res.begin();p != res.end();++p){
        oo += (*p).second;
    }

    cout << oo << endl;
  //  cout << search(a,0,n,-1) << endl;
}

#include"bits/stdc++.h"
using namespace std;
#define LL long long
#define PB push_back
#define MP make_pair

const LL MOD = 1000000007;

int N;
int A[500000];
int wa[500000];

LL dp1[500000][2];
LL solve1(int now, int z){
	if(now == N-1 && z == 1) return 1;
	if(now == N-1) return 0;
	if(dp1[now][z] != -1) return dp1[now][z];
	dp1[now][z] = solve1(now+1, z);
	if(z == 0 && wa[now] == 0){
		//cout << "y" << endl;
		dp1[now][z] += solve1(now+1, 1);
	}
	if(z == 1 && wa[now] == wa[N-1]){
		//cout << now << " y1" << endl;
		dp1[now][z] += solve1(now+1, 0);
	}
	return dp1[now][z] = dp1[now][z] % MOD;
}

vector<int> all[1<<20];
int dp2[500000];
LL solve2(int now){
	if(dp2[now] != -1) return dp2[now];
	dp2[now] = 1;
	int tmp = wa[now];
	int idx = lower_bound(all[tmp].begin(), all[tmp].end(), now) - all[tmp].begin();
	if(tmp == 0){
		for(int i=idx+1; i<all[tmp].size(); i++){
			int nx = all[tmp][i];
			dp2[now] += solve2(nx);
		}
		return dp2[now] = dp2[now] % MOD;
	}
	for(int i=idx+1; i<all[tmp].size(); i++){
		int nx = all[tmp][i];
		LL s = upper_bound(all[0].begin(), all[0].end(), nx)-lower_bound(all[0].begin(), all[0].end(), now);
		dp2[now] += s*solve2(nx);
		dp2[now] %= MOD;
	}
	return dp2[now] = dp2[now] % MOD;
}

int main(){
	scanf("%d", &N);
	for(int i=0; i<N; i++) scanf("%d", A+i);
	wa[0] = A[0];
	for(int i=1; i<N; i++) wa[i] = (wa[i-1] ^ A[i]);
	for(int i=0; i<N; i++){
		all[wa[i]].PB(i);
		//cout << wa[i] << endl;
	}
	if(wa[N-1] != 0){
		for(int i=0; i<N; i++){
			dp1[i][0] = -1;
			dp1[i][1] = -1;
		}
		printf("%lld\n", solve1(0, 1));
	}
	else{
		for(int i=0; i<N; i++){
			dp2[i] = -1;
		}
		LL ans = 0;
		int z = 0;
		for(int i=0; i<N; i++){ //最初の区切り
			if(wa[i] == 0){
				z++;
				continue;
			}
			ans += solve2(i);
		}
		LL tmp = 1;
		for(int i=0; i<z-1; i++){
			tmp *= 2;
			tmp %= MOD;
		}
		printf("%lld\n", (ans+tmp)%MOD);
	}
}

