using namespace std;

const int maxN = 500000;
const int mod = 1000000007;

int N;
int A[maxN];
int X[maxN + 1];
int g[maxN + 1];

template <class T>
inline int remainder(const T & x) {
	if (x < 0)
		return x + mod;
	else if (x < mod)
		return x;
	else
		return x - mod;
}

void initialize() {
	g[0] = 1;
	for (int i = 1; i <= maxN; i++)
		g[i] = remainder(g[i - 1] << 1);
}

int answer() {
	X[0] = 0;
	for (int i = 0; i < N; i++)
		X[i + 1] = X[i] ^ A[i];

	map<int, vector<int> > idxmap;
	for (int i = 0; i <= N; i++)
		idxmap[X[i]].push_back(i);

	vector<int> vtr;
	if (X[N] == 0) {
		for (const auto & p : idxmap)
			vtr.push_back(p.first);
	} else
		vtr.push_back(X[N]);

	int ans = 0;
	int f[2];
	auto & idx0 = idxmap[0];
	bool b = X[N];
	for (const auto & x : vtr) {
		auto & idx1 = idxmap[x];
		if (x == 0)
			ans = remainder(ans + g[idx0.size() - 2]);
		else {
			f[0] = 1;
			f[1] = 0;
			for (int i = 1, j = 0; i < idx0.size() || j < idx1.size(); ) {
				if (i < idx0.size() && (j == idx1.size() || idx0[i] < idx1[j])) {
					f[0] = remainder(f[0] + f[1]);
					i++;
				} else {
					f[1] = remainder(f[0] + f[1]);
					j++;
				}
			}
			ans = remainder(ans + f[b ^ 1]);
			memset(f, 0, sizeof f);
		}
	}

	return ans;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	initialize();

	cin >> N;
	for (int i = 0; i < N; i++)
		cin >> A[i];

	cout << answer() << '\n';

	return 0;
}

