int dp(vector<vector<int>> V) {
    vector<vector<int>> D(V.size()+1, vector<int>(2,0));
    D[0][0] = 1; D[0][1] = 0;
    for (int i=1;i<=V.size();i++) {
        D[i][0] = D[i-1][0];
        D[i][1] = D[i-1][1];
        if (V[i-1][0] == 0) {
            D[i][0] += D[i-1][1]*V[i-1][1] % MOD;
        } else {
            D[i][1] += D[i-1][0];
        }
        D[i][0] %= MOD;
        D[i][1] %= MOD;
    }
    return D[V.size()][1];
}

