int go(vector<int> & v)
{
    if (v.empty())
        return 0;
    ll dp[2] = {1,1};
    for (int i = 1; i < v.size(); ++i) {
        int j = v[i], k = v[i-1];
        int o = s0[j] - s0[k];
        dp[0] = (dp[0] + dp[1] * o) % M;
        dp[1] = (dp[1] + dp[0]) % M;
    }
    if (v.back() == n)
        return dp[0];
    return dp[1];
}
ll solve2()
{
    for (int i = 1; i <= n; ++i) {
