      for (int i = 1; i <= N; ++i) {
        for (int c = 0; c < 2; ++c) {
          if (pre[i] == 0) {
            (dp[i + 1][c][1][1] += dp[i][c][0][0]) %= M;
            (dp[i + 1][c][1][1] += dp[i][c][0][1]) %= M;
          } else if (pre[i] == pre[N]) {
            (dp[i + 1][c ^ 1][0][1] += dp[i][c][1][0]) %= M;
            (dp[i + 1][c ^ 1][0][1] += dp[i][c][1][1]) %= M;
          }
