ll inq(ll x, ll q)
{
    if (q == 0)
        return 1;
    ll l = inq(x, q / 2);
    if (q % 2)
    {
        return l * l % MOD * x % MOD;
    }
    else
    {
        return l * l % MOD;
    }
}

