    //cout << x << endl;
    //pos[x].push_back(n);
    vector<int> dp(pos[x].size());
    ll summ0 = 0, summx = 1;
    ll worked_zeroes = 0;

    for (int i = 0; i < pos[x].size(); i++)
    {
        dp[i] = summx;
        summ0 += summx;
        summ0 %= MOD;

        if (i + 1 < pos[x].size())
        {
            worked_zeroes = cnt_of_0[pos[x][i]];
            ll new_zeroes = cnt_of_0[pos[x][i + 1]] - worked_zeroes;
            summx = (summx + summ0 * new_zeroes) % MOD;
        }
