template <std::uint_fast64_t Modulus> class modint {
  using u64 = std::uint_fast64_t;

  u64 a;

public:
  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr bool operator==(const modint rhs) const noexcept {
    return modint(*this).value() == rhs.value();
  }
  modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  modint &operator/=(modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};
using mint = modint<MOD>;

typedef vector<mint> vec;
typedef vector<vector<mint>> mat;

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;

  vector<int> a(n);
  REP(i,n) cin >> a[i];

  vector<int> s(n,a[0]);
  REP(i,n-1){
    s[i+1] = s[i]^a[i+1];
  }

  mat dp(2,vec(1<<20,0));
  vector<int> cnt(1<<20,0);
  REP(i,1<<20) dp[1][i] = 1;

  int sum = 0;
  REP(i,n-1){
    if(s[i]){
      dp[1][s[i]] += dp[0][s[i]]*(sum-cnt[s[i]]); //次に1をとるやつ まとめて更新
      dp[0][s[i]] += dp[1][s[i]]; //次に0をとるやつ
      cnt[s[i]] = sum;
    }
    else sum++;
  }

  if(s[n-1]) cout << (dp[1][s[n-1]]+dp[0][s[n-1]]*(sum-cnt[s[n-1]])).value() << endl;
  else{
    mint ans = 1;
    REP(_,sum) ans *= 2;
    vector<int> flag(1<<20,0);
    REP(i,n){
      if(!s[i] || flag[s[i]]) continue;
      ans += dp[0][s[i]];
      flag[s[i]]++;
    }
    cout << ans.value() << endl; 
  }

  return 0;
}

