const int MAXN = 3010;

vl fact(MAXN);
vl rfact(MAXN);

ll mod_pow(ll x, ll p, ll M = MOD) {
  ll a = 1;
  while (p) {
    if (p % 2)
      a = a*x%M;
    x = x*x%M;
    p /= 2;
  }
  return a;
}

ll mod_inverse(ll a, ll M = MOD) {
  return mod_pow(a, M - 2, M);
}

void set_fact(ll n, ll M = MOD) {
  fact[0] = fact[1] = rfact[0] = rfact[1] = 1;
  for (ll i = 2; i <= n; i++) {
    fact[i] = i * fact[i - 1] % M;
    rfact[i] = mod_inverse(fact[i], M);
  }
}

//http://drken1215.hatenablog.com/entry/2018/06/08/210000
//nが大きくfactが計算できないときのほかの計算方法について書いてある
ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  ll ret = fact[n];
  ret = (ret*rfact[r]) % M;
  ret = (ret*rfact[n - r]) % M;
  return ret;
}


int n;
vi a;

ll solve1(int x) {
  int now = 0;
  int cnt = 0;
  rep (i, n) {
    now ^= a[i];
    if (now == x) {
      cnt++;
      now = 0;
    }
  }

  vll dp(cnt + 1, vl(2));
  dp[0][0] = 1;
  rep (i, cnt) {
    rep (j, 2) {
      if (j == 0) {
        (dp[i + 1][0] += dp[i][j]) %= MOD;
        (dp[i + 1][1] += dp[i][j]) %= MOD;
      }
      else {
        (dp[i + 1][0] += dp[i][j]) %= MOD;
      }
    }
  }
  return dp[cnt][0];
}

ll solve21() {
  int now = 0;
  ll cnt = 0;
  rep (i, n) {
    now ^= a[i];
    if (now == 0) cnt++;
  }
  cnt--;
  return mod_pow(2, cnt);
}

ll solve22() {
  while (a.size() > 0 && a.back() == 0) a.pop_back();
  reverse(all(a));
  while (a.size() > 0 && a.back() == 0) a.pop_back();
  reverse(all(a));

  n = a.size();
  if (n == 0) return 0;

  vi b(n + 1);
  rep (i, n) {
    b[i + 1] = b[i] ^ a[i];
  }

  const int log = 20;

  vll dp(1 << log, vl(2));
  rep (i, 1 << log) {
    dp[i][0] = 1;
  }
  vi al(1 << log);

  int cnt = 0;
  rep1 (i, n) {
    if (b[i] == 0) {
      cnt++;
    }
    else {
      int x = b[i];
      (dp[x][0] += (cnt - al[x]) * dp[x][1] % MOD) %= MOD;
      (dp[x][1] += dp[x][0]) %= MOD;
      al[x] = cnt;
    }
  }

  ll res = 0;
  rep (i, 1 << log) {
    if (i == 0) continue;
    (res += dp[i][1]) %= MOD;
  }
  return (res + MOD) % MOD;
}

