int calc(int x)
{
    int dp[2] = {0};
    dp[0] = 1;

    int s = 1;
    int l = 0, r = 0;
    while(1)
    {
        r = l + 1;
        while(r < v[x].size() && sum[v[x][r]] - sum[v[x][l]] == 0)
        {
            r++;
        }

        int t = r - l;
        dp[1] = (dp[1] + (LL) dp[0] * t) % MOD;

        if(r < v[x].size())
        {
            t = sum[v[x][r]] - sum[v[x][l]];
            dp[0] = (dp[0] + (LL) dp[1] * t) % MOD;
        }
        else
        {
            if(v[x].back() == n) s = 0;
            else s = 1;
            break;
        }

        l = r;
    }

    return dp[s];
}

