vector < int > compute(vector < int > &g)
{
        vector < int > res;

        int S = 0, T = 0;
        for(int x: g){
                d[x] = 1;
                add(d[x], 1ll * S * s[x] % mod);
                add(d[x], T);
                add(T, - 1ll * d[x] * s[x] % mod);
                add(S, d[x]);
                res.push_back(d[x]);
        }
        return res;
}

