const long long MAXN = 1 << 20, MOD = 1e9 + 7, INF = ((1ll << 60) - 1) * 2 + 1;

//mt19937 random(time(0));

ll n, m;

ll ar[ll(5e5+1)];
ll pre[MAXN];

vector<ll> gap[MAXN];
vector<ll> c[MAXN];

ll temp[MAXN];

ll f(ll id){
    ll num = c[id][0];
    ll cnt = 0;

    ll ans = num;
    forI(i, gap[id].size()){
        ll val = (num * c[id][i] % MOD * gap[id][i - 1] % MOD + cnt * c[id][i] % MOD) % MOD;

        ans += val + c[id][i];
        ans %= MOD;

        cnt = (cnt + num * gap[id][i - 1]) % MOD;
        num = val;
    }
    return ans;
}

ll pw(ll a, ll b){
    if(b == 0) return 1;
    ll e = pw(a, b >> 1);
    if(b & 1) return e * e % MOD * a % MOD;
    return e * e % MOD;
}

void solve() {
    cin >> n;
    ll xr = 0;
    vector<ll> gc;
    ll block_num = 0;
    forI(i, n){
        cin >> ar[i];
        xr ^= ar[i];
        ar[i] = xr;

        ++temp[xr];
        if(temp[xr] == 1) gc.push_back(xr);

        if(xr == 0){
            ++block_num;
            for(ll e: gc){
                c[e].push_back(temp[e]);
                temp[e] = 0;

                if(pre[e])
                    gap[e].push_back(block_num - pre[e]);
                pre[e] = block_num;
            }
            gc.clear();
        }
    }


    if(xr){
        ll cnt = 0;
        fori(i, n){
            if(cnt % 2 == 0 && ar[i] == xr) ++cnt;
            else if(cnt % 2 == 1 && ar[i] == 0) ++cnt;
        }
        //fibonacci?
        ll a = 0;
        ll b = 1;
        fori(i, cnt - 1){
            a += b;
            if(a >= MOD) a -= MOD;
            swap(a, b);
        }
        cout << b;
        return;
    }


    ll ans = pw(2, block_num - 1);
    fori(i, MAXN){
        if(pre[i]){
            //delete?
            if(i == 0) continue;


            ans += f(i);
            ans %= MOD;
        }
    }
    cout << ans;
}

