signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	V<int> b(a);
	REP(i, n - 1) b[i + 1] ^= b[i];

	if (b.back()) {
		const int X = b.back();
		VV<int> dp(n + 1, V<int>(2, 0));
		dp[0][0] = 1;
		REP(i, n) REP(j, 2) {
			(dp[i + 1][j] += dp[i][j]) %= MOD;
			if (j == 0 && b[i] == X || j == 1 && b[i] == 0) (dp[i + 1][1 - j] += dp[i][j]) %= MOD;
		}
		OUT(dp[n][0])BR;
	}
	else {
		std::map<int, V<int>> map;
		REP(i, n) map[b[i]].emplace_back(i);

		int ans = 0;
		V<int> cnt0(n + 1, 0);
		REP(i, n) cnt0[i + 1] = cnt0[i] + (b[i] == 0);
		for (auto& p : map) {
			int x = p.first;
			if (x == 0) {
				int t = 1;
				REP(_, p.second.size() - 1) (t *= 2) %= MOD;
				(ans += t) %= MOD;
			}
			else {
				V<PAIR> v;
				v.reserve(p.second.size() * 2);
				REP(i, p.second.size()) {
					if (i) v.emplace_back(0, cnt0[p.second[i] + 1] - cnt0[p.second[i - 1]]);
					v.emplace_back(1, 1);
				}

				VV<int> dp(v.size() + 1, V<int>(2, 0));
				dp[0][0] = 1;
				REP(i, v.size()) REP(j, 2) {
					(dp[i + 1][j] += dp[i][j]) %= MOD;
					if (v[i].first != j) (dp[i + 1][1 - j] += dp[i][j] * v[i].second) %= MOD;
				}

				(ans += dp[v.size()][1]) %= MOD;
			}
		}

		OUT(ans)BR;
	}

	return 0;
}
/*
XOR(a) == X > 0
-> b[i] = XOR(a[0,i))
   をつくってdp[i][j]:=i番目まで見て直前に(j?X:0)で区切った場合の数，でDP
   初期条件 : dp[0][0] = 1
   遷移 : dp[i+1][j] += dp[i][j] (いつでも)
		 dp[i+1][1-j] += dp[i][j] (j==0 && b[i]==X || j==1 && b[i]==0)
   解 : dp[n][1]
*/

#include<iostream>
#include<vector>
#define mod 1000000007
#define DIM 500005
using namespace std;
int n, i, ii, sol, sum, s, x;
int z[DIM], d[DIM];
vector<int> v[(1 << 20) + 2];
int main(){
    cin>> n;
    for(i = 1; i <= n; i++){
        cin>> x;
        s ^= x;
        v[s].push_back(i);
        if(s == 0){
            z[i] = 1;
        }
        z[i] += z[i - 1];
    }
    if(s != 0){
        ii = s;
        sum = 1;
        s = 0;
        for(i = 1; i <= v[ii].size() - 1; i++){
            s = (s + sum * 1LL * (z[ v[ii][i] ] - z[ v[ii][i - 1] ]) ) % mod;
            d[i] = (s + 1) % mod;
            sum = (sum + d[i]) % mod;
        }
        cout<< d[ v[ii].size() - 1];
        return 0;
    }
    sol = 1;
    for(i = 1; i < v[0].size(); i++){
        sol = sol * 2 % mod;
    }
    for(ii = 1; ii < (1 << 20); ii++){
        if(v[ii].size() == 0){
            continue;
        }
        sum = 1;
        s = 0;
        for(i = 1; i < v[ii].size(); i++){
            s = (s + sum * 1LL * (z[ v[ii][i] ] - z[ v[ii][i - 1] ]) ) % mod;
            d[i] = (s + 1) % mod;
            sum = (sum + d[i]) % mod;
        }
        sol = (sol + sum) % mod;
    }
    cout<< sol;
}

