        sum[i] = sum[i - 1] + (s[i] == 0);
    }
    int all = 0;
    for(int i = 1 ; i <= N ; ++i) {
        if(s[i] != 0) {
            dp[i] = mul(pre[0][s[i]],sum[i - 1]) + 1;
            update(dp[i],MOD - pre[1][s[i]]);
        }
        else dp[i] = inc(all,MOD - pre[0][0]);
        update(pre[0][s[i]],dp[i]);
        update(pre[1][s[i]],mul(dp[i],sum[i]));
        update(all,dp[i]);
    }
    if(s[N] == 0) {
        update(dp[N],fpow(2,sum[N] - 1));
    }
    out(dp[N] % MOD);enter;
