vector<int> get_zero(const vector<int>& l)
{
	vector<int> z(l.size() - 1);
	for (uint i = 0; i + 1 < l.size(); i++) z[i] = zero[l[i + 1]] - zero[l[i]];
	return z;
}
map<int, vector<int>> indexes(const vector<int>& x)
{
	map<int, vector<int>> dic;
	for (uint i = 0; i < x.size(); i++) dic[x[i]].emplace_back(i);
	return dic;
}
vector<ll> calc(const vector<int>& zs)
{
	auto L = zs.size();
	vector<ll> dp(L + 1, 1);
	ll sum = 1;
	for (uint j = 0; j < L; j++)
	{
		dp[j + 1] = (dp[j] + zs[j] * sum % MOD) % MOD;
		sum = (sum + dp[j + 1]) % MOD;
	}
	return dp;
}
ll pow(ll a, ll b, ll mod)
{
	ll p = 1, x = a;
	while (b > 0)
	{
		if ((b & 1L) == 1L) p = p * x % mod;
		b >>= 1;
		x = x * x % mod;
	}
	return p;
}

