using namespace std;
const long long MOD = 1000000007LL;

long long solve_dp(vector<int>& v) {
    vector<long long> c(2), cp(2);
    c[0] = 1;
    for (int i=0;i<v.size();i++) {
        cp.swap(c);
        c[0] = cp[0];
        c[1] = cp[1];
        if (v[i]==0) {
            c[0] += cp[1];
            if (c[0]>=MOD) c[0] -= MOD;
        }
        if (v[i]==1) {
            c[1] += cp[0];
            if (c[1]>=MOD) c[1] -= MOD;
        }
    }
    return (c[v.back()] + MOD - cp[v.back()]) % MOD;
}

int main() {
