const int M = int(1e9 + 7);

int brute_force(vector<int> a) {
  vector<int> p(a.size() + 1);
  for (int i = 0; i < a.size(); ++i) p[i + 1] = p[i] ^ a[i];
  int ans = 0;
  for (int i = 0; i < 1 << p.size(); ++i) {
    if (~i >> 0 & 1) continue;
    if (~i >> a.size() & 1) continue;
    int s = -1;
    int r = 0;
    for (int j = 1; j < p.size(); ++j) {
      if (~i >> j & 1) continue;
      if (s == -1) s = p[j];
      else if ((p[j] ^ r) != s) {
        s = -1;
        break;
      }
      r = p[j];
    }
    ans += s != -1;
  }
  return ans;
}

