// ＜方針＞
// 累積xorを利用。
// グループ分けをしたときに各グループの要素全てのxorをAとすると、
// Aが0でない場合については
// 累積xorから  0→A→0→A→...→A→0  という部分列の取り出し方を求める問題になる。
// （累積xorが  0,0,A,*,A,0,0,*,*,A,A,0,A,*,A,*,0,*,0   みたいになっていて（*はA,0以外の数）   
//　 そこから 0,A,0,A,0,A,0 のような部分列の取り出し方の総数を求める）
// この計算を全てのAの値について足し合わせるので、単純にdpをすると計算時間が膨大になるが、
// Aのタイミングでだけdp値を更新する形にすれば計算量を抑えることができる。
// 具体的には
//    dp[i]   上記のような数列の1～i番目の項の中から、0,A,0,A,...,0,A   という部分列の取り出し方の数
//    dp0[i]  上記のような数列の1～i番目の項の中から、0,A,0,A,...,0,A,0 という部分列の取り出し方の数
// とおいて、Aのタイミングでだけdp値を求める。
// そのためには前回のAの位置を覚えておくことと、前回のAから今回のAまでの間に出てくる0の数を知ることが必要。
// 前者はAからlast index を知ることができるような map を持つ形、後者は0の個数の累積和を使った。

int main(int argc, char* argv[])
{
    int n;
    scanf("%ld", &n);

    vector<int> a(n), s(n+1), s0(n+1);
    int i;
    s[0]=0, s0[0]=1;
    for(i=0; i<n; i++) {
        scanf("%d", &a[i]);
        s[i+1]=s[i]^a[i];
        s0[i+1]=s0[i]+((s[i+1]==0)? 1: 0);
    }

    map<int, int> z;   // val, previous index
    vector<ll> dp(n), dp0(n);
    dp0[0]=1;
    for(i=1; i<n; i++) {
        if(s[i]!=0) {
            int prev=z[s[i]];
            int num0 = s0[i]-s0[prev];
            dp0[i]=(dp[prev]*(num0)+dp0[prev])%MOD;
            dp[i]=(dp[prev]*(num0+1)+dp0[prev])%MOD;
            z[s[i]]=i;
        }
    }

    ll ans=1;
    if(s[n]==0) {
        for(i=0; i<s0[n]-2; i++) {
            ans = ans*2%MOD;
        }
        auto it=z.begin();
        for(; it!=z.end(); ++it) {
            ans = (ans + dp[it->second])%MOD;
        }
    }
    else {
        int prev=z[s[n]];
        int num0 = s0[n]-s0[prev];
        ans = (dp0[prev] + dp[prev]*num0)%MOD;
    }
    printf("%lld\n", ans);
    return 0;
}

