#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;

const ll MOD = 1e9 + 7;

ll Solve() {
    ll n;
    cin >> n;

    vector<ll> pow2(n + 1);
    pow2[0] = 1;
    for (int i = 1; i <= n; ++i) (pow2[i] = 2 * pow2[i - 1]) %= MOD;

    vector<ll> a(n), cnt_zero(n + 1);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (i != 0) a[i] ^= a[i - 1];
        if (a[i] == 0) ++cnt_zero[i];
    }
    for (int i = 1; i <= n; ++i) cnt_zero[i] += cnt_zero[i - 1];

    vector<int> nxt(n, -1);
    map<int, int> memo;
    for (int i = n - 1; 0 <= i; --i) {
        if (memo.count(a[i]) != 0) nxt[i] = memo[a[i]];
        memo[a[i]] = i;
    }

    // for (int i = 0; i < n; ++i)
    //     cout << "nxt[" << i << "] = " << nxt[i] << endl;
    // for (int i = 0; i <= n; ++i)
    //     cout << "cnt_zero[" << i << "] = " << cnt_zero[i] << endl;
    // for (int i = 0; i < n; ++i)
    //     cout << "a[" << i << "] = " << a[i] << endl;
    // cout << "a.back() = " << a.back() << endl;

    set<int> used;
    ll sum = 1;
    for (int i = 0; i + 1 < n; ++i) {
        if (used.count(a[i]) != 0) continue;
        if (a.back() != 0 && a.back() != a[i]) continue;
        // cout << "start: i = " << i << ", sum = " << sum << endl;

        if (a[i] == 0) {
            // cout << "i = " << i << ": " << sum;
            if (a.back() != 0) continue;
            int num_zero = cnt_zero[n - 1];
            if (i != 0) num_zero -= cnt_zero[i - 1];
            (sum += pow2[num_zero - 1] - 1 + MOD) %= MOD;
            // cout << " -> " << sum << ", num_zero = " << num_zero << endl;
        }
        else {
            ll sum_a = 1, sum_b = 0, idx = i;
            while (nxt[idx] != -1) {
                ll num_zero = cnt_zero[nxt[idx]];
                if (i != 0) num_zero -= cnt_zero[idx - 1];
                (sum_b += (num_zero * sum_a) % MOD) %= MOD;
                (sum_a += sum_b + 1) %= MOD;
                idx = nxt[idx];
            }
            if (idx == n - 1) (sum += sum_b) %= MOD;
            else (sum += sum_a) %= MOD;
        }
        used.insert(a[i]);
        // cout << "end: i = " << i << ", sum = " << sum << endl;
    }

    return sum % MOD;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    // cout << setprecision(8) << setiosflags(ios::fixed);

    cout << Solve() << endl;

    return 0;
}

