using namespace std;

const int MOD = 1000000007;

int modPow(int a, int p){
    if(p == 0) return 1;
    long long half = modPow(a, p/2);
    long long res = (half * half) % MOD;
    if(p % 2) res = (res * a) % MOD;
    return res;
}

int main(){
    int N;
    while(cin >> N){
        vector<int> A(N);
        for(auto& t : A) cin >> t;
        vector<int> B(N+1, 0);
        for(int i=0;i<N;i++) B[i+1] = B[i]^A[i];
        vector<int> checked0(1<<20, 0);
        vector<vector<int>> seq(1<<20, vector<int>());
        int cnt0 = 0;
        long long res = 0;
        if(B.back() == 0){
            for(auto& t : B){
                if(t == 0) ++cnt0;
                else {
                    if(checked0[t] != cnt0){
                        seq[t].push_back(cnt0 - checked0[t]);
                        seq[t].push_back(1);
                        checked0[t] = cnt0;
                    } else {
                        ++seq[t].back();
                    }
                }
            }
            for(int i=0;i<(1<<20);i++){
                seq[i].push_back(cnt0 - checked0[i]);
            }
            res = modPow(2, seq[0][0] - 2);
            for(int i=1;i<(1<<20);i++){
                if(seq[i].size() == 1) continue;
                long long num0 = 1, num1 = 0;
                for(int j=1;j<seq[i].size();j+=2){
                    num1 += num0 * seq[i][j];
                    num1 %= MOD;
                    num0 += num1 * seq[i][j+1];
                    num0 %= MOD;
                }
                res = (res + num1) % MOD;
            }
        } else {
            long long num0 = 1, num1 = 0;
            for(auto& t : B){
                if(t==0){
                    num0 = (num0 + num1) % MOD; 
                } else if(t==B.back()){
                    num1 = (num0 + num1) % MOD;
                }
            }
            res = num1;
        }
        cout << res << endl;
    }
}

