const int MOD = 1000000007;

long long solve(const vector<int>& a)
{
    int n = a.size();
    vector<int> b(n);
    b[0] = a[0];
    for(int i=1; i<n; ++i)
        b[i] = a[i] ^ b[i-1];

    long long ans = 1;
    if(b.back() == 0){
        for(int i=0; i<n-1; ++i){
            if(b[i] == 0){
                ans *= 2;
                ans %= MOD;
            }
        }
    }

    int cnt = 0;
    map<long long, long long> dp1, dp2, prev;
    for(int i=0; i<n; ++i){
        if(b[i] == 0){
            ++ cnt;
        }
        else{
            dp1[b[i]] += dp2[b[i]] * (cnt - prev[b[i]]);
            dp1[b[i]] %= MOD;
            prev[b[i]] = cnt;
            dp2[b[i]] += dp1[b[i]] + 1;
            dp2[b[i]] %= MOD;
        }
    }
    if(b.back() == 0){
        for(const auto& p : dp2){
            ans += p.second;
            ans %= MOD;
        }
    }
    else{
        ans += dp1[b.back()];
        ans %= MOD;
    }
    return ans;
}

long long solve2(const vector<int>& a)
{
    int n = a.size();
    int ans = 0;
    for(int i=0; i<(1<<(n-1)); ++i){
        bitset<32> bs(i);
        set<int> s;
        int x = 0;
        for(int j=0; j<n; ++j){
            x ^= a[j];
            if(!bs[j]){
                s.insert(x);
                x = 0;
            }
        }
        if(s.size() == 1)
            ++ ans;
    }

    return ans;
}

int main()
{
    int n;
    cin >> n;
    vector<int> a(n);
    for(int i=0; i<n; ++i)
        cin >> a[i];

    cout << solve(a) << endl;

    return 0;
}

