vector<int> cnt[1050000];
int n,a[500010],all = 0,ans = 0,lst[1050000],dp[500010];

void calc(int m,bool flag){
	if(cnt[m].size() == 0) return;
	cnt[m][0] = 1;
	dp[0] = 1;
	int odd = 0,even = 1;
	for(int i = 1;i < cnt[m].size();i++){
		dp[i] = ((i % 2) ? even : odd) * cnt[m][i] % MOD;
		if(i % 2) odd = (odd + dp[i]) % MOD;
		else even = (even + dp[i]) % MOD;
	}
	if(flag) ans = (ans + odd) % MOD;
	else ans = dp[cnt[m].size() - 1];
}

signed main(){
	cin >> n;
	int zero = 0;
	for(int i = 0;i < n;i++){
		cin >> a[i];
		all ^= a[i];
		if(!all) zero++;
		cnt[all].pb(zero - lst[all]);
		cnt[all].pb(1);
		lst[all] = zero;
	}
	if(!all){
		for(int i = 1;i < 1050000;i++) calc(i,true);
		int tmp = 1;
		for(int i = 0;i < zero - 1;i++) tmp = tmp * 2 % MOD;
		ans = (ans + tmp) % MOD;
	}else calc(all,false);
	cout << ans << endl;
}

