#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define f(i, x, n) for (int i = x; i < (int)(n); ++i)

int const N = 500000, M = 1 << 20, md = 1e9 + 7;
int x[N + 1], fr[N + 1], an, n;
vector<int> v[M];

inline void ad(int &x, int y) { if ((x += y) >= md)x -= md; }
inline int s0(int l, int r) { return fr[r] - fr[l - 1]; }

void go(vector<int> const &v){
	int sa = 0, dps = 0;
	f(i, 1, v.size()){
		ad(sa, (ll)dps * s0(v[i - 1], v[i]) % md);
		ad(an, sa + 1);
		ad(dps, sa + 1);
	}
}

int main(){
	scanf("%d", &n);
	f(i, 1, n + 1)scanf("%d", x + i);
	f(i, 1, n + 1)x[i] ^= x[i - 1];
	if (x[n]) { printf("1\n"); return 0; }
	f(i, 1, n + 1)fr[i] = fr[i - 1] + (x[i] == 0);
	f(i, 1, M)v[i].push_back(1);
	f(i, 1, n + 1)if (x[i])v[x[i]].push_back(i);
	an = 1;
	f(i, 1, fr[n])ad(an, an);
	f(i, 1, M)go(v[i]);
	printf("%d\n", an);
}

