constexpr long long MOD = 1000000007;

vector<vector<int>> make_vector(vector<int> C, int X) {
    int N = C.size();
    vector<int> Z(N+1,0);
    Z[0] = 0;
    for (int i=1;i<=N;i++) {
        Z[i] = Z[i-1];
        if (C[i-1] == 0) Z[i]++;
    }
    // for (int i=0;i<=N;i++) cout << Z[i] << " ";
    // cout << endl;
    vector<vector<int>> V;
    // cout << X << endl;
    int zero;
    auto itrX = find(C.begin(), C.end(), X);
    auto itrXP = C.begin();
    do {
        zero = Z[itrX-C.begin()+1] - Z[itrXP-C.begin()];
        // if (zero <= 0) (V.back())[1]++;
        if (zero <= 0) V[V.size()-1][1]++;
        else {
            V.push_back(std::vector<int>({0, zero}));
            V.push_back(std::vector<int>({X, 1}));
        }
        itrXP = itrX;
        itrX = find(itrX+1, C.end(), X);
    } while (itrX != C.end());
    return V;
}

int main(void) {
    int N, ret = 0;
    cin >> N;
    vector<int> A(N,-1), C(N+1,-1);
    for (int i=0;i<N;i++) cin >> A[i];

    C[0] = 0;
    for (int i=1;i<=N;i++) C[i] = C[i-1]^A[i-1];
    // for (int i=0;i<=N;i++) cout << C[i] << " ";
    // cout << endl;

    if (C[N] != 0) {
        int X = C[N];
        vector<vector<int>> V;
        V = make_vector(C,X);
        vector<vector<int>> dp(V.size()+1, vector<int>(2,0));
        dp[0][0] = 1; dp[0][1] = 0;
        for (int i=1;i<=V.size();i++) {
            dp[i][0] = dp[i-1][0];
            dp[i][1] = dp[i-1][1];
            if (V[i-1][0] == 0) {
                dp[i][0] += dp[i-1][1]*V[i-1][1];
            }
            if (V[i-1][0] == X) {
                dp[i][1] += dp[i-1][0];
            }
            dp[i][0] %= MOD;
            dp[i][1] %= MOD;
        }
        // for (int i=0;i<=V.size();i++) cout << V[i][0] << " ";
        // cout << endl;
        // for (int i=0;i<=V.size();i++) cout << V[i][1] << " ";
