        // for (int i=0;i<=V.size();i++) cout << dp[i][0] << " ";
        // cout << endl;
        // for (int i=0;i<=V.size();i++) cout << dp[i][1] << " ";
        // cout << endl;
        // cout << X << endl;
        ret = dp[V.size()][1];
        ret %= MOD;
    } else {
        vector<int> U(C);
        sort(U.begin(),U.end());
        reverse(U.begin(), U.end());
        unique(U.begin(), U.end());
        auto itr = find(U.begin(), U.end(), 0);
        U.erase(itr, U.end());

        for (auto& X : U) {
            vector<vector<int>> V = make_vector(C,X);
            vector<vector<int>> dp(V.size()+1, vector<int>(2,0));
            dp[0][0] = 1; dp[0][1] = 0;
            for (int i=1;i<=V.size();i++) {
                dp[i][0] = dp[i-1][0];
                dp[i][1] = dp[i-1][1];
                if (V[i-1][0] == 0) {
                    dp[i][0] += dp[i-1][1]*V[i-1][1];
                }
                if (V[i-1][0] == X) {
                    dp[i][1] += dp[i-1][0];
                }
                dp[i][0] %= MOD;
                dp[i][1] %= MOD;
            }
            // cout << X << endl;
            ret += dp[V.size()][1];
            ret %= MOD;
        }
        int cnt = 0;
        itr = find(C.begin(), C.end(), 0);
        do {
            cnt++;
            itr = find(itr+1, C.end(), 0);
        } while (itr != C.end());
        ret += (1LL<<(cnt-2)) % MOD;
        ret %= MOD;
    }

    cout << ret << endl;
    return 0;
}

