                dp[i + 1][0] += dp[i][1]; // 1->0の遷移
            } else if (A[i] == 0) {
                dp[i + 1][1] += dp[i][0]; // 0->1の遷移
            }
            dp[i + 1][0] += dp[i][0]; // 0->0の遷移
            dp[i + 1][1] += dp[i][1]; // 1->1の遷移
        }
        cout << dp[n][1] << endl; // n-1個目までで0,末尾の1を取る
        //REP (i, 0, n + 2) {
        //    cout << dp[i][0] << " " << dp[i][1] << endl;
        //}
    } else {
        assert(n == 0);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define MAX (1 << 20)
#define mod 1000000007

long long dp[MAX+1][2];
long long zerocount[MAX+1];
int pre[MAX+1];


long long modpow(int n, int r) {
    long long ret = 1; long long tmp = (long long) n;
    while (r != 0) {
        if (r % 2) ret *= tmp;
        tmp *= tmp; tmp %= mod; ret %= mod;
        r /= 2;
    }
    return ret;
}

int main() {
    int n; cin >> n;
    vector<int> v(n); int all = 0;
    for (int i = 0; i < n; i++) {
        cin >> v[i]; all ^= v[i]; v[i] = all;
    }
    memset(pre, -1, sizeof(pre));
    for (int i = 0; i < n; i++) {
        int c = v[i];
        zerocount[i+1] = zerocount[i] + (c == 0);
        if (pre[c] == -1) {
            dp[c][0] = 1; dp[c][1] = 1;
        } else {
            long long zc = (zerocount[i]-zerocount[pre[c]]);
            dp[c][1] = (dp[c][1] + zc * dp[c][0]) % mod;
            dp[c][0] = (dp[c][0] + dp[c][1]) % mod;
        }
        pre[c] = i;
    }
    long long sum = 0;
    for (int i = 1; i <= MAX; i++) {
        sum += dp[i][0]; sum %= mod;
    }
    if (all) {
        cout << dp[all][1] % mod << endl;
    } else {
        long long ans = sum + modpow(2, zerocount[n]-1);
        cout << ans % mod << endl;
    }
    return 0;
}

