int mul(int x, int y) {
    return (1LL * x * y) % mod;
}

int get_pr(int x, int pos) {
    auto it = lower_bound(all[x].begin(), all[x].end(), pos);
    if (it == all[x].begin()) {
        return -1;
    }
    --it;
    return *it;
}

bool get_bit(int mask, int pos) {
    return (bool) (mask & (1 << pos));
}

int triv() {
    int ans = 0;
    for (int mask = 0; mask < (1 << (n - 1)); ++mask) {
        int f = 0, x = -1, ok = 1;
        for (int i = 0; i < n; ++i) {
            if (get_bit(mask, i) || i + 1 == n) {
                if (x == -1) {
                    x = a[i];
                }
                if (f == 0 && x != a[i]) {
                    ok = 0;
                    break;
                }
                if (f == 1 && a[i] != 0) {
                    ok = 0;
                    break;
                }
                f ^= 1;
            }
        }
        if (x == 2) ans += ok;
    }
    return ans;
}

