        cin >> a[i];
        b[i+1] = b[i] xor a[i];
    }
    mint zero = (mint)0,posi = (mint)1;
    mint ans = 0;
    for(int i = n;i >= 1;i--){
        if(b[i] == b[n-1]){
            zero += posi;
        }else if(b[i] == 0){
            posi += zero;
        }else{
            continue;
        }
    }
    ans += posi;
    if(b[n] == 0)ans = (mint)0;
    else{cout << ans.x << '\n';return 0;}

    vector<int> cum(n+1,0);
    for(int i = 0;i <= n;i++){
        if(i == 0)cum[i] = 1;
        else cum[i] = cum[i-1] + (b[i] == 0);
    }

    vector<vector<int> > pos((1 << 20),vector<int>(0));
    for(int i = 0;i < n+1;i++){
        pos[b[i]].push_back(i);
    }
    ans += mod_pow(2,cum[n] - 2);
    for(int i = 1;i < (1 << 20);i++){
        if(pos[i].size() == 0)continue;
        else{
            vector<pair<int,int> > run;//element,size
            for(int j = 0;j < pos[i].size();j++){
                if(j == 0)run.emplace_back(0,cum[j]);
                else if(cum[pos[i][j]] - cum[pos[i][j-1]] > 0)run.eb(0,cum[pos[i][j]] - cum[pos[i][j-1]]);
                run.emplace_back(i,1);
            }
            run.eb(0,1);
            int m = run.size();
            zero = (mint)1,posi = (mint)0;
            for(int i = m-2;i >= 1;i--){
                if(run[i].first != 0){
                    posi += zero;
                }else{
                    zero += (mint)run[i].second * posi;
                }
            }
            ans += posi;
        }
    }
    cout << ans.x << '\n';
}
