#define ll long long
const int MOD=1000000007;

ll dip(ll x){
  ll a=1,b=2;
  while(x){
    if(x%2){
      a*=b;
    }
    x/=2;
    a%=MOD;
    b%=MOD;
  }
  return a;
}

int main(){
  map<ll,pair<int,int>> X;
  map<ll,ll> M;
  ll N,k=0,a,it=0;
  cin>>N;
  for(int i=0;i<N;i++){
    cin>>a;
    k=k^a;
    if(k==0)
      it++;
    else{
      X.try_emplace(k,{1,0});
      M.try_emplace(k,it);
      if(M.at(k)!=it){
        X.at(k).second+=(it-M.at(k))*X.at(k).first%MOD;
        M.at(k)=it;
      }
      X.at(k).first+=X.at(k).second+1;
      X.at(k).first%=MOD;
    }
  }
  auto itX=X.begin();
  auto itM=M.begin();
  ll cnt=0;
  if(k==0){
    while(itX!=X.end()){
      cnt+=*X.second+(it-*M)*(*X).first%MOD;
    }
    cnt+=dip(it);
  }else{
    cnt=X.at(k).first;
  }
  cnt%=MOD;
  cout<<cnt<<endl;
}

