  preff.resize(n);
  for (int i = 0; i < n; i++) {
    cin >> A[i];
    preff[i] = A[i];
    if (i) {
      preff[i] ^= preff[i - 1];
    }
    if (preff[i] == 0) {
      zero.push_back(i);
    } else {
      imp[preff[i]].push_back(i);
    }
  }
  long long int ans = 0;
  for (int el = 1; el < N; el++) {
    if (imp[el].size() == 0) {
      continue;
    }
