      continue;
    }
    //cout << el << ' ' << imp[el].size() << endl;
    int sz = imp[el].size();
    vector<ll> dp(sz, 0);
    ll cur = 0, suff = 0;
    for (int i = sz - 1; i >= 0; i--) {
      if (i == sz - 1) {
        dp[i] = 1;
        cur = 0;
        suff = dp[i];
        continue;
      }
      int qnt = upper_bound(zero.begin(), zero.end(), imp[el][i + 1]) - lower_bound(zero.begin(), zero.end(), imp[el][i]);
      dp[i] = (cur + 1 + suff * 1ll * qnt % mod) % mod;
      cur = (cur + dp[i + 1] * 1ll * qnt % mod) % mod;
      suff = (suff + dp[i]) % mod;
    }
    for (int i = 0; i < sz; i++) {
      //cout << dp[i] << ' ';
