	return p2 - p1;
}

int calc(int x) {
	memset(dp, 0, sizeof dp);
	int s = 0, t = 0;
	for(int i=0;i<(int)p[x].size();i++) {
		if(i>0) s = ma.add(s, ma.mul(t, get_cnt(p[x][i-1], p[x][i], 0)));

		// printf("- %d\n", t);
		dp[i] = (i==0) ? 1 : ma.add(s, 1);

		t = ma.add(t, dp[i]);
	}
	int res = dp[(int)p[x].size()-1];
	// printf("! %d %d %d\n", x, res, t);
	return t;
