        l_l now;
        now.first = i;
        ll deltazero = 0;
        if(!dp[xorsum[i]].empty()) deltazero = timesofzero[i] - timesofzero[dp[xorsum[i]].back().first];
        now.second = 1;
        now.second += dp[xorsum[i]].size() * deltazero;
        now.second %= mod;
        dp[xorsum[i]].push_back(now);
