const int maxn = 512345;
const int MOD = 1e9 + 7;

int n, a[maxn];
vector<int> G[1 << 20];

inline int add(int x, int y) {
  x += y;
  if (x >= MOD) x -= y;
  return x;
}

inline int mul(int x, int y) {
  return ll(x) * y % MOD;
}

int pow_mod(int x, int k) {
  int ret = 1;
  while (k) {
    if (k & 1) ret = mul(ret, x);
    x = mul(x, x);
    k >>= 1;
  }
  return ret;
}

int solve(int mask) {
  if (G[mask].empty()) return 0;
  vector<int> c0, cn;
  int m = G[mask].size(), cnt = 1, pre = 0;
  c0.eb(1);
  FOR(i, 1, m - 1) {
    auto it1 = lower_bound(all(G[0]), G[mask][i - 1]), it2 = lower_bound(all(G[0]), G[mask][i]);
    if (it1 != it2) {
      c0.eb(distance(it1, it2));
      cn.eb(i - pre);
      pre = i;
      cnt++;
    }
  }
  cn.eb(m - pre);
  int pre0 = 1, pre1 = 0, sum0 = 0, sum1 = 0;
  REP(i, cnt) {
    sum0 = add(sum0, mul(pre0, c0[i]));
    pre1 = sum0;
    sum1 = add(sum1, mul(pre1, cn[i]));
    pre0 = sum1;
  }
  if (a[n]) return pre1;
  else return sum1;
}

int main() {
  scanf("%d", &n);
  G[0].eb(0);
  FOR(i, 1, n) {
    scanf("%d", a + i);
    a[i] ^= a[i - 1];
    G[a[i]].eb(i);
  }
  int ans = 0;
  if (a[n]) {
    ans = solve(a[n]);
  } else {
    ans = pow_mod(2, int(G[0].size()) - 2);
    FOR(mask, 1, (1 << 20) - 1) ans = add(ans, solve(mask));
  }
  printf("%d", ans);
}

