const ll MOD = 1000000007ll;

int n;
int a[525252];
int s[525252];
int c[525252];
vi xs[1<<20];

int main(){
    scanf("%d",&n);
    REP(i,n)scanf("%d",a+i);
    REP(i,n)s[i+1]=s[i]^a[i];
    REP(i,n+1)c[i+1]=c[i]+(s[i]==0);
    REP(i,n+1)xs[s[i]].push_back(i);
    ll ans = 0;
    // 0
    if(s[n]==0){
        int x = xs[0].size()-2;
        ll add = 1;
        while(x--)add=add*2%MOD;
        ans += add;
        ans %= MOD;
    }
    // >0
    FOR(v,1,1<<20)if(xs[v].size()){
        // dp
        int p = 0;
        ll dp0 = 1, dp1 = 0;
        for(int x : xs[v]){
            ll c0 = c[x] - c[p];
            ll ndp0 = (dp0 + dp1 * c0 % MOD) % MOD;
            ll ndp1 = dp1;
            dp0 = ndp0;
            dp1 = (ndp1 + ndp0) % MOD;
            p = x;
        }
        if(s[n]==0){
            ans += dp1;
        }else if(s[n]==v){
            ans += dp0;
        }
        // if(s[n]==0){
        //     ans += dp1;
        // }else if(s[n]==v){
        //     ans += dp0;
        // }
        ans %= MOD;
    }
    printf("%lld\n",ans);
    return 0;
}

