	vector<ll> nextZeroIndex(N+1, LLONG_MAX);
	vector<ll> nextSameIndex(N+1, LLONG_MAX);
	vector<ll> firstShown(1048576, -1);
	vector<ll> lastIndex(N+1, -1);

	lastIndex[0] = 0;
	for(int i=0;i<N;i++){
		sum[i+1] = (sum[i] ^ a[i]);
		if (firstShown[sum[i+1]] == -1) firstShown[sum[i+1]] = i+1;
		if (lastIndex[sum[i+1]] != -1){
			nextSameIndex[lastIndex[sum[i+1]]] = i+1;
			if (sum[i+1] == 0){
				for(int j=lastIndex[0];j<=i;j++) nextZeroIndex[j] = i+1;
			}
		}
		lastIndex[sum[i+1]] = i+1;
	}

	llm ans(0);

	// each XOR == i > 0 のケースを数える．
	for(int i=1;i<1048576;i++){
		if (firstShown[i] == -1) continue;
		if (sum[N] != 0 && i != sum[N]) continue;

		ll now = firstShown[i];
		llm cum0(1), cumi(1);
		while(1){
			if (now == LLONG_MAX) break;
			if (nextSameIndex[now]==LLONG_MAX && nextZeroIndex[now]==LLONG_MAX) break;
			if (nextSameIndex[now] > nextZeroIndex[now]){ // i よりも 0 が先に来る場合
				ll zeroCount = 0; // 次の i までに 0 が何個登場するか．
				ll pos = nextZeroIndex[now];
				while(nextSameIndex[now] > pos){
					zeroCount++;
					pos = nextZeroIndex[pos];				
				}
				cum0 += cumi * llm(zeroCount);
				if (nextSameIndex[now] < LLONG_MAX) cumi += cum0;
			}else{ // 0 よりも i が先に来る場合
				cumi += cum0;
			}
			now = nextSameIndex[now];
		}
		if (sum[N] == 0){
			// cerr << i << ":" << cumi << endl;
			ans += cumi;
		}else if (sum[N] == i){
			// cerr << i << ":" << cum0 << endl;
			ans += cum0;
		}
	}
	// each XOR == 0 のケースを数える．
	if (sum[N] == 0){
		llm p(1);
		for(int i=1;i<N;i++) if (sum[i]==0) p *= llm(2);
		ans += p;
	}


	cout << ans << endl;

    return 0;
}

