ll bin_power(ll x, ll y, ll mod) {
	if (y == 0)return 1;
	if (y == 1)return x % mod;
	if (y % 2 == 0)return POW(bin_power(x, y / 2, mod), 2LL) % mod;
	return ((POW(bin_power(x, y / 2, mod), 2LL) % mod)*(x%mod)) % mod;
}
ll div_ferm(ll a, ll  b, ll mod) {
	return (a* bin_power(b, mod - 2, mod)) % mod;
}


