    vector<ModInt<>> dp(n + 1, 1);
    {
      ModInt<> sum[2] = {1, 1};
      for (int i = 2; i <= n; ++i) {
        dp[i] = sum[i & 1 ^ 1];
        sum[i & 1] += dp[i];
      }
