    return dp[cnt];
  }
  ModInt<> res;
  // zero(zero)
  {
    int now = 0, zero = 0;
    for (int i = 0; i < n; ++i) {
      now ^= a[i];
      if (!now) ++zero;
    }
    res += ModInt<>(2).pow(zero - 1);
  }
  // zero(nonzero)
  {
    int now = 0, zero = 0;
    vector<int> cnt(1 << 20, 0);
    vector<vector<ModInt<>>> dp(2, vector<ModInt<>>(1 << 20, 1));
    dp[1].assign(1 << 20, 0);
    for (int i = 0; i < n; ++i) {
