      if (now) {
        dp[0][now] += dp[1][now] * (zero - cnt[now]);
        dp[1][now] += dp[0][now];
        cnt[now] = zero;
      } else
        ++zero;
    }
    for (auto p : dp[1]) res += p;
  }
  return res;
}

