typedef long long ll;
const int mod = 1e9 + 7;
const int maxn = 5e5 + 5;
int n;
int a[maxn], c[maxn];
ll ans;
vector <int> st[1048576 + 5];

void add(ll &a, ll b){ a = (a + b) % mod; }

ll qpow(ll x, ll n){ ll y = 1;
  for(; n; n >>= 1, x = x * x % mod)
	if(n & 1) y = y * x % mod;
  return y;
}

void work(int x, int op){
  if(!st[x].size()) return ;
  ll s0, s1;
  s0 = s1 = 0;
  for(int i = 0; i < st[x].size(); ++ i){
	int p = st[x][i];
	add(s1, s0 + 1);
	if(i < st[x].size() - 1){
	  add(s0, (c[st[x][i + 1]] - c[p]) * s1);
	}
  } 
  if(op) add(ans, s1);
  else add(ans, s0 + 1);
}

int main(){
