	c[i] += c[i - 1];
  }
  if(a[n]) work(a[n], 0);
  else{
	int all = (1 << 20) - 1;
	rep(i, 1, all) work(i, 1);
	ans = (ans + qpow(2, c[n] - 1)) % mod;
  }
  printf("%lld\n", ans);
  return 0;
}

