vector<vector<int>> make_vector(vector<int> C, vector<int> Z, int X) {
    int N = Z.size();
    vector<vector<int>> V;
    int zero;
    auto itrX = find(C.begin(), C.end(), X);
    auto itrXP = C.begin();
    do {
        zero = Z[itrX-C.begin()+1] - Z[itrXP-C.begin()];
        if (zero <= 0) (V.back())[1]++;
        else {
            V.push_back(std::vector<int>({0, zero}));
            V.push_back(std::vector<int>({X, 1}));
        }
        itrXP = itrX;
        itrX = find(itrX+1, C.end(), X);
    } while (itrX != C.end());
    zero = Z[N-1] - Z[itrXP-C.begin()];
    if (zero > 0) V.push_back(std::vector<int>({0, zero}));
    return V;
}

