void solve(long long N, std::vector<long long> A) {
  const int MAXM = (1 << 20);
  vector<mint<>> ans0(MAXM, mint<>(1));
  vector<mint<>> ansk(MAXM, mint<>(0));

  int sumx = 0;
  set<int> yobi;
  vector<int> time0(MAXM, 0);
  int time0all = 0;
  mint<> finalans = 0;
  for (int i = 0; i < A.size(); i++) {
    int a = A[i];
    sumx ^= a;
    if (sumx > 0) {
      mint<> adder = ans0[sumx];
      if (time0all != time0[sumx]) {
        adder += ansk[sumx] * (time0all - time0[sumx]);
        ans0[sumx] = adder;
        time0[sumx] = time0all;
      }
      ansk[sumx] += adder;
      yobi.insert(sumx);
      finalans = adder;
      // cout << sumx << endl;
    }
    if (sumx == 0) {
      if (i == A.size() - 1) {
        for (int j = 1; j < (MAXM); j++) yobi.insert(j);
      }
      time0all++;
      finalans = 0;
      for (auto b : yobi) {
        ans0[b] += ansk[b];
        finalans += ansk[b];
        time0[b] = time0all;
      }
      yobi.clear();
    }
    /*
    for (int j = 0; j < 15; j++) cout << ansk[j] << " ";
    cout << endl;
    for (int j = 0; j < 15; j++) cout << ans0[j] << " ";
    cout << endl << endl;
 */
  }
  if (sumx == 0) {
    mint<> ans = 1;
    for (int i = 0; i < time0all - 1; i++) ans *= 2;
    ans += finalans;
    // ans -= (MAXM)-1;
    cout << ans << endl;
    return;
  }
  cout << finalans << endl;
}

