    vector<vector<int>> G(1<<MAX_B);
    for (int i=0;i<N+1;++i) G[rui[i]].emplace_back(i);
    vector<vector<mint>> dp(N+1,vector<mint>(2,0));
    vector<vector<mint>> sum(N+1,vector<mint>(2,0));
    sum[0][0]=1;
    for (int i=1;i<=N;++i){
        auto itr=lower_bound(G[rui[i]].begin(),G[rui[i]].end(),i);
        if (itr==G[rui[i]].begin()){
            dp[i][1]+=1; sum[i][0]+=1;
        } else {
            int pre=*(--itr);
            int cnt=lower_bound(G[0].begin(),G[0].end(),i)
                    -upper_bound(G[0].begin(),G[0].end(),pre);
            if (!rui[i]) dp[i][0]+=sum[pre][1];
            else dp[i][1]+=sum[pre][1]*cnt;
            dp[i][1]+=sum[pre][0];
            sum[i][0]+=sum[pre][0];
            sum[i][1]+=sum[pre][1];
        }
        sum[i][0]+=dp[i][0];
        sum[i][1]+=dp[i][1];
    }
    mint ans=dp[N][0]+dp[N][1];
    if (rui[N]==0){
        for (int bit=1;bit<(1<<MAX_B);++bit){
            int s=G[bit].size();
            if (s) ans+=sum[G[bit][s-1]][1];
        }
    }
