LL dp1[500000][2];
LL solve1(int now, int z){
	if(now == N-1 && z == 1) return 1;
	if(now == N-1) return 0;
	if(dp1[now][z] != -1) return dp1[now][z];
	dp1[now][z] = solve1(now+1, z);
	if(z == 0 && wa[now] == 0){
		//cout << "y" << endl;
		dp1[now][z] += solve1(now+1, 1);
	}
	if(z == 1 && wa[now] == wa[N-1]){
		//cout << now << " y1" << endl;
		dp1[now][z] += solve1(now+1, 0);
	}
	return dp1[now][z] = dp1[now][z] % MOD;
}

vector<int> all[1<<20];
int dp2[500000];
LL solve2(int now){
	if(dp2[now] != -1) return dp2[now];
	dp2[now] = 1;
	int tmp = wa[now];
	int idx = lower_bound(all[tmp].begin(), all[tmp].end(), now) - all[tmp].begin();
	if(tmp == 0){
		for(int i=idx+1; i<all[tmp].size(); i++){
			int nx = all[tmp][i];
			dp2[now] += solve2(nx);
		}
		return dp2[now] = dp2[now] % MOD;
	}
	for(int i=idx+1; i<all[tmp].size(); i++){
		int nx = all[tmp][i];
		LL s = upper_bound(all[0].begin(), all[0].end(), nx)-lower_bound(all[0].begin(), all[0].end(), now);
		dp2[now] += s*solve2(nx);
		dp2[now] %= MOD;
	}
	return dp2[now] = dp2[now] % MOD;
}

