template<typename T>
T mypow(T x, T n, const T &p) {
  T ret = 1;
  while(n) {
    if(n&1) {
      ret *= x;
      ret %= p;
    }
    x *= x;
    x %= p;
    n>>=1;
  }
  return ret;
}

