		// debug(G[i]);
		rep(j, 0, sz(G[i])) {
			// debug(i, j, suma, sumz);
			ll v = sumz;
			ADD(suma, v);
			if(j != sz(G[i]) - 1) {
				ll c = rui.get(G[i][j], G[i][j + 1]);
				ADD(sumz, suma * c % mod);
				// debug(G[i][j], G[i][j + 1], c);
			}
		}
		if(sum == 0) {
			ADD(ans, suma);
		}
		else if(sum == i) {
			ADD(ans, sumz);
		}
	}
	cout << ans << "\n";
}

