typedef vector<mint> vec;
typedef vector<vector<mint>> mat;

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;

  vector<int> a(n);
  REP(i,n) cin >> a[i];

  REP(i,n-1) a[i+1] ^= a[i];

  assert(a[n-1]);

  mat dp(2,vec(n+1,0));
  dp[0][1] = 1;
  REP(i,n){
    dp[0][i+1] += dp[0][i];
    dp[1][i+1] += dp[1][i];
    if(a[i] == a[n-1]) dp[0][i+1] += dp[1][i];
    if(a[i] == 0) dp[1][i+1] += dp[0][i];
  }

  cout << dp[n][0].value() << endl;

  return 0;
}

