ll qry0(int l, int r) {
    if (l>r) return 0;
    return zero[r] - (l>0 ? zero[l-1] : 0);
}


ll solve(vector<int> a) {
    // count odd length subsequences that alternate: 101..0101, must start and end with 1
    vector<ll> dp(2, 0);
    dp[0] = 1;
    //101010...01

    int len = a.size();
    for (int i=0; i<len; i++) {
	dp[1]=(dp[1]+dp[0])%mod;
	if (i+1<len) {
	    ll zcnt = qry0(a[i], a[i+1]);
	    dp[0]=(dp[1]*zcnt%mod + dp[0])%mod;
	}
    }

    return dp[1];
}

