	zero = vector<int>(N + 2, 0);
	for (uint i = 0; i <= N; i++) zero[i + 1] = zero[i] + (sum[i] == 0 ? 1 : 0);
	auto dic = indexes(sum);
	if (sum[N]) cout << calc(get_zero(dic[sum[N]])).back() << endl;
	else
	{
		ll ans = pow(2, zero[N + 1] - 2, MOD);
		for (auto&& x: dic) if (x.first) for (auto v : calc(get_zero(x.second))) ans += v;
		cout << ans % MOD << endl;
	}
	cout << flush;
	return 0;
}

