uint64_t f(uint64_t index,uint64_t target) {
    if (index == n){
        return 1;
    }
    uint64_t sum = 0;
    for (uint64_t i=index;i<n;i++){
        if ((memo[index-1] ^ memo[i]) == target){
            sum += f(i+1,target) % 1000000007;
        }
    }
    return sum;
}

