lolo myPow(lolo x, lolo n, lolo m) {
	if (n == 0)
		return 1;
	if (n % 2 == 0)
		return myPow(x * x % m, n / 2, m);
	else
		return x * myPow(x, n - 1, m) % m;
}

int main()
{
	lolo N;
	cin >> N;
	vec A(N);
	vec s(N+1,0);
	FOR(i, N) cin >> A[i];
	FOR(i, N) s[i + 1] = A[i] ^ s[i];

	vvec DP1(N + 1, vec(2, 0));
	vvec DP2(N + 1, vec(2, 0));
	// DP1が有効、DP2 は無効( スキップ )

	DP1[0][0] = 1;

	FOR(i, N+1)
		cerr << s[i] << " ";
	cerr << endl;

	if (s.back() != 0) {
		lolo X = s.back();
		FOR(i, N) {
			(DP2[i + 1][0] += DP2[i][0]) %= MOD;
			(DP2[i + 1][1] += DP2[i][1]) %= MOD;
			(DP2[i + 1][0] += DP1[i][0]) %= MOD;
			(DP2[i + 1][1] += DP1[i][1]) %= MOD;

			if (s[i+1 ] == 0) {	
				(DP1[i + 1][0] += DP1[i][1]) %= MOD;
				(DP1[i + 1][0] += DP2[i][1]) %= MOD;	
			}
			else if (s[i+1] == X) {
				(DP1[i + 1][1] += DP1[i][0]) %= MOD;
				(DP1[i + 1][1] += DP2[i][0]) %= MOD;
			}
		}
		cout << DP1[N][1] << endl;			
	}
	else {
		vec X(1 << 20, 0);
		vec Y(1 << 20, 1);
		vec Z(1 << 20, 0); 

		lolo z = 0;

		FOR(i, N) {
			lolo n = s[i+1];

			if (n == 0) {
				z += 1;
				continue;
			}
			else {
				// Xはその数字を踏んだ場合の数
				// Yはすでにゼロを踏んだ(しかしそのマスは踏まない)場合の数

				lolo nz = z - Z[n];
				lolo newX;
				lolo newY; 

				//newY = (nz * X[n] + Y[n]) % MOD;
				//newX = (X[n] + newY) % MOD;


				newX = (nz + 1) * X[n] + Y[n];
				newY = nz * X[n] + Y[n];


				X[n] = newX % MOD;
				Y[n] = newY % MOD;
				Z[n] = z % MOD;
			}
		}

		lolo ans = 0;
		lolo zero_cnt = 0;
		FOR(i, N) {
			if (s[i + 1] == 0) zero_cnt += 1;
		}
		ans += myPow(2, zero_cnt - 1, MOD);

		FOR(i, 1 << 20) {
			(ans += X[i]) %= MOD;
		}

		cout << ans % MOD << endl;
	}

}

