    map < ll,ll > cnt;
    REP(i,N) {
        txor ^= a[i];
        if (txor == 0) {
            used.clear();
            cnt[0]++;
        } else {
            if (used.find(txor) != used.end()) continue;
            used.insert(txor);
            cnt[txor]++;
        }
    }

    ll ans = 0;
    if (txor != 0) {
        ll p = cnt[txor] - 1;
        ans = pow_mod(2LL, p, MOD);
    } else {
        ans += pow_mod(2LL, cnt[0] - 1, MOD);
        ans %= MOD;
        for (ll i = 1LL; i <= (1LL << 21LL); i++) {
            ll p = cnt[i];
            if (p <= 0) continue;
            ans += pow_mod(2LL, p, MOD);
            ans %= MOD;
            ans -= 1;
            ans += MOD;
            ans %= MOD;
        }   
    }

