            continue;

        V p;

        p.push_back(1);

        int j = 0;
        while (j < w[i].size())
        {
            int cnt = 1;
            while (j < w[i].size() && reiwa[w[i][j + 1]] - reiwa[w[i][j]] == 0)
            {
                cnt++;
                j++;
            }
            if (j == w[i].size())
                j--;
            p.push_back(cnt);

            if (j == w[i].size() - 1)
                p.push_back(1);
            else
                p.push_back(reiwa[w[i][j + 1]] - reiwa[w[i][j]]);

            j++;
        }

