                (nex[0] += cur[1] * p[j]) %= MOD;

            swap(cur, nex);
        }

        (res += cur[0]) %= MOD;
    }

    (res += fastPow(2, reiwa[v.size()] - 2)) %= MOD;

    cout << res << endl;

    return 0;
}

