            if (a[i] == 0) {
                for (auto &p : cnt) {
                    zeros[p.first] += p.second;
                }
            } else {
                if (cnt.count(a[i]) == 0) {
                    cnt[a[i]]   = 1;
                    zeros[a[i]] = 1;
                } else
                    cnt[a[i]] += zeros[a[i]];
            }
        }
