    for (int i = 0; i < N; ++i) {
      cin >> a[i];
    }

    // 累積XORと累積0の個数
    vector<int>cuXOR(N);
    vector<int>zero(N, 0);
    cuXOR[0] = a[0];
    for (int i = 1; i < N; ++i) {
        cuXOR[i] = cuXOR[i-1] ^ a[i];
        if(cuXOR[i] == 0) zero[i]++;
        if(i != N-1) zero[i+1] = zero[i];
    }

    // 美しさbで現在の区間より前のxorが0ならdp[b][0], bならdp[b][1]が場合の数
    ll dp[MAX_a][2] = {};
    for (int i = 0; i < MAX_a; ++i) {
        dp[i][0] = 1;
    }
    ll prev[MAX_a] = {};
    for (int i = 0; i < N; ++i) {
        int cur = cuXOR[i];
        if(cur != 0){
            dp[cur][0] += dp[cur][1] * (zero[i] - zero[prev[cur]]);
            dp[cur][0] %= mod;
            dp[cur][1] += dp[cur][0];
            dp[cur][1] %= mod;
            prev[cur] = i;
        }
    }

    ll ans = 0;
    if(cuXOR[N-1] == 0){
        ans += modPow(2, zero[N-1]);
        for (int i = 1; i < MAX_a; ++i) {
            ans += dp[i][1];
            ans %= mod;
        }
    } else{
        ans += dp[cuXOR[N-1]][0];
        ans %= mod;
    }
    cout << ans;
    return 0;
}

