	for(int i=0; i<N; i++){
		all[wa[i]].PB(i);
		//cout << wa[i] << endl;
	}
	if(wa[N-1] != 0){
		for(int i=0; i<N; i++){
			dp1[i][0] = -1;
			dp1[i][1] = -1;
		}
		printf("%lld\n", solve1(0, 1));
	}
	else{
		for(int i=0; i<N; i++){
			dp2[i] = -1;
		}
		LL ans = 0;
		int z = 0;
		for(int i=0; i<N; i++){ //最初の区切り
			if(wa[i] == 0){
				z++;
				continue;
			}
			ans += solve2(i);
		}
		LL tmp = 1;
		for(int i=0; i<z-1; i++){
			tmp *= 2;
			tmp %= MOD;
		}
		printf("%lld\n", (ans+tmp)%MOD);
	}
}

