int go(vector<int> & v)
{
    if (v.empty())
        return 0;
    ll dp[2] = {1,1};
    for (int i = 1; i < v.size(); ++i) {
        int j = v[i], k = v[i-1];
        int o = s0[j] - s0[k];
        dp[0] = (dp[0] + dp[1] * o) % M;
        dp[1] = (dp[1] + dp[0]) % M;
    }
    if (v.back() == n)
        return dp[0];
    return dp[1];
}
ll solve2()
{
    for (int i = 1; i <= n; ++i) {
        p[a[i]].push_back(i);
        s0[i] = s0[i-1] + (a[i] == 0);
    }
    ll ans=0;
    if (a[n] == 0) {
        ans = 1;
        for (int i = 0; i < p[0].size()-1; ++i)
            ans = 2*ans%M;
        for (int i = 1; i < C; ++i) {
            int w = go(p[i]);
            ans += w;
        }
    } else {
        ans = go(p[a[n]]);
    }
    return ans;
}
