int pref[N];
int cache[N][2];
set<int> pos[M];

int dp(int idx, int cur)
{
	if(idx == n + 1)
		return (cur == 1);
	int &ans = cache[idx][cur];
	if(ans != -1)
		return ans;
	ans = dp(idx + 1, cur);
	if(cur == 0 && pref[idx] == 0)
		ans += dp(idx + 1, cur ^ 1);
	if(cur == 1 && pref[idx] == x)
		ans += dp(idx + 1, cur ^ 1);
	ans %= MOD;
	return ans;
}	

map<int, int> vis[2];

int dp2(int idx, int cur)
{
	if(idx == n + 1)
		return (cur == 0);
	if(vis[cur].find(idx) != vis[cur].end())
		return vis[cur][idx];
	int &ans = vis[cur][idx];
	if(cur == 1) //Searching for x
	{
		auto next0 = pos[0].upper_bound(idx);
		if(next0 != pos[0].end())
			ans += dp2(*next0, 0);
		auto nextX = pos[x].upper_bound(idx);
		if(nextX != pos[x].end())
			ans += dp2(*nextX, 1);
	}	
	else //Searching for 0
	{
		auto next0 = pos[0].upper_bound(idx);
		if(next0 != pos[0].end())
			ans += dp2(*next0, 0);
		auto nextX = pos[x].upper_bound(idx);
		if(nextX != pos[x].end())
			ans += dp2(*nextX, 1);
	}
	ans %= MOD;
	return ans;
}

