using namespace std;
long long solve(int first, int N, vector<int>& A, vector<int>& agg){
  if(first==N)
    return 1;
  int unit=agg[first];
  if(unit!=0){
    long long zero = 0;
    long long other = 1;
    for (int i = first+1; i < N; i++)
    {
      if(agg[i]==0){
        zero += other;
        zero %= 1000000007;
      }
      if(agg[i]==unit){
        other += zero;
        other %= 1000000007;
      }
    }
    if(agg[N]==0)
      return other;
    if(agg[N]==unit)
      return zero;
    return 0;
  }else{
    long long zero = 1;
    for (int i = first+1; i < N; i++)
    {
      if(agg[i]==0){
        zero += zero;
        zero %= 1000000007;
      }
    }
    if(agg[N]==0)
      return zero;
    return 0;
  }
}
