  agg[0] = 0;
  for (int i = 0; i < N; i++)
  {
    agg[i+1] = agg[i] ^ A[i];
  }
  long long sum = 0;
  for (int i = 1;i<=N;i++){
    auto ret=solve(i, N, A, agg);
    // cout<<i<<" "<<agg[i]<<" "<<ret<<endl;
    sum += ret;
    sum %= 1000000007;
  }
