ll modpow(ll a, ll t) {
    if(t < 0) return 0LL;
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

template<typename T>class BIT {
    public:
    int n;
    vector<T> bit;

    BIT(int n): n(n){
        bit.resize(n);
        fill(bit.begin(), bit.end(), (T)0);
    }

    void add(int idx, T x){
        for(int i=idx;i<=this->n;i+=i&-i) {
            bit[i] += x;
            bit[i] %= MOD;
        }
    }

    //bit[1]からbit[end]までの和 (閉区間)
    T sum(int end){
        T ret = (T)0;
        for(int i=end;i>=1;i-=i&-i) {
            ret += bit[i];
            ret %= MOD;
        }
        return ret;
    }
};

