int MOD(int v, int M)
{
    v %= M;
    if (v < 0)
        v += M;

    return v;
}


int stupid(vi kek)
{
    int n = SZ(kek);
    int ans = 0;

    for (int x = 0; x < B; ++x) {
        int cur = 0;
        map<int, int> flex;
        flex[cur] = 1;

        for (int i = 0; i < n; ++i) {
            int v = kek[i];

            cur ^= v;
            int cnt = flex[cur ^ x];
            flex[cur] = MOD(flex[cur] + cnt, M);

            if (i + 1 == n)
                ans += cnt;
        }
    }

    return ans;
}


