    for (int i = 1; i < n; ++i)
        lel[i] ^= lel[i - 1];

    int ans = 0;

    if (x != 0)
    {
        int cur = 0;
        map<int, int> flex;
        flex[cur] = 1;

        for (int i = 0; i < n; ++i)
        {
            int v = kek[i];

            cur ^= v;
            int cnt = flex[cur ^ x];
            flex[cur] = MOD(flex[cur] + cnt, M);

            if (i + 1 == n)
                ans = cnt;
        }
    }
    else
    {
        int cur = 0;
        map<int, int> flex;
        flex[cur] = 1;

        for (int i = 0; i < n; ++i)
        {
            int v = kek[i];

            cur ^= v;
            int cnt = flex[cur ^ x];
            flex[cur] = MOD(flex[cur] + cnt, M);

            if (i + 1 == n)
                ans = cnt;
        }

        vpi segs;
        int prev = 0;
        cur = 0;

        for (int i = 0; i < n; ++i)
        {
            cur ^= kek[i];
            if (!cur)
            {
                segs.push_back(mp(prev, i));
                prev = i + 1;
            }
        }

        map<int, vi> vseg;
        map<int, map<int, int>> hui;

        for (int i = 0; i < SZ(segs); ++i)
        {
            auto p = segs[i];

            int l = p.first, r = p.second;
            for (int j = l; j < r; ++j)
                vseg[lel[r] ^ lel[j]].push_back(i),
                hui[lel[r] ^ lel[j]][i]++;
        }

        for (auto p : vseg)
        {
            vi cur = p.second;
            stable_sort(ALL(cur));
            cur.erase(unique(ALL(cur)), cur.end());

            vpi dp(SZ(cur));

            for (int i = 0; i < SZ(dp); ++i)
                dp[i].first = hui[p.first][cur[i]],
                dp[i].second = hui[p.first][cur[i]];

            for (int i = 0; i + 1 < SZ(dp); ++i)
            {
                int d = cur[i + 1] - cur[i];

                {//open - yes

                    {//will close - yes

                        {//next person - block - Yes
                            dp[i + 1].second = MOD(dp[i + 1].second + dp[i].first * d, M);
                        }

                        {//next person - block - No
                            dp[i + 1].first = MOD(dp[i + 1].first + dp[i].first * MOD((d - 1) * hui[p.first][cur[i + 1]], M), M);
                            dp[i + 1].second = MOD(dp[i + 1].first + dp[i].first * MOD((d - 1) * hui[p.first][cur[i + 1]], M), M);
                        }
                    }

                    {//will close - no
                        dp[i + 1].first = MOD(dp[i + 1].first + dp[i].first, M);
                    }

                }



                {//open - no

                    {//next person - block - Yes
                        dp[i + 1].second = MOD(dp[i + 1].second + dp[i].second, M);
                    }

                    {//next person - block - No
                        dp[i + 1].first = MOD(dp[i + 1].first + dp[i].second * hui[p.first][cur[i + 1]], M);
                        dp[i + 1].second = MOD(dp[i + 1].second + dp[i].second * hui[p.first][cur[i + 1]], M);
                    }
                }
            }

            ans = MOD(ans + dp.back().first, M);
        }
    }

    cout << ans;
}

