struct st_t {
  int sz = 1;
  VV<map<int,int>> CNT;
  VV<int>SUM;
  VV<int>MARK;
  int gen = 1;
  explicit st_t(int N){
    while(sz<=N)sz*=2;
    CNT.resize(2*sz);
    SUM.resize(2*sz);
    MARK.resize(2*sz);
  }
  void add(int a, int val) {
    for(int p=sz+a;p>=1;p/=2){
      SUM[p] += val;
    }
  }
  LL do_add(int p, int x) {
    if (p < 1) return 0;
    if (MARK[p] == gen) return 0;
    MARK[p] = gen;
    LL res = 0;
    res = (res + CNT[p][x] * 1LL * SUM[p]) % MOD;
    res = (res + do_add(p/2, x)) % MOD;

    return res;
  }

  LL get(int a, int b, int x) {
    gen++;
    LL res = 0;
    for(int p1=sz+a,p2=sz+b+1;p1<p2;p1/=2,p2/=2){
      if (p1&1){
        res = (res + do_add(p1, x)) % MOD;
        p1++;
      }
      if (p2&1){
        p2--;
        res = (res + do_add(p2, x)) % MOD;
      }
    }

    return res;
  }

  void add_range(int a, int b, int x, LL ways) {
    for(int p1=sz+a,p2=sz+b+1;p1<p2;p1/=2,p2/=2){
      if (p1&1){
        CNT[p1][x] = (CNT[p1][x] + ways) % MOD;
        p1++;
      }
      if (p2&1){
        p2--;
        CNT[p2][x] = (CNT[p2][x] + ways) % MOD;
      }
    }
  }

  LL get_all(int a) {
    LL res = 0;
    for(int p=sz+a;p>=1;p/=2){
      for(auto el:CNT[p]) res=(res+el.second)%MOD;
    }
    return res;
  }
};

struct Solver {
  void solve() {
    int N;
    cin>>N;
    VV<int>A(N);
    REP(n,N)cin>>A[n];
    st_t st(N);

    for(int XOR=0,n=0;n<N;n++) {
      XOR ^= A[n];
      if (XOR == 0) {
        st.add(n, 1);
      }

    }
    LL x0 = 1;
    LL XOR = 0;
    LL ways = 0;
    REP(n,N) {
      XOR ^= A[n];
      if (XOR == 0) {
        ways = x0;
        x0 = (x0 + ways) % MOD;
      }
      else {
        ways = 1;
        ways += st.get(0,n-1, XOR);
        st.add_range(n+1,N-1, XOR, ways);
      }
    }
    DB(XOR);

    LL res = 0;
    if (XOR == 0) {
      res += ways;
      res += st.get_all(N-1);
    }
    else {
      res += ways;
    }
    cout<<(res%MOD+MOD)%MOD<<"\n";
  }
};


