      V<> b{1};
      for (int i = 0; i < m; ++i) {
        b.push_back(-1);
        if (i == m - 1) break;
        b.push_back(z[p[x][i + 1]] - z[p[x][i]]);
      }
      b.push_back(1);
      m = b.size();
