		bt.add(0,0,1);
		for(i=1;i<1<<20;i++) if(id[i].size()) {
			FORR(j,id[i]) {
				x=lower_bound(ALL(id[0]),j)-id[0].begin();
				V[j]=bt.total(x-1);
				bt.add(x,1<<20,V[j]);
			}
			ret+=bt.total(1<<20)-bt.total((1<<20)-1);
			FORR(j,id[i]) {
				x=lower_bound(ALL(id[0]),j)-id[0].begin();
				bt.add(x,1<<20,mo-V[j]);
			}
		}
		cout<<(ret%mo+mo)%mo<<endl;
	}
	else {
		dp[0]=1;
		x=0;
		FOR(i,N) {
			x^=A[i];
			if(x==tot) (dp[1]+=dp[0])%=mo;
			if(x==0) (dp[0]+=dp[1])%=mo;
		}
		cout<<dp[0]<<endl;
	}


}


