#define MOD 1000000007
using namespace std;

long mod_pow(long x, int k) {
    long ret = 1;
    while (k > 0) {
        if (k & 1) {
            ret *= x;
            ret %= MOD;
        }
        k >>= 1;
        x *= x;
        x %= MOD;
    }
    return ret;
}

int main() {
    int n;
    cin >> n;
    int b[n];
    cin >> b[0];
    for (int i = 1; i < n; i++) {
        int a;
        cin >> a;
        b[i] = a ^ b[i - 1];
    }
    long ans = 0;
    if (b[n - 1] > 0) {
        int x = b[n - 1];
        long dp[n][2];
        dp[0][0] = 1;
        dp[0][1] = 0;
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + ((b[i] == 0) ? dp[i - 1][1] : 0);
            dp[i][1] = ((b[i] == x) ? dp[i - 1][0] : 0) + dp[i - 1][1];
            dp[i][0] %= MOD;
            dp[i][1] %= MOD;
        }
        ans = dp[n - 1][1];
    } else {
        int count_zero = 0;
        for (int i = 0; i < n; i++) {
            if (b[i] == 0)
                count_zero++;
        }
        ans = mod_pow(2, count_zero - 1);
        ans %= MOD;

        unordered_map<int, long> dp, dp0, counter_zero;
        long count = 0;
        for (int i = 0; i < n; i++) {
            if (b[i] == 0) {
                count++;
            } else {
                int top = b[i];
                if (dp.find(top) == dp.end()) {
                    dp[top] = 0;
                    dp0[top] = 1;
                }
                dp0[top] = ((count - counter_zero[top]) * dp[top]) % MOD + dp0[top];
                dp[top] += dp0[top];
                dp0[top] %= MOD;
                dp[top] %= MOD;
                counter_zero[top] = count;
            }
        }
        for (auto p: dp) {
            long x = p.second;
            ans += x;
            ans %= MOD;
        } 
    }
    cout << ans << endl;
    return 0;
}

