        ans += dp[1].sum(indexes[v].size()-1) - dp[1].sum(indexes[v].size()-2);
    } else {
        assert(false);
        ans += modpow(2, count_zero.back()-1);
        for(int v=1;v<=vs.size();++v) {
            vector<BIT<ll>> dp(2, BIT<ll>(n+1)); // BIT のサイズ， indexes[v].size() でよくないか？
            for(int i=1;i<indexes[v].size();++i) {
                zero = count_zero[indexes[v][i]] - count_zero[indexes[v][i-1]];
                dp[0].add(indexes[v][i], dp[1].sum(indexes[v][i]-1) % MOD);
                dp[1].add(indexes[v][i], (zero*dp[0].sum(indexes[v][i]-1) + 1) % MOD);
            }
            zero = count_zero[n] - count_zero[indexes[v].back()];

            ans += (zero*dp[0].sum(n-1) + 1) % MOD;
            ans %= MOD;
        }
    }

    cout << ans << endl;

}

