    int zero = 0;
    for (int i=0;i<C.size();i++) {
        if (C[i] == 0) zero++;
        else {
            int K = C[i];
            int t = zero - cnt[K];
            if (t>0) {
                V[K].push_back(make_pair(0,t));
            }
            V[K].push_back(make_pair(K,1));
            cnt[K] = zero;
        }
    }
    for (int K=1;K<(1<<20);K++) {
        int t = zero - cnt[K];
        if (t>0) V[K].push_back(make_pair(0,t));
    }
    V[0].push_back(make_pair(0,zero));
    return V;
}

pair<int,int> dp(vector<pair<int,int>> V) {
    vector<pair<int,int>> D(V.size()+1, make_pair(0,0));
    D[0].first = 1; D[0].second = 0;
    for (int i=1;i<=V.size();i++) {
        D[i].first = D[i-1].first;
        D[i].second = D[i-1].second;
        if (V[i-1].first == 0) {
            D[i].first += (D[i-1].second)*(V[i-1].second) % MOD;
        } else {
            D[i].second += D[i-1].first;
        }
        D[i].first %= MOD;
        D[i].second %= MOD;
    }
    return D[V.size()];
}

