vector<int> v[(1<<20)];
int a[500005],tree[2000005],lazy[2000005];
void push(int node,int st,int en)
{
	tree[node]=(tree[node]+1LL*lazy[node]*(en-st+1))%mod;
	if (st!=en)
	{
		lazy[2*node]=(lazy[2*node]+lazy[node])%mod;
		lazy[2*node+1]=(lazy[2*node+1]+lazy[node])%mod;
	}
	lazy[node]=0;
}
void update(int node,int st,int en,int l,int r,int val)
{
	if (l<=st && en<=r)
	lazy[node]=(lazy[node]+val)%mod;
	push(node,st,en);
	if (en<l || st>r || r<l || (l<=st && en<=r))
	return;
	int mid=(st+en)/2;
	update(2*node,st,mid,l,r,val);
	update(2*node+1,mid+1,en,l,r,val);
	tree[node]=(tree[2*node]+tree[2*node+1])%mod;
}
int query(int node,int st,int en,int l,int r)
{
	push(node,st,en);
	if (en<l || st>r || r<l)
	return 0;
	if (l<=st && en<=r)
	return tree[node];
	int mid=(st+en)/2;
	return (query(2*node,st,mid,l,r)+query(2*node+1,mid+1,en,l,r))%mod;
}
