int mod = 1'000'000'007;

//最後のすべて0のときのためにmodpowを作っておく
long long modpow(int x, int y){
    if (y==0) return 1;
    if (y%2 == 0) return modpow(x, y/2) * modpow(x, y/2) % mod;
    else return x * modpow(x, y-1) % mod;
}

int main(){
    //ansは非常に大きくなることがある
    long long ans;
    //nは10**5ぐらい
    int n;
    cin >> n;
    //累積XOR
    vector<long long> acc(n);
    for (int i = 0; i<n; i++){
        cin >> acc[i];
        if (i) acc[i] ^= acc[i-1];
    }
    //最後が0ではないとき
    if (acc.back()){
        //0 X 0 X...0 Xとなるのでdpで簡単に行ける
        vector<long long> dp(2, 0);
        dp[0] = 1;
        for (int i = 0; i<n-1; i++){
            if (acc[i] == 0) dp[0] += dp[1];
            else if (acc[i] == acc.back()) dp[1] += dp[0];
            dp[0] %= mod;
            dp[1] %= mod;
        }
        ans = dp[0];
    }
    //最後が0ならば 0 X 0 X ... 0 もしくは 0 0 0 0 ... 0
    else{
        //ある数が存在するか
        vector<vector<int>> num(1<<20);
        //0番目は0なので
        num[0].push_back(0);
        //それぞれ対応するとこに突っ込む　こうすると、結局dpを回す部分がn個になるのでO(N)で求まる
        for (int i = 0; i<n; i++) num[acc[i]].push_back(i+1);
        //ある区間の0の数をO(1)で求めるために累積和を求める 0番目からn番目まで
        vector<int> zero(n+1, 0);
        zero[0] = 1;
        for (int i = 0; i<n; i++){
            if (acc[i]==0) zero[i+1]++;
        }
        for (int i = 1; i<n+1; i++){
            zero[i] += zero[i-1];
        }
        ans = 0;
        //X=0のとき以外についてdpをする
        for (int i = 1; i<(1<<20); i++){
            if (num[i].size() > 0){
                int left = 0;
                int right = num[i][0];
                vector<long long> dp(2, 0);
                dp[0] = 1;
                for (int k = 0; k<(int)num[i].size(); k++){
                    //modをとりつつdpする
                    dp[0] += (dp[1] * (zero[right] - zero[left]) % mod);
                    dp[0] %= mod;
                    dp[1] += dp[0];
                    dp[1] %= mod;
                    left = num[i][k];
                    right = num[i][k+1];
                }
                //のこりは全部0なので、もう選べない
                ans += dp[1];
                ans %= mod;
            }
        }
        //最後に全て0のときを求める　単純にその0を使うか使わないかなので2**(0の個数)となる
        ans += modpow(2, zero.back() - 2);
        ans %= mod;
    }
    cout << ans << endl;
}

