ll p[MN][2];
ll solve(int pos, int empt) {
    if(pos > n) return !empt;

    ll &x = p[pos][empt];
    if(x != -1) return x;
    x = 0;

    ll xo = a[pos], j = pos;
    while(xo != 0) {
        xo ^= a[++j];
    }

    x = (solve(j + 1, 0) + solve(j + 1, 1)) % MOD;
    return x;
}

