    occ[txor].push_back(0);
    for(int i = 1; i <= n; i++) {
        txor ^= a[i];
        ac[i] = txor;
        occ[txor].push_back(i);
    }
    txor = ac[0];

    dp[n+1] = 0;
    for(int i = n; i > 0; i--) {
        int ai = ac[i-1];
        int l = lower_bound(occ[ai].begin(), occ[ai].end(), i-1) - occ[ai].begin();
        int r = l + 1;

        assert(l < occ[ai].size() && occ[ai][l] == i - 1);

        if(r == occ[ai].size()) dp[i] = 1, adp[i] = 1;
        else {
            ll z = zs(i, occ[ai][r]);
            dp[i] = (dp[occ[ai][r]+1] + z * adp[occ[ai][r]+1]) % MOD;
            adp[i] = (adp[occ[ai][r]+1] + dp[i]) % MOD;
        }
    }

    if(txor == 0) {
        for(int i = 1; i + 1 <= n; i++) {
            if(ac[i]) ans += dp[i+1];
            if(ans >= MOD) ans -= MOD;
        }
        ans += solve(1, 0);
        if(ans >= MOD) ans -= MOD;
    }
    else ans = dp[1];

    printf("%lld\n", ans);
    return 0;
}

