struct LazySegmentTree{
    public:
    ll size;
    vector<pair<Modint,Modint>>data;
    vector<ll>lazy;
    LazySegmentTree(ll n){
        size=1;
        while(size<n)size*=2;
        data.assign(size*2,{1,0});
        lazy.resize(size*2);
    }
    void update(ll at){
        ll i=0;
        while(at>>i)i++;
        rrep(j,1,i){
            ll a=at>>j;
            if(lazy[a]){
                lazy[a*2]+=lazy[a];
                lazy[a*2+1]+=lazy[a];
                lazy[a]=0;
            }
        }
    }
    void add(ll val){
        if(!val){
            lazy[1]++;
            return;
        }
        val+=size;
        update(val);
        if(lazy[val]){
            data[val].first+=data[val].second*lazy[val];
            lazy[val]=0;
        }
        data[val].second+=data[val].first;
    }
    Modint get(){
        Modint ans=0;
        rep(i,size,size*2)ans+=data[i].second;
        return ans;
    }
};
