void solve() {
	ll N;
	cin>>N;
	vector<ll> a(N);
	rep(i,N)cin>>a[i];

	Modint ans=0;
	vector<ll> rui(N+1, 0);
	rep(i, N) { rui[i+1] = rui[i] ^ a[i]; }
	if(rui.back()){
		exit(1);
		//vector<Modint> dp(N,1);
		BinaryIndexedTree<Modint> bitx(N+1),bit0(N+1);
		bit0.add(0,1,1);
		ll x=rui.back();
		rep(i,N+1){
			if(rui[i]==0){
				Modint t=bitx.sum(0,i);
				bit0.add(i,i+1,t);
			}else if(rui[i]==x){
				Modint t=bit0.sum(0,i);
				bitx.add(i,i+1,t);
			}
		}
		ans=bitx.sum(N,N+1);
		debug(rui);
		debug(bitx);
		debug(bit0);
	}else{
		vector<ll> rui0(N+1, 0);
		rep(i, N) { rui0[i+1] = rui0[i] + (rui[i]==0 ? 1 : 0); }
		map<ll,vector<ll>> m;
		rep(i,N+1){
			m[rui[i]].push_back(i);
		}
		ans+=Modint(2).pow(m[0].size()-2);
		for(pair<ll,vector<ll>> pr:m){
			if(pr.first==0)continue;
			vector<Modint> dp(pr.second.size(),0);
			rep(i,pr.second.size()){
				Modint t=1;
				rep(j,i){
					t+=dp[j]*(rui0[pr.second[i]]-rui0[pr.second[j]]);
				}
				dp[i]=t;
			}
			rep(i,pr.second.size()){
				ans+=dp[i];
			}
		}
	}
	p(ans);
}

