ll solve() {
    ll N;
    cin >> N;
    V<ll> A(N);
    for(auto &&ele : A) cin >> ele;

    ll xor_sum = 0;
    V<ll> cnt_zero(cnt_size), cnt_pos(cnt_size), zero_sum(cnt_size);
    ll idx_a = 0, back_a = N, prefix_zero = 0, suffix_zero = 0;

    while(idx_a < N && A[idx_a] == 0) idx_a++;
    prefix_zero = idx_a;

    if(idx_a == N) {
        ll ret = 1;
        for(ll i = 1; i < N; i++) (ret *= 2) %= mod;
        return ret;
    }

    while(A[back_a - 1] == 0) back_a--;
    suffix_zero = N - back_a;

    DEBUG(make_tuple(prefix_zero, suffix_zero, idx_a, back_a));
    ll zero = 0;

    for(; idx_a < back_a; idx_a++) {
        ll num = A[idx_a];
        xor_sum ^= num;

        if(xor_sum == 0) {
            zero++;
            continue;
        }

        DEBUG(xor_sum);

        ll diff_zero = zero - zero_sum[xor_sum];
        zero_sum[xor_sum] = zero;
        (cnt_zero[xor_sum] += cnt_pos[xor_sum] * diff_zero % mod) %= mod;
        (cnt_pos[xor_sum] += cnt_zero[xor_sum] + 1) %= mod;

        DEBUG(cnt_pos[xor_sum]);
    }

    if(xor_sum) return (cnt_zero[xor_sum] + 1) % mod;

    ll ans = 1;
    for(ll i = 1; i < zero + suffix_zero + prefix_zero; i++) (ans *= 2) %= mod;
    DEBUG(ans);
    for(ll i = 0; i < 10; i++) DEBUG(PLL(i, cnt_zero[i]));
    (ans += accumulate(next(cnt_pos.begin()), cnt_pos.end(), 0ll)) %= mod;

    return ans;
}

