template <typename T>
class SegmentTreeUpdAdd {
public:
    ll n;
    std::vector<T> node;
    SegmentTreeUpdAdd(std::vector<T> v) {
        ll sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n, 0);
        for(ll i=0;i<sz;++i) node[i+n-1] = v[i];
        for(ll i=n-2;i>=0;--i) node[i] = node[2*i+1] + node[2*i+2];
    }
    void update(ll idx, T val) {
        assert(0 <= idx && idx < n);
        node[idx + n - 1] = val;
        idx = idx + n - 1;
        while(idx > 0) {
            idx = (idx - 1) / 2;
            node[idx] = node[2*idx + 1] + node[2*idx + 2];
        }
    }
    T query(ll a, ll b, ll k, ll l, ll r) {
        if(r <= a || b <= l) {
            return 0;
        }
        if(a <= l && r <= b) return node[k];
        T vl = query(a, b, k*2+1, l, (l+r)/2);
        T vr = query(a, b, k*2+2, (l+r)/2, r);
        return vl + vr;
    }
    T query(ll a, ll b) {
        return query(a, b, 0, 0, n);
    }
};
template<typename T>
T mypow(T x, T n, const T &p) {
  T ret = 1;
  while(n) {
    if(n&1) {
      ret *= x;
      ret %= p;
    }
    x *= x;
    x %= p;
    n>>=1;
  }
  return ret;
}
