	for(int i=0;i<N;i++){
		sum[i+1] = (sum[i] ^ a[i]);
		if (firstShown[sum[i+1]] == -1) firstShown[sum[i+1]] = i+1;
		if (lastIndex[sum[i+1]] != -1){
			nextSameIndex[lastIndex[sum[i+1]]] = i+1;
			if (sum[i+1] == 0){
				for(int j=lastIndex[0];j<=i;j++) nextZeroIndex[j] = i+1;
			}
		}
		lastIndex[sum[i+1]] = i+1;
	}

	llm ans(0);

	// each XOR == i > 0 のケースを数える．
	for(int i=1;i<1048576;i++){
		if (firstShown[i] == -1) continue;
		if (sum[N] != 0 && i != sum[N]) continue;

		ll now = firstShown[i];
		if (now == N) {ans += llm(1); continue;}

