		while(1){
			if (now == LLONG_MAX) break;
			if (nextSameIndex[now]==LLONG_MAX && nextZeroIndex[now]==LLONG_MAX) break;
			if (nextSameIndex[now] > nextZeroIndex[now]){ // i よりも 0 が先に来る場合
				ll zeroCount = 0; // 次の i までに 0 が何個登場するか．
				ll pos = nextZeroIndex[now];
				while(nextSameIndex[now] > pos){
					zeroCount++;
					pos = nextZeroIndex[pos];				
				}
				cum0 += cumi * llm(zeroCount);
				if (nextSameIndex[now] < LLONG_MAX) cumi += cum0;
			}else{ // 0 よりも i が先に来る場合
				cumi += cum0;
			}
			now = nextSameIndex[now];
		}
