			// cerr << i << ":" << cumi << endl;
			ans += cumi;
		}else if (sum[N] == i){
			// cerr << i << ":" << cum0 << endl;
			ans += cum0;
		}
	}
	// each XOR == 0 のケースを数える．
	if (sum[N] == 0){
		llm p(1);
		for(int i=1;i<N;i++) if (sum[i]==0) p *= llm(2);
