template<class type>
class matrix {
private:
	size_t H, W;
	std::vector<type> mat;
public:
	matrix() : H(0), W(0), mat(std::vector<type>()) {};
	matrix(size_t N_) : H(N_), W(N_), mat(std::vector<type>(N_* N_)) {};
	matrix(size_t H_, size_t W_) : H(H_), W(W_), mat(std::vector<type>(H_* W_)) {};
	type& entry(size_t r, size_t c) { return mat[r * W + c]; }
	type entry(size_t r, size_t c) const { return mat[r * W + c]; }
	matrix& operator+=(const matrix& m) {
		assert(H == m.H && W == m.W);
		for (size_t i = 0; i < H; ++i) {
			for (size_t j = 0; j < W; ++j) {
				mat[i * W + j] += m.mat[i * W + j];
			}
		}
	}
	matrix& operator-=(const matrix& m) {
		assert(H == m.H && W == m.W);
		for (size_t i = 0; i < H; ++i) {
			for (size_t j = 0; j < W; ++j) {
				mat[i * W + j] -= m.mat[i * W + j];
			}
		}
	}
	matrix& operator*=(const matrix& m) {
		assert(W == m.H);
		matrix ans(H, m.W);
		for (size_t i = 0; i < H; ++i) {
			for (size_t j = 0; j < m.W; ++j) {
				for (size_t k = 0; k < W; ++k) {
					ans.mat[i * m.W + j] += mat[i * W + k] * m.mat[k * m.W + j];
				}
			}
		}
		return (*this) = ans;
	}
	matrix operator+(const matrix& m) const { return matrix(*this) += m; }
	matrix operator-(const matrix& m) const { return matrix(*this) -= m; }
	matrix operator*(const matrix& m) const { return matrix(*this) *= m; }
};

template<class type>
matrix<type> unit(int N) {
	matrix<type> ret(N);
	for (size_t i = 0; i < N; ++i) {
		ret.entry(i, i) = type(1);
	}
	return ret;
}

