    // }
    // cerr << endl;

    vector<BIT2D<ll>> dp(2, BIT2D<ll>(A_MAX, n+1));
    vector<int> prev(A_MAX, 0);
    ll ans = modpow(2, count_zero[n]-1);

    for(int i=1;i<=n;++i) {
        if(b[i]) {
            vs.insert(b[i]);
            zero = count_zero[i] - count_zero[prev[b[i]]];
            if(b[i] == 1) cerr << b[i] << ": " << zero << endl;
            dp[0].add(
                b[i], i,
                (dp[1].sum(b[i], i-1) - dp[1].sum(b[i]-1, i-1)) % MOD
            );
            dp[1].add(
                b[i], i, 
                (zero*(dp[0].sum(b[i], i-1) - dp[0].sum(b[i]-1, i)) + 1) % MOD
            );
            prev[b[i]] = i;
            // cerr << b[i] << ": " << dp[0].sum(b[i], i) - dp[0].sum(b[i], i-1) - dp[0].sum(b[i]-1, i) + dp[0].sum(b[i]-1, i-1) << " " << dp[1].sum(b[i], i) - dp[1].sum(b[i], i-1) - dp[1].sum(b[i]-1, i) + dp[1].sum(b[i]-1, i-1) << endl;
        }
    }

    if(b.back()) {
        ans += dp[1].sum(b.back(), n) - dp[1].sum(b.back()-1, n) - dp[1].sum(b.back(), n-1) + dp[1].sum(b.back()-1, n-1);
    } else {
        for(ll v: vs) {
            zero = count_zero[n] - count_zero[prev[v]];
            dp[1].add(
                v, n,
