            );
            // cerr << v << ": " << (zero*(dp[0].sum(v, n) - dp[0].sum(v-1, n)) + 1) % MOD << endl;
        }
        ans += dp[1].sum(A_MAX, n) - dp[1].sum(A_MAX, n-1);
    }
    ans %= MOD;
    cout << ans << endl;

}

