long long check(int n, int a[], int p[], int i)
{
    int partial_xor = p[i];
    int j;
    int ptr = i;
    int cnt = 0;

    //printf("i = %d, partial_xor = %x\n", i, partial_xor);

    for (j = i + 1; j < n; j++) {
    //    printf("%d-%d, %x\n", ptr, j, p[j]^p[ptr]);
        if ((p[j]^p[ptr]) == partial_xor) {
            cnt++;
            ptr = j;
        }
    }
    //printf("%d-%d, %x\n", ptr, j, p[j]^p[ptr]);
    if ((p[j]^p[ptr]) != partial_xor) {
        return 0;
    }
    //printf("cnt = %d\n", cnt);

    return pow(2, cnt);
}

int main(int argc, char *argv[])
{
    int n;
    int a[500000];
    int p[500001]; //左からn個をxor
    int all_xor;
    int i;
    long long ans;

    scanf("%d", &n);

    all_xor = 0;
    p[0] = 0;
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        all_xor ^= a[i];
        p[i + 1] = p[i] ^ a[i]; //累積XOR
    }

    ans = 1;

    if (all_xor == 0) {
        // 偶数個に分割．all_xor が0なので
        for (i = 1; i < n; i++) { 
            ans += check(n, a, p, i);
            ans %= 1000000007;
        }
    } else {
        // all_xor が 0でない → 奇数個に分割．仕切った各部はall_xorと等価
        int cnt = 1;
        int ptr = 0;
        for (i = 1; i < n; i++) {
            if ((p[i]^p[ptr]) == all_xor) {
                cnt++;
                ptr = i;
            }
        }
        if ((p[i]^p[ptr]) != all_xor) {cnt = 1;}
        ans = pow(2, cnt) - 1;
    }

    printf("%lld\n", ans);

    return 0;
}

