		x = s[i];
		if(prev[x] == -1){
			dp[x] = 1;
			sum[x] = 1;
		}
		else{
			dp[x] = MOD(sum[x] * (Onum[i] - Onum[prev[x]]) + 1);
			sum[x] = MOD(sum[x] +dp[x]);
		}
		prev[x] = i;
//		printf("i = %lld\n", i);
//		printf("dp[%lld] = %lld\n", x, dp[x]);
//		printf("sum[%lld] = %lld\n", x, sum[x]);
	}
	int ans = 0;
	for(i = 1; i < M; i++){
		if(s[N] != 0 && s[N] != i){
			continue;
		}
		else if(s[N] == 0){
			ans = MOD(ans + sum[i]);
		}
		else{
			ans = MOD(ans + dp[i]);
		}
	}
	if(s[N] == 0){
		ans = MOD(ans + power(2, Onum[N] - 1));
	}
	printf("%lld\n", ans);
	return 0;
}

