val MOD = 1000000007L
fun main(args: Array<String>) {
    val L = readLine()!!
    val SIZE = L.length
    var num = 0
    var res = 0L
    for (i in 0 until SIZE) {
        val len =  SIZE - i - 1
        if (L[i] == '1') {
            res += (modPow(2, num) * modPow(3, len))
            ++num
        }
    }
    res += modPow(2, num)
    println("${res}")
}

fun modPow(A: Int, N: Int): Long {
    var a = A.toLong()
    var n = N.toLong()
    var res = 1L
    while (n > 0) {
        if (n and 1 != 0L) res = res * a % MOD
        a = a * a % MOD
        n = n shr 1
    }
    return res % MOD
}

