  }
  val zeroCountArray = IntArray(n + 1)
  zeroCountArray[0] = 1
  for (i in 1..n) {
    zeroCountArray[i] = zeroCountArray[i - 1] + (if (xorArray[i] == 0) 1 else 0)
  }

