    val x = xorArray[n]
    // println(indexLists[x])
    val xIndexArray = indexLists[x].toIntArray()
    if (xIndexArray.size == 1) return 1L

    val dp1 = LongArray(xIndexArray.size)
    val dp2 = LongArray(xIndexArray.size)
    dp1[0] = 1
    dp2[0] = 1
    for (i in 1 until dp1.size) {
      val zeroCountDiff = zeroCountArray[xIndexArray[i]] - zeroCountArray[xIndexArray[i - 1]]
      dp1[i] = dp2[i - 1] * zeroCountDiff  + dp1[i - 1]
      dp1[i] %= P
      dp2[i] = dp2[i - 1] + dp1[i]
      dp2[i] %= P
    }

    return dp1.last()
  }

