      dp1[i] = dp2[i - 1] * zeroCountDiff  + dp1[i - 1]
      dp1[i] %= P
      dp2[i] = dp2[i - 1] + dp1[i]
      dp2[i] %= P
    }

    count += dp2.last()
    count %= P
    // println("count: $count")
  }
  return count
}

