            for(int j=i+1;j<=str.length();j++){
                String s = str.substring(i,j);

                if(s.length() == 0)
                    continue;

                int r = xor(s);

                if(map.containsKey(r)){
                    Set<String> set = map.get(r);
                    set.add(s);
