            }
        }
    }

    private static int xor(String str){

        int res = Integer.parseInt(str.substring(0,1));

        for(int i=1;i<str.length();i++){
            int n = Integer.parseInt(str.substring(i,i+1));
            res = res ^ n;
        }

        return res;
    }

