    static class XORPartitioning {
        NumberTheory.Modular mod = new NumberTheory.Modular(1e9 + 7);
        NumberTheory.Power pow = new NumberTheory.Power(mod);

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] a = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                a[i] = in.readInt();
            }

            PreXor pre = new PreXor(a);
            int[] registries = new int[1 << 20];
            SequenceUtils.deepFill(registries, -1);

            int[] last = new int[n + 1];
            int[] lastSkip = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                int p = (int) pre.intervalSum(1, i);
                last[i] = registries[p];
                if (registries[0] < last[i]) {
                    lastSkip[i] = lastSkip[last[i]];
                } else {
                    lastSkip[i] = last[i];
                }
                registries[p] = i;
            }

            int[][] dp = new int[2][1 << 20];
            for (int i = 1; i <= n; i++) {
                int p = (int) pre.intervalSum(1, i);
                if (last[i] == -1) {
                    dp[1][p] = 1;
                    continue;
                }
                if (last[i] == lastSkip[i]) {
                    dp[0][p] = dp[1][p];
                }
                dp[1][p] = mod.plus(1, mod.plus(dp[1][p], dp[0][p]));
            }

            if (pre.intervalSum(1, n) != 0) {
                int ans = mod.plus(1, dp[0][(int) pre.intervalSum(1, n)]);
                out.println(ans);
                return;
            }

            int ans = 0;
            for (int i = 1; i < (1 << 20); i++) {
                ans = mod.plus(ans, dp[1][i]);
            }
            int zeroCnt = 0;
            for (int i = 1; i < n; i++) {
                if (pre.intervalSum(1, i) == 0) {
                    zeroCnt++;
                }
            }
            ans = mod.plus(ans, pow.pow(2, zeroCnt));
            out.println(ans);
        }

    }
