						ct++;
					}
					if (sx[i] == 0) {
						t[p++] = ct;
						ct = 0;
					}
				}
				dp = new long[l.size()];
				dp[0] = t[0];
				long sum = dp[0];
				for (int i = 1; i < l.size(); i++) {
					dp[i] = add(add(mul(sum, t[i]), dp[i - 1]), t[i]);
