public class Main {


  private static void solve() {
    int n = ni();
    int[] a = na(n);
    for (int i = 0; i < n - 1; i ++) {
      a[i + 1] ^= a[i];
    }
    int mod = 1000000000 + 7;

    long[] dp1 = new long[1 << n];
    long[] dp0 = new long[1 << n];
    long[] cnt = new long[1 << n];
    Arrays.fill(dp0, 1);
    int x = 0;
    for (int i = 0; i < n; i ++) {
      if (a[i] == 0) {
        x ++;
      } else {
        dp0[a[i]] += dp1[a[i]] * (x - cnt[a[i]]);
        dp1[a[i]] += dp0[a[i]];
        dp0[a[i]] %= mod;
        dp1[a[i]] %= mod;

        cnt[a[i]] = x;
      }
    }

    if (a[n - 1] > 0) {
      System.out.println(dp0[a[n-1]]);
    } else {
      long ret = 1;
      for (int i = 0; i < x - 1; i ++) {
        ret = ret * 2 % mod;
      }
      for (int i = 0; i < (1 << n); i ++) {
        ret += dp1[i];
        ret %= mod;
      }
      System.out.println(ret);
    }
  }


  public static long CX(long n, long r, int p, int[][] fif)
  {
      if(n < 0 || r < 0 || r > n)return 0;
      int np = (int)(n%p), rp = (int)(r%p);
      if(np < rp)return 0;
      if(n == 0 && r == 0)return 1;
      int nrp = np-rp;
      if(nrp < 0)nrp += p;
      return (long)fif[0][np]*fif[1][rp]%p*fif[1][nrp]%p*CX(n/p, r/p, p, fif)%p;
  }

  public static int[][] enumFIF(int n, int mod)
  {
      int[] f = new int[n+1];
      int[] invf = new int[n+1];
      f[0] = 1;
      for(int i = 1;i <= n;i++){
          f[i] = (int)((long)f[i-1] * i % mod);
      }
      long a = f[n];
      long b = mod;
      long p = 1, q = 0;
      while(b > 0){
          long c = a / b;
          long d;
          d = a; a = b; b = d % b;
          d = p; p = q; q = d - c * q;
      }
      invf[n] = (int)(p < 0 ? p + mod : p);
      for(int i = n-1;i >= 0;i--){
          invf[i] = (int)((long)invf[i+1] * (i+1) % mod);
      }
      return new int[][]{f, invf};
  }

