import java.util.InputMismatchException;
import java.util.Map;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int mod = 1000000007;
		int n = ni();
		int[] a = na(n);
		long c = 0;
		int[] zs = new int[n+1];
		int p = 0;
		zs[p++] = 0;
		for(int i = 0;i < n;i++){
			c ^= a[i];
			if(c == 0){
				zs[p++] = i+1;
			}
		}
		// 2ac+abc+bc+ab+a+b+c+1
		long ans = 0; // all 0
		if(zs[p-1] == n){
			ans += pow(2, p-2, mod);
			long[] f = new long[1<<20];
			long[] fsum = new long[1<<20];
			long[] flsum = new long[1<<20];
			int[] last = new int[1<<20];
			Arrays.fill(last, -1);
			for(int i = 0;i < p-1;i++){
				int t = 0;
				Map<Integer, Integer> map = new HashMap<>();
				for(int j = zs[i];j < zs[i+1]-1;j++){
					t ^= a[j];
					if(map.containsKey(t)){
						map.put(t, map.get(t)+1);
					}else{
						map.put(t, 1);
					}
				}

				for(int k : map.keySet()){
					int v = map.get(k);
					flsum[k] += fsum[k] * (i-last[k]);
					flsum[k] %= mod;
					f[k] = (flsum[k]+1) * v % mod;
					ans += f[k];
					fsum[k] += f[k];
					if(fsum[k] >= mod)fsum[k] -= mod;
					last[k] = i;
				}
			}
			out.println(ans%mod);
		}else{
			int baset = 0 ;
			for(int i = zs[p-1];i < n;i++){
				baset ^= a[i];
			}
			ans = 1;

			// ab+a+b
			for(int i = 0;i < p-1;i++){
				int t = 0;
				int ct = 0;
				for(int j = zs[i];j < zs[i+1]-1;j++){
					t ^= a[j];
					if(t == baset)ct++;
				}
				ans = ans * (ct + 1) % mod;
			}
			out.println(ans);
		}
	}

	public static long pow(long a, long n, long mod) {
		//		a %= mod;
		long ret = 1;
		int x = 63 - Long.numberOfLeadingZeros(n);
		for (; x >= 0; x--) {
			ret = ret * ret % mod;
			if (n << 63 - x < 0)
				ret = ret * a % mod;
		}
		return ret;
	}


