public class Solver
{
    int n;
    int[] a;
    int[,] m;
    public void Solve()
    {
        n = ri;
        a = new int[n];
        m = new int[n, 1 << 20];
        for(int i = 0; i < n; i++) { a[i] = ri; }
        int s = 0, p = 0;
        for (int i = 0; i < n; i++)
        {
            s = s ^ a[i];
            p = (p + search(i, s)) % mod; //最初に区切るのがa[i]のうしろ
        }
        Console.WriteLine(p);
    }

    int search(int t, int q)//t:基準点(a[t]のうしろでくぎられてる) q:基準値
    {
        if (t == n - 1)
        {
            return 1;
        }
        else if (m[t, q] > 0)
        {
            return m[t, q] - 1;
        }
        else
        {
            int s = 0, p = 0;
            for (int i = t + 1; i < n; i++)
            {
                s = s ^ a[i];
                if (q == s) { p = (p + search(i, q)) % mod; }
            }
            m[t, q] = p + 1;
            return p;
        }
    }


