	static ulong All(int k) => One(k) - 1;
	static bool Has(ulong s, int k) => (s & One(k)) != 0;
	const int MOD = 1000000007;
	public K()
	{
		SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
		Solve();
		Out.Flush();
	}
	void Solve()
	{
		var N = F;
		var A = G;
		var sum = new int[N + 1];
		for (var i = 0; i < N; i++) sum[i + 1] = sum[i] ^ A[i];
		var zero = new int[N + 2];
		for (var i = 0; i <= N; i++) zero[i + 1] = zero[i] + (sum[i] == 0 ? 1 : 0);
		var dic = Indexes(sum);
		if (sum[N] == 0)
		{
			var ans = Pow(2, zero[N + 1] - 2, MOD);
			foreach (var t in dic)
			{
				if (t.Key == 0) continue;
				var zs = new int[t.Value.Count - 1];
				for (var i = 0; i + 1 < t.Value.Count; i++) zs[i] = zero[t.Value[i + 1]] - zero[t.Value[i]];
				foreach (var j in DP(zs)) ans += j;
				ans %= MOD;
			}
			WriteLine(ans % MOD);
		}
		else
		{
			var l = dic[0];
			var zs = new int[l.Count - 1];
			for (var i = 0; i + 1 < l.Count; i++) zs[i] = zero[l[i + 1]] - zero[l[i]];
			WriteLine(DP(zs).Last());
		}
	}
	static Dictionary<int, List<int>> Indexes(IList<int> x)
	{
		var dic = new Dictionary<int, List<int>>();
		for (var i = 0; i < x.Count; i++)
		{
			if (!dic.ContainsKey(x[i])) dic[x[i]] = new List<int>();
			dic[x[i]].Add(i);
		}
		return dic;
	}
	static long[] DP(IList<int> zs)
	{
		var L = zs.Count;
		var dp = new long[L + 1];
		dp[0] = 1;
		var sum = 1L;
		for (var j = 0; j < L; j++)
		{
			dp[j + 1] = (dp[j] + zs[j] * sum % MOD) % MOD;
			sum = (sum + dp[j + 1]) % MOD;
		}
		return dp;
	}
	public static long Pow(long a, long b, long mod)
	{
		var p = 1L;
		var x = a;
		while (b > 0)
		{
			if ((b & 1) == 1) p = (p * x) % mod;
			b >>= 1;
			x = (x * x) % mod;
		}
		return p;
	}
}

