        a = Console.ReadLine().Split().Select(long.Parse).ToArray();
        long[] xor = new long[n + 1]; //累積xor
        for (int i = 1;i <= n;i++)
            xor[i] = xor[i - 1] ^ a[i - 1];

        if (xor[n] == 0){ //全体のxorが0
            long ans = 0;
            int c = 0;
            for (int i = 1;i < n;i++)
                if (xor[i] == 0) c++;
            ans += Pow(2,c); //0|0|0|...

            /* わからん */

            Console.WriteLine(ans);
            return;
        }

        long x = xor[n];
        List<long> ls = new List<long>();
        for (int i = 1;i <= n;i++)
            if (xor[i] == 0 || xor[i] == x)
                ls.Add(xor[i]);
        long[,] dp = new long[ls.Count + 1,2];
        dp[0,1] = 1;
        for (int i = 1;i <= ls.Count;i++){
            if (ls[i - 1] == x){
                dp[i,0] = (dp[i-1,0] + dp[i,1]) % mod;
                dp[i,1] = dp[i-1,1];
            }
            else{
                dp[i,0] = dp[i-1,0];
                dp[i,1] = (dp[i-1,1] + dp[i-1,0]) % mod;
            }
        }
        Console.WriteLine(dp[ls.Count - 1,1]);
    }

    static long Pow(long p,long k){
        p %= mod;
        if (k == 0) return 1;
        if (k == 1) return p;
        long t = Pow(p,k/2);
        if (k % 2 == 0) return t * t % mod;
        return (t * t % mod) * p % mod;
    }
}

