    static BigInteger power(BigInteger b, BigInteger p)
    {
        BigInteger t = b;
        BigInteger q = 1;
        while (p > 0)
        {
            if (p % 2 == 1) q *= t;
            t *= t;
            p -= p % 2;
            p /= 2;
        }
