public class Hello
{
    private const int MOD_N = 1000000000 + 7;

    public static void Main()
    {
        var n = long.Parse(Console.ReadLine());
        var line2 = Console.ReadLine().Split(' ');
        var ass = new uint[n];
        for (int i = 0; i < ass.Length; ++i)
            ass[i] = uint.Parse(line2[i]);

        var beauties = new uint[n];
        beauties[0] = ass[0];

        var counts = new int[n];
        counts[0] = 1;

        var progresses = new uint[n][];
        for (int i = 0; i < progresses.Length; ++i)
            progresses[i] = new uint[n * 2];

        var zeros = new int[n][];
        for (int i = 0; i < zeros.Length; ++i)
            zeros[i] = new int[n * 2];

        for (int i = 1; i < ass.Length; ++i)
        {
            var a = ass[i];
            beauties[i] = beauties[i - 1] ^ a;
            counts[i] = 1;
            progresses[i][0] = 0;
            zeros[i][0] = 0;

            for (int j = 0; j < i; ++j)
            {
                var beauty = beauties[j];
                var progress = progresses[j];
                var zero = zeros[j];
                for (int k = 0, count = counts[j]; k < count; ++k)
                {
                    progress[k] ^= a;
                    var p = progress[k];
                    if (p == 0)
                    {
                        ++zero[k];
                    }
                    else if (p == beauty)
                    {
                        var c = ++counts[j];
                        progress[c] = 0;
                        zero[c] = 0;
                    }
                }
            }
        }

        progresses[progresses.Length - 1][0] = beauties[beauties.Length - 1];

        int answer = 0;

        for (int i = 0; i < beauties.Length; ++i)
        {
            var beauty = beauties[i];
            var progress = progresses[i];
            var zero = zeros[i];
            if (beauty == 0)
            {
                if (progress[0] == 0)
                {
                    if (zero[0] > 0)
                        answer += (int)(Math.Pow(2, zero[0] - 1) % MOD_N);
                    else
                        ++answer;
                    answer %= MOD_N;
                }
                continue;
            }
            for (int j = 0, count = counts[i]; j < count; ++j)
            {
                if (beauty != progress[j])
                    continue;
                var z = j > 0 ? zero[j] : 0;
                answer += 1 + z;
                answer %= MOD_N;
            }
        }

        Console.WriteLine(answer);
    }
}

