        int dif = uniform(0, 100);
        a[i] += dif;
        sumSegTree.add(i, dif);
    }

    foreach (i; 0 .. n) {
        foreach (j; i .. n + 1) {
            assert(sumSegTree.query(i, j) == a[i .. j].sum());
        }
