    foreach (i; 0 .. n) {
        minSegTree.assign(i, a[i]);
    }

    foreach (i; 0 .. n) {
        foreach (j; i + 1 .. n + 1) {
            assert(minSegTree.query(i, j) == a[i .. j].minElement);
        }
