	xs[a] = (zcnt - zs[a]) * ys[a] + xs[a]
	として更新
	( = 0 のときはスルー)

	全体が = 0 だった場合は最後に全部見て和を取る

	*/

	foreach(i; 1 .. n + 1){
		if(sums[i] == 0){
			zcnt += 1;
			continue; 
		}
		else{
			long s = sums[i];
			if(s !in xs){
				xs[s] = 1, ys[s] = 0, zs[s] = 0;
			}
			xs[s] += (zcnt - zs[s]) * ys[s], xs[s] %= mod;
			ys[s] += xs[s], ys[s] %= mod;
			zs[s] = zcnt;
		}
		print!1("i:", i, " s:", sums[i], " xs:", xs, " ys:", ys, " zs:", zs, " zcnt:", zcnt);
	}

	long ans;
	if(sums[n] != 0) ans = xs[sums[n]];
	else{
		ans = 1;
		long[] ks = ys.keys;
		foreach(k; ks) ans += ys[k], ans %= mod;
		long t = 1;
		foreach(i; 1 .. zcnt) ans += t, t *= 2, ans %= mod;
	}

	ans.writeln;

}

