def XOR_partition(A, mod):
    l = len(A)
    count = 0

    if l == 1 and A[0] % 2 == mod:
        return 1
    elif l == 1 and A[0] % 2 != mod:
        return 0
    else:
        for i in range(l-1):
            if sum(A[0:i+1]) % 2 == mod:
                count += XOR_partition(A[i+1:], mod)
        if sum(A) % 2 == mod:
            count += 1
        return count

