def xor_partitioning(N: int, A: list)->int:
    MOD = 10**9 + 7

    B = [0] * (N+1)
    for n, a in enumerate(A):
        B[n+1] = a ^ B[n]

    if B[-1] == 0:
        X = set(B)
    else:
        X = set([B[-1]])

    res = 1
    # dp[i][0] = i マス目まで処理した時に現在こまが置かれているますに 0 が書かれている
    # dp[i][1] = i マス目まで処理した時に現在こまが置かれているマスに X が書かれている。
    dp = [[0, 0] for _ in range(N+1)]

    for x in X:
        dp[0] = [1, 0]

        for i in range(N):
            b = B[i+1]

            if b == 0:
                dp[i+1][0] = (dp[i][0] + dp[i][1]) % MOD
            else:
                dp[i+1][0] = dp[i][0]

            if b == x:
                dp[i+1][1] = (dp[i][1] + dp[i][0]) % MOD
            else:
                dp[i+1][1] = dp[i][1]

        res = (res + dp[N][0] - 1) % MOD

    return res


