pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();
    let a = i.read_vec::<u32>(n);

    writeln!(o, "{}", solve(&a)).unwrap();
}
fn solve(a: &[u32]) -> usize {
    let mut x_to_idxs = vec![Vec::new(); 2usize.pow(20)];
    let mut xs = Vec::new();
    let mut x = 0;
    let mut m = BTreeMap::new();
    for i in 0..a.len() {
        x ^= a[i];
        xs.push(x);
        x_to_idxs[x as usize].push(i);
        m.insert((i, x), Mod::new(1));
    }

    while let Some((&(i, b), &count)) = m.iter().next() {
        if i + 1 == a.len() {
            break;
        }
        m.remove(&(i, b));
        let x_next = xs[i] ^ b;
        for &i_next in &x_to_idxs[x_next as usize] {
            if i_next > i {
                *m.entry((i_next, b)).or_insert(Mod::new(0)) += count;
            }
        }
    }
    let mut sum = Mod::new(0);
    for &count in m.values() {
        sum += count;
    }
    sum.0
}

