}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();
    let a = i.read_vec::<u32>(n);

    writeln!(o, "{}", solve(&a)).unwrap();
}
fn solve(a: &[u32]) -> usize {
    let mut x_to_idxs = vec![VecDeque::new(); 2usize.pow(20)];
    let mut xs = Vec::new();
    let mut x = 0;
    let mut m = vec![HashMap::new(); a.len()];
    for i in 0..a.len() {
        x ^= a[i];
        xs.push(x);
        x_to_idxs[x as usize].push_back(i);
    }
    for i in 0..a.len() - 1 {
        let x = xs[i];
        *m[i].entry(x).or_insert(Mod::new(0)) += Mod::new(1);
        x_to_idxs[x as usize].pop_front();

        let mut mi = HashMap::new();
        std::mem::swap(&mut mi, &mut m[i]);

        for (b, count) in mi {
            let x_next = x ^ b;
            for &i_next in &x_to_idxs[x_next as usize] {
                *m[i_next].entry(b).or_insert(Mod::new(0)) += count;
            }
        }
    }
    let mut sum = Mod::new(1);
    for (_, &count) in &m[a.len() - 1] {
        sum += count;
    }
    sum.0

}

