trait Bisect<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}

impl<T: Ord> Bisect<T> for [T] {
    fn lower_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] >= val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
    fn upper_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] > val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [usize; n],
    }
    let mut acc = vec![0; n + 1];
    for i in 0..n {
        acc[i + 1] = acc[i] ^ a[i];
    }
    let mut tot = ModInt::new(0);
    const W: usize = 1 << 20;
    let mut occ = vec![vec![]; W];
    for i in 0..n + 1 {
        occ[acc[i]].push(i);
    }
    // 0
    if acc[n] == 0 {
        tot += ModInt::new(2).pow(occ[0].len() as i64 - 2);
    }
    // others
    for s in 1..W {
        if acc[n] != 0 && acc[n] != s { continue; }
        let l = occ[s].len();
        if l == 0 { continue; }
        let mut cnt = vec![0; l];
        for i in 0..l - 1 {
            let hi = occ[0].upper_bound(&occ[s][i + 1]);
            let lo = occ[0].lower_bound(&occ[s][i]);
            cnt[i + 1] = hi - lo;
        }
        // eprintln!("s = {}, cnt = {:?}", s, cnt);
        // 0 => 0, 1 => s
        let mut dp = vec![[ModInt::new(0); 2]; l + 1];
        dp[0][0] = ModInt::new(1);
        for i in 0..l {
            let u = cnt[i] as i64;
            dp[i + 1][0] += dp[i][0];
            dp[i + 1][1] += dp[i][0];
            dp[i + 1][0] += dp[i][1] * u;
            dp[i + 1][1] += dp[i][1] + dp[i][1] * u;
        }
        // eprintln!("dp = {:?}", dp);
        if acc[n] == 0 {
            tot += dp[l][1];
        } else {
            tot += dp[l - 1][0] + dp[l - 1][1];
        }
    }
    puts!("{}\n", tot);
}

