#[derive(Debug)]
struct Counter {
    zeros: usize,
    count: usize
}

impl Counter {
    fn new(zeros: usize, count: usize) -> Counter {
        Counter { zeros: zeros, count: count }
    }
}

fn count(ns: &[usize], even: bool, memo: &mut [Vec<Option<ModP>>]) -> ModP {
    match ns.split_first() {
        None => if even { modp(1) } else { modp(0) },
        Some((&hd1, tl1)) => {
            match tl1.split_first() {
                None => if even { modp(0) } else { modp(hd1 as u64) },
                Some((_, tl2)) => {
                    memo[even as usize][ns.len()].unwrap_or_else(|| {
                        let ans = hd1 as u64 * count(tl1, !even, memo) + count(tl2, even, memo);
                        memo[even as usize][ns.len()] = Some(ans);
                        ans
                    })
                }
            }
        }
    }
}

fn main() {
    read!();
    read!(aa = Vec<u32>);
    let prefix_xor: Vec<u32> = aa.into_iter()
        .lscan(0, |&acc, next| acc ^ next)
        .collect();
    let k = *prefix_xor.last().unwrap();
    let ans = if k != 0 {
        let mut ns: Vec<usize> = prefix_xor.into_iter()
            .filter(|&x| x == 0 || x == k)
            .group_by(|&x| x)
            .skip(1)
            .map(|(_, xs)| xs.len())
            .collect();
        ns.pop();
        count(&ns, true, &mut vec![vec![None; ns.len() + 1]; 2])
    } else {
        let mut zeros = 0;
        let mut ns_map = HashMap::new();
        for x in prefix_xor {
            if x == 0 {
                zeros += 1;
            } else {
                let mut ns = ns_map.entry(x).or_insert(vec![Counter::new(zeros, 0)]);
                if ns.last().unwrap().zeros == zeros {
                    ns.last_mut().unwrap().count += 1;
                } else {
                    ns.push(Counter::new(zeros, 1));
                }
            }
        }
        let ans_0 = modp(2).pow(zeros as u64 - 2);
        let ans_else: ModP = ns_map.values().map(|cs| {
            let mut zeros = cs[0].zeros;
            let mut ns = Vec::new();
            for c in cs {
                ns.push(c.zeros - zeros);
                ns.push(c.count);
                zeros = c.zeros;
            }
            ns.remove(0);
            count(&ns, false, &mut vec![vec![None; ns.len() + 1]; 2])
        }).sum();
        ans_0 + ans_else
    };
    println!("{}", ans);
}

