pub mod modular {
    const M: i64 = 1000000007;

    #[derive(Debug, Clone, Copy, Default, PartialOrd, Ord, PartialEq, Eq)]
    pub struct Mod(i64);

    impl ::std::fmt::Display for Mod {
        fn fmt(&self, f: &mut ::std::fmt::Formatter) -> ::std::fmt::Result {
            write!(f, "{}", self.0)
        }
    }

    impl Mod {
        pub fn new(v: i64) -> Mod {
            Mod(v % M)
        }

        pub fn pow(self, mut r: i64) -> Mod {
            let mut k = self;
            let mut ret = 1.into();

            while r > 0 {
                if r % 2 != 0 {
                    ret = ret * k;
                }
                r /= 2;
                k = k * k;
            }

            ret
        }

        // This requires M is prime
        pub fn recip(self) -> Mod {
            self.pow(M - 2)
        }
    }

    use std::ops::*;

    impl<T: Into<Mod>> Add<T> for Mod {
        type Output = Mod;
        fn add(self, rhs: T) -> Self::Output {
            Mod::new(self.0 + rhs.into().0)
        }
    }
    impl<T: Into<Mod>> AddAssign<T> for Mod {
        fn add_assign(&mut self, rhs: T) {
            *self = *self + rhs;
        }
    }

    impl<T: Into<Mod>> Sub<T> for Mod {
        type Output = Mod;
        fn sub(self, rhs: T) -> Self::Output {
            Mod::new(self.0 - rhs.into().0 + M)
        }
    }
    impl<T: Into<Mod>> SubAssign<T> for Mod {
        fn sub_assign(&mut self, rhs: T) {
            *self = *self - rhs;
        }
    }

    impl<T: Into<Mod>> Mul<T> for Mod {
        type Output = Mod;
        fn mul(self, rhs: T) -> Self::Output {
            Mod::new(self.0 * rhs.into().0)
        }
    }
    impl<T: Into<Mod>> MulAssign<T> for Mod {
        fn mul_assign(&mut self, rhs: T) {
            *self = *self * rhs;
        }
    }

    impl<T: Into<Mod>> Div<T> for Mod {
        type Output = Mod;
        fn div(self, rhs: T) -> Self::Output {
            self * rhs.into().recip()
        }
    }
    impl<T: Into<Mod>> DivAssign<T> for Mod {
        fn div_assign(&mut self, rhs: T) {
            *self = *self / rhs;
        }
    }

    impl Neg for Mod {
        type Output = Mod;
        fn neg(self) -> Self::Output {
            Mod(0) - self
        }
    }

    impl<T: ::std::convert::Into<i64>> ::std::convert::From<T> for Mod {
        fn from(v: T) -> Self {
            Mod::new(v.into())
        }
    }
}

use modular::Mod;
use std::collections::BTreeMap;

fn main() {
    input! {
        n: usize,
        a: [i32; n],
    }

    let mut suml = vec![0; n + 1]; // sum [0..i)
    let mut sumr = vec![0; n + 1]; // sum [i..n)

    for i in 0..n {
        suml[i + 1] = suml[i] ^ a[i];
    }

    for i in (0..n).rev() {
        sumr[i] = sumr[i + 1] ^ a[i];
    }

    // dbg!(&suml);

    let mut mm = BTreeMap::new();
    let ans = solve(0, -1, n, &suml, &mut mm);

    println!("{}", ans);
}

fn solve(i: usize, tgt: i32, n: usize, suml: &[i32], tbl: &mut BTreeMap<(usize, i32), Mod>) -> Mod {
    if i >= n {
        return 1.into();
    }

    let key = (i, tgt);
    if let Some(ret) = tbl.get(&key) {
        return *ret;
    }

    let mut ret = 0.into();

    for j in i + 1..n + 1 {
        let x = suml[i] ^ suml[j];

        // dbg!((i, j, x));

        if tgt == -1 || x == tgt {
            ret += solve(j, x, n, suml, tbl);
        }
    }

    tbl.insert(key, ret);
    ret
}

