        }
        impl DpItem {
            fn new() -> Self {
                DpItem {
                    count_0: Mod::new(1),
                    count_x: Mod::new(0),
                    zeros: 0,
                }
            }
        }
        let mut b_to_idx = vec![u32::max_value(); 2usize.pow(20)];
        let mut dp = Vec::new();

        b_to_idx[0] = 0;
        dp.push(DpItem::new());

        let mut b = 0;
        for i in 0..a.len() {
            b ^= a[i];
            let idx = &mut b_to_idx[b as usize];
            if *idx == u32::max_value() {
                *idx = dp.len() as u32;
                dp.push(DpItem::new());
            }
        }

        let mut b = 0;
        let mut zeros = 0;
        for i in 0..a.len() {
            b ^= a[i];
            if b == 0 {
                zeros += 1;
            } else {
                let dp = &mut dp[b_to_idx[b as usize] as usize];
                dp.count_0 += dp.count_x * (zeros - dp.zeros);
                dp.zeros = zeros;
                dp.count_x += dp.count_0;
            }
        }

        let mut sum = Mod::new(0);
        for dp in dp {
            sum += dp.count_x;
        }
        sum += Mod::new(2).pow(zeros - 1);
        sum.0

    } else {
        let mut count_0 = Mod::new(1);
        let mut count_x = Mod::new(0);
        let x = b;
        let mut b = 0;
        for i in 0..a.len() {
            b ^= a[i];
            if b == 0 {
                count_0 += count_x;
            } else if b == x {
                count_x += count_0;
            }
        }
        count_0.0
    }
}

