use std::collections::HashMap;

const MOD: u64 = 1_000_000_007;

fn pow2(exp: u64) -> u64 {
    if exp == 0 { 1 } else {
        let sub = pow2(exp / 2);
        if exp % 2 == 0 {
            (sub * sub) % MOD
        } else {
            (2 * sub * sub) % MOD
        }
    }
}

fn solve_nonzero(ss: &[u64], last: u64) -> u64 {
    let mut dp = [vec![0; ss.len() + 1], vec![0; ss.len() + 1]];
    dp[1][0] = 1;
    for (i, &s) in (1..).zip(ss) {
        if s == last {
            dp[0][i] = (dp[0][i-1] + dp[1][i-1]) % MOD;
            dp[1][i] = dp[1][i-1];
        } else if s == 0 {
            dp[0][i] = dp[0][i-1];
            dp[1][i] = (dp[1][i-1] + dp[0][i-1]) % MOD;
        } else {
            dp[0][i] = dp[0][i-1];
            dp[1][i] = dp[1][i-1];
        }
    }
    *dp[1].last().unwrap() % MOD
}

fn solve_zero(ss: &[u64]) -> u64 {
    let zeros: Vec<u64> = ss.iter().map(|&s| if s == 0 { 1 } else { 0 })
        .lscan(0, |&acc, z| acc + z).collect();
    let mut seqs = HashMap::new();
    for (i, &s) in ss.iter().enumerate() {
        if s == 0 { continue; }
        let mut seq = seqs.entry(s).or_insert(Vec::new());
        match seq.last().cloned() {
            None => seq.push((i, zeros[i+1])),
            Some((last_index, _)) => seq.push((i, zeros[i+1] - zeros[last_index+1]))
        }
    }

    let ans_zero = pow2(*zeros.last().unwrap());
    let ans_nonzero: u64 = seqs.into_iter().map(|(_, seq)| {
        seq.into_iter().skip(1)
            .map(|(_, zero_count)| zero_count)
            .fold(1, |acc, zero_count| {
                (1 + acc + acc * zero_count) % MOD
            })
    }).sum();
    (ans_zero + ans_nonzero) % MOD
}

fn main() {
    read!();
    read!(aa = Vec<u64>);
    let ss: Vec<u64> = aa.into_iter().lscan(0, |&acc, a| acc ^ a).collect();
    let last = *ss.last().unwrap();
    let ss: Vec<u64> = ss.into_iter()
        .skip(1)
        .rev().skip(1)
        .rev().collect();
    let ans = if last != 0 {
        solve_nonzero(&ss, last)
    } else {
        solve_zero(&ss)
    };
    println!("{}", ans);
}

