    let mut zero_sum = vec![0; 1 << 20];

    let mut sum = 0;
    let mut zero_count = 0;
    for i in 0..n {
        sum ^= a[i];
        if sum == 0 {
            zero_count += 1;
        }
        if sum > 0 {
            zeros[sum].push(zero_count - zero_sum[sum]);
            zero_sum[sum] = zero_count;
        }
    }

    if sum == 0 {
        let mut ans = ModInt(2).pow(zero_count - 1);
        for mask in 1..(1 << 20) {
            let dp = dp(&zeros[mask]);
            ans += dp[1];
