fn dp(zeros: &Vec<usize>) -> Vec<ModInt<usize>> {
    let mut dp = vec![ModInt(0); 2];
    dp[0] = ModInt(1);
    for &zero_count in zeros.iter() {
        let mut next = vec![ModInt(0); 2];
        next[0] = dp[0] + dp[1] * zero_count;
        next[1] = dp[0] + dp[1] * (zero_count + 1);
        dp = next;
    }
    dp
}

