    let mut sumr = vec![0; n + 1]; // sum [i..n)

    for i in 0..n {
        suml[i + 1] = suml[i] ^ a[i];
    }

    for i in (0..n).rev() {
        sumr[i] = sumr[i + 1] ^ a[i];
    }

    // dbg!(&suml);

    let mut mm = HashMap::new();
    let ans = solve(0, -1, n, &suml, &sumr, &mut mm);

