fn solve(
    i: usize,
    tgt: i32,
    n: usize,
    suml: &[i32],
    sumr: &[i32],
    tbl: &mut HashMap<(usize, i32), Mod>,
) -> Mod {
    if i >= n {
        return 1.into();
    }

    let key = (i, tgt);
    if let Some(ret) = tbl.get(&key) {
        return *ret;
    }

    let mut ret = 0.into();

    for j in i + 1..n + 1 {
        let x = suml[i] ^ suml[j];
        let y = sumr[j];

        // dbg!((i, j, x));

        if (tgt == -1 || x == tgt) && (y == x || y == 0) {
            ret += solve(j, x, n, suml, sumr, tbl);
        }
    }

    tbl.insert(key, ret);
    ret
}

