fn doit(a: i32, pos: Vec<usize>, zero_sum: &Vec<i64>, last_is_zero: bool) -> i64 {
    let n = zero_sum.len()-1;
    let pn = pos.len();

    if a == 0 {
        assert!(last_is_zero);
        return pow(2, zero_sum[n]-1);
    }

    let mut dp_sum = 1;
    let mut addr = 1;

    let mut dp = vec![0; pn];
    dp[0] = 1;
    for i in 1..pn {
        let zcnt = zero_sum[pos[i]+1] - zero_sum[pos[i-1]];
        addr += dp_sum * zcnt % MOD;
        addr %= MOD;
        dp[i] = addr;
        dp_sum += addr;
        dp_sum %= MOD;
    }

    if last_is_zero {
        let mut total = 0;
        for f in 0..pn {
            total += dp[f];
        }
        total % MOD
    } else {
        dp[pn-1]
    }
}

