fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();
    let a = i.read_vec::<u32>(n);

    writeln!(o, "{}", solve(a)).unwrap();
}
fn solve(mut a: Vec<u32>) -> usize {
    let mut x = 0;
    for a in a.iter_mut() {
        x ^= *a;
        *a = x;
    }
    if x == 0 {
        let mut to_idx = vec![u32::max_value(); 2usize.pow(20)];
        to_idx[0] = 0;

        let mut dp_len = 1;
        for &a in &a {
            let idx = &mut to_idx[a as usize];
            if *idx == u32::max_value() {
                *idx = dp_len;
                dp_len += 1;
            }
        }

        #[derive(Copy, Clone)]
        struct Dp {
            count_0: Mod,
            count_x: Mod,
            zeros: usize,
        }
        let dp_init = Dp {
            count_0: Mod::new(1),
            count_x: Mod::new(0),
            zeros: 0,
        };
        let mut dp = vec![dp_init; dp_len as usize];

        let mut zeros = 0;
        for &a in &a {
            if a == 0 {
                zeros += 1;
            } else {
                let dp = &mut dp[to_idx[a as usize] as usize];
                dp.count_0 += dp.count_x * (zeros - dp.zeros);
                dp.zeros = zeros;
                dp.count_x += dp.count_0;
            }
        }

        let mut sum = Mod::new(0);
        for dp in dp {
            sum += dp.count_x;
        }
        sum += Mod::new(2).pow(zeros - 1);
        sum.0

    } else {
        let mut count_0 = Mod::new(1);
        let mut count_x = Mod::new(0);
        for &a in &a {
            if a == 0 {
                count_0 += count_x;
            } else if a == x {
                count_x += count_0;
            }
        }
        count_0.0
    }
}

