use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [i64; n],
    }
    let mut ys = vec![0];
    for i in 0..n {
        let t = ys[i] ^ xs[i];
        ys.push(t);
    }
    let ys_zero_cum = {
        let ts: Vec<i64> = ys.iter().map(|&x| if x == 0 { 1 } else { 0 }).collect();
        gen_cum(0, &ts)
    };
    // eprintln!("ys = {:?}", ys);
    let mut a_to_i = vec![vec![]; 1 << 20];
    for (i, &y) in ys.iter().enumerate() {
        a_to_i[y as usize].push(i);
    }
    if ys.last().unwrap() == &0 {
        let mut res = Mod::new(0);
        // 0
        res += dbg!(Mod::new(2).pow(a_to_i[0].len() as u64 - 2));
        // 1..2^20
        for a in 1..1 << 20 {
            let mut total_zero = Mod::new(1);
            let mut total_non_zero = Mod::new(0);
            for ii in (0..a_to_i[a].len()).rev() {
                let i = a_to_i[a][ii];
                total_non_zero += total_zero;
                if ii != 0 {
                    total_zero += Mod::new(
                        (ys_zero_cum[a_to_i[a][ii]] - ys_zero_cum[a_to_i[a][ii - 1]]) as u32,
                    ) * total_non_zero;
                }
            }
            if a <= 16 {
                // eprintln!("a = {}, res = {}", a, total_non_zero.as_u32());
            }
            res += total_non_zero;
        }
        writeln!(buf, "{}", res.as_u32());
    } else {
        let last = *ys.last().unwrap();
        let mut total_non_zero = Mod::new(1);
        let mut total_zero = Mod::new(0);
        for (i, &y) in ys.iter().enumerate().rev() {
            if y == 0 {
                total_zero += total_non_zero;
            } else if y == last {
                total_non_zero += total_zero;
            }
        }
        writeln!(buf, "{}", total_zero.as_u32());
    }
    buf
}

