const MAX: usize = 1<<20;
const MOD: i64 = 1e9 as i64 + 7;

fn make(a: &Vec<usize>, want: usize) -> i64 {
    let n = a.len();
    let mut xorsum = vec![0; n+1];
    for i in 0..n {
        xorsum[i+1] = xorsum[i] ^ a[i];
    }
    let mut dp = vec![0i64; n+1];
    dp[0] = 1;
    for t in 1..n+1 {
        for f in 0..t {
            let xor = xorsum[t] ^ xorsum[f];
            if xor == want {
                dp[t] += dp[f];
                dp[t] %= MOD;
            }
        }
    }
    dp[n]
}

fn main() {
    input! {
        n: usize,
        a: [usize; n]
    };

    // {
    //     let mut tt = 0;
    //     for i in 0..16  {
    //         let w = make(&a, i);
    //         debug!(i, w);
    //         tt += w;
    //     }
    //     tt %= MOD;
    //     debug!(tt);
    // }

    let mut xorsum = vec![0; n+1];
    for i in 0..n {
        xorsum[i+1] = xorsum[i] ^ a[i];
    }


    let mut dp = vec![0; MAX];
    let mut dp_zero = vec![0; MAX];
    let mut last_zero = vec![0; MAX];

    let mut idx = n;
    let mut mode = xorsum[n];
    let mut zero_count = 0;
    if mode == 0 {
        for i in 1..MAX {
            dp_zero[i] = 1;
        }
    } else {
        dp[mode] = 1;
    }

    loop {
        let mut histories = vec![];
        while idx >= 0 && xorsum[idx] != 0 {
            histories.push(xorsum[idx]);
            idx -= 1;
        }

        histories.sort();
        let hn = histories.len();
        let mut fr = 0;
        while fr < hn {
            let mut to = fr;
            while to < hn && histories[to] == histories[fr] {
                to += 1;
            }
            let count = (to - fr) as i64;
            let num = histories[fr];

            let add_zero = zero_count - last_zero[num];
            last_zero[num] = zero_count;
            dp_zero[num] += add_zero * dp[num] % MOD;
            dp_zero[num] %= MOD;

            dp[num] += count * dp_zero[num] % MOD;
            dp[num] %= MOD;

            // debug!(num, last_zero[num], zero_count, dp_zero[num], dp[num]);

            fr = to;
        }

        while idx >= 1 && xorsum[idx] == 0 {
            idx -= 1;
            zero_count += 1;
        }

        if idx == 0 {
            break;
        }
    }

    let mut ans = 0;
    if mode == 0 {
        for w in 1..MAX {
            ans += dp[w];
            ans %= MOD;
        }
        let mut count = 1;
        for i in 1..n {
            if xorsum[i] == 0 {
                count *= 2;
                count %= MOD;
            }
        }
        ans += count;
        ans %= MOD;
    } else {
        ans = dp[mode];
    }
    println!("{}", ans);
}

