use algonium::math::Mint107;

fn run() {
    input! {
        n: usize,
        a: [usize; n],
    }
    let mut s: Vec<usize> = Vec::new();
    s.push(0);
    for x in a {
        let next = *s.last().unwrap() ^ x;
        s.push(next);
    }
    if *s.last().unwrap() == 0 {
        let ans1 = {
            let mut s_last_m: HashMap<usize, Mint107> = HashMap::new();
            let mut s_last_sum: Mint107 = 0.into();
            let mut s_zero_m: HashMap<usize, Mint107> = HashMap::new();

            let mut zero_count: usize = 0;
            let mut last_zero: HashMap<usize, usize> = HashMap::new();
            for i in 0..n - 1 {
                let b = s[i + 1];
                if b == 0 {
                    zero_count += 1;
                } else {
                    if *last_zero.entry(b).or_insert(0) != zero_count {
                        let diff = zero_count - last_zero[&b];
                        last_zero.insert(b, zero_count);
                        let now = *s_zero_m.entry(b).or_insert(0.into());
                        let unit = *s_last_m.entry(b).or_insert(0.into());
                        s_zero_m.insert(b, now + unit * diff);
                    }
                    *s_last_m.entry(b).or_insert(0.into()) +=
                        *s_zero_m.entry(b).or_insert(0.into()) + 1;
                    s_last_sum += s_zero_m[&b] + 1;
                }
            }
            s_last_sum
        };
        let ans2 = {
            let mut s_zero: Mint107 = 1.into();
            for i in 0..n - 1 {
                let b = s[i + 1];
                if b == 0 {
                    s_zero += s_zero;
                }
            }
            s_zero
        };
        println!("{}", ans1 + ans2);
    } else {
        let mut s_last: Mint107 = 0.into();
        let mut s_zero: Mint107 = 1.into();
        for i in 0..n - 1 {
            let b = s[i + 1];
            if b == 0 {
                s_zero += s_last;
            } else if b == *s.last().unwrap() {
                s_last += s_zero;
            }
        }
        println!("{}", s_zero);
    }
}

