use std::collections::HashMap;

fn main() {
    input!{
        n: usize,
        v: [usize; n]
    }
    let mut ac: Vec<usize> = vec![0; n + 1];
    for i in 0..n {
        ac[i + 1] = ac[i] ^ v[i];
    }
    let mut ans;
    let d = 1000000007;
    if ac[n] != 0 {
        let mut ls: Vec<usize> = Vec::new();
        let mut prev = 0;
        let mut c = 1;
        for i in 0..n {
            if ac[i + 1] == ac[n] || ac[i + 1] == 0 {
                if ac[i + 1] == prev {
                    c += 1;
                } else {
                    ls.push(c);
                    c = 1;
                    prev = ac[i + 1];
                }
            }
        }
        if c > 0 {
            ls.push(c);
        }
        ans = solve(&ls, d);
    } else {
        let mut zs: Vec<usize> = vec![0; n + 1];
        zs[0] = 1;
        for i in 0..n {
            zs[i + 1] = zs[i];
            if ac[i + 1] == 0 {
                zs[i + 1] += 1;
            }
        }
        ans = pow_m(2, zs[n] - 2, d);
        let mut map: HashMap<usize, Vec<usize>> = HashMap::new();
        for (i, x) in ac.iter().enumerate().filter(|x| *x.1 != 0) {
            map.entry(*x).or_insert(vec![0]).push(i);
        }
        for locs in map.values() {
            let mut ls: Vec<usize> = vec![zs[locs[1]]];
            let mut c = 1;
            for i in 1..locs.len() - 1 {
                let z = zs[locs[i + 1]] - zs[locs[i]];
                if z > 0 {
                    ls.push(c);
                    ls.push(z);
                    c = 1;
                } else {
                    c += 1;
                }
            }
            ls.push(c);
            let z = zs[n] - zs[locs[locs.len() - 1]];
            if z > 0 {
                ls.push(z);
            }
            ans = (ans + solve(&ls, d)) % d;
        }
    }
    println!("{}", ans);
}

fn solve(ls: &Vec<usize>, d: usize) -> usize {
    let n = ls.len();
    if n == 1 {
        return 1;
    }
    let mut dp: Vec<Vec<usize>> = vec![vec![0; 2]; n - 1];
    dp[0][0] = 1;
    for i in 1..n - 1 {
        if i % 2 == 0 {
            dp[i][0] = (dp[i - 1][0] + dp[i - 1][1] * ls[i]) % d;
            dp[i][1] = dp[i - 1][1];
        } else {
            dp[i][0] = dp[i - 1][0];
            dp[i][1] = (dp[i - 1][0] * ls[i] + dp[i - 1][1]) % d;
        }
    }
    if n % 2 == 1 {
        dp[n - 2][1]
    } else {
        dp[n - 2][0]
    }
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut ret = 1;
    let mut r = n;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

use self::mod_int::ModInt;

const N: usize = 1 << 21;
const MOD: usize = 1e9 as usize + 7;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let mut sum = vec![0; n + 1];
    for i in 0..n {
        sum[i + 1] = sum[i] ^ a[i];
    }

    let mut zero_count = vec![0; n + 1];
    for i in 0..n {
        zero_count[i + 1] = zero_count[i] + if sum[i + 1] == 0 { 1 } else { 0 };
    }

    let mut prev: Vec<Option<usize>> = vec![None; N];
    let mut zeros = vec![vec![]; N];
    for i in 1..(n + 1) {
        if sum[i] != 0 {
            let mask = sum[i];
            match prev[mask] {
                Some(p) => {
                    let count = zero_count[i] - zero_count[p];
                    zeros[mask].push(count);
                }
                _ => {
                    let count = zero_count[i];
                    zeros[mask].push(count);
                }
            }
            prev[mask] = Some(i);
        }
    }
    for mask in 1..N {
        if let Some(p) = prev[mask] {
            let count = zero_count[n] - zero_count[p];
            zeros[mask].push(count);
        }
    }

    if sum[n] == 0 {
        let mut ans = ModInt(0);
        for mask in 1..N {
            if zeros[mask].is_empty() {
                continue;
            }
            let dp = calc(&zeros[mask]);
            // assert_eq!(dp[0].0, naive(&sum, mask)[0].0);
            ans += dp[1];
        }

        let zeros = sum.iter().filter(|&&s| s == 0).count();
        ans += ModInt(2).pow(zeros - 2);
        println!("{}", ans.0);
    } else {
        let dp = calc(&zeros[sum[n]]);
        println!("{}", (dp[1] - 1).0);
    }
}

fn calc(zeros: &Vec<usize>) -> Vec<ModInt<usize>> {
    let mut dp = vec![ModInt(1), ModInt(0)];
    let n = zeros.len();
    for i in 0..(n - 1) {
        let c = zeros[i];
        dp = vec![dp[0] + dp[1] * c, dp[1]];
        dp = vec![dp[0], dp[0] + dp[1]];
    }
    let c = zeros[n - 1];
    dp = vec![dp[0] + dp[1] * c, dp[1]];
    dp
}

fn naive(sum: &Vec<usize>, x: usize) -> Vec<ModInt<usize>> {
    let mut dp = vec![ModInt(1), ModInt(0)];
    for &s in sum.iter().skip(1) {
        if s == x {
            let d = dp[0];
            dp[1] += d;
        } else if s == 0 {
            let d = dp[1];
            dp[0] += d;
        }
    }
    dp
}

